#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

struct Event {
    time_t timestamp;
    int eventType;
    char* uniqueId;
};

struct EventCollection {
    struct Event** events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void initEventCollection(struct EventCollection* collection) {
    collection->events = malloc(sizeof(struct Event*) * 10);
    collection->capacity = 10;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
}

void addEvent(struct EventCollection* collection, struct Event event) {
    pthread_mutex_lock(&collection->mutex);
    if (collection->count == collection->capacity) {
        collection->events = realloc(collection->events, sizeof(struct Event*) * (collection->capacity + 10));
        collection->capacity += 10;
    }
    collection->events[collection->count++] = malloc(sizeof(struct Event));
    memcpy(collection->events[collection->count - 1], &event, sizeof(struct Event));
    pthread_mutex_unlock(&collection->mutex);
}

void removeOldEvents(struct EventCollection* collection, time_t threshold) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i]->timestamp <= threshold) {
            free(collection->events[i]);
            --collection->count;
            memmove(collection->events + i, collection->events + i + 1, sizeof(struct Event*) * (collection->count - i));
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

void retrieveEvents(struct EventCollection* collection, time_t startTime, time_t endTime) {
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->events[i]->timestamp >= startTime && collection->events[i]->timestamp <= endTime) {
            printf("%d: %s\n", collection->events[i]->eventType, collection->events[i]->uniqueId);
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}
