record** initialize_arrays(size_t num_records, size_t offset_size, size_t key_size) {
    // Validate input parameters
    if (num_records == 0 || offset_size == 0 || key_size == 0) {
        return NULL;
    }

    // Allocate memory for the arrays
    long* offsets = malloc(sizeof(long) * num_records);
    int* keys = malloc(sizeof(int) * num_records);
    record** records = malloc(sizeof(record*) * num_records);

    // Initialize the offset array
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(record);
    }

    // Initialize the key array
    srand(time(NULL));
    for (size_t i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
    }

    // Initialize the record structures
    for (size_t i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(record));
        records[i]->key = keys[i];
        records[i]->value = rand() % 100;
        records[i]->data_block = NULL;
    }

    // Ensure proper alignment of the record structures
    for (size_t i = 0; i < num_records; i++) {
        records[i] = (record*)(((uintptr_t)records[i]) + offsets[i]);
    }

    // Validate the size of the arrays at runtime to prevent buffer overflows
    if (sizeof(long) * num_records > SIZE_MAX / sizeof(int)) {
        return NULL;
    }
    if (sizeof(record*) * num_records > SIZE_MAX / sizeof(record)) {
        return NULL;
    }

    // Fill the value field of each record with a random integer within a specified range
    for (size_t i = 0; i < num_records; i++) {
        records[i]->value = rand() % 100;
    }

    return records;
}
