#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

void process_log(char* input_file, char* output_file, char* pattern, bool include_line_numbers) {
    // Open the input file for reading
    FILE* in = fopen(input_file, "r");
    if (in == NULL) {
        printf("Error: unable to open input file %s\n", input_file);
        return;
    }

    // Open the output file for writing
    FILE* out = fopen(output_file, "w");
    if (out == NULL) {
        printf("Error: unable to open output file %s\n", output_file);
        fclose(in);
        return;
    }

    // Read and process the input file in chunks
    char* buffer = malloc(BUFSIZ);
    size_t bytes_read = 0;
    while ((bytes_read = fread(buffer, sizeof(char), BUFSIZ, in)) > 0) {
        // Process the read data
        for (size_t i = 0; i < bytes_read; i++) {
            if (strstr(buffer + i, pattern) != NULL) {
                // Match found, write to output file
                if (include_line_numbers) {
                    fprintf(out, "%zu: %s\n", i + 1, buffer + i);
                } else {
                    fprintf(out, "%s\n", buffer + i);
                }
            }
        }
    }

    // Clean up resources
    free(buffer);
    fclose(in);
    fclose(out);
}
```
