#include <openssl/des.h>
#include <json-c/json.h>

bool verify_json(const char *json) {
    json_object *obj = json_tokener_parse(json);
    if (!obj) {
        return false;
    }

    const char *access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!access_token) {
        return false;
    }

    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in <= 0) {
        return false;
    }

    const char *token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    const char *refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strcmp(refresh_token, "") == 0) {
        return false;
    }

    return true;
}

EVP_CIPHER *des_cipher(const char *json) {
    json_object *obj = json_tokener_parse(json);
    if (!obj) {
        return NULL;
    }

    const char *mode = json_object_get_string(json_object_object_get(obj, "mode"));
    if (!mode) {
        return NULL;
    }

    int key_len = 0;
    unsigned char key[8];
    switch (mode[0]) {
        case 'E':
            key_len = 56;
            break;
        case 'D':
            key_len = 112;
            break;
        case 'C':
            key_len = 168;
            break;
        default:
            return NULL;
    }

    const char *key_str = json_object_get_string(json_object_object_get(obj, "key"));
    if (!key_str) {
        return NULL;
    }

    int i = 0;
    for (i = 0; i < key_len && i < strlen(key_str); ++i) {
        key[i] = key_str[i];
    }

    EVP_CIPHER *cipher = NULL;
    switch (mode[0]) {
        case 'E':
            cipher = EVP_enc_des_cbc();
            break;
        case 'D':
            cipher = EVP_dec_des_cbc();
            break;
        case 'C':
            cipher = EVP_enc_des_ede3_cbc();
            break;
        default:
            return NULL;
    }

    if (!cipher) {
        return NULL;
    }

