public static void modifyKickstartConfig(KickstartConfig config, Pokemon pokemon) throws IOException {
    // Read the contents of the Kickstart configuration file
    String originalContent = Files.readString(Paths.get("kickstart.conf"));

    // Replace placeholders with actual values from the KickstartConfig object
    String modifiedContent = originalContent.replaceAll("%POKEMON_NAME%", pokemon.getName())
            .replaceAll("%POKEMON_TYPE%", pokemon.getType().toString());

    // Append a new line with an encrypted version of the Pokemon's weakness
    String weakness = encryptWeakness(pokemon.getWeakness());
    modifiedContent += "\n" + weakness;

    // Save modifications to a new file named "modified_kickstart.conf"
    Files.writeString(Paths.get("modified_kickstart.conf"), modifiedContent);
}

private static String encryptWeakness(String weakness) {
    // Encrypt the Pokemon's weakness using a custom encryption algorithm
    return "ENCRYPTED_" + weakness;
}
