import org.json.JSONObject;

public class Pokemon {
    private String name;
    private List<String> types;

    public Pokemon(String name, List<String> types) {
        this.name = name;
        this.types = types;
    }

    public JSONObject getDetailedInfo() {
        JSONObject json = new JSONObject();
        json.put("name", name);
        json.put("types", types);

        List<String> weaknesses = new ArrayList<>();
        List<String> resistances = new ArrayList<>();
        List<String> immunities = new ArrayList<>();

        for (String type : types) {
            switch (type) {
                case "Fire":
                    weaknesses.add("Water");
                    break;
                case "Water":
                    weaknesses.add("Fire");
                    break;
                case "Electric":
                    weaknesses.add("Ground");
                    break;
                case "Ground":
                    weaknesses.add("Electric");
                    break;
                case "Fighting":
                    weaknesses.add("Flying");
                    break;
                case "Flying":
                    weaknesses.add("Fighting");
                    break;
                case "Poison":
                    weaknesses.add("Ground");
                    break;
                case "Ground":
                    weaknesses.add("Poison");
                    break;
                case "Ghost":
                    weaknesses.add("Normal");
                    break;
                case "Normal":
                    weaknesses.add("Ghost");
                    break;
                case "Steel":
                    weaknesses.add("Fairy");
                    break;
                case "Fairy":
                    weaknesses.add("Steel");
                    break;
            }
        }

        json.put("weaknesses", weaknesses);
        json.put("resistances", resistances);
        json.put("immunities", immunities);

        return json;
    }
}
