#include <openssl/des.h>
#include <openssl/evp.h>
#include <json-c/json.h>

bool validate_json(const char *json) {
    json_object *obj = json_tokener_parse(json);
    if (!obj) {
        return false;
    }

    const char *token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in <= 0) {
        return false;
    }

    const char *refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strlen(refresh_token) > 0) {
        // Optional field is present and has a non-empty value
        return false;
    }

    return true;
}

EVP_CIPHER *setup_cipher(const char *json, int mode) {
    if (!validate_json(json)) {
        return NULL;
    }

    json_object *obj = json_tokener_parse(json);
    const char *access_token = json_object_get_string(json_object_object_get(obj, "access_token"));

    EVP_CIPHER *cipher = NULL;
    switch (mode) {
        case ECB:
            cipher = EVP_des_ecb();
            break;
        case EDE:
            cipher = EVP_des_ede();
            break;
        case EDE3:
            cipher = EVP_des_ede3();
            break;
        case CFB:
            cipher = EVP_des_cfb();
            break;
    }

    if (!cipher) {
        return NULL;
    }

    int ret = EVP_CipherInit(cipher, access_token, NULL, 1);
    if (ret != 1) {
        return NULL;
    }

    return cipher;
}
