#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

void manageSharedMemory(char* sharedMemName, int size) {
    // Create a shared memory segment with the given name and size
    int shm_fd = shm_open(sharedMemName, O_CREAT | O_EXCL | O_RDWR, 0644);
    if (shm_fd == -1) {
        perror("Error creating shared memory segment");
        exit(1);
    }

    // Set the size of the shared memory segment
    ftruncate(shm_fd, size);

    // Map the shared memory segment to the process's address space
    void* shm_addr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_addr == MAP_FAILED) {
        perror("Error mapping shared memory segment");
        exit(1);
    }

    // Initialize the shared memory segment with a mutex and a condition variable
    pthread_mutex_t* mutex = (pthread_mutex_t*)shm_addr;
    pthread_cond_t* cond = (pthread_cond_t*)(shm_addr + sizeof(pthread_mutex_t));
    pthread_mutex_init(mutex, NULL);
    pthread_cond_init(cond, NULL);

    // Allow multiple processes to read and write to the shared memory segment
    pthread_rwlock_t* rwlock = (pthread_rwlock_t*)shm_addr;
    pthread_rwlock_init(rwlock, NULL);

    // Destroy the shared memory segment when it is no longer needed
    shm_unlink(sharedMemName);
}
