<?php

function userAccount($request) {
    // Validate the request data
    $validation = validateRequest($request);
    if ($validation['status'] === 'error') {
        return json_encode(['message' => 'error', 'data' => null]);
    }

    // Check if the user account exists
    $userAccount = getUserAccount($request['id']);
    if (!$userAccount) {
        // Create a new user account
        $userAccount = createUserAccount($request);
    } else {
        // Update an existing user account
        $userAccount = updateUserAccount($request, $userAccount);
    }

    // Save the user account to the database
    saveUserAccount($userAccount);

    // Return a JSON response with the updated user account data
    return json_encode(['message' => 'success', 'data' => $userAccount]);
}

function validateRequest($request) {
    // Check if the request has all required keys
    if (!isset($request['name'], $request['email'], $request['password'])) {
        return ['status' => 'error', 'message' => 'Missing required fields'];
    }

    // Validate the email format
    if (!validateEmailFormat($request['email'])) {
        return ['status' => 'error', 'message' => 'Invalid email format'];
    }

    // Check if the email is unique across the system
    if (emailExists($request['email'])) {
        return ['status' => 'error', 'message' => 'Email already exists'];
    }

    // Hash the password before saving to the database
    $request['password'] = hashPassword($request['password']);

    // Check if the request has a sub_action key and validate it
    if (isset($request['sub_action'])) {
        switch ($request['sub_action']) {
            case 'delete':
                // Delete the user account
                deleteUserAccount($request['id']);
                break;
            default:
                return ['status' => 'error', 'message' => 'Invalid sub_action'];
        }
    }

    return ['status' => 'success', 'message' => 'Request validated'];
}

function createUserAccount($request) {
    // Create a new user account object
    $userAccount = new UserAccount();
    $userAccount->name = $request['name'];
    $userAccount->email = $request['email'];
    $userAccount->password = $request['password'];

    return $userAccount;
}

function updateUserAccount($request, $userAccount) {
    // Update the user account object with new data
    $userAccount->name = $request['name'];
    $userAccount->email = $request['email'];
    $userAccount->password = $request['password'];

    return $userAccount;
}

function saveUserAccount($userAccount) {
    // Save the user account to the database
    $db = new Database();
    $db->save($userAccount);
}

function getUserAccount($id) {
    // Retrieve the user account from the database
    $db = new Database();
    return $db->getById($id);
}

function deleteUserAccount($id) {
    // Delete the user account from the database
    $db = new Database();
    $db->delete($id);
}

function validateEmailFormat($email) {
    // Implement custom email validation logic here
    return true;
}

function emailExists($email) {
    // Check if the email exists in the database
    $db = new Database();
    return $db->exists('email', $email);
}

function hashPassword($password) {
    // Hash the password using a secure hashing algorithm
    return password_hash($password, PASSWORD_DEFAULT);
}

function getLocale() {
    // Get the locale from the request headers or session data
    $locale = 'en';
    if (isset($_SERVER['HTTP_ACCEPT_LANGUAGE'])) {
        $locale = substr($_SERVER['HTTP_ACCEPT_LANGUAGE'], 0, 2);
    } elseif (isset($_SESSION['locale'])) {
        $locale = $_SESSION['locale'];
    }
    return $locale;
}

function getMessage($message) {
    // Get the message based on the locale
    switch ($message) {
        case 'success':
            return 'Success!';
        case 'error':
            return 'Error!';
        default:
            return 'Unknown message.';
    }
}
