const oldTestamentBooks = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
const punctuationRegex = /[.,\/#!$%\^&\*;:{}=\-_`~()]/g;
const specialCharactersRegex = /[^a-zA-Z0-9 ]/g;
const ignoreBooksRegex = /(Psalms|Proverbs|Ecclesiastes|Song of Solomon)/gi;

function extractOldTestamentBooks(text) {
  const bookCounts = {};
  for (let i = 0; i < oldTestamentBooks.length; i++) {
    const bookName = oldTestamentBooks[i];
    const regex = new RegExp(`\\b${bookName}\\b`, 'gi');
    let match;
    while ((match = regex.exec(text)) !== null) {
      if (!ignoreBooksRegex.test(match[0])) {
        bookCounts[bookName] = (bookCounts[bookName] || 0) + 1;
      }
    }
  }
  return bookCounts;
}
