// Module Loader
const moduleLoader = (function() {
  // Cache for successfully loaded modules
  const cache = {};

  // Load a single module file
  function loadModule(file) {
    return new Promise((resolve, reject) => {
      fetch(file)
        .then(response => response.text())
        .then(code => {
          try {
            const module = eval(code);
            cache[file] = module;
            resolve(module);
          } catch (error) {
            reject(error);
          }
        })
        .catch(error => reject(error));
    });
  }

  // Load a list of module files in the specified order
  function loadModules(files) {
    return Promise.all(files.map(file => loadModule(file)));
  }

  // Execute a single module file
  function executeModule(module) {
    try {
      module();
    } catch (error) {
      console.error(`Error executing module: ${error}`);
    }
  }

  // Execute a list of module files in the specified order
  function executeModules(modules) {
    modules.forEach(module => executeModule(module));
  }

  return {
    loadModules,
    executeModules
  };
})();
