import java.io.File;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class FileDuplicateFinder {
    public static void main(String[] args) {
        // List of file paths to process
        List<String> filePaths = Arrays.asList("file1", "file2", "file3");

        // Create a HashMap to store file paths by their hash values
        Map<Integer, Set<File>> hashMap = new HashMap<>();

        // Create a Union-Find data structure to efficiently manage and query duplicate relationships
        UnionFind unionFind = new UnionFind();

        // Iterate over the list of file paths
        for (String filePath : filePaths) {
            File file = new File(filePath);

            // Hash the file contents to get its hash value
            int hashValue = hashFileContents(file);

            // Add the file path to the HashMap using the hash value as the key
            Set<File> filesWithHash = hashMap.getOrDefault(hashValue, new HashSet<>());
            filesWithHash.add(file);
            hashMap.put(hashValue, filesWithHash);

            // Add the file to the Union-Find data structure
            unionFind.add(file);
        }

        // Iterate over the HashMap and count the number of unique file hashes
        int numUniqueHashes = 0;
        for (Map.Entry<Integer, Set<File>> entry : hashMap.entrySet()) {
            if (entry.getValue().size() > 1) {
                // If there are multiple files with the same hash value, they are duplicates
                numUniqueHashes++;
            }
        }

        // Iterate over the Union-Find data structure and count the total size of all duplicate files
        long totalDuplicateSize = 0;
        for (File file : unionFind.getRoots()) {
            if (!unionFind.isRoot(file)) {
                // If the file is not a root, it is a duplicate
                totalDuplicateSize += file.length();
            }
        }

        System.out.println("Number of unique hashes: " + numUniqueHashes);
        System.out.println("Total size of duplicate files: " + totalDuplicateSize);
    }

    // Hash the contents of a file to get its hash value
    private static int hashFileContents(File file) {
        try (InputStream inputStream = new FileInputStream(file)) {
            byte[] buffer = new byte[1024];
            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
            while (inputStream.read(buffer) > 0) {
                messageDigest.update(buffer);
            }
            return messageDigest.digest();
        } catch (IOException | NoSuchAlgorithmException e) {
            throw new RuntimeException("Error hashing file contents", e);
        }
    }
}
