import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.TimeUnit;

public class ConnectionManager {
    private AsynchronousServerSocketChannel serverSocket;
    private int timeout = 30; // seconds

    public void start() throws IOException {
        serverSocket = AsynchronousServerSocketChannel.open();
        serverSocket.bind(new InetSocketAddress("localhost", 8080));
        serverSocket.setOption(AsynchronousSocketChannel.SO_TIMEOUT, timeout);
    }

    public void stop() throws IOException {
        if (serverSocket != null) {
            serverSocket.close();
        }
    }

    public void handleConnection(AsynchronousSocketChannel socket) {
        try {
            // Handle client connection here
            System.out.println("New client connected: " + socket);
            TimeUnit.SECONDS.sleep(timeout);
            if (socket.isOpen()) {
                System.out.println("Client is still active");
            } else {
                System.out.println("Client timed out");
            }
        } catch (IOException | InterruptedException e) {
            // Handle exception here
            System.out.println("Error handling client connection: " + e);
        } finally {
            if (socket != null && socket.isOpen()) {
                try {
                    socket.close();
                } catch (IOException e) {
                    // Handle exception here
                    System.out.println("Error closing client connection: " + e);
                }
            }
        }
    }
}
