<?php

class PasswordUtility {
    private $charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+';
    private $hashingMethod = 'bcrypt';
    private $iterations = 10;

    public function generateRandomString($length) {
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charset[rand(0, strlen($this->charset) - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password) {
        return password_hash($password, $this->hashingMethod, ['cost' => $this->iterations]);
    }

    public function validatePassword($providedPassword, $generatedPassword) {
        if (strlen($providedPassword) !== strlen($generatedPassword)) {
            return false;
        }
        $time = microtime(true);
        for ($i = 0; $i < strlen($providedPassword); $i++) {
            if ($providedPassword[$i] !== $generatedPassword[$i]) {
                return false;
            }
        }
        return true;
    }

    public function loadCustomCharset($file) {
        if (!is_readable($file)) {
            throw new Exception('Invalid configuration file');
        }
        $this->charset = file_get_contents($file);
    }

    public function setHashingMethod($method) {
        if (in_array($method, hash_algos())) {
            $this->hashingMethod = $method;
        } else {
            throw new Exception('Invalid hashing method');
        }
    }

    public function setIterations($iterations) {
        if ($iterations > 0) {
            $this->iterations = $iterations;
        } else {
            throw new Exception('Invalid number of iterations');
        }
    }
}
```
