function manageUserSessions($oauthClient) {
    // Check if there is an active session
    if (!isset($_SESSION['access_token'])) {
        // If not, initiate the OAuth 2.0 client for authentication
        $oauthClient->initiateAuthentication();
    } else {
        // If there is an active session, check if the access token has expired
        if ($oauthClient->isAccessTokenExpired()) {
            // If it has, refresh the access token and store it in the session variable
            $accessToken = $oauthClient->refreshAccessToken();
            $_SESSION['access_token'] = $accessToken;
        }
    }

    // Retrieve user information upon successful authentication
    if (isset($_SESSION['access_token'])) {
        $userInfo = $oauthClient->getUserInformation($_SESSION['access_token']);
        $_SESSION['user_info'] = $userInfo;
    }

    // Cache the user data locally to minimize API calls
    if (isset($_SESSION['user_info'])) {
        $cachedUserData = json_encode($_SESSION['user_info']);
        file_put_contents('user_data.json', $cachedUserData);
    }
}
