#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

class Octree {
public:
    // Constructor to initialize the octree with a given number of nodes
    Octree(int numNodes) {
        this->numNodes = numNodes;
        this->nodes.resize(numNodes);
        this->objects.reserve(10000000);
    }

    // Function to add an object to the octree
    void addObject(const Object& obj) {
        int nodeIdx = getNodeIndex(obj.getPosition());
        nodes[nodeIdx].objects.push_back(obj);
    }

    // Function to remove an object from the octree
    void removeObject(const Object& obj) {
        int nodeIdx = getNodeIndex(obj.getPosition());
        auto it = std::find(nodes[nodeIdx].objects.begin(), nodes[nodeIdx].objects.end(), obj);
        if (it != nodes[nodeIdx].objects.end()) {
            nodes[nodeIdx].objects.erase(it);
        }
    }

    // Function to query the nearest neighbor of an object in the octree
    Object getNearestNeighbor(const Object& obj) {
        int nodeIdx = getNodeIndex(obj.getPosition());
        return nodes[nodeIdx].objects[0];
    }

private:
    // Function to get the index of the node that an object belongs to
    int getNodeIndex(const glm::vec3& position) {
        int x = (int)(position.x / nodeSize);
        int y = (int)(position.y / nodeSize);
        int z = (int)(position.z / nodeSize);
        return x + y * numNodes + z * numNodes * numNodes;
    }

    // Structure to represent an octree node
    struct Node {
        std::vector<Object> objects;
    };

    // Vector of nodes in the octree
    std::vector<Node> nodes;

    // Number of nodes in the octree
    int numNodes;

    // Size of each node in the octree
    float nodeSize = 1.0f;
};
```
