// Structure to store transaction data
typedef struct {
    int id;
    double weight;
    long timestamp;
} Transaction;

// Function to process a single transaction
void processTransaction(Transaction *transaction) {
    // Calculate the weighted sum for the current transaction
    double weightedSum = transaction->weight + getAverageWeight(transaction->id);

    // Update the system metrics
    updateMetrics(weightedSum, transaction->id);
}

// Function to calculate the average weight of the last 10 transactions in the sliding window
double getAverageWeight(int id) {
    // Initialize variables for the sliding window and the total weight
    int window[WINDOW_SIZE];
    double totalWeight = 0;

    // Iterate over the last 10 transactions in the sliding window
    for (int i = 0; i < WINDOW_SIZE; i++) {
        // Check if the transaction ID is valid and has a weight
        if (id - i >= 0 && transactions[id - i].weight > 0) {
            // Add the weight to the total weight and store the transaction ID in the sliding window
            totalWeight += transactions[id - i].weight;
            window[i] = id - i;
        } else {
            // If the transaction ID is invalid or has no weight, break the loop
            break;
        }
    }

    // Return the average weight of the last 10 transactions in the sliding window
    return totalWeight / WINDOW_SIZE;
}

// Function to update the system metrics
