    }

    // Return the average weight of the last 10 transactions in the sliding window
    return totalWeight / WINDOW_SIZE;
}

// Function to handle edge cases such as missing timestamps or invalid weights gracefully
void handleEdgeCases(Transaction *transaction) {
    // Check if the transaction has a valid timestamp and weight
