char* append_slash(const char* input, size_t limit, char* buffer) {
    // Check if the input string length exceeds the specified size limit
    if (strlen(input) > limit) {
        return NULL;
    }

    // Append a forward slash to the end of the string and store the result in the provided buffer
    strcpy(buffer, input);
    buffer[strlen(input)] = '/';
    buffer[strlen(input) + 1] = '\0';

    // Ensure the buffer is large enough to hold the modified string
    if (strlen(buffer) > limit) {
        char* new_buffer = realloc(buffer, strlen(buffer) * 2);
        if (!new_buffer) {
            free(buffer);
            return NULL;
        }
        buffer = new_buffer;
    }

    // Return a pointer to the buffer containing the modified string
    return buffer;
}
