void* parseTIFFAndEncrypt(const char* filePath, const char* commandLineOption) {
    // Open the TIFF image file
    FILE* tiffFile = fopen(filePath, "rb");
    if (tiffFile == NULL) {
        printf("Error: Could not open TIFF image file.\n");
        return NULL;
    }

    // Read the TIFF header and check for errors
    unsigned char tiffHeader[4];
    size_t bytesRead = fread(tiffHeader, 1, sizeof(tiffHeader), tiffFile);
    if (bytesRead != sizeof(tiffHeader)) {
        printf("Error: Could not read TIFF header.\n");
        fclose(tiffFile);
        return NULL;
    }

    // Check the TIFF header for errors and extract information about the image's bits per sample and sample per pixel
    unsigned short bitsPerSample = 0;
    unsigned short samplesPerPixel = 0;
    if (tiffHeader[0] == 'M' && tiffHeader[1] == 'M') {
        // Big-endian TIFF header
        bitsPerSample = *(unsigned short*)(&tiffHeader[2]);
        samplesPerPixel = *(unsigned short*)(&tiffHeader[4]);
    } else if (tiffHeader[0] == 'I' && tiffHeader[1] == 'I') {
        // Little-endian TIFF header
        bitsPerSample = *(unsigned short*)(&tiffHeader[2]);
        samplesPerPixel = *(unsigned short*)(&tiffHeader[4]);
    } else {
        printf("Error: Unsupported TIFF header.\n");
        fclose(tiffFile);
        return NULL;
    }

    // Check the bits per sample and samples per pixel for errors and handle cases where the image has extra samples
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        printf("Error: Unsupported bits per sample.\n");
        fclose(tiffFile);
        return NULL;
    }
    if (samplesPerPixel > 3) {
        // Handle extra samples by reading the image data and extracting information about them
        unsigned char* imageData = malloc(sizeof(unsigned char) * samplesPerPixel * width * height);
        fread(imageData, sizeof(unsigned char), samplesPerPixel * width * height, tiffFile);
        // ...
    }

    // Perform the encryption operation based on the provided command line option
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Could not create cipher context.\n");
        fclose(tiffFile);
        return NULL;
    }
    int ret = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
    if (ret != 1) {
        printf("Error: Could not initialize cipher context.\n");
        fclose(tiffFile);
        return NULL;
    }
    ret = EVP_EncryptUpdate(ctx, imageData, &bytesWritten, imageData, width * height * samplesPerPixel);
    if (ret != 1) {
        printf("Error: Could not encrypt image data.\n");
        fclose(tiffFile);
        return NULL;
    }
    ret = EVP_EncryptFinal_ex(ctx, imageData + bytesWritten, &bytesWritten);
    if (ret != 1) {
        printf("Error: Could not finalize encryption.\n");
        fclose(tiffFile);
        return NULL;
    }

    // Return the cipher object and close the TIFF image file
    EVP_CIPHER_CTX_free(ctx);
    fclose(tiffFile);
    return imageData;
}
