#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char* modify_filename(const char* original_filename) {
    // Extract base name and extension from input filename
    const char* dot = strrchr(original_filename, '.');
    size_t basename_len = dot - original_filename;
    size_t extension_len = strlen(dot + 1);
    char* new_filename = malloc(basename_len + extension_len + 10);
    memcpy(new_filename, original_filename, basename_len);
    new_filename[basename_len] = '\0';

    // Determine number of digits in base name and generate new filename
    int num_digits = 0;
    for (int i = 0; i < basename_len; i++) {
        if (isdigit(original_filename[i])) {
            num_digits++;
        }
    }
    sprintf(new_filename + basename_len, "%d.%s", num_digits, dot + 1);

    // Handle filenames with no extension or multiple extensions gracefully
    if (extension_len == 0) {
        new_filename[basename_len] = '\0';
    } else if (extension_len > 5) {
        new_filename[basename_len + 5] = '\0';
    }

    // Ensure that the new filename does not exceed a maximum length of 255 characters
    size_t new_filename_len = strlen(new_filename);
    if (new_filename_len > 255) {
        new_filename[255] = '\0';
    }

    // Use sprintf and strcat for string manipulation, but avoid buffer overflows by carefully managing string lengths
    char* result = malloc(new_filename_len + 1);
    memcpy(result, new_filename, new_filename_len);
    result[new_filename_len] = '\0';

    // Preserve the original filename if the new filename exceeds the maximum length constraint
    if (strcmp(original_filename, new_filename) == 0) {
        free(result);
        return NULL;
    } else {
        return result;
    }
}
```
