    EVP_add_cipher(EVP_camellia_192_cbc(), NULL);
    EVP_add_cipher(EVP_camellia_256_cbc(), NULL);

    // Add MD5 digest
    EVP_add_digest(EVP_md5(), NULL);

    // Add SHA1 digest
    EVP_add_digest(EVP_sha1(), NULL);

    // Add RSA with SHA1 signature
    EVP_add_signature(EVP_sha1(), EVP_PKEY_RSA, NULL);

    // Create alias for custom digest algorithm
    EVP_add_digest_alias("custom", "custom_digest");
}

void init_cryptographic_library() {
    // Initialize OpenSSL library
    OPENSSL_init_ssl(OPENSSL_INIT_LOAD_CRYPTO_STRINGS, NULL);

    // Add cryptographic primitives to the library
    add_cryptographic_primitives();
}

void deinit_cryptographic_library() {
    // Deinitialize OpenSSL library
    OPENSSL_cleanup();
}

