// Define the AES-256-CBC cipher context structure
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} aes256cbc_ctx;

// Function to initialize the AES-256-CBC cipher with a given password
int init_aes256cbc(const char *password, size_t password_len) {
    // Check if the password is valid
    if (password == NULL || password_len < 1) {
        return -1;
    }

    // Generate a random IV for each initialization
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Derive the encryption key from the password using a secure KDF
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return -2;
    }
    int ret = EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), iv, password, password_len, 1, ctx->key, ctx->iv);
    if (ret <= 0) {
        return -3;
    }

    // Initialize the AES-256-CBC cipher context with the derived key and IV
    aes256cbc_ctx *aes = malloc(sizeof(aes256cbc_ctx));
    if (aes == NULL) {
        return -4;
    }
    aes->ctx = ctx;
    memcpy(aes->iv, iv, AES_BLOCK_SIZE);

    // Return the initialized cipher context
    return 0;
}

// Function to encrypt data using the AES-256-CBC cipher
int aes256cbc_encrypt(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Check if the input parameters are valid
    if (plaintext == NULL || plaintext_len < 1 || ciphertext == NULL) {
        return -1;
    }

    // Get the initialized AES-256-CBC cipher context
    aes256cbc_ctx *aes = get_aes256cbc_ctx();
    if (aes == NULL) {
        return -2;
    }

    // Encrypt the plaintext using the AES-256-CBC cipher
    int ret = EVP_EncryptUpdate(aes->ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    if (ret <= 0) {
        return -3;
    }

    // Return the encrypted data
    return plaintext_len;
}

// Function to decrypt data using the AES-256-CBC cipher
int aes256cbc_decrypt(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Check if the input parameters are valid
    if (ciphertext == NULL || ciphertext_len < 1 || plaintext == NULL) {
        return -1;
    }

    // Get the initialized AES-256-CBC cipher context
    aes256cbc_ctx *aes = get_aes256cbc_ctx();
    if (aes == NULL) {
        return -2;
    }

    // Decrypt the ciphertext using the AES-256-CBC cipher
    int ret = EVP_DecryptUpdate(aes->ctx, plaintext, &ciphertext_len, ciphertext, ciphertext_len);
    if (ret <= 0) {
        return -3;
    }

    // Return the decrypted data
    return ciphertext_len;
}

// Function to securely clean up and disable the AES-256-CBC cipher context
void aes256cbc_cleanup(aes256cbc_ctx *aes) {
    // Check if the input parameter is valid
    if (aes == NULL) {
        return;
    }

    // Clean up and disable the AES-256-CBC cipher context
    EVP_CIPHER_CTX_cleanup(aes->ctx);
    free(aes);
}
```
