#define MAX_ARGS 10
#define MAX_ARG_LEN 512
#define LOG_FILE "background_processes.log"

int run_command(char *cmd, char **args) {
    int pid, status;
    if (args == NULL || cmd == NULL) {
        return -1;
    }
    // Fork a child process to execute the command
    pid = fork();
    if (pid < 0) {
        perror("fork");
        return -2;
    } else if (pid == 0) {
        // Child process: execute the command and exit
        execvp(cmd, args);
        perror("execvp");
        exit(1);
    }
    // Parent process: wait for the child to finish
    while (wait(&status) != pid) {}
    if (!WIFEXITED(status)) {
        return -3;
    }
    int ret = WEXITSTATUS(status);
    if (ret != 0) {
        // Log the command execution status to a file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            return -4;
        }
        char log_msg[MAX_ARG_LEN];
        snprintf(log_msg, MAX_ARG_LEN, "%s: %d\n", cmd, ret);
        fputs(log_msg, log_file);
        fclose(log_file);
    }
    return ret;
}
```
