bool verify_oauth2_token(const char *json) {
    json_object *obj = json_tokener_parse(json);
    if (!obj) {
        return false;
    }

    // Check for required fields
    const char *access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!access_token) {
        return false;
    }

    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in < 0) {
        return false;
    }

    const char *token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    // Check for optional fields
    const char *refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strlen(refresh_token) == 0) {
        return false;
    }

    // Check for alphanumeric characters and hyphens in access token
    const char *access_token_str = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!access_token_str || !is_alphanumeric(access_token_str)) {
        return false;
    }

    // Check for alphanumeric characters and hyphens in refresh token (if present)
    const char *refresh_token_str = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token_str && !is_alphanumeric(refresh_token_str)) {
        return false;
    }

    // Check for integer overflow in expires_in value
    if (expires_in > INT_MAX) {
        return false;
    }

    json_object_put(obj);
    return true;
}

bool is_alphanumeric(const char *str) {
    for (size_t i = 0; i < strlen(str); i++) {
        if (!isalpha(str[i]) && !isdigit(str[i])) {
            return false;
        }
    }
    return true;
}
```
