using System.Security.Cryptography;
using System.Text;

public static class CryptoHelper
{
    public static List<string> DecryptAndHashMessages(string messages)
    {
        var decryptedMessages = new List<string>();

        try
        {
            // Split the input string into individual messages
            var messageBatch = messages.Split('|');

            // Limit the number of messages processed per invocation to 1000
            if (messageBatch.Length > 1000)
            {
                throw new ArgumentException("Too many messages provided", nameof(messages));
            }

            // Decrypt each message using Triple DES encryption with a provided key and initialization vector (IV)
            foreach (var message in messageBatch)
            {
                var decryptedMessage = DecryptTripleDes(message, "your_key", "your_iv");
                decryptedMessages.Add(decryptedMessage);
            }
        }
        catch (ArgumentNullException ex)
        {
            // Handle ArgumentNullException
            Console.WriteLine("Error: " + ex.Message);
        }
        catch (FormatException ex)
        {
            // Handle FormatException
            Console.WriteLine("Error: " + ex.Message);
        }
        catch (CryptographicException ex)
        {
            // Handle CryptographicException
            Console.WriteLine("Error: " + ex.Message);
        }

        return decryptedMessages;
    }

    private static string DecryptTripleDes(string message, string key, string iv)
    {
        var des = new TripleDESCryptoServiceProvider();
        var ms = new MemoryStream();
        var cs = new CryptoStream(ms, des.CreateDecryptor(Encoding.UTF8.GetBytes(key), Encoding.UTF8.GetBytes(iv)), CryptoStreamMode.Write);

        try
        {
            // Write the encrypted message to the crypto stream and flush it
            var bytes = Convert.FromBase64String(message);
            cs.Write(bytes, 0, bytes.Length);
            cs.FlushFinalBlock();

            // Return the decrypted message as a string
            return Encoding.UTF8.GetString(ms.ToArray());
        }
        finally
        {
            // Dispose of the crypto stream and memory stream
            cs.Dispose();
            ms.Dispose();
        }
    }
}
