using System;
using System.Security.Cryptography;
using System.Text;

public static class AESCBCDecryption
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, PaddingMode padding)
    {
        // Validate input parameters
        if (ciphertext == null || ciphertext.Length == 0)
            throw new ArgumentException("Ciphertext cannot be null or empty", nameof(ciphertext));
        if (encryptionKey == null || encryptionKey.Length == 0)
            throw new ArgumentException("Encryption key cannot be null or empty", nameof(encryptionKey));
        if (initializationVector == null || initializationVector.Length == 0)
            throw new ArgumentException("Initialization vector cannot be null or empty", nameof(initializationVector));
        if (padding != PaddingMode.PKCS7 && padding != PaddingMode.Zeros)
            throw new ArgumentException("Invalid padding mode specified", nameof(padding));

        // Create AES-CBC decryptor with the provided key and initialization vector
        using var aes = new AesCbcDecryptor(encryptionKey, initializationVector);

        // Decrypt ciphertext using AES-CBC
        byte[] plaintext;
        try
        {
            plaintext = aes.Decrypt(ciphertext);
        }
        catch (Exception ex)
        {
            // Log error and return empty byte array if decryption fails
            Console.WriteLine($"Error occurred during decryption: {ex.Message}");
            return new byte[0];
        }

        // Validate integrity of the decrypted data using HMAC-SHA256
        var hmac = new HMACSHA256(encryptionKey);
        var integrityTag = hmac.ComputeHash(plaintext);
        if (!integrityTag.SequenceEqual(ciphertext.SkipLast(32)))
        {
            // Log error and return empty byte array if integrity tag is not valid
            Console.WriteLine("Integrity tag is not valid");
            return new byte[0];
        }

        // Remove padding from plaintext
        var unpaddedPlaintext = PaddingUtilities.RemovePadding(plaintext, padding);

        // Return decrypted and integrity-validated plaintext
        return unpaddedPlaintext;
    }
}
```
