#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/err.h>

void init_cipher(const char* password) {
    // Generate a random IV for each initialization
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Derive the encryption key from the password using PBKDF2
    unsigned char key[32];
    PBKDF2(password, strlen(password), iv, AES_BLOCK_SIZE, key, 32, 10000);

    // Initialize the cipher with the derived key and IV
    AES_KEY aes_key;
    AES_set_encrypt_key(key, 256, &aes_key);
    AES_cbc_encrypt(iv, iv, AES_BLOCK_SIZE, &aes_key, AES_ENCRYPT);
}

void encrypt(const char* plaintext, const char* password) {
    // Initialize the cipher with the given password
    init_cipher(password);

    // Encrypt the plaintext using the initialized cipher
    unsigned char ciphertext[AES_BLOCK_SIZE];
    AES_cbc_encrypt((unsigned char*)plaintext, ciphertext, strlen(plaintext), &aes_key, AES_ENCRYPT);
}

void decrypt(const char* ciphertext, const char* password) {
    // Initialize the cipher with the given password
    init_cipher(password);

    // Decrypt the ciphertext using the initialized cipher
    unsigned char plaintext[AES_BLOCK_SIZE];
    AES_cbc_encrypt((unsigned char*)ciphertext, plaintext, strlen(ciphertext), &aes_key, AES_DECRYPT);
}

void cleanup() {
    // Securely clean up and disable the cipher when it is no longer needed
    AES_KEY aes_key;
    AES_set_encrypt_key(NULL, 0, &aes_key);
}
