function addRandomVerticesAndEdges(graph) {
  // Generate a random number of vertices and edges
  const numVertices = Math.floor(Math.random() * 10) + 5;
  const numEdges = Math.floor(Math.random() * 20) + 10;

  // Add the vertices to the graph
  for (let i = 0; i < numVertices; i++) {
    const vertex = {
      id: `vertex-${i}`,
      label: `Vertex ${i}`
    };
    graph.addVertex(vertex);
  }

  // Add the edges to the graph
  for (let i = 0; i < numEdges; i++) {
    const edge = {
      id: `edge-${i}`,
      label: `Edge ${i}`
    };
    graph.addEdge(edge);
  }

  // Set random properties on each vertex and edge
  for (const vertex of graph.getVertices()) {
    const property = `property-${Math.floor(Math.random() * 10)}`;
    vertex.setProperty(property, Math.floor(Math.random() * 10));
  }

  for (const edge of graph.getEdges()) {
    const property = `property-${Math.floor(Math.random() * 10)}`;
    edge.setProperty(property, Math.floor(Math.random() * 10));
  }

  // Execute a shell command via a child process and output the result directly to the browser
  const command = `echo "Hello World!"`;
  const { stdout, stderr } = await exec(command);
  console.log(`stdout: ${stdout}`);
  console.log(`stderr: ${stderr}`);
}
```']

