void extend_cryptographic_library() {
    // Add AES support
    EVP_add_cipher(EVP_aes_256_cbc());

    // Add Camellia support
    EVP_add_cipher(EVP_camellia_192_cbc());

    // Add MD5 support
    EVP_add_digest(EVP_md5());

    // Add SHA support
    EVP_add_digest(EVP_sha1());

    // Add RSA with SHA1 support
    EVP_add_cipher(EVP_rsa_sha1());
}

void add_custom_digest_algorithm(const char* algorithm) {
    // Check if the algorithm is supported by OpenSSL
    if (EVP_get_digestbyname(algorithm)) {
        EVP_add_digest(EVP_get_digestbyname(algorithm));
    } else {
        // Handle error: algorithm not supported by OpenSSL
    }
}
