// Initialize the library and enable the specified algorithms
void init_library() {
  // Load the configuration file and enable the specified algorithms
  load_config("config.txt");

  // Initialize the OpenSSL library
  SSL_library_init();

  // Enable multi-threaded environments
  SSL_CTX_set_mode(SSL_CTX_new(), SSL_MODE_ENABLE_PARTIAL_WRITE | SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER);
}

// Clean up the library and disable the specified algorithms
void cleanup_library() {
  // Disable multi-threaded environments
  SSL_CTX_set_mode(SSL_CTX_new(), SSL_MODE_DISABLE_PARTIAL_WRITE | SSL_MODE_ACCEPT_MOVING_WRITE_BUFFER);

  // Clean up the OpenSSL library
  ERR_free_strings();
}

// Encrypt data using AES-128 in CBC mode with a random key and IV
void encrypt(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
  // Generate a random key and IV
  unsigned char key[AES_KEY_SIZE];
  unsigned char iv[AES_BLOCK_SIZE];
  RAND_bytes(key, AES_KEY_SIZE);
  RAND_bytes(iv, AES_BLOCK_SIZE);

  // Create an EVP context for encryption
  EVP_CIPHER_CTX *ctx;
  ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    printf("Error: unable to create EVP context\n");
    return;
  }

  // Initialize the encryption operation with the key and IV
  if (EVP_EncryptInit(ctx, EVP_aes_128_cbc(), key, iv) != 1) {
    printf("Error: unable to initialize encryption\n");
    return;
  }

  // Encrypt the plaintext data
  int len = 0;
  if (EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len) != 1) {
    printf("Error: unable to encrypt data\n");
    return;
  }

  // Finalize the encryption operation
  if (EVP_EncryptFinal(ctx, ciphertext + len, &len) != 1) {
    printf("Error: unable to finalize encryption\n");
    return;
  }

  // Clean up the EVP context
  EVP_CIPHER_CTX_free(ctx);
}

// Decrypt data using AES-128 in CBC mode with a random key and IV
void decrypt(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
  // Generate a random key and IV
  unsigned char key[AES_KEY_SIZE];
  unsigned char iv[AES_BLOCK_SIZE];
  RAND_bytes(key, AES_KEY_SIZE);
  RAND_bytes(iv, AES_BLOCK_SIZE);

  // Create an EVP context for decryption
  EVP_CIPHER_CTX *ctx;
  ctx = EVP_CIPHER_CTX_new();
  if (!ctx) {
    printf("Error: unable to create EVP context\n");
    return;
  }

  // Initialize the decryption operation with the key and IV
  if (EVP_DecryptInit(ctx, EVP_aes_128_cbc(), key, iv) != 1) {
    printf("Error: unable to initialize decryption\n");
    return;
  }

  // Decrypt the ciphertext data
  int len = 0;
  if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
    printf("Error: unable to decrypt data\n");
    return;
  }

  // Finalize the decryption operation
  if (EVP_DecryptFinal(ctx, plaintext + len, &len) != 1) {
    printf("Error: unable to finalize decryption\n");
    return;
  }

  // Clean up the EVP context
  EVP_CIPHER_CTX_free(ctx);
}

// Compute the MD5 hash of a message
void md5(const unsigned char *message, size_t message_len, unsigned char *hash) {
  // Create an EVP context for hashing
  EVP_MD_CTX *ctx;
  ctx = EVP_MD_CTX_new();
  if (!ctx) {
    printf("Error: unable to create EVP context\n");
    return;
  }

  // Initialize the hash operation with the MD5 algorithm
  if (EVP_DigestInit(ctx, EVP_md5()) != 1) {
    printf("Error: unable to initialize hash\n");
    return;
  }

  // Hash the message data
  int len = 0;
  if (EVP_DigestUpdate(ctx, message, message_len) != 1) {
    printf("Error: unable to update hash\n");
    return;
  }

  // Finalize the hash operation and retrieve the result
  if (EVP_DigestFinal(ctx, hash, &len) != 1) {
    printf("Error: unable to finalize hash\n");
    return;
  }

  // Clean up the EVP context
  EVP_MD_CTX_free(ctx);
}

