// Define the maximum depth limit for the tree structure
#define MAX_DEPTH 10

// Define the data structure to represent a node in the tree
typedef struct Node {
    char *name;
    int num_files;
    int num_subdirs;
    struct Node **children;
} Node;

// Define the function to process the list of file paths and organize them into a hierarchical tree structure
void process_file_paths(char **file_paths, int max_depth, Node *tree, FILE *log_file, PerformanceMetricsCollector *perf_metrics) {
    // Initialize the performance metrics collector
    perf_metrics->init();

    // Iterate over each file path in the list
    for (int i = 0; i < num_file_paths; i++) {
        char *path = file_paths[i];

        // Validate the file path against the maximum depth limit
        if (validate_depth(path, max_depth)) {
            log_message("Skipping file path %s due to depth violation", path);
            continue;
        }

        // Dynamically allocate memory for the tree structure
        Node *node = malloc(sizeof(Node));
        node->name = strdup(path);
        node->num_files = 0;
        node->num_subdirs = 0;
        node->children = NULL;

        // Recursively traverse the directory and populate the tree structure
        traverse_directory(node, path, max_depth - 1);

        // Add the node to the tree
        add_node_to_tree(tree, node);

        // Log the function call and performance metrics
        log_message("Processed file path %s", path);
        perf_metrics->log_performance();
    }

    // Free any allocated memory for the tree structure
    free_tree(tree);
}

// Validate the depth of a file path against the maximum depth limit
bool validate_depth(char *path, int max_depth) {
    char *dir = dirname(path);
    int depth = 0;

    while (strcmp(dir, ".") != 0 && strcmp(dir, "/") != 0) {
        depth++;
        dir = dirname(dir);
    }

    return depth > max_depth;
}

// Recursively traverse a directory and populate the tree structure
void traverse_directory(Node *node, char *path, int max_depth) {
    // Open the directory
    DIR *dir = opendir(path);
    if (dir == NULL) {
        log_message("Error opening directory %s: %s", path, strerror(errno));
        return;
    }

    // Iterate over each entry in the directory
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *name = entry->d_name;

        // Skip hidden files and directories
        if (strncmp(name, ".", 1) == 0) {
            continue;
        }

        // Create a new node for the file or directory
        Node *child = malloc(sizeof(Node));
        child->name = strdup(name);
        child->num_files = 0;
        child->num_subdirs = 0;
        child->children = NULL;

        // Add the node to the parent directory
        add_node_to_tree(node, child);

        // Recursively traverse subdirectories
        if (entry->d_type == DT_DIR) {
            char *subdir = malloc(strlen(path) + strlen(name) + 2);
            sprintf(subdir, "%s/%s", path, name);
            traverse_directory(child, subdir, max_depth - 1);
        }
    }

    // Close the directory
    closedir(dir);
}

// Add a node to the tree structure
void add_node_to_tree(Node *tree, Node *node) {
    if (tree->children == NULL) {
        tree->children = malloc(sizeof(Node));
        tree->num_subdirs++;
    } else {
        // Add a new node to the children list
        tree->children = realloc(tree->children, sizeof(Node) * (tree->num_subdirs + 1));
        tree->num_subdirs++;
    }

    tree->children[tree->num_subdirs - 1] = node;
}

// Free any allocated memory for the tree structure
void free_tree(Node *tree) {
    if (tree == NULL) {
        return;
    }

    // Recursively free the children nodes
    for (int i = 0; i < tree->num_subdirs; i++) {
        Node *child = tree->children[i];
        free_tree(child);
    }

    // Free the node itself
    free(tree);
}
