    struct Node* parent; // Pointer to the parent node
    struct Node* children; // Pointer to the first child node
};

// Define a function to validate a file path and return its depth limit
int validate_path(char* path) {
    int depth = 0;
    char* token = strtok(path, "/");
    while (token != NULL) {
        if (strcmp(token, ".") == 0 || strcmp(token, "..") == 0) {
            // Skip the current directory and parent directory tokens
            token = strtok(NULL, "/");
            continue;
        }
        depth++;
        token = strtok(NULL, "/");
    }
    return depth;
}

// Define a function to create a node for a file or directory
struct Node* create_node(char* path) {
    struct stat sb;
    if (stat(path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        // Create a node for the directory
        struct Node* node = malloc(sizeof(struct Node));
        node->path = path;
        node->depth = validate_path(path);
        node->parent = NULL;
        node->children = NULL;
        return node;
    } else {
        // Create a node for the file
        struct Node* node = malloc(sizeof(struct Node));
        node->path = path;
        node->depth = validate_path(path);
        node->parent = NULL;
        node->children = NULL;
        return node;
    }
}

// Define a function to recursively traverse a directory and create nodes for files and directories
void traverse_directory(struct Node* root, char* path) {
    struct stat sb;
    if (stat(path, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        // Traverse the directory
        DIR* dir = opendir(path);
        while ((struct dirent* entry = readdir(dir)) != NULL) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
                // Skip the current directory and parent directory entries
                continue;
            }
            char* child_path = malloc(sizeof(char) * (strlen(path) + strlen(entry->d_name) + 2));
            sprintf(child_path, "%s/%s", path, entry->d_name);
            struct Node* child = create_node(child_path);
            if (root->children == NULL) {
                root->children = child;
            } else {
                struct Node* current = root->children;
                while (current->next != NULL) {
                    current = current->next;
                }
                current->next = child;
            }
            traverse_directory(child, child_path);
        }
        closedir(dir);
    } else {
        // Create a node for the file
        struct Node* node = create_node(path);
        if (root->children == NULL) {
            root->children = node;
        } else {
            struct Node* current = root->children;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }
}

