// Define the function to validate a JSON object containing OAuth2 access tokens
bool validate_json(const json_t *json) {
    // Check if the JSON object is null or empty
    if (!json || json_object_size(json) == 0) {
        return false;
    }

    // Get the token type and expiration time from the JSON object
    const char *token_type = json_string_value(json_object_get(json, "token_type"));
    int expires_in = json_integer_value(json_object_get(json, "expires_in"));

    // Check if the token type is 'Bearer' and the expiration time is positive
    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        return false;
    }

    // Get the refresh token from the JSON object (if present)
    const char *refresh_token = json_string_value(json_object_get(json, "refresh_token"));

    // Check if the refresh token is valid (if present)
    if (refresh_token && strlen(refresh_token) == 0) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

// Define the function to setup a cipher object based on the given command line option
struct CipherObject *setup_cipher(const char *command_line_option) {
    // Initialize the cipher object with default properties
    struct CipherObject *cipher = malloc(sizeof(struct CipherObject));
    cipher->ctx = EVP_CIPHER_CTX_new();
    cipher->key_len = 0;
    cipher->iv_len = 0;

    // Check if the command line option is valid
    if (!command_line_option || strlen(command_line_option) == 0) {
        return false;
    }

    // Get the cipher mode from the command line option
    enum CipherMode mode = ECB;
    if (strcmp(command_line_option, "ECB") == 0) {
        mode = ECB;
    } else if (strcmp(command_line_option, "EDE") == 0) {
        mode = EDE;
    } else if (strcmp(command_line_option, "EDE3") == 0) {
        mode = EDE3;
    } else if (strcmp(command_line_option, "CFB") == 0) {
        mode = CFB;
    } else {
        return false;
    }

    // Setup the cipher object based on the cipher mode
    switch (mode) {
        case ECB:
            EVP_EncryptInit(cipher->ctx, EVP_des_ecb(), NULL, NULL);
            break;
        case EDE:
            EVP_EncryptInit(cipher->ctx, EVP_des_ede(), NULL, NULL);
            break;
        case EDE3:
            EVP_EncryptInit(cipher->ctx, EVP_des_ede3(), NULL, NULL);
            break;
        case CFB:
            EVP_EncryptInit(cipher->ctx, EVP_des_cfb(), NULL, NULL);
            break;
    }

    // Return the cipher object if setup is successful
    return cipher;
}

// Define the function to encrypt a string using the given cipher object
bool encrypt(const char *plaintext, const struct CipherObject *cipher) {
    // Check if the plaintext and cipher object are valid
    if (!plaintext || !cipher) {
        return false;
    }

    // Setup the encryption parameters based on the cipher mode
    int key_len = 0;
    int iv_len = 0;
    switch (cipher->mode) {
        case ECB:
            key_len = EVP_CIPHER_CTX_key_length(cipher->ctx);
            iv_len = EVP_CIPHER_CTX_iv_length(cipher->ctx);
            break;
        case EDE:
            key_len = EVP_CIPHER_CTX_key_length(cipher->ctx) / 2;
            iv_len = EVP_CIPHER_CTX_iv_length(cipher->ctx) / 2;
            break;
        case EDE3:
            key_len = EVP_CIPHER_CTX_key_length(cipher->ctx) / 3;
            iv_len = EVP_CIPHER_CTX_iv_length(cipher->ctx) / 3;
            break;
        case CFB:
            key_len = EVP_CIPHER_CTX_key_length(cipher->ctx);
            iv_len = EVP_CIPHER_CTX_iv_length(cipher->ctx);
            break;
    }

    // Allocate memory for the encryption parameters
    unsigned char *key = malloc(key_len);
    unsigned char *iv = malloc(iv_len);

    // Setup the encryption parameters based on the cipher mode
    switch (cipher->mode) {
