            break;
        case CFB:
            EVP_EncryptInit(cipher->ctx, NULL, key, iv);
            break;
    }

    // Encrypt the plaintext using the cipher object
    int len = strlen(plaintext);
    unsigned char *encrypted = malloc(len + 1);
    EVP_EncryptUpdate(cipher->ctx, encrypted, &len, (unsigned char *)plaintext, len);

    // Free the encryption parameters memory
    free(key);
    free(iv);

    // Return the encrypted string
    return true;
}

// Define the function to decrypt a string using the given cipher object
bool decrypt(const char *ciphertext, const struct CipherObject *cipher) {
    // Check if the ciphertext and cipher object are valid
    if (!ciphertext || !cipher) {
        return false;
    }

    // Setup the decryption parameters based on the cipher mode
