            EVP_DecryptInit(cipher->ctx, NULL, key, iv);
            break;
        case CFB:
            EVP_DecryptInit(cipher->ctx, NULL, key, iv);
            break;
    }

    // Decrypt the ciphertext using the cipher object
    int len = strlen(ciphertext);
    unsigned char *decrypted = malloc(len + 1);
    EVP_DecryptUpdate(cipher->ctx, decrypted, &len, (unsigned char *)ciphertext, len);

    // Free the decryption parameters memory
    free(key);
    free(iv);

    // Return the decrypted string
    return true;
}

