typedef struct record {
    int key;
    int value;
    void* data_block;
} record;

typedef struct state {
    int index;
    record* records;
    struct state* next;
} state;

state* constructFSAModifiedRecords(const char* filename, FSA* fsa) {
    // Validate input pointers and ensure sufficient memory is available for the new state list
    if (filename == NULL || fsa == NULL) {
        return NULL;
    }

    // Allocate memory for the new state list using malloc
    state* head = malloc(sizeof(state));
    if (head == NULL) {
        return NULL;
    }

    // Initialize each state pointer to point to the next state in the sequence
    state* current = head;
    for (int i = 0; i < fsa->num_states; i++) {
        current->index = i;
        current->records = malloc(sizeof(record) * fsa->num_records);
        if (current->records == NULL) {
            return NULL;
        }
        for (int j = 0; j < fsa->num_records; j++) {
            current->records[j].key = rand() % fsa->max_value + 1;
            current->records[j].value = rand() % fsa->max_value + 1;
            current->records[j].data_block = NULL;
        }
        current->next = malloc(sizeof(state));
        if (current->next == NULL) {
            return NULL;
        }
        current = current->next;
    }

    // Handle edge cases where the FSA might have no transitions or invalid state indices
    if (fsa->num_transitions == 0 || fsa->start_state < 0 || fsa->start_state >= fsa->num_states) {
        return NULL;
    }

    // Adjust the direction of transitions accordingly if the state list is marked as reversible
    if (fsa->reversible) {
        current = head;
        while (current != NULL) {
            for (int i = 0; i < fsa->num_transitions; i++) {
                if (current->index == fsa->transitions[i].from && fsa->transitions[i].to >= 0 && fsa->transitions[i].to < fsa->num_states) {
                    current->next = &fsa->states[fsa->transitions[i].to];
                }
            }
            current = current->next;
        }
    }

    // Modify the filename's extension using sprintf and strcat
    char* new_filename = malloc(strlen(filename) + 10);
    if (new_filename == NULL) {
        return NULL;
    }
    sprintf(new_filename, "%s.%d", filename, fsa->num_states);
    strcat(new_filename, ".modified");

    // Return the head of the new state list or NULL if memory allocation fails
    return head;
}
