#include <openssl/err.h>

void init_cryptographic_library() {
    // Add AES, Camellia, MD5, SHA, and RSA with SHA1 to the EVP library
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_192_cbc());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());
    EVP_add_digest(EVP_rsa_sha1());

    // Add aliases for the digests
    EVP_add_digest_alias("MD5", "md5");
    EVP_add_digest_alias("SHA-1", "sha1");
    EVP_add_digest_alias("RSA-SHA1", "rsa_sha1");

    // Initialize the OpenSSL library
    OPENSSL_init_crypto(OPENSSL_INIT_ADD_ALL_CIPHERS | OPENSSL_INIT_ADD_ALL_DIGESTS, NULL);
}

void deinit_cryptographic_library() {
    // Deinitialize the OpenSSL library
    OPENSSL_cleanup();
}

void* load_custom_digest(const char* name) {
    // Validate the custom digest algorithm name
    if (!name || strlen(name) == 0) {
        return NULL;
    }

    // Load the custom digest algorithm from a file or other source
    FILE* fp = fopen(name, "r");
    if (!fp) {
        return NULL;
    }

    // Read the custom digest algorithm from the file
    char buffer[1024];
    size_t len = fread(buffer, 1, sizeof(buffer), fp);
    if (len == 0) {
        fclose(fp);
        return NULL;
    }

    // Create a new EVP_MD object for the custom digest algorithm
    EVP_MD* md = EVP_MD_fetch(NULL, name, NULL);
    if (!md) {
        fclose(fp);
        return NULL;
    }

    // Set the custom digest algorithm on the EVP_MD object
    int ret = EVP_DigestInit_ex(md, buffer, len);
    if (ret != 1) {
        EVP_MD_free(md);
        fclose(fp);
        return NULL;
    }

    // Return the custom digest algorithm object
    return md;
}

void* create_cryptographic_key(const char* name, int key_size) {
    // Validate the key size
    if (key_size <= 0) {
        return NULL;
    }

    // Create a new EVP_CIPHER object for the specified cipher
    EVP_CIPHER* cipher = EVP_get_cipherbyname(name);
    if (!cipher) {
        return NULL;
    }

    // Generate a random key of the specified size
    unsigned char* key = OPENSSL_malloc(key_size);
    RAND_bytes(key, key_size);

    // Create a new EVP_CIPHER_CTX object for the cipher
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        OPENSSL_free(key);
        return NULL;
    }

    // Initialize the cipher context with the key and other parameters
    int ret = EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(key);
        return NULL;
    }

    // Return the cryptographic key object
    return ctx;
}

void* create_cryptographic_operation(const char* name, int key_size) {
    // Validate the operation name and key size
    if (!name || strlen(name) == 0 || key_size <= 0) {
        return NULL;
    }

    // Create a new EVP_CIPHER object for the specified cipher
    EVP_CIPHER* cipher = EVP_get_cipherbyname(name);
    if (!cipher) {
        return NULL;
    }

    // Generate a random key of the specified size
    unsigned char* key = OPENSSL_malloc(key_size);
    RAND_bytes(key, key_size);

    // Create a new EVP_CIPHER_CTX object for the cipher
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        OPENSSL_free(key);
        return NULL;
    }

    // Initialize the cipher context with the key and other parameters
    int ret = EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(key);
        return NULL;
    }

    // Return the cryptographic operation object
    return ctx;
}

void* create_cryptographic_digest(const char* name) {
    // Validate the digest algorithm name
    if (!name || strlen(name) == 0) {
        return NULL;
    }

    // Create a new EVP_MD object for the specified digest algorithm
    EVP_MD* md = EVP_get_digestbyname(name);
    if (!md) {
        return NULL;
    }

    // Initialize the digest context with the digest algorithm
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        return NULL;
    }

    // Return the cryptographic digest object
    return ctx;
}

void destroy_cryptographic_object(void* obj) {
    // Validate the object pointer
    if (!obj) {
        return;
    }

    // Free the memory allocated for the object
    EVP_CIPHER_CTX_free((EVP_CIPHER_CTX*)obj);
}

void* cryptographic_operation(const char* name, void* key, const unsigned char* data, size_t len) {
    // Validate the operation name and key pointer
    if (!name || !key || !data || len == 0) {
        return NULL;
    }

    // Create a new EVP_CIPHER object for the specified cipher
    EVP_CIPHER* cipher = EVP_get_cipherbyname(name);
    if (!cipher) {
        return NULL;
    }

    // Initialize the cipher context with the key and other parameters
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;
    }

    int ret = EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Process the input data in chunks
    size_t chunk_size = 4096;
    unsigned char* out = OPENSSL_malloc(chunk_size);
    int out_len = 0;
    while (len > 0) {
        int ret = EVP_EncryptUpdate(ctx, out + out_len, &chunk_size, data, len);
        if (ret != 1) {
            EVP_CIPHER_CTX_free(ctx);
            OPENSSL_free(out);
            return NULL;
        }
        len -= chunk_size;
        out_len += chunk_size;
    }

    // Finalize the encryption operation
    int ret = EVP_EncryptFinal_ex(ctx, out + out_len, &chunk_size);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        OPENSSL_free(out);
        return NULL;
    }

    // Return the encrypted data
    return out;
}

void* cryptographic_digest(const char* name, const unsigned char* data, size_t len) {
    // Validate the digest algorithm name and input data pointer
    if (!name || !data || len == 0) {
        return NULL;
    }

    // Create a new EVP_MD object for the specified digest algorithm
    EVP_MD* md = EVP_get_digestbyname(name);
    if (!md) {
        return NULL;
    }

    // Initialize the digest context with the digest algorithm
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        return NULL;
    }

    int ret = EVP_DigestInit_ex(ctx, md, NULL);
    if (ret != 1) {
        EVP_MD_CTX_free(ctx);
        return NULL;
    }

    // Process the input data in chunks
    size_t chunk_size = 4096;
    unsigned char* out = OPENSSL_malloc(chunk_size);
    int out_len = 0;
    while (len > 0) {
        ret = EVP_DigestUpdate(ctx, data, len);
        if (ret != 1) {
            EVP_MD_CTX_free(ctx);
            OPENSSL_free(out);
            return NULL;
        }
        len -= chunk_size;
        out_len += chunk_size;
    }

    // Finalize the digest operation
    ret = EVP_DigestFinal_ex(ctx, out + out_len, &chunk_size);
    if (ret != 1) {
        EVP_MD_CTX_free(ctx);
        OPENSSL_free(out);
        return NULL;
    }

    // Return the digest result
    return out;
