#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <pthread.h>

// Define the data structure for a record
typedef struct {
    int key;
    int value;
    void* data_block;
} Record;

// Define the data structure for a node in the hierarchical tree
typedef struct Node {
    char* name;
    int depth;
    int size;
    struct Node* parent;
    struct Node** children;
} Node;

// Function to read a directory hierarchy and process a list of file paths, sorting the lines of each file and extracting a sequence number from the last line
void process_directory(char* path) {
    // Validate the input path
    if (path == NULL || strlen(path) == 0) {
        printf("Invalid path\n");
        return;
    }

    // Initialize a hierarchical tree structure to efficiently represent directories and files
    Node* root = malloc(sizeof(Node));
    root->name = path;
    root->depth = 0;
    root->size = 0;
    root->parent = NULL;
    root->children = NULL;

    // Traverse the directory hierarchy and process each file
    DIR* dir = opendir(path);
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char* filename = entry->d_name;
        if (filename[0] == '.') continue; // Skip hidden files

        // Validate the file name against the naming convention and maximum depth limit
        int depth = 0;
        while (depth < MAX_DEPTH && strlen(filename) > 0) {
            if (filename[strlen(filename) - 1] == '/') break;
            filename = dirname(filename);
            depth++;
        }
        if (depth >= MAX_DEPTH) continue; // Skip files that exceed the maximum depth limit

        // Read the file and extract a sequence number from the last line
        FILE* file = fopen(filename, "r");
        char* line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, file)) != -1) {
            // Sort the lines of each file and extract a sequence number from the last line
            qsort(line, read, sizeof(char), compare);
            char* seq_num = strrchr(line, ':');
            if (seq_num == NULL) continue; // Skip files without a valid sequence number
            int num = atoi(seq_num + 1);
            printf("File %s has sequence number %d\n", filename, num);
        }
        fclose(file);
    }
    closedir(dir);
}

// Function to modify and initialize records
void modifyAndInitializeRecords(char* filename) {
    // Validate the input filename
    if (filename == NULL || strlen(filename) == 0) {
        printf("Invalid filename\n");
        return;
    }

    // Dynamically allocate memory for and initialize three separate arrays: one for 'long' offset values, one for 'int' keys, and another for 'record' structures
    long* offsets = malloc(sizeof(long) * 10);
    int* keys = malloc(sizeof(int) * 10);
    Record* records = malloc(sizeof(Record) * 10);
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Fill the 'value' field of each record with a random integer within a specified range, ensuring that no two records have the same key value
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        offsets[i] = rand() % 100 + 1;
        keys[i] = rand() % 100 + 1;
        records[i].key = keys[i];
        records[i].value = rand() % 100 + 1;
    }

    // Optimize the random number generation to ensure a uniform distribution across all possible values
    for (int i = 0; i < 10; i++) {
        int j = i + 1;
        while (j < 10) {
            if (records[i].key == records[j].key) {
                records[j].key = rand() % 100 + 1;
            }
            j++;
        }
    }

    // Handle memory allocation failures gracefully, providing detailed error codes to indicate the nature of the failure
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Only return the initialized 'record' structures, and do not free any allocated memory in the function
    return records;
}
