public static MoSTState loadAndEncryptToken(String filePath, String jsonString) {
    // Validate the JSON string
    JSONObject json = new JSONObject(jsonString);
    if (!json.has("access_token") || !json.has("expires_in") || !json.has("token_type")) {
        return null;
    }

    String accessToken = json.getString("access_token");
    int expiresIn = json.getInt("expires_in");
    String tokenType = json.getString("token_type");

    if (!tokenType.equals("Bearer")) {
        return null;
    }

    if (expiresIn <= 0) {
        return null;
    }

    // Load the state object from the file
    MoSTState state = null;
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
        state = (MoSTState) ois.readObject();
    } catch (IOException | ClassNotFoundException e) {
        // Handle exception gracefully
    }

    if (!(state instanceof MoSTState)) {
        return null;
    }

    // Encrypt the access token using DES algorithm with ECB mode
    try {
        Cipher cipher = Cipher.getInstance("DES/ECB/NoPadding");
        SecretKeySpec key = new SecretKeySpec(accessToken.getBytes(), "DES");
        IvParameterSpec iv = new IvParameterSpec(new byte[8]);
        cipher.init(Cipher.ENCRYPT_MODE, key, iv);
        byte[] encryptedToken = cipher.doFinal(accessToken.getBytes());
        state.setEncryptedAccessToken(encryptedToken);
    } catch (GeneralSecurityException e) {
        // Handle exception gracefully
    }

    return state;
}
