struct Configuration {
    int num_settings;
    int max_settings;
    struct Setting *settings;
};

struct Setting {
    // ...
};

struct Configuration* add_setting(struct Configuration *config, int current_num_settings, int max_allowed_settings) {
    if (current_num_settings >= max_allowed_settings) {
        // resize internal storage
        config->max_settings = max_allowed_settings;
        config->settings = realloc(config->settings, sizeof(struct Setting) * max_allowed_settings);
        if (!config->settings) {
            return NULL;
        }
    }

    // add new setting to list
    struct Setting *new_setting = malloc(sizeof(struct Setting));
    config->settings[current_num_settings] = new_setting;
    config->num_settings++;

    // update references if necessary
    for (int i = 0; i < current_num_settings; i++) {
        struct Setting *setting = config->settings[i];
        if (setting->next == NULL) {
            setting->next = new_setting;
        }
    }

    return config;
}
