#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>

struct Node {
    double data;
    Node* next;
    Node* prev;
};

enum Status {
    SUCCESS,
    FAILURE
};

std::vector<double> allocateDoubleVector(size_t size) {
    std::vector<double> vec(size);
    return vec;
}

std::vector<std::string> allocateStringVector(size_t size, size_t maxLength) {
    std::vector<std::string> vec(size);
    for (auto& str : vec) {
        str.reserve(maxLength);
    }
    return vec;
}

std::vector<Node*> allocateNodeVector(size_t size) {
    std::vector<Node*> vec(size);
    for (auto& node : vec) {
        node = new Node();
    }
    return vec;
}

std::vector<Status> allocateStatusVector(size_t size) {
    std::vector<Status> vec(size);
    return vec;
}

std::vector<int*> allocateIntVector(size_t size) {
    std::vector<int*> vec(size);
    for (auto& i : vec) {
        i = new int();
    }
    return vec;
}

void fillDoubleVector(std::vector<double>& vec, double min, double max) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dist(min, max);
    for (auto& d : vec) {
        d = dist(gen);
    }
}

void fillStringVector(std::vector<std::string>& vec, const std::string& str) {
    for (auto& s : vec) {
        s = str;
    }
}

void fillNodeVector(std::vector<Node*>& vec, double min, double max) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<double> dist(min, max);
    for (auto& node : vec) {
        node->data = dist(gen);
    }
}

void fillStatusVector(std::vector<Status>& vec, Status status) {
    for (auto& s : vec) {
        s = status;
    }
}

void fillIntVector(std::vector<int*>& vec, int min, int max) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dist(min, max);
    for (auto& i : vec) {
        *i = dist(gen);
    }
}

void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    if (str1.empty() || str2.empty()) {
        return;
    }
    auto it = std::find(list.begin(), list.end(), str1);
    if (it != list.end()) {
        ++it;
        list.insert_after(it, str2);
    } else {
        list.push_front(str2);
    }
}

void initializeVectors(std::vector<double>& doubleVec, std::vector<std::string>& stringVec, std::vector<Node*>& nodeVec, std::vector<Status>& statusVec, std::vector<int*>& intVec) {
    fillDoubleVector(doubleVec, 0.0, 1.0);
    fillStringVector(stringVec, "");
    fillNodeVector(nodeVec, 0.0, 1.0);
    fillStatusVector(statusVec, SUCCESS);
    fillIntVector(intVec, 0, 10);
}

void insertStringAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    if (str1.empty() || str2.empty()) {
        return;
    }
    auto it = std::find(list.begin(), list.end(), str1);
    if (it != list.end()) {
        ++it;
        list.insert_after(it, str2);
    } else {
        list.push_front(str2);
    }
}

int main() {
    std::vector<double> doubleVec = allocateDoubleVector(5);
    std::vector<std::string> stringVec = allocateStringVector(5, 256);
    std::vector<Node*> nodeVec = allocateNodeVector(5);
    std::vector<Status> statusVec = allocateStatusVector(5);
    std::vector<int*> intVec = allocateIntVector(5);
    initializeVectors(doubleVec, stringVec, nodeVec, statusVec, intVec);
    return 0;
}
```
