// Define record structure
typedef struct {
    int value;
} record;

int init_data(long *offset_arr, int *key_arr, record **records, size_t max_records, int seed) {
    // Allocate memory for offset and key arrays
    offset_arr = (long *)malloc(max_records * sizeof(long));
    if (!offset_arr) {
        return -1;
    }
    key_arr = (int *)malloc(max_records * sizeof(int));
    if (!key_arr) {
        free(offset_arr);
        return -2;
    }

    // Initialize offset and key arrays with random values
    srand(seed);
    for (size_t i = 0; i < max_records; i++) {
        offset_arr[i] = rand() % 1000;
        key_arr[i] = rand() % 1000;
    }

    // Allocate memory for record array
    records = (record **)malloc(max_records * sizeof(record));
    if (!records) {
        free(offset_arr);
        free(key_arr);
        return -3;
    }

    // Initialize record array with random values
    for (size_t i = 0; i < max_records; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            free(offset_arr);
            free(key_arr);
            free(records);
            return -4;
        }
        records[i]->value = rand() % 1000;
    }

    // Log successful memory allocation and initialization
    printf("Memory allocated and initialized successfully\n");

    // Return success
    return 0;
}
