                state.setRefreshToken(refreshToken);
            }

            // Integrate with external authentication service
            // TODO: integrate with external authentication service

            return new Tuple<>(true, state);
        } catch (IOException | JSONException e) {
            return new Tuple<>(false, null);
        }
    }
}
