#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <json-c/json.h>

// Log levels
#define DEBUG 0
#define INFO 1
#define WARNING 2
#define ERROR 3
#define CRITICAL 4

// Custom logging format
#define LOG_FORMAT "%s [%d] %s (%s:%d) - %s"

// Logging configuration file path
#define CONFIG_FILE_PATH "logging.json"

// Thread-safe queue for storing log messages
struct thread_safe_queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int head, tail;
    char** data;
};

// Initialize a thread-safe queue with the given capacity
void init_queue(struct thread_safe_queue* q, int capacity) {
    q->head = 0;
    q->tail = 0;
    q->data = (char**)malloc(capacity * sizeof(char*));
}

// Enqueue a log message in the queue
void enqueue(struct thread_safe_queue* q, char* msg) {
    pthread_mutex_lock(&q->mutex);
    while ((q->tail + 1) % capacity == q->head) {
        // Wait for space to become available in the queue
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    q->data[q->tail] = msg;
    q->tail = (q->tail + 1) % capacity;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
}

// Dequeue a log message from the queue
char* dequeue(struct thread_safe_queue* q) {
    char* msg = NULL;
    pthread_mutex_lock(&q->mutex);
    while (q->head == q->tail) {
        // Wait for a message to become available in the queue
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    msg = q->data[q->head];
    q->head = (q->head + 1) % capacity;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
    return msg;
}

// Log a message with the given level and context
void log(int level, char* ctx, char* fmt, ...) {
    // Check if the message should be logged based on its level
    if (level < min_log_level) {
        return;
    }

    // Format the message using the custom logging format
    va_list args;
    va_start(args, fmt);
    char* msg = vsprintf(LOG_FORMAT, args);
    va_end(args);

    // Enqueue the log message in the thread-safe queue
    enqueue(&log_queue, msg);
}

// Flush the logs to a remote server when network conditions permit
void flush_logs() {
    // Check if there are any pending logs
    if (log_queue.head == log_queue.tail) {
        return;
    }

    // Connect to the remote server and send the logs
    // ...
}

// Main function for the logging system
int main() {
    // Initialize the thread-safe queue with a capacity of 1024
    init_queue(&log_queue, 1024);

    // Load the logging configuration from the JSON file
    json_object* config = json_object_from_file(CONFIG_FILE_PATH);
    if (config == NULL) {
        printf("Error loading logging configuration\n");
        return 1;
    }

    // Parse the logging configuration and set the minimum log level
    min_log_level = json_object_get_int(json_object_object_get(config, "min_log_level"));

    // Start a thread to flush logs to a remote server when network conditions permit
    pthread_t flush_thread;
    pthread_create(&flush_thread, NULL, &flush_logs, NULL);

    // Initialize the logging system with the custom logging format and minimum log level
    log(DEBUG, "main", "Logging system initialized");

    // Start the main loop to process log messages
    while (1) {
        char* msg = dequeue(&log_queue);
        if (msg == NULL) {
            break;
        }
        printf("%s\n", msg);
    }

    // Clean up the thread-safe queue and flush logs before exiting
    pthread_join(flush_thread, NULL);
    free(log_queue.data);
    return 0;
}
```
This code implements a flexible and extensible logging system in C that supports multiple log levels (DEBUG, INFO, WARNING, ERROR, CRITICAL) and allows for dynamic configuration via a JSON-based configuration file. The logging system uses a thread-safe queue to store log messages and provides mechanisms for filtering log messages based on severity levels and flushing logs to a remote server when network conditions permit.

The `log` function is the main entry point for logging messages, which takes the level of the message (DEBUG, INFO, WARNING, ERROR, CRITICAL), a context string that provides additional information about the message, and a format string that specifies how to format the message. The function checks if the message should be logged based on its level and formats the message using the custom logging format. If the message should be logged, it is enqueued in the thread-safe queue for processing.

The `flush_logs` function is a separate thread that runs in the background to flush logs to a remote server when network conditions permit. The function checks if there are any pending logs and connects to the remote server using the configuration file. If the connection is successful, it sends the logs to the remote server and disconnects.

The `main` function initializes the thread-safe queue with a capacity of 1024, loads the logging configuration from the JSON file, sets the minimum log level based on the configuration, starts a separate thread for flushing logs, and initializes the logging system with the custom logging format and minimum log level. The main loop processes log messages by dequeuing them from the queue and printing them to the console. Before exiting, the function joins the flush thread and frees the memory allocated for the thread-safe queue.']

