// Define the function for initializing the metrics system
void initMetrics() {
    // Load the configuration file and parse it into a YAML node
    YAML::Node config = YAML::LoadFile("metrics.yaml");

    // Initialize the metric memory structure
    struct MetricMemory* memory = malloc(sizeof(struct MetricMemory));
    memory->data = NULL;
    memory->capacity = 0;
    memory->count = 0;

    // Iterate over the metrics in the configuration file and create a new metric data structure for each one
    for (YAML::Node metric : config["metrics"]) {
        struct MetricData* data = malloc(sizeof(struct MetricData));
