        data->value = 0;
        data->identifier = strdup(metric["identifier"].as<char*>());
        data->context = strdup(metric["context"].as<char*>());
        data->timestamp = time(NULL);

        // Add the new metric data structure to the memory structure
        if (memory->capacity == 0) {
            memory->data = malloc(sizeof(struct MetricData));
            memory->capacity = 1;
        } else {
            memory->data = realloc(memory->data, sizeof(struct MetricData) * (memory->count + 1));
            memory->capacity++;
        }
        memory->data[memory->count++] = data;
