    for (size_t i = 0; i < memory->count; i++) {
        if (strcmp(memory->data[i]->identifier, identifier) == 0 && strcmp(memory->data[i]->tags[tag], value) == 0) {
            data = memory->data[i];
            break;
        }
    }

    // Update the metric value and timestamp
