#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/chacha20.h>
#include <openssl/poly1305.h>
#include <stdbool.h>
#include <string.h>

// Define a structure to hold the cryptographic algorithms and their corresponding contexts
typedef struct {
  EVP_CIPHER_CTX *aes;
  EVP_MD_CTX *md5;
  EVP_MD_CTX *sha1;
  EVP_MD_CTX *sha256;
  EVP_MD_CTX *rsa;
  EVP_CIPHER_CTX *chacha20;
  EVP_CIPHER_CTX *poly1305;
} cryptographic_algorithms_t;

// Define a function to initialize the cryptographic algorithms and their contexts
void init_cryptographic_algorithms(cryptographic_algorithms_t *algorithms) {
  // Initialize AES context
  EVP_CIPHER_CTX_init(&algorithms->aes);
  EVP_EncryptInit_ex(&algorithms->aes, EVP_aes_256_cbc(), NULL, NULL, NULL);

  // Initialize MD5 context
  EVP_MD_CTX_init(&algorithms->md5);
  EVP_DigestInit_ex(&algorithms->md5, EVP_md5(), NULL);

  // Initialize SHA1 context
  EVP_MD_CTX_init(&algorithms->sha1);
  EVP_DigestInit_ex(&algorithms->sha1, EVP_sha1(), NULL);

  // Initialize SHA256 context
  EVP_MD_CTX_init(&algorithms->sha256);
  EVP_DigestInit_ex(&algorithms->sha256, EVP_sha256(), NULL);

  // Initialize RSA context
  EVP_PKEY_CTX *pkey_ctx = EVP_PKEY_CTX_new(EVP_PKEY_RSA, NULL);
  EVP_PKEY_keygen_init(pkey_ctx);
  EVP_PKEY_keygen(pkey_ctx, &algorithms->rsa);
  EVP_PKEY_CTX_free(pkey_ctx);

