// Function to verify an OAuth2 access token response
bool verify_oauth2_token(const char* json) {
  // Parse the JSON object and extract the required fields
  cJSON* root = cJSON_Parse(json);
  if (!root) {
    return false;
  }

  const char* access_token = cJSON_GetObjectItemCaseSensitive(root, "access_token")->valuestring;
  int expires_in = cJSON_GetObjectItemCaseSensitive(root, "expires_in")->valueint;
  const char* token_type = cJSON_GetObjectItemCaseSensitive(root, "token_type")->valuestring;
  const char* refresh_token = cJSON_GetObjectItemCaseSensitive(root, "refresh_token") ? cJSON_GetObjectItemCaseSensitive(root, "refresh_token")->valuestring : NULL;

  // Check that the token type is 'Bearer' and that the expires in field is a positive integer
  if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
    cJSON_Delete(root);
    return false;
  }

  // Check that the access token is not empty and has the correct length
  if (access_token == NULL || strlen(access_token) != 256) {
    cJSON_Delete(root);
    return false;
  }

  // Check that the refresh token is not empty and has the correct length
  if (refresh_token != NULL && strlen(refresh_token) != 256) {
    cJSON_Delete(root);
    return false;
  }

  // Delete the JSON object and return true if all checks passed
  cJSON_Delete(root);
  return true;
}
