<?php
// User management system
class User {
  private $username;
  private $password;
  private $salt;
  private $hash;

  public function __construct($username, $password) {
    $this->username = $username;
    $this->password = $password;
    $this->salt = bin2hex(openssl_random_pseudo_bytes(16));
    $this->hash = password_hash($this->password . $this->salt, PASSWORD_BCRYPT);
  }

  public function getUsername() {
    return $this->username;
  }

  public function getPassword() {
    return $this->password;
  }

  public function getSalt() {
    return $this->salt;
  }

  public function getHash() {
    return $this->hash;
  }
}

// Database connection and query functions
function connectToDatabase($host, $username, $password) {
  // Connect to the database using mysqli_connect
  $conn = mysqli_connect($host, $username, $password);
  if (!$conn) {
    die("Connection failed: " . mysqli_connect_error());
  }
  return $conn;
}

function queryDatabase($conn, $query) {
  // Execute the query using mysqli_query
  $result = mysqli_query($conn, $query);
  if (!$result) {
    die("Query failed: " . mysqli_error($conn));
  }
  return $result;
}

function closeDatabaseConnection($conn) {
  // Close the database connection using mysqli_close
  mysqli_close($conn);
}

// User management functions
function createUser($username, $password) {
  // Create a new user object and save it to the database
  $user = new User($username, $password);
  $query = "INSERT INTO users (username, password, salt) VALUES ('" . $user->getUsername() . "', '" . $user->getHash() . "', '" . $user->getSalt() . "')";
  $conn = connectToDatabase("localhost", "root", "");
  queryDatabase($conn, $query);
  closeDatabaseConnection($conn);
}

function updateUser($username, $password) {
  // Update the user's password and salt in the database
  $user = new User($username, $password);
  $query = "UPDATE users SET password='" . $user->getHash() . "', salt='" . $user->getSalt() . "' WHERE username='" . $user->getUsername() . "'";
  $conn = connectToDatabase("localhost", "root", "");
  queryDatabase($conn, $query);
  closeDatabaseConnection($conn);
}

function deleteUser($username) {
  // Delete the user from the database
  $query = "DELETE FROM users WHERE username='" . $username . "'";
  $conn = connectToDatabase("localhost", "root", "");
  queryDatabase($conn, $query);
  closeDatabaseConnection($conn);
}

function getUser($username) {
  // Get the user's password and salt from the database
  $query = "SELECT password, salt FROM users WHERE username='" . $username . "'";
  $conn = connectToDatabase("localhost", "root", "");
  $result = queryDatabase($conn, $query);
  $row = mysqli_fetch_assoc($result);
  closeDatabaseConnection($conn);
  return new User($username, $row["password"], $row["salt"]);
}
