void add_records(int num_records, int *key_indices, double *values) {
    // Check if there is enough memory for the new records
    if (num_records > storage->size - head->next) {
        printf("Error: Not enough memory to add new records\n");
        exit(1);
    }

    // Add new records to the linked list
