    new_node->record = (record *)malloc(sizeof(record));
    if (!new_node->record) {
        printf("Error: Failed to allocate memory for new record\n");
        exit(1);
    }
    new_node->next = head;
    head = new_node;

    // Update storage array with new values
    int i;
    for (i = 0; i < num_records; i++) {
        storage[head->record->index] = values[i];
        head->record->value = values[i];
        head->record->key_index = key_indices[i];
        head->record->timestamp = time(NULL);
    }
}

// Function to update existing records
void update_records(int num_records, int *key_indices, double *values) {
    // Check if there is enough memory for the updated records
    if (num_records > storage->size - head->next) {
        printf("Error: Not enough memory to update existing records\n");
        exit(1);
    }

    // Update existing records in the linked list
    struct node *current = head;
    int i;
    for (i = 0; i < num_records; i++) {
        while (current->next != NULL && current->record->key_index == key_indices[i]) {
            current->record->value = values[i];
            current->record->timestamp = time(NULL);
            current = current->next;
        }
    }
}

// Function to retrieve records by key
void get_records(int num_keys, int *key_indices) {
    // Check if there is enough memory for the retrieved records
    if (num_keys > storage->size - head->next) {
        printf("Error: Not enough memory to retrieve records\n");
        exit(1);
    }

    // Retrieve records from the linked list
    struct node *current = head;
    int i;
    for (i = 0; i < num_keys; i++) {
        while (current->next != NULL && current->record->key_index == key_indices[i]) {
            printf("Record %d: value=%f, timestamp=%s\n", i, current->record->value, ctime(&current->record->timestamp));
            current = current->next;
        }
    }
}

// Function to free all allocated memory at the end of operation
void free_memory() {
    // Free storage array
    free(storage);

    // Free key array
    free(keys);

    // Free record array
    free(records);

    // Free historical data array
    free(historical_data);

    // Free linked list nodes
    struct node *current = head;
    while (current != NULL) {
        struct node *next = current->next;
        free(current);
        current = next;
    }
}
