// Function to modify the filename based on specific rules
char* modify_filename(const char* original_filename) {
    // Check if the input filename is NULL or contains invalid characters that cannot be safely processed
    if (original_filename == NULL || strchr(original_filename, '/') != NULL) {
        return NULL;
    }

    // Extract the base name and extension from the original filename
    char* base_name = strrchr(original_filename, '.');
    char* extension = strrchr(original_filename, '.');
    if (base_name == NULL || extension == NULL) {
        return NULL;
    }

    // Determine the number of digits in the base name
    int num_digits = 0;
    for (int i = 0; i < strlen(base_name); i++) {
        if (isdigit(base_name[i])) {
            num_digits++;
        }
    }

    // Generate a new filename by appending the number of digits found in the base name followed by a specified file type extension
    char* new_filename = malloc(MAX_FILENAME_LENGTH);
    if (new_filename == NULL) {
        return NULL;
    }
    sprintf(new_filename, "%s%d.%s", base_name, num_digits, extension);

    // Handle filenames with no extension or multiple extensions gracefully
    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        char* unique_id = malloc(MAX_FILENAME_LENGTH);
        if (unique_id == NULL) {
            free(new_filename);
            return NULL;
        }
        sprintf(unique_id, "%d", time(NULL));
        strcat(new_filename, unique_id);
    }

    // Ensure that the new filename does not exceed a maximum length of 255 characters
    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        free(new_filename);
        return NULL;
    }

    // Preserve the original filename if the new filename exceeds the maximum length constraint
    if (strcmp(original_filename, new_filename) == 0) {
        free(new_filename);
        return NULL;
    }

    // Handle Unicode filenames and filenames containing special characters
    char* safe_filename = malloc(MAX_FILENAME_LENGTH);
    if (safe_filename == NULL) {
        free(new_filename);
        return NULL;
    }
    strcpy(safe_filename, new_filename);
    for (int i = 0; i < strlen(safe_filename); i++) {
        if (!isalnum(safe_filename[i]) && safe_filename[i] != '.') {
            safe_filename[i] = '_';
        }
    }

    // Return a pointer to the new filename
    return safe_filename;
}
