int execute_shell_command_and_return_result(char *command, int max_depth) {
    // Check for command injection vulnerabilities
    if (strchr(command, '|') || strchr(command, ';')) {
        return -1;
    }

    // Create a child process to execute the command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: execute the command and exit
        int status = system(command);
        _exit(status);
    } else if (pid < 0) {
        return -1;
    }

    // Parent process: wait for the child to finish and retrieve its output
    int status, output_size;
    char *output = NULL;
    while ((status = wait(&status)) != pid) {
        if (status < 0 && errno != EINTR) {
            return -1;
        }
    }

    // Read the child's output from stdout
    FILE *fp = fdopen(STDOUT_FILENO, "r");
    if (!fp) {
        return -1;
    }
    char buf[BUFSIZ];
    while ((output_size = fread(buf, 1, BUFSIZ, fp)) > 0) {
        output = realloc(output, output_size + 1);
        memcpy(output, buf, output_size);
        output[output_size] = '\0';
    }
    fclose(fp);

    // Check for command execution errors
    if (WIFEXITED(status) && WEXITSTATUS(status)) {
        return -1;
    } else if (WIFSIGNALED(status)) {
        return -1;
    }

    // Return the output as a string
    return output;
}

int execute_nested_shell_command(char *command, int max_depth) {
    // Check for nested depth limit
    if (max_depth <= 0 || max_depth > MAX_NESTED_DEPTH) {
        return -1;
    }

    // Parse the command and its parameters
    char *cmd = strtok(command, " ");
    char *param = NULL;
    nested_param_t params[MAX_NESTED_DEPTH];
    int depth = 0;
    while ((param = strtok(NULL, " ")) != NULL) {
        if (depth >= max_depth) {
            return -1;
        }
        params[depth].command = param;
        params[depth].depth = depth + 1;
        depth++;
    }

    // Execute the command and its parameters recursively
    for (int i = 0; i < depth; i++) {
        char *nested_cmd = params[i].command;
        int nested_depth = params[i].depth;
        if (nested_depth > max_depth) {
            return -1;
        }
        char *output = execute_shell_command_and_return_result(nested_cmd, nested_depth);
        if (!output) {
            return -1;
        }
    }

    // Return the output as a string
    return output;
}
```
