using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicValueGenerator
{
    private int _minValue;
    private int _maxValue;
    private bool _inclusive;
    private bool _exclusive;
    private Random _random = new Random();

    public DynamicValueGenerator(int minValue, int maxValue, bool inclusive = true, bool exclusive = false)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _inclusive = inclusive;
        _exclusive = exclusive;
    }

    public int GenerateRandomInteger()
    {
        return _random.Next(_minValue, _maxValue + (_inclusive ? 1 : 0));
    }

    public float GenerateRandomFloat()
    {
        return (float)(_random.NextDouble() * (_maxValue - _minValue) + _minValue);
    }

    public IEnumerable<int> SampleMultipleRandomIntegers(int count)
    {
        for (int i = 0; i < count; i++)
            yield return GenerateRandomInteger();
    }

    public IEnumerable<float> SampleMultipleRandomFloats(int count)
    {
        for (int i = 0; i < count; i++)
            yield return GenerateRandomFloat();
    }

    public void Reset()
    {
        _random = new Random();
    }

    public override string ToString()
    {
        if (_minValue == int.MinValue && _maxValue == int.MaxValue)
            return "Range: Infinite";
        else if (_minValue == _maxValue)
            return $"Range: {_minValue}";
        else
            return $"Range: [{_minValue}, {(_inclusive ? "]" : ")")}{_maxValue}]";
    }
}
```
