int largestInteger(int* arr, int size) {
    if (size == 0) return -1;
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

int main() {
    int* arr;
    scanf("%d", &size);
    arr = malloc(sizeof(int) * size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }
    printf("%d\n", largestInteger(arr, size));
    free(arr);
    return 0;
}
