public class DynamicRandomValueGenerator
{
    private float minValue;
    private float maxValue;
    private int seed;
    private bool isInclusive;
    private DistributionType distributionType;

    public enum DistributionType
    {
        Uniform,
        Gaussian,
        Exponential,
        Poisson
    }

    public DynamicRandomValueGenerator(float minValue, float maxValue, int seed = 0, bool isInclusive = true, DistributionType distributionType = DistributionType.Uniform)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.seed = seed;
        this.isInclusive = isInclusive;
        this.distributionType = distributionType;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue);
    }

    public string GetCurrentSettings()
    {
        return $"Min value: {minValue}, Max value: {maxValue}, Seed: {seed}, Distribution type: {distributionType}";
    }

    public void ResetState(int seed = 0)
    {
        this.seed = seed;
    }

    private float GetRandomFloatInternal()
    {
        switch (distributionType)
        {
            case DistributionType.Uniform:
                return UnityEngine.Random.Range(minValue, maxValue);
            case DistributionType.Gaussian:
                return UnityEngine.Random.Gaussian(minValue, maxValue - minValue);
            case DistributionType.Exponential:
                return UnityEngine.Random.Exponential(maxValue - minValue);
            case DistributionType.Poisson:
                return UnityEngine.Random.Poisson(maxValue - minValue);
        }
    }
}
