    {
        private float minValue;
        private float maxValue;
        private int seed;
        private Distribution initialDistribution;

        public DynamicRandomValueGenerator(float minValue, float maxValue, int seed = 0, Distribution initialDistribution = null)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
            this.seed = seed;
            this.initialDistribution = initialDistribution ?? new UniformDistribution();
        }

        public float GetRandomFloat(bool isInclusive)
        {
            var random = new Random(this.seed);
            var distribution = this.GetCurrentDistribution();
            return (float)(distribution.NextDouble() * (isInclusive ? 1 : 0)) * (this.maxValue - this.minValue) + this.minValue;
        }

        public int GetRandomInt(bool isInclusive)
        {
            var random = new Random(this.seed);
            var distribution = this.GetCurrentDistribution();
            return (int)(distribution.NextDouble() * (isInclusive ? 1 : 0)) * (this.maxValue - this.minValue) + this.minValue;
        }

        public Distribution GetCurrentDistribution()
        {
            var distribution = new UniformDistribution();
            if (this.initialDistribution != null)
            {
                distribution = this.initialDistribution;
            }
            return distribution;
        }

        public string GetCurrentSettings()
        {
            return $"Min value: {this.minValue}, Max value: {this.maxValue}, Seed: {this.seed}, Distribution: {this.GetCurrentDistribution()}";
