def parse_and_index_binary_log(input_file, output_file, transformation_rules):
    """
    Parses and indexes a large binary log file stored in compressed formats like .xz or .gz.
    The function handles files that may exceed available memory by reading them in manageable chunks to ensure optimal performance and resource usage.
    This function integrates into an existing log processing pipeline that manages multiple log formats and sources, coexisting with filtering, aggregation, and visualization operations without causing bottlenecks or resource contention.

    Optimize the function for both initial setup and ongoing execution, considering potential impacts on system performance and resource allocation during peak usage times. Provide clear documentation on how the function interacts with other components, including error handling and recovery strategies for partial failures. Support parallel processing where appropriate to maximize throughput on multi-core systems. Address design challenges related to maintaining data consistency and avoiding race conditions when multiple threads or processes access shared resources.
    """
    # Set up the input file reader
    if input_file.endswith('.xz'):
        with lzma.open(input_file, 'rb') as f:
            reader = pd.read_csv(f, compression='infer', sep='\t', header=None)
    elif input_file.endswith('.gz'):
        with gzip.open(input_file, 'rb') as f:
            reader = pd.read_csv(f, compression='infer', sep='\t', header=None)
    else:
        raise ValueError('Unsupported input file format')

    # Set up the output file writer
    with open(output_file, 'wb') as f:
        writer = pd.DataFrameWriter(f, compression='infer', sep='\t')

    # Apply transformation rules to each chunk of data
    for chunk in reader.iterrows():
        transformed_chunk = apply_transformation_rules(chunk, transformation_rules)
        writer.write_row(transformed_chunk)

def apply_transformation_rules(chunk, transformation_rules):
    """
    Applies the specified transformation rules to a single chunk of data.
    The function should handle partial failures and provide clear documentation on how it interacts with other components.
    """
    # Parse the input chunk into a pandas DataFrame
    df = pd.DataFrame(chunk, columns=['timestamp', 'message'])

    # Apply transformation rules to each column of the DataFrame
    for col in df:
        if transformation_rules[col] == 'lowercase':
            df[col] = df[col].str.lower()
        elif transformation_rules[col] == 'uppercase':
            df[col] = df[col].str.upper()
        else:
            raise ValueError('Unsupported transformation rule')

    # Return the transformed chunk as a pandas DataFrame
    return df
