} MemoryPool;

// Define a function to allocate and initialize a memory pool
MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) {
        return NULL;
    }
    pool->size = size;
    pool->buffer = malloc(size);
    if (pool->buffer == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Define a function to release the memory pool
void destroy_memory_pool(MemoryPool* pool) {
    free(pool->buffer);
    free(pool);
}

// Define a function to allocate memory from the memory pool
char* allocate_memory(MemoryPool* pool, size_t size) {
    if (size > pool->size) {
        return NULL;
    }
    char* buffer = malloc(size);
    if (buffer == NULL) {
        return NULL;
    }
    memcpy(buffer, pool->buffer, size);
    return buffer;
}

