    EVP_add_cipher(EVP_rsa_sha1());

    // Create aliases for AES and Camellia key sizes
    EVP_add_digest_alias("AES-128", "aes-128-ecb");
    EVP_add_digest_alias("AES-192", "aes-192-ecb");
    EVP_add_digest_alias("AES-256", "aes-256-ecb");
    EVP_add_digest_alias("Camellia-128", "camellia-128-ecb");
    EVP_add_digest_alias("Camellia-192", "camellia-192-ecb");
    EVP_add_digest_alias("Camellia-256", "camellia-256-ecb");

    // Dynamically select key size based on configuration parameters
    int key_size = get_key_size();
    if (key_size == 128) {
        EVP_add_cipher(EVP_aes_128_ecb());
        EVP_add_digest("AES-128");
    } else if (key_size == 192) {
        EVP_add_cipher(EVP_aes_192_ecb());
        EVP_add_digest("AES-192");
    } else if (key_size == 256) {
        EVP_add_cipher(EVP_aes_256_ecb());
        EVP_add_digest("AES-256");
    }

    // Log time taken to add each cipher and digest
    long start = get_time();
    EVP_add_cipher(EVP_aes_128_ecb());
    long end = get_time() - start;
    printf("Adding AES-128 took %ld ms\n", end);

    start = get_time();
    EVP_add_cipher(EVP_aes_192_ecb());
    end = get_time() - start;
    printf("Adding AES-192 took %ld ms\n", end);

    start = get_time();
    EVP_add_cipher(EVP_aes_256_ecb());
    end = get_time() - start;
    printf("Adding AES-256 took %ld ms\n", end);

    start = get_time();
    EVP_add_digest("AES-128");
    end = get_time() - start;
    printf("Adding MD5 took %ld ms\n", end);

    start = get_time();
    EVP_add_digest("SHA-1");
    end = get_time() - start;
    printf("Adding SHA-1 took %ld ms\n", end);

    start = get_time();
    EVP_add_digest("SHA-256");
    end = get_time() - start;
    printf("Adding SHA-256 took %ld ms\n", end);

    start = get_time();
    EVP_add_digest("SHA-384");
    end = get_time() - start;
    printf("Adding SHA-384 took %ld ms\n", end);

    start = get_time();
    EVP_add_digest("SHA-512");
    end = get_time() - start;
    printf("Adding SHA-512 took %ld ms\n", end);

    // Verify integrity of library
    if (EVP_get_cipherbyname("AES-128") == NULL) {
        printf("Error: AES-128 cipher not found in library\n");
    }
    if (EVP_get_digestbyname("MD5") == NULL) {
        printf("Error: MD5 digest not found in library\n");
    }
    if (EVP_get_digestbyname("SHA-1") == NULL) {
        printf("Error: SHA-1 digest not found in library\n");
    }
    if (EVP_get_digestbyname("SHA-256") == NULL) {
        printf("Error: SHA-256 digest not found in library\n");
    }
    if (EVP_get_digestbyname("SHA-384") == NULL) {
        printf("Error: SHA-384 digest not found in library\n");
    }
    if (EVP_get_digestbyname("SHA-512") == NULL) {
        printf("Error: SHA-512 digest not found in library\n");
    }
}

int get_key_size() {
    // Return key size based on configuration parameters
    return 128;
}

long get_time() {
    // Get current time in milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}
