#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <openssl/evp.h>

// Define the supported encryption modes
enum DES_MODE { ECB, EDE, EDE3, CFB };

// Define the structure to hold the configuration data
struct config {
    char *access_token;
    char *refresh_token;
    int expires_in;
    char *token_type;
};

// Function to validate the JSON object against the criteria
int validate_json(const json_object *json) {
    // Check for presence of access token
    if (!json_object_get_string(json, "access_token")) {
        return 0;
    }

    // Check for token type set to 'Bearer'
    const char *token_type = json_object_get_string(json, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        return 0;
    }

    // Check for expiration time as a positive integer
    int expires_in = json_object_get_int(json, "expires_in");
    if (expires_in <= 0) {
        return 0;
    }

    // Check for optional refresh token
    const char *refresh_token = json_object_get_string(json, "refresh_token");
    if (refresh_token && strlen(refresh_token) > 0) {
        return 1;
    }

    return 1;
}

// Function to initialize the DES encryption mode based on the configuration file
EVP_CIPHER *init_des_mode(const char *config_file) {
    // Load the JSON object from the configuration file
    json_object *json = json_object_from_file(config_file);
    if (!json) {
        return NULL;
    }

    // Validate the JSON object against the criteria
    if (!validate_json(json)) {
        json_object_put(json);
        return NULL;
    }

    // Get the access token and expiration time from the JSON object
    const char *access_token = json_object_get_string(json, "access_token");
    int expires_in = json_object_get_int(json, "expires_in");

    // Initialize the DES encryption mode based on the configuration file
    EVP_CIPHER *cipher = NULL;
    switch (json_object_get_string(json, "mode")) {
        case ECB:
            cipher = EVP_des_ecb();
            break;
        case EDE:
            cipher = EVP_des_ede();
            break;
        case EDE3:
            cipher = EVP_des_ede3();
            break;
        case CFB:
            cipher = EVP_des_cfb();
            break;
    }

    // Set the access token and expiration time for the DES encryption mode
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, cipher, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_ACCESS_TOKEN, strlen(access_token), (void *)access_token);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_SET_EXPIRES_IN, expires_in, NULL);

    // Free the JSON object and return the DES encryption mode
    json_object_put(json);
    return cipher;
}
