// Define the record structure
typedef struct {
    int value;
    char key[10]; // Unique key for each record
} Record;

// Function to manage memory allocation and initialization for a dynamic database-like structure
void initializeDatabase(int numRecords, int minRange, int maxRange, bool uniqueKeys) {
    // Allocate memory dynamically for an array of 'record' structures
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Error: Insufficient memory available. Exiting...\n");
        exit(1);
    }

    // Initialize the integer values in each record to a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % (maxRange - minRange + 1) + minRange;
        if (uniqueKeys) {
            // Generate a unique key for each record
            sprintf(records[i].key, "%d", i);
        }
    }

    // Handle potential memory allocation failures gracefully
    atexit(freeDatabase);
}

// Function to free all allocated memory upon function exit
void freeDatabase() {
    if (records) {
        free(records);
    }
}

int main() {
    // Test the initializeDatabase function with different parameters
    initializeDatabase(10, 1, 10, true);
    initializeDatabase(20, 1, 10, false);
    initializeDatabase(30, 1, 10, true);

    return 0;
}
