// Define the record structure
typedef struct {
    int value;
    char key[10]; // Unique key for each record
} Record;

// Define the graph structure
typedef struct {
    int num_vertices;
    int num_edges;
    Record *records;
    Vertex **vertices;
    Edge **edges;
} Graph;

// Function to manage memory allocation and initialization for a dynamic database-like structure
void init_database(int num_records, int min_range, int max_range, bool unique_keys) {
    // Allocate memory for the array of records
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Insufficient memory to allocate records\n");
        return;
    }

    // Initialize the integer values in each record to a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (max_range - min_range + 1) + min_range;
        if (unique_keys) {
            sprintf(records[i].key, "%d", records[i].value);
        }
    }

    // Add a random number of vertices and edges to the graph
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    if (!graph) {
        printf("Error: Insufficient memory to allocate graph\n");
        return;
    }
    graph->num_vertices = rand() % num_records + 1;
    graph->num_edges = rand() % (num_records - 1) + 1;
    graph->records = records;
    graph->vertices = (Vertex **)malloc(graph->num_vertices * sizeof(Vertex *));
    if (!graph->vertices) {
        printf("Error: Insufficient memory to allocate vertices\n");
        return;
    }
    for (int i = 0; i < graph->num_vertices; i++) {
        graph->vertices[i] = (Vertex *)malloc(sizeof(Vertex));
        if (!graph->vertices[i]) {
            printf("Error: Insufficient memory to allocate vertex %d\n", i);
            return;
        }
    }
    graph->edges = (Edge **)malloc(graph->num_edges * sizeof(Edge *));
    if (!graph->edges) {
        printf("Error: Insufficient memory to allocate edges\n");
        return;
    }
    for (int i = 0; i < graph->num_edges; i++) {
        graph->edges[i] = (Edge *)malloc(sizeof(Edge));
        if (!graph->edges[i]) {
            printf("Error: Insufficient memory to allocate edge %d\n", i);
            return;
        }
    }

    // Set random properties on the vertices and edges using standard library functions
    for (int i = 0; i < graph->num_vertices; i++) {
        Vertex *vertex = graph->vertices[i];
        vertex->id = i;
        vertex->label = "Vertex";
        vertex->properties = (Property *)malloc(sizeof(Property));
        if (!vertex->properties) {
            printf("Error: Insufficient memory to allocate properties for vertex %d\n", i);
            return;
        }
    }
    for (int i = 0; i < graph->num_edges; i++) {
        Edge *edge = graph->edges[i];
        edge->id = i;
        edge->label = "Edge";
        edge->properties = (Property *)malloc(sizeof(Property));
        if (!edge->properties) {
            printf("Error: Insufficient memory to allocate properties for edge %d\n", i);
            return;
        }
    }
}

// Method in a graph database to add vertices and edges
void add_vertices_and_edges(Graph *graph, int num_vertices, int num_edges) {
    // Add the specified number of vertices and edges to the graph
    for (int i = 0; i < num_vertices; i++) {
        Vertex *vertex = (Vertex *)malloc(sizeof(Vertex));
        if (!vertex) {
            printf("Error: Insufficient memory to allocate vertex %d\n", i);
            return;
        }
        graph->num_vertices++;
        graph->vertices = (Vertex **)realloc(graph->vertices, graph->num_vertices * sizeof(Vertex *));
        if (!graph->vertices) {
            printf("Error: Insufficient memory to reallocate vertices\n");
            return;
        }
        graph->vertices[i] = vertex;
    }
    for (int i = 0; i < num_edges; i++) {
        Edge *edge = (Edge *)malloc(sizeof(Edge));
        if (!edge) {
            printf("Error: Insufficient memory to allocate edge %d\n", i);
            return;
        }
        graph->num_edges++;
        graph->edges = (Edge **)realloc(graph->edges, graph->num_edges * sizeof(Edge *));
        if (!graph->edges) {
            printf("Error: Insufficient memory to reallocate edges\n");
            return;
        }
        graph->edges[i] = edge;
    }
}
