#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for file metadata
typedef struct {
    int id;
    char name[256];
    long size;
    int metadata_fields;
    int* metadata;
} file;

// Function to manage memory allocation and initialization for the file indexing system
void init_file_index(int num_files, int index_by_name, int max_size, int num_metadata_fields, int min_metadata_value, int max_metadata_value) {
    // Check input parameters for validity
    if (num_files <= 0 || index_by_name < 0 || max_size <= 0 || num_metadata_fields <= 0 || min_metadata_value >= max_metadata_value) {
        printf("Invalid input parameters. Exiting.\n");
        return;
    }

    // Allocate memory for the array of file structures
    file* files = (file*)malloc(num_files * sizeof(file));
    if (!files) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    // Initialize the file names and sizes randomly within the specified range
    for (int i = 0; i < num_files; i++) {
        files[i].id = i + 1;
        if (index_by_name) {
            sprintf(files[i].name, "file%d", i + 1);
        } else {
            files[i].size = rand() % max_size + 1;
        }
    }

    // Allocate memory for the metadata fields and fill them with random values within predefined ranges
    for (int i = 0; i < num_files; i++) {
        files[i].metadata_fields = num_metadata_fields;
        files[i].metadata = (int*)malloc(num_metadata_fields * sizeof(int));
        if (!files[i].metadata) {
            printf("Memory allocation failed. Exiting.\n");
            return;
        }
        for (int j = 0; j < num_metadata_fields; j++) {
            files[i].metadata[j] = rand() % (max_metadata_value - min_metadata_value + 1) + min_metadata_value;
        }
    }

    // Add new files to the index and retrieve metadata for existing files
    void add_file(file* f) {
        if (!f) {
            printf("Invalid file pointer. Exiting.\n");
            return;
        }
        int id = f->id;
        char* name = f->name;
        long size = f->size;
        int* metadata = f->metadata;
        if (index_by_name) {
            // Search for the file by name in the index
            for (int i = 0; i < num_files; i++) {
                if (!strcmp(files[i].name, name)) {
                    id = files[i].id;
                    size = files[i].size;
                    metadata = files[i].metadata;
                    break;
                }
            }
        } else {
            // Search for the file by size in the index
            for (int i = 0; i < num_files; i++) {
                if (files[i].size == size) {
                    id = files[i].id;
                    name = files[i].name;
                    metadata = files[i].metadata;
                    break;
                }
            }
        }
        // Add the file to the index if it is not already present
        if (id == 0) {
            id = num_files + 1;
            strcpy(name, f->name);
            size = f->size;
            metadata = f->metadata;
