public:
    MemoryManager(int limit) : limit_(limit), random_engine_(std::mt19937(std::random_device())) {}

    ~MemoryManager() {
        for (auto& record : records_) {
            delete[] record.key;
            delete[] record.value;
        }
    }

    void addRecord(int key, const char* value) {
        if (records_.size() == limit_) {
            compactRecords();
        }

        records_.push_back({key, new char[256], new int});
        strcpy(records_.back().value, value);
    }

    void updateRecord(int key, const char* value) {
        for (auto& record : records_) {
            if (record.key == key) {
                delete[] record.value;
                record.value = new char[256];
                strcpy(record.value, value);
                return;
            }
        }
    }

    void compactRecords() {
        vector<Record> compacted_records;
        for (auto& record : records_) {
            if (record.key != -1) {
                compacted_records.push_back(record);
            }
        }
        records_.swap(compacted_records);
    }

private:
    struct Record {
        int key;
        char* value;
        int* random_value;
    };

    vector<Record> records_;
    int limit_;
    std::mt19937 random_engine_;
};
