        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < resources->num_widgets; i++) {
            if (resources->widgets[i] == widget) {
                resources->events[i].timestamp = getCurrentTime();
                pthread_cond_signal(&cond);
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    gui_widget_t* getRecord(dynamic_resources_t* resources, int key) {
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < resources->num_widgets; i++) {
            if (resources->widgets[i]->key == key) {
                pthread_cond_signal(&cond);
                pthread_mutex_unlock(&mutex);
                return resources->widgets[i];
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Update a record's timestamp to trigger re-validation of the tree structure
    void updateTimestamp(dynamic_resources_t* resources, gui_widget_t* widget) {
        pthread_mutex_lock(&mutex);
        for (size_t i = 0; i < resources->num_widgets; i++) {
            if (resources->widgets[i] == widget) {
                resources->events[i].timestamp = getCurrentTime();
                pthread_cond_signal(&cond);
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    // Incorporate error checking for all memory allocations and handle varying input sizes efficiently
    if (resources->num_widgets > 0) {
        resources->widgets[resources->num_widgets - 1]->key = key;
    }

    // Provide a mechanism to free all allocated memory at the end of operations
    void freeMemory(dynamic_resources_t* resources) {
        deallocateMemory(resources);
        fclose(log_file);
    }

    // Implement a helper function called `calculateMD5Hash` to compute the MD5 hash of a given string using a standard library function, handling exceptions gracefully
    char* calculateMD5Hash(const char* input) {
        unsigned char md5[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input, strlen(input), md5);
        return hex_encode(md5, sizeof(md5));
    }
