    char *input_file;
    char *output_file;
    int count_characters;
    int help;
};

int main(int argc, char **argv) {
    // Initialize a structure to store the parsed command line arguments
    struct cmdline_args args = {NULL, NULL, 0, 0};

    // Parse the command line arguments using getopt()
    int c;
    while ((c = getopt(argc, argv, "ho:c")) != -1) {
        switch (c) {
            case OPTION_HELP:
                args.help = 1;
                break;
            case OPTION_OUTPUT_FILE:
                args.output_file = optarg;
                break;
            case OPTION_COUNT_CHARACTERS:
                args.count_characters = 1;
                break;
        }
    }

    // Check if the input file was specified and is accessible
    if (args.input_file == NULL || access(args.input_file, R_OK) != 0) {
        fprintf(stderr, "Error: Input file not specified or not accessible\n");
        return 1;
    }

    // Open the input file for reading
    FILE *fp = fopen(args.input_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open input file\n");
        return 1;
    }

    // Initialize variables to store the total number of lines and characters
    int num_lines = 0;
    long num_chars = 0;

    // Read from the input file line by line and count the number of lines and characters
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        num_lines++;
        if (args.count_characters) {
            num_chars += strlen(line);
        }
    }

    // Close the input file
    fclose(fp);

    // Print the total number of lines and characters to the console
    printf("Total number of lines: %d\n", num_lines);
    if (args.count_characters) {
        printf("Total number of characters: %ld\n", num_chars);
    }

    // If an output file was specified, write the total number of lines and characters to it
    if (args.output_file != NULL) {
        FILE *fp = fopen(args.output_file, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error: Failed to open output file\n");
            return 1;
        }
        fprintf(fp, "%d", num_lines);
        if (args.count_characters) {
            fprintf(fp, ", %ld", num_chars);
        }
        fclose(fp);
    }

    // Free the memory allocated for the line buffer
    free(line);

    return 0;
}
