// Define the log format and its corresponding regular expression pattern
const string logFormat = "%Y-%m-%d %H:%M:%S [%L] %t";
const regex logPattern(R"(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} \[(?<level>ERROR|WARNING|INFO)\] (?<message>.*))");

// Define the command line options and their corresponding variables
