const string directoryOption = "-d";
const string filterOption = "-f";
const string dateRangeOption = "-r";
const string logLevelOption = "-l";

// Define the usage message for the program
const string usageMessage = "Usage: log_processor [options] <directory>";

// Define the default values for the command line options
const string defaultDirectoryPath = "";
const string defaultFilterPattern = "";
const string defaultDateRange = "";
const LogLevel defaultLogLevel = LogLevel::INFO;

