    // Parse the command line arguments and display usage message if necessary
    if (argc == 1 || (argc == 2 && strcmp(argv[1], helpOption) == 0)) {
        cout << usageMessage << endl;
        return 0;
    }

    // Define the variables for the command line options and their corresponding values
    string directoryPath = defaultDirectoryPath;
    string filterPattern = defaultFilterPattern;
    string dateRange = defaultDateRange;
    LogLevel logLevel = defaultLogLevel;

    // Parse the command line arguments and set the corresponding variables
    for (int i = 1; i < argc - 1; ++i) {
        if (strcmp(argv[i], directoryOption) == 0) {
            directoryPath = argv[++i];
        } else if (strcmp(argv[i], filterOption) == 0) {
            filterPattern = argv[++i];
        } else if (strcmp(argv[i], dateRangeOption) == 0) {
            dateRange = argv[++i];
        } else if (strcmp(argv[i], logLevelOption) == 0) {
            logLevel = LogLevel::ERROR;
        }
    }

    // Check if the directory path is valid and display an error message if not
    if (!filesystem::is_directory(directoryPath)) {
        cout << "Error: Invalid directory path" << endl;
        return 1;
    }

    // Define the variables for the log processing and archiving
    vector<string> processedLogs;
    queue<string> unprocessedLogs;
    mutex logsMutex;
    condition_variable logsCondition;
    bool isProcessing = false;

    // Define the function to process a single log file
    auto processLogFile = [&](const string& filename) {
        ifstream logFile(filename);
        string line;
        while (getline(logFile, line)) {
            smatch match;
            regex_search(line, match, logPattern);
            if (match.size() > 0) {
                LogLevel level = LogLevel::INFO;
                if (match["level"].str() == "ERROR") {
                    level = LogLevel::ERROR;
                } else if (match["level"].str() == "WARNING") {
                    level = LogLevel::WARNING;
                }
                string message = match["message"].str();
                // Check if the log matches the filter pattern and date range
                bool isMatch = true;
                if (!filterPattern.empty()) {
                    isMatch &= regex_search(message, regex(filterPattern));
                }
                if (!dateRange.empty()) {
                    string date = match["date"].str();
                    auto startDate = chrono::system_clock::from_time_t(stoi(dateRange.substr(0, 4)) - 1900);
                    auto endDate = chrono::system_clock::from_time_t(stoi(dateRange.substr(5, 2)) - 1900);
                    isMatch &= (startDate <= chrono::system_clock::now()) && (chrono::system_clock::now() <= endDate);
                }
                if (isMatch) {
                    // Add the log to the processed logs queue
                    lock_guard<mutex> lock(logsMutex);
                    processedLogs.push_back(message);
                } else {
                    // Add the log to the unprocessed logs queue
                    lock_guard<mutex> lock(logsMutex);
                    unprocessedLogs.push(filename);
                }
            }
        }
    };

    // Define the function to archive processed logs to a backup directory
    auto archiveProcessedLogs = [&]() {
        if (processedLogs.empty()) {
            return;
        }
        string backupDirectoryPath = directoryPath + ".bak";
        filesystem::create_directory(backupDirectoryPath);
        for (const string& log : processedLogs) {
            string filename = filesystem::path(log).filename().string();
            ofstream archiveFile(backupDirectoryPath + "/" + filename);
            archiveFile << log;
        }
    };

    // Define the function to process logs in a separate thread
    auto processLogsThread = [&]() {
        while (true) {
            lock_guard<mutex> lock(logsMutex);
            if (!unprocessedLogs.empty()) {
                string filename = unprocessedLogs.front();
                unprocessedLogs.pop();
                processLogFile(filename);
            } else {
                isProcessing = false;
                break;
            }
        }
    };

    // Start the log processing thread and wait for it to finish
    thread logsThread(processLogsThread);
    while (isProcessing) {
        this_thread::sleep_for(chrono::milliseconds(100));
    }
    logsCondition.notify_all();
    logsThread.join();

    // Print the processed logs to the console
    for (const string& log : processedLogs) {
        cout << logColors[logLevel] << log << "\033[0m" << endl;
    }

    // Archive the processed logs to a backup directory
    archiveProcessedLogs();

    return 0;
}
