using namespace std;

// Define the log levels
enum LogLevel {
    ERROR,
    WARNING,
    INFO
};

// Define the metadata fields
struct Metadata {
    string userId;
    string ipAddress;
};

// Define the log entry structure
struct LogEntry {
    string message;
    LogLevel level;
    Metadata metadata;
    chrono::system_clock::time_point timestamp;
};

// Define the log file structure
struct LogFile {
    string path;
    vector<LogEntry> entries;
};

// Define the command line options
struct Options {
    bool help;
    string directoryPath;
    chrono::system_clock::time_point startDate;
    chrono::system_clock::time_point endDate;
    vector<string> metadataFields;
};

// Define the log file reader class
class LogFileReader {
public:
    LogFileReader(const string& path) : path_(path) {}

    void read() {
        ifstream file(path_);
        if (!file.is_open()) {
            throw runtime_error("Failed to open log file");
        }

        string line;
        while (getline(file, line)) {
            // Parse the log entry from the line
            LogEntry entry = parseLogEntry(line);

            // Add the entry to the vector of entries
            entries_.push_back(entry);
        }
    }

    const vector<LogEntry>& getEntries() const {
        return entries_;
    }

private:
    string path_;
    vector<LogEntry> entries_;
};

// Define the log file processor class
class LogFileProcessor {
public:
    LogFileProcessor(const Options& options) : options_(options) {}

    void process() {
        // Create a vector of log files to process
        vector<LogFile> logFiles;

        // Read each log file in the directory and add it to the vector
        for (auto& path : options_.directoryPath) {
            LogFileReader reader(path);
            reader.read();
            logFiles.push_back(reader.getEntries());
        }

        // Filter the log files by date range
        if (!options_.startDate.empty() && !options_.endDate.empty()) {
            filterByDateRange(logFiles);
        }

        // Filter the log files by metadata fields
        if (!options_.metadataFields.empty()) {
            filterByMetadata(logFiles);
        }

        // Process each log file and extract the error logs
        for (auto& logFile : logFiles) {
            processLogFile(logFile);
        }
    }

private:
    void filterByDateRange(vector<LogFile>& logFiles) {
        auto start = chrono::system_clock::to_time_t(options_.startDate);
        auto end = chrono::system_clock::to_time_t(options_.endDate);

        // Filter the log files by date range
        for (auto it = logFiles.begin(); it != logFiles.end();) {
            if (it->timestamp < start || it->timestamp > end) {
                it = logFiles.erase(it);
            } else {
                ++it;
            }
        }
    }

    void filterByMetadata(vector<LogFile>& logFiles) {
        // Filter the log files by metadata fields
        for (auto it = logFiles.begin(); it != logFiles.end();) {
            bool match = true;
            for (auto& field : options_.metadataFields) {
                if (!it->metadata.contains(field)) {
                    match = false;
                    break;
                }
            }
            if (!match) {
                it = logFiles.erase(it);
            } else {
                ++it;
            }
        }
    }

    void processLogFile(const LogFile& logFile) {
        // Extract the error logs from the log file
        vector<LogEntry> errorLogs;
        for (auto& entry : logFile.entries) {
            if (entry.level == ERROR) {
                errorLogs.push_back(entry);
            }
        }

        // Archive the processed logs to a backup directory
        archiveLogs(logFile, errorLogs);
    }

    void archiveLogs(const LogFile& logFile, const vector<LogEntry>& errorLogs) {
        // Create a backup directory if it doesn't exist
        string backupDir = "backup";
        if (!exists(backupDir)) {
            create_directory(backupDir);
        }

        // Archive the processed logs to the backup directory
        for (auto& entry : errorLogs) {
            ofstream file(backupDir + "/" + logFile.path, ios::app);
            if (!file.is_open()) {
                throw runtime_error("Failed to open backup log file");
            }
            file << entry.message << endl;
        }
    }

private:
    Options options_;
};

int main(int argc, char** argv) {
    // Parse the command line arguments
    Options options = parseCommandLineArguments(argc, argv);

    // Create a log file processor instance
    LogFileProcessor processor(options);

    // Process each log file in the directory
    processor.process();

    return 0;
}
