// Define the priority queue for managing and processing logs based on their severity levels
struct PriorityQueue {
    map<LogLevel, vector<LogEntry>> logEntries;
    mutex mtx;
    condition_variable cv;

    void push(const LogEntry& entry) {
        unique_lock<mutex> lock(mtx);
        logEntries[entry.level].push_back(entry);
        cv.notify_all();
    }

    void pop() {
        unique_lock<mutex> lock(mtx);
        while (logEntries.empty()) {
            cv.wait(lock);
        }
        LogLevel level = logEntries.begin()->first;
        vector<LogEntry>& entries = logEntries[level];
        if (!entries.empty()) {
            LogEntry entry = entries.back();
            entries.pop_back();
            return entry;
        }
    }
};

// Define the logging mechanism for monitoring program performance and resource usage
