#define MAX_SHUFFLE_BUFFER_SIZE 1024
#define MAX_KEYS 1000

struct record {
    long *offset;
    int key;
};

struct record* allocate_records(int num_offsets, int num_keys, long min_key, long max_key) {
    // Validate input parameters
    if (num_keys > MAX_KEYS) {
        printf("Error: Number of keys exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for offset values and initialize them with sequential numbers
    long *offsets = malloc(sizeof(long) * num_offsets);
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Allocate memory for key values and initialize them with unique random values within the specified range
    int *keys = malloc(sizeof(int) * num_keys);
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the array of records and initialize each record with a random key and offset value
    struct record *records = malloc(sizeof(struct record) * num_keys);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[rand() % num_offsets];
        records[i].key = keys[i];
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    int shuffled_indices[MAX_SHUFFLE_BUFFER_SIZE];
    for (int i = 0; i < num_keys; i++) {
        shuffled_indices[i] = i;
    }
    for (int i = 0; i < num_keys - 1; i++) {
        int j = rand() % (num_keys - i) + i;
        int temp = shuffled_indices[j];
        shuffled_indices[j] = shuffled_indices[i];
        shuffled_indices[i] = temp;
    }
    for (int i = 0; i < num_keys; i++) {
        records[shuffled_indices[i]].offset = &offsets[rand() % num_offsets];
        records[shuffled_indices[i]].key = keys[i];
    }

    // Free the temporary buffer used for shuffling the indices
    free(shuffled_indices);

    return records;
}
