        return;
    }

    // Allocate memory for the shuffled indices buffer
    int* shuffledIndices = malloc(sizeof(int) * num_keys);
    if (shuffledIndices == NULL) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        return;
    }

    // Initialize the shuffled indices buffer with sequential numbers starting from 0
    for (int i = 0; i < num_keys; i++) {
        shuffledIndices[i] = i;
    }

    // Shuffle the array of integers using the Fisher-Yates algorithm
    for (int i = num_keys - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = shuffledIndices[i];
        shuffledIndices[i] = shuffledIndices[j];
        shuffledIndices[j] = temp;
    }

    // Deallocate memory for the shuffled indices buffer
    free(shuffledIndices);
}
