memory_manager* init_memory_manager(int num_connections, int num_requests, int min_id, int max_id, int shuffle_buffer_size) {
    if (num_connections > MAX_CONNECTIONS || num_requests > MAX_REQUESTS || shuffle_buffer_size > MAX_SHUFFLE_BUFFER_SIZE) {
        printf("Invalid configuration: number of connections, requests, or shuffle buffer size exceeds maximum allowed value\n");
        return NULL;
    }

    memory_manager *mm = (memory_manager*) malloc(sizeof(memory_manager));
    if (!mm) {
        printf("Failed to allocate memory for memory manager\n");
        return NULL;
    }

    mm->num_connections = num_connections;
    mm->num_requests = num_requests;
    mm->min_id = min_id;
    mm->max_id = max_id;
    mm->shuffle_buffer_size = shuffle_buffer_size;

    // allocate memory for request IDs and socket descriptors
    int *request_ids = (int*) malloc(num_requests * sizeof(int));
    if (!request_ids) {
        printf("Failed to allocate memory for request IDs\n");
        free(mm);
        return NULL;
    }
    mm->request_ids = request_ids;

    int *socket_descriptors = (int*) malloc(num_connections * sizeof(int));
    if (!socket_descriptors) {
        printf("Failed to allocate memory for socket descriptors\n");
        free(mm);
        return NULL;
    }
    mm->socket_descriptors = socket_descriptors;

    // initialize request IDs and socket descriptors
    for (int i = 0; i < num_requests; i++) {
        request_ids[i] = rand() % (max_id - min_id + 1) + min_id;
    }
    for (int i = 0; i < num_connections; i++) {
        socket_descriptors[i] = i;
    }

    // allocate memory for request records
    request_record *request_records = (request_record*) malloc(num_requests * sizeof(request_record));
    if (!request_records) {
        printf("Failed to allocate memory for request records\n");
        free(mm);
        return NULL;
    }
    mm->request_records = request_records;

    // initialize request records
    for (int i = 0; i < num_requests; i++) {
        request_records[i].id = request_ids[i];
        request_records[i].socket = socket_descriptors[i % num_connections];
    }

    return mm;
}

void deallocate_memory_manager(memory_manager *mm) {
    if (!mm) {
        return;
    }

    free(mm->request_ids);
    free(mm->socket_descriptors);
    free(mm->request_records);
    free(mm);
}
