    while (id < 0 || id > MAX_RECORDS) {
        id = rand();
    }
    return id;
}

void* initialize_connection_pool(size_t num_connections) {
    if (num_connections > MAX_CONNECTIONS) {
        printf("Error: Number of connections exceeds maximum allowed value\n");
        return NULL;
    }
    connection_t* pool = allocate_memory(sizeof(connection_t) * num_connections);
    if (pool == NULL) {
        return NULL;
    }
    for (int i = 0; i < num_connections; i++) {
        pool[i].socket = socket(AF_INET, SOCK_STREAM, 0);
        if (pool[i].socket == -1) {
            printf("Error: Failed to create socket\n");
            return NULL;
        }
    }
    return pool;
}

void* initialize_record_storage(size_t num_records) {
    if (num_records > MAX_RECORDS) {
        printf("Error: Number of records exceeds maximum allowed value\n");
        return NULL;
    }
    record_t* storage = allocate_memory(sizeof(record_t) * num_records);
    if (storage == NULL) {
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        storage[i].offset = generate_unique_id();
        storage[i].key = rand() % MAX_RECORDS;
