#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>

#define MAX_HASH_TABLE_SIZE 1000000
#define MAX_ENTRIES 1000000
#define MIN_VALUE 0
#define MAX_VALUE 1000000

typedef struct {
    long offset;
    char* key;
} Record;

typedef struct {
    int num_records;
    Record* records;
} RecordSet;

void init_record_set(RecordSet* record_set, int num_records) {
    // Allocate memory for the record set
    record_set->records = (Record*)malloc(num_records * sizeof(Record));
    if (!record_set->records) {
        printf("Error: Failed to allocate memory for record set\n");
        return;
    }

    // Initialize the records with unique keys and values
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        Record* record = &record_set->records[i];
        char key[16];
        snprintf(key, sizeof(key), "%d", rand() % MAX_VALUE);
        record->offset = rand() % MAX_VALUE;
        record->key = strdup(key);
    }
}

void deallocate_record_set(RecordSet* record_set) {
    // Free the memory allocated for the records
    for (int i = 0; i < record_set->num_records; ++i) {
        Record* record = &record_set->records[i];
        free(record->key);
    }
    free(record_set->records);
}

void init_hash_table() {
    // Initialize the hash table with a fixed size of MAX_HASH_TABLE_SIZE entries
    pthread_mutex_init(&hash_table_lock, NULL);
    hash_table = (HashTable*)malloc(sizeof(HashTable) * MAX_HASH_TABLE_SIZE);
    if (!hash_table) {
        printf("Error: Failed to allocate memory for hash table\n");
        return;
    }
}

void deallocate_hash_table() {
    // Free the memory allocated for the hash table
    free(hash_table);
}

int add_record_to_hash_table(Record* record) {
    // Acquire a lock on the hash table to prevent race conditions
    pthread_mutex_lock(&hash_table_lock);

    // Check if the hash table is full
    if (hash_table_size == MAX_HASH_TABLE_SIZE) {
        printf("Error: Hash table is full\n");
        return -1;
    }

    // Add the record to the hash table
    int index = hash(record->key);
    while (hash_table[index].used) {
        if (++index == MAX_HASH_TABLE_SIZE) {
            index = 0;
        }
    }
    hash_table[index] = *record;
    hash_table[index].used = true;
    ++hash_table_size;

    // Release the lock on the hash table
    pthread_mutex_unlock(&hash_table_lock);
}

int get_record_from_hash_table(char* key, Record** record) {
    // Acquire a lock on the hash table to prevent race conditions
    pthread_mutex_lock(&hash_table_lock);

    // Check if the hash table is empty
    if (hash_table_size == 0) {
        printf("Error: Hash table is empty\n");
        return -1;
    }

    // Find the record in the hash table
    int index = hash(key);
    while (!hash_table[index].used || strcmp(hash_table[index].key, key) != 0) {
        if (++index == MAX_HASH_TABLE_SIZE) {
            index = 0;
        }
    }
    *record = &hash_table[index];

    // Release the lock on the hash table
    pthread_mutex_unlock(&hash_table_lock);
}

int main(int argc, char** argv) {
    // Initialize the record set and hash table
    RecordSet* record_set = (RecordSet*)malloc(sizeof(RecordSet));
    init_record_set(record_set, MAX_ENTRIES);
    init_hash_table();

    // Process the records in parallel using multiple threads
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, process_records, record_set);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Deallocate the memory allocated for the record set and hash table
    deallocate_record_set(record_set);
    deallocate_hash_table();

    return 0;
}

void* process_records(void* arg) {
    RecordSet* record_set = (RecordSet*)arg;

    // Process the records in parallel using multiple threads
    for (int i = 0; i < record_set->num_records; ++i) {
        Record* record = &record_set->records[i];

        // Add the record to the hash table if it does not already exist
        int index = get_record_from_hash_table(record->key, record);
        if (index == -1) {
            add_record_to_hash_table(record);
        }
    }
}
