void* add_primitives(int num_offsets, int num_keys, long min_key, long max_key) {
    // Validate input parameters
    if (num_keys > MAX_KEYS || num_offsets <= 0) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the offsets and keys arrays
    long *offsets = malloc(sizeof(long) * num_offsets);
    int *keys = malloc(sizeof(int) * num_keys);
    if (offsets == NULL || keys == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the offsets array with sequential numbers starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Generate unique random keys within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        while (key == keys[i]) {
            // If the generated key is not unique, try again with a different algorithm
            key = rand() % (max_key - min_key + 1) + min_key;
        }
        keys[i] = key;
    }

    // Allocate memory for an array of record structures
    record *records = malloc(sizeof(record) * num_keys);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the records with pointers to valid elements in the offsets and keys arrays
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    int *shuffled_indices = malloc(sizeof(int) * num_keys);
    if (shuffled_indices == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_keys; i++) {
        shuffled_indices[i] = i;
    }
    shuffle(shuffled_indices, num_keys);
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[shuffled_indices[i]];
        records[i].key = keys[shuffled_indices[i]];
    }

    // Free the temporary shuffle buffer
    free(shuffled_indices);

    return records;
}

void shuffle(int *arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        int j = i + rand() / (RAND_MAX / (n - i) + 1);
        int tmp = arr[j];
        arr[j] = arr[i];
        arr[i] = tmp;
    }
}
