    record->offset = offset;
}

// Bulk update records with the given key and offset values
void bulkUpdateRecords(Record** records, size_t numRecords, int key, long offset) {
    for (size_t i = 0; i < numRecords; i++) {
        updateRecord(records[i], key, offset);
    }
}

