    // Allocate a new block of memory if the current block is full
    if (allocator->numBlocks == 0 || allocator->blockSize * allocator->numBlocks >= 5 * 1024 * 1024) {
        void* newBlock = allocateBlock(allocator);
        if (newBlock == NULL) {
