    Record* newRecord = allocateRecord(key, offset);
    if (newRecord == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }

    // Add the new record to the current block
    allocator->blocks[allocator->numBlocks - 1] = newRecord;
}

// Periodically update records with the given key and offset values
void periodicUpdate(struct BlockAllocator* allocator, int key, long offset) {
    // Bulk update records with the given key and offset values
    bulkUpdateRecords(allocator->blocks[allocator->numBlocks - 1], 10000, key, offset);
}

// Integrate the system with an external data source that provides records in batches
void integrateWithDataSource(struct BlockAllocator* allocator) {
    // Fetch a batch of records from the external data source
    Record** records = fetchRecordsFromDataSource();
    if (records == NULL) {
        return;
