// Function to dynamically allocate memory for an array of 'sensor' structures
sensor* allocate_sensors(int num_sensors) {
    // Allocate memory for the array of sensors
    sensor* sensors = (sensor*)malloc(num_sensors * sizeof(sensor));
    if (!sensors) {
        perror("Failed to allocate memory for sensors");
        exit(1);
    }

    // Initialize each sensor structure with a unique ID, accuracy, and timestamp
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].id = (char*)malloc(sizeof(char) * 256);
        if (!sensors[i].id) {
            perror("Failed to allocate memory for sensor ID");
            exit(1);
        }
        sensors[i].accuracy = 0.0;
        sensors[i].last_timestamp = time(NULL);
    }

    return sensors;
}

// Function to initialize a hash table for storing sensor data
hash_table* init_hash_table(int size) {
    // Allocate memory for the hash table
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(1);
    }

    // Initialize the size of the hash table and the data array
    table->size = size;
    table->data = (sensor**)malloc(sizeof(sensor*) * size);
    if (!table->data) {
        perror("Failed to allocate memory for hash table data");
        exit(1);
    }

    // Initialize each element of the data array to NULL
    for (int i = 0; i < size; i++) {
        table->data[i] = NULL;
    }

    return table;
}

// Function to populate a hash table with data from a network feed
void populate_hash_table(hash_table* table, int num_sensors) {
    // Allocate memory for the array of sensors
    sensor* sensors = allocate_sensors(num_sensors);

    // Read data from the network feed and store it in the hash table
    for (int i = 0; i < num_sensors; i++) {
        // Read the next set of sensor data from the network feed
        read_sensor_data(sensors + i);

        // Store the sensor data in the hash table
        store_sensor_data(table, sensors[i].id, &sensors[i]);
    }
}

// Function to read sensor data from a network feed
void read_sensor_data(sensor* sensor) {
    // Connect to the network feed and read the next set of sensor data
    int sock = connect_to_network_feed();
    if (sock < 0) {
        perror("Failed to connect to network feed");
        exit(1);
    }

    // Read the next set of sensor data from the network feed
    read(sock, sensor, sizeof(sensor));
}

// Function to store sensor data in a hash table
void store_sensor_data(hash_table* table, char* id, sensor* data) {
    // Calculate the hash value for the sensor ID
    int hash = calculate_hash(id);

    // Store the sensor data in the hash table
    table->data[hash] = data;
}

// Function to calculate a hash value for a given string
int calculate_hash(char* str) {
    // Calculate the hash value for the string
    int hash = 0;
    for (int i = 0; i < strlen(str); i++) {
        hash += str[i];
    }

    return hash % table->size;
}

// Function to free all allocated memory once the task is complete
void cleanup() {
    // Free the memory for the array of sensors
    free(sensors);

    // Free the memory for the hash table data
    for (int i = 0; i < table->size; i++) {
        if (table->data[i]) {
            free(table->data[i]);
        }
    }

    // Free the memory for the hash table itself
    free(table);
}
