#include <regex.h>

// Define the structure for a sensor reading
typedef struct {
    char* id;
    float accuracy;
    time_t timestamp;
} sensor;

// Define the hash table to store and retrieve sensor data
typedef struct {
    int size;
    sensor** data;
} hash_table;

// Function to dynamically allocate memory for an array of 'sensor' structures
sensor* create_sensors(int num_sensors) {
    // Allocate memory for the array of sensors
    sensor* sensors = (sensor*)malloc(num_sensors * sizeof(sensor));
    if (!sensors) {
        printf("Error: Failed to allocate memory for sensors\n");
        return NULL;
    }

    // Initialize the hash table to store and retrieve sensor data
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) {
        printf("Error: Failed to allocate memory for hash table\n");
        free(sensors);
        return NULL;
    }
    table->size = num_sensors;
    table->data = (sensor**)malloc(num_sensors * sizeof(sensor*));
    if (!table->data) {
        printf("Error: Failed to allocate memory for hash table data\n");
        free(sensors);
        free(table);
        return NULL;
    }

    // Populate the hash table with data from a network feed containing sensor IDs, measurements, and timestamps
    int i = 0;
    while (i < num_sensors) {
        char* id = read_sensor_id();
        float measurement = read_measurement();
        time_t timestamp = read_timestamp();
        sensors[i].id = id;
        sensors[i].accuracy = measurement;
        sensors[i].timestamp = timestamp;
        table->data[i] = &sensors[i];
        i++;
    }

    return sensors;
}

// Function to free all allocated memory once the task is complete
void destroy_sensors(sensor* sensors, hash_table* table) {
    // Free the array of sensors
    free(sensors);

    // Free the hash table data
    for (int i = 0; i < table->size; i++) {
        free(table->data[i]);
    }
    free(table->data);

    // Free the hash table itself
    free(table);
}
