const regex_chapter = /\d+/;

// Function to search for matches in the network feed and extract book names
function extract_books(feed) {
    // Initialize an object to store the extracted book names
    const books = {};

    // Loop through each line of the network feed
    for (const line of feed.split('\n')) {
        // Check if the line contains a book name using regular expressions
        const match_book = regex_book.exec(line);
        if (match_book) {
            // Extract the book name from the line
