// Define the sensor structure
typedef struct {
    char* id;
    float accuracy;
    time_t timestamp;
} sensor;

// Define the hash table for storing sensor data
typedef struct {
    char* key;
    sensor value;
} hash_table;

// Function to dynamically allocate memory for an array of sensors
sensor* allocate_sensors(int num_sensors) {
    // Allocate memory for the array of sensors
    sensor* sensors = (sensor*)malloc(num_sensors * sizeof(sensor));
    if (!sensors) {
        printf("Error: Failed to allocate memory for sensors\n");
        return NULL;
    }

    // Initialize the hash table for storing sensor data
    hash_table* hash = (hash_table*)malloc(num_sensors * sizeof(hash_table));
    if (!hash) {
        printf("Error: Failed to allocate memory for hash table\n");
        free(sensors);
        return NULL;
    }

    // Initialize the sensors and hash table
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].id = NULL;
        sensors[i].accuracy = 0.0f;
        sensors[i].timestamp = 0;
        hash[i].key = NULL;
        hash[i].value = sensors[i];
    }

    return sensors;
}

// Function to free memory allocated for an array of sensors
void free_sensors(sensor* sensors, int num_sensors) {
    // Free the memory allocated for the array of sensors
    free(sensors);

    // Free the memory allocated for the hash table
    free(hash);
}

// Function to update the hash table with data from a network feed
void update_hash_table(sensor* sensors, int num_sensors) {
    // Loop through each sensor in the array
    for (int i = 0; i < num_sensors; i++) {
        // Check if the sensor ID is already present in the hash table
        bool found = false;
        for (int j = 0; j < num_sensors; j++) {
            if (!strcmp(sensors[i].id, sensors[j].id)) {
                found = true;
                break;
            }
        }

        // If the sensor ID is not present in the hash table, add it
        if (!found) {
            hash_table* new_entry = (hash_table*)malloc(sizeof(hash_table));
            new_entry->key = sensors[i].id;
            new_entry->value = sensors[i];
            hash_table* temp = (hash_table*)realloc(hash, (num_sensors + 1) * sizeof(hash_table));
            if (!temp) {
                printf("Error: Failed to reallocate memory for hash table\n");
                free(new_entry);
                return;
            }
            hash = temp;
        }
    }
}

// Function to periodically update the stored data to reflect current sensor readings, considering network latency and data freshness
void update_data() {
    // Loop through each sensor in the array
    for (int i = 0; i < num_sensors; i++) {
        // Check if the sensor ID is present in the hash table
        bool found = false;
        for (int j = 0; j < num_sensors; j++) {
            if (!strcmp(sensors[i].id, sensors[j].id)) {
                found = true;
                break;
            }
        }

        // If the sensor ID is present in the hash table, update its data
        if (found) {
            sensors[i].accuracy = 0.0f;
            sensors[i].timestamp = time(NULL);
        }
    }
}

// Function to handle network connection failures gracefully and provide a mechanism to free all allocated memory once the task is complete
void handle_network_failure() {
    // Free the memory allocated for the array of sensors
    free_sensors(sensors, num_sensors);

    // Free the memory allocated for the hash table
    free(hash);
}

// Function to implement checksum validation for each sensor data packet received from the network feed before updating the hash table
void validate_checksum() {
    // Loop through each sensor in the array
    for (int i = 0; i < num_sensors; i++) {
        // Check if the checksum is valid
        bool valid = true;
        for (int j = 0; j < num_sensors; j++) {
            if (!strcmp(sensors[i].id, sensors[j].id)) {
                valid = false;
                break;
            }
        }

        // If the checksum is not valid, log the error and continue processing without altering the hash table
        if (!valid) {
            printf("Error: Checksum failed for sensor ID %s\n", sensors[i].id);
            continue;
        }
    }
}

// Function to incorporate a multi-threaded approach to handle concurrent updates to the hash table
void update_hash_table_concurrently() {
    // Create a mutex for protecting the hash table
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each sensor in the array
    for (int i = 0; i < num_sensors; i++) {
        // Check if the sensor ID is already present in the hash table
        bool found = false;
        for (int j = 0; j < num_sensors; j++) {
            if (!strcmp(sensors[i].id, sensors[j].id)) {
                found = true;
                break;
            }
        }

        // If the sensor ID is not present in the hash table, add it
        if (!found) {
            hash_table* new_entry = (hash_table*)malloc(sizeof(hash_table));
            new_entry->key = sensors[i].id;
            new_entry->value = sensors[i];
            pthread_mutex_lock(&mutex);
            hash_table* temp = (hash_table*)realloc(hash, (num_sensors + 1) * sizeof(hash_table));
            if (!temp) {
                printf("Error: Failed to reallocate memory for hash table\n");
                free(new_entry);
                pthread_mutex_unlock(&mutex);
                return;
            }
            hash = temp;
            pthread_mutex_unlock(&mutex);
        }
    }
}

// Function to incorporate a logging mechanism to track all operations performed on the sensor data, including successful updates, failed checksums, and memory allocation/deallocation events
void log_operations() {
