        // Log memory allocation/deallocation events
        if (sensors[i].id == NULL) {
            fprintf(log, "Memory allocation for sensor ID %s\n", sensors[i].id);
        } else {
            fprintf(log, "Memory deallocation for sensor ID %s\n", sensors[i].id);
        }
    }
}

