    for (int i = 0; i < num_sensors; i++) {
        // Check if the sensor ID is present in the hash table
        bool found = false;
        for (int j = 0; j < num_sensors; j++) {
            if (!strcmp(sensors[i].id, sensors[j].id)) {
                found = true;
                break;
            }
        }

        // If the sensor ID is present in the hash table, extract book names using regular expressions
        if (found) {
            char* data = sensors[i].data;
            int len = strlen(data);
            regcomp(&regex, "\\b[A-Z][a-z]+\\b", REG_EXTENDED | REG_ICASE);
            if (regexec(&regex, data, 2, matches, 0) == 0) {
                int start = matches[1].rm_so;
                int end = matches[1].rm_eo;
                char* book_name = strndup(data + start, end - start);
