connection* setup_connections(int num_connections) {
    if (num_connections > MAX_CONNECTIONS) {
        printf("Error: Number of connections exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for the connection structures
    connection *connections = malloc(sizeof(connection) * num_connections);
    if (connections == NULL) {
        printf("Error: Failed to allocate memory for connections\n");
        return NULL;
    }

    // Initialize the SSL contexts with appropriate configurations
    for (int i = 0; i < num_connections; i++) {
        connections[i].ssl_ctx = SSL_CTX_new(TLS_client_method());
        if (connections[i].ssl_ctx == NULL) {
            printf("Error: Failed to initialize SSL context\n");
            return NULL;
        }
