    for (int i = 0; i < num_connections; i++) {
        connections[i].socket = socket(AF_INET, SOCK_STREAM, 0);
        if (connections[i].socket == -1) {
            printf("Error: Failed to allocate socket descriptor\n");
            return NULL;
