    // Shuffle the order of the connections in the array
    int shuffled_indices[MAX_SHUFFLE_BUFFER_SIZE];
    for (int i = 0; i < num_connections; i++) {
        shuffled_indices[i] = i;
    }
    shuffle(shuffled_indices, num_connections);

    // Initialize the buffers for data transmission and reception
