// Define the maximum number of sensor readings that can be handled by the function
#define MAX_SENSOR_READINGS 100

// Define the minimum and maximum temperature ranges for random temperature generation
#define MIN_TEMPERATURE 20.0f
#define MAX_TEMPERATURE 30.0f

// Define the valid sensor identifiers and thresholds
const char* validSensorIdentifiers[] = {"sensor1", "sensor2", "sensor3"};
unsigned int validThresholds[] = {50, 60, 70};

// Define the enum for sensor statuses
enum sensorStatus {
    SENSOR_OK,
    SENSOR_WARNING,
    SENSOR_CRITICAL
};

// Define the struct for sensor readings
struct sensorReading {
    int sensorID;
    float temperature;
    char identifier;
    unsigned long timestamp;
    enum sensorStatus status;
    unsigned int threshold;
};

// Define the function to dynamically allocate memory for and initialize the arrays
void initSensorReadings(int numSensors, const char* configFilePath) {
    // Allocate memory for the sensor IDs array
    int* sensorIDs = (int*)malloc(numSensors * sizeof(int));
    if (!sensorIDs) {
        logError("Failed to allocate memory for sensor IDs");
        return;
    }

    // Allocate memory for the sensor readings array
    struct sensorReading* sensorReadings = (struct sensorReading*)malloc(numSensors * sizeof(struct sensorReading));
    if (!sensorReadings) {
        logError("Failed to allocate memory for sensor readings");
        free(sensorIDs);
        return;
    }

    // Allocate memory for the error messages array
    const char** errorMessages = (const char**)malloc(numSensors * sizeof(const char*));
    if (!errorMessages) {
        logError("Failed to allocate memory for error messages");
        free(sensorIDs);
        free(sensorReadings);
        return;
    }

    // Initialize the sensor IDs array with random values
    for (int i = 0; i < numSensors; i++) {
        sensorIDs[i] = rand() % MAX_SENSOR_READINGS + 1;
    }

    // Initialize the sensor readings array with random temperature, identifier, timestamp, status, and threshold values
    for (int i = 0; i < numSensors; i++) {
        struct sensorReading* reading = &sensorReadings[i];
        reading->sensorID = sensorIDs[i];
        reading->temperature = MIN_TEMPERATURE + ((float)rand() / (float)(RAND_MAX)) * (MAX_TEMPERATURE - MIN_TEMPERATURE);
        reading->identifier = validSensorIdentifiers[i % sizeof(validSensorIdentifiers)];
        reading->timestamp = time(NULL);
        reading->status = SENSOR_OK;
        reading->threshold = validThresholds[i % sizeof(validThresholds)];
    }

    // Deallocate memory for the error messages array if any allocation fails
    if (errorMessages) {
        free(errorMessages);
    }
}

// Define the function to deallocate all allocated memory when the function is done
void cleanupSensorReadings() {
    // Free the sensor IDs array
    free(sensorIDs);

    // Free the sensor readings array
    free(sensorReadings);
}

// Define the function to handle logging for memory allocation failures
void logError(const char* message) {
    printf("[ERROR] %s\n", message);
}
