#include <openssl/md5.h>

// Structure for storing temperature data
typedef struct node {
    long timestamp;
    double temperature;
    struct node* next;
} node;

// Function to parse temperature data from file
void parseTemperatureData(char* filename) {
    // Open the input file
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize a linked list of nodes
    node* head = NULL;
    node* current = NULL;

    // Read data from the file and populate the linked list
    while (fscanf(fp, "%ld %lf", &current->timestamp, &current->temperature) == 2) {
        if (head == NULL) {
            head = current;
        } else {
            current->next = malloc(sizeof(node));
            current = current->next;
        }
    }

    // Close the input file
    fclose(fp);

    // Calculate MD5 hash for each line of the input file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, stdin)) != -1) {
        if (line[strlen(line)-1] == '\n') {
            line[strlen(line)-1] = '\0';
        }
        char* hash = calculateMD5Hash(line);
        printf("Line %d: %s\n", read, hash);
    }

    // Free all allocated memory
    node* temp = head;
    while (temp != NULL) {
        current = temp->next;
        free(temp);
        temp = current;
    }
}

// Helper method to calculate MD5 hash of a string
char* calculateMD5Hash(char* str) {
    unsigned char* digest = NULL;
    int len = strlen(str);
    digest = (unsigned char*)malloc(16 * sizeof(unsigned char));
    if (digest == NULL) {
        printf("Error: unable to allocate memory for MD5 hash\n");
        return NULL;
    }
    MD5((unsigned char*)str, len, digest);
    char* hash = (char*)malloc(32 * sizeof(char));
    if (hash == NULL) {
        printf("Error: unable to allocate memory for MD5 hash\n");
        return NULL;
    }
    for (int i = 0; i < 16; i++) {
        sprintf(hash + i * 2, "%02x", digest[i]);
    }
    free(digest);
    return hash;
}
```
