// Structure to represent a weather event
typedef struct weatherEvent {
    char* eventName;
    double rainfallAmount;
    time_t timestamp;
} WeatherEvent;

// Function to parse the weather data from the file
WeatherEvent* parseWeatherData(const char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return NULL;
    }

    // Initialize a linked list of weather events
    WeatherEvent* head = NULL;
    WeatherEvent* current = NULL;

    // Read the data from the file and populate the linked list
    while (fscanf(fp, "%s %lf %ld", eventName, &rainfallAmount, &timestamp) == 3) {
        // Allocate memory for a new weather event
        WeatherEvent* newEvent = malloc(sizeof(WeatherEvent));
        if (newEvent == NULL) {
            printf("Error: unable to allocate memory for weather event\n");
            break;
        }

        // Initialize the fields of the new weather event
        newEvent->eventName = strdup(eventName);
        newEvent->rainfallAmount = rainfallAmount;
        newEvent->timestamp = timestamp;

        // Add the new weather event to the linked list
        if (head == NULL) {
            head = current = newEvent;
        } else {
            current->next = newEvent;
            current = newEvent;
        }
    }

    // Close the file
    fclose(fp);

    return head;
}

// Helper method to format a timestamp for logging purposes
char* formatTimestamp(time_t timestamp) {
    char* formattedTime = malloc(sizeof(char) * 20);
    if (formattedTime == NULL) {
        printf("Error: unable to allocate memory for formatted time\n");
        return NULL;
    }

    // Format the timestamp as a human-readable string
    struct tm* timeInfo = localtime(&timestamp);
    strftime(formattedTime, 20, "%Y-%m-%d %H:%M:%S", timeInfo);

    return formattedTime;
}
