                memory += sizeof(node);

                // Initialize the node with the parsed data
                new_node->timestamp = timestamp;
                new_node->temperature = temperature;
                new_node->next = NULL;

                // Add the node to the linked list
                if (head == NULL) {
                    head = new_node;
                } else {
                    tail->next = new_node;
                }
                tail = new_node;

                // Log the memory usage, traversal time, and node creation time for this iteration
                total_memory += memory;
                total_traversal_time += traversal_time;
                total_node_creation_time += node_creation_time;
            }

            // Close the file
            fclose(fp);
        } else {
            // Skip this iteration if the file path does not meet the naming convention or maximum depth limit
            continue;
        }
    }

    // Free all allocated memory once the task is complete
    free(root);
    free(head);
