bool validateFilePath(const char* file_path) {
    // Check if the file path meets the naming convention
    if (strncmp(file_path, FILE_NAMING_CONVENTION, strlen(FILE_NAMING_CONVENTION)) != 0) {
        return false;
    }

    // Check if the file path exceeds the maximum depth limit
    int depth = getDepth(file_path);
    if (depth > MAX_DEPTH) {
        return false;
    }

    return true;
}

// Define a function to validate the depth limit for the directory traversal
bool validateDepthLimit(int depth) {
    return depth <= MAX_DEPTH;
}

// Define a function to get the depth of a file path
int getDepth(const char* file_path) {
    int depth = 0;
    while (file_path[depth] != '\0') {
        if (file_path[depth] == '/') {
            depth++;
        } else {
            break;
        }
    }
    return depth;
}
