// Define constants for memory management
#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 1000000
#define MIN_KEY 0
#define MAX_KEY INT_MAX
#define SHUFFLE_DETERMINISTIC false

// Define a structure to represent a record
typedef struct {
    long *offset;
    int key;
} Record;

// Define a function to allocate memory for the offsets and keys arrays
Record* allocateMemory(int numOffsets, int numKeys) {
    // Allocate memory for the offsets array
    long *offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize the offsets array with sequential numbers starting from 0
    for (int i = 0; i < numOffsets; i++) {
        offsets[i] = i;
    }

    // Allocate memory for the keys array
    int *keys = (int*)malloc(numKeys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }

    // Initialize the keys array with unique random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < numKeys; i++) {
        int key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        while (!isUniqueKey(keys, i, key)) {
            key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        }
        keys[i] = key;
    }

    // Allocate memory for the records array and initialize it with pointers to the offsets and keys arrays
    Record *records = (Record*)malloc(numOffsets * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }
    for (int i = 0; i < numOffsets; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    shuffleRecords(records, numOffsets);

    return records;
}

// Define a function to free memory for the offsets and keys arrays
void freeMemory(Record *records) {
    // Free the offsets array
    free(records->offset);

    // Free the keys array
    free(records->key);

    // Free the records array
    free(records);
}

// Define a function to check if a key is unique
bool isUniqueKey(int *keys, int index, int key) {
    for (int i = 0; i < index; i++) {
        if (keys[i] == key) {
            return false;
        }
    }
    return true;
}

// Define a function to shuffle the order of the records in the array
void shuffleRecords(Record *records, int numOffsets) {
    // Allocate memory for a temporary buffer to hold the shuffled indices
    int *shuffleBuffer = (int*)malloc(numOffsets * sizeof(int));
    if (!shuffleBuffer) {
        printf("Error: Failed to allocate memory for shuffle buffer\n");
        return;
    }

    // Initialize the temporary buffer with sequential numbers starting from 0
    for (int i = 0; i < numOffsets; i++) {
        shuffleBuffer[i] = i;
    }

    // Shuffle the order of the records in the array using a Fisher-Yates shuffle algorithm
    for (int i = numOffsets - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = shuffleBuffer[i];
        shuffleBuffer[i] = shuffleBuffer[j];
        shuffleBuffer[j] = temp;
    }

    // Update the records array with the new order of indices
    for (int i = 0; i < numOffsets; i++) {
        int index = shuffleBuffer[i];
        records[index].offset = &offsets[i];
        records[index].key = keys[i];
    }

    // Free the temporary buffer
    free(shuffleBuffer);
}

