// Structure to store file metadata
typedef struct {
    char *name;
    size_t size;
    time_t modification_time;
} file_metadata;

// Function to manage dynamic memory for an array of file_metadata structures
void manage_memory(file_metadata **files, int num_files, int interval) {
    // Initialize the array of file metadata structures
    *files = (file_metadata *)malloc(num_files * sizeof(file_metadata));

    // Set the initial modification time for each file to 0
    for (int i = 0; i < num_files; i++) {
        (*files)[i].modification_time = 0;
    }

    // Loop indefinitely, updating the metadata for each file at the specified interval
    while (1) {
        // Sleep for the specified interval before updating the metadata
        sleep(interval);

        // Update the modification time for each file
        for (int i = 0; i < num_files; i++) {
            (*files)[i].modification_time = get_file_modification_time((*files)[i].name);
        }
    }
}

// Function to retrieve the modification time of a file
time_t get_file_modification_time(const char *filename) {
    // Use the stat function to retrieve the metadata for the file
    struct stat buf;
    if (stat(filename, &buf) == 0) {
        return buf.st_mtime;
    } else {
        return -1;
    }
}

