    return filesize;
}

// Function to handle service unavailability and incomplete data responses gracefully
void handle_service_unavailability(file_metadata **files, int num_files) {
    // Loop through each file and check if the service is available for that file
    for (int i = 0; i < num_files; i++) {
        if (!is_service_available((*files)[i].name)) {
            (*files)[i].modification_time = -1;
        }
    }
}

// Function to handle incomplete data responses gracefully
void handle_incomplete_data(file_metadata **files, int num_files) {
    // Loop through each file and check if the service returned incomplete data for that file
    for (int i = 0; i < num_files; i++) {
        if ((*files)[i].size == -1 || (*files)[i].modification_time == -1) {
            (*files)[i].modification_time = get_file_modification_time((*files)[i].name);
        }
    }
}

// Function to implement caching strategies to minimize redundant file system calls and optimize performance, especially for large directories.
void implement_caching(file_metadata **files, int num_files) {
    // Use a hash table to store the metadata for each file
    struct hash_table *hash = create_hash_table();

    // Loop through each file and add its metadata to the hash table
    for (int i = 0; i < num_files; i++) {
        add_to_hash(hash, (*files)[i].name, &(*files)[i]);
    }

    // Use the hash table to retrieve the metadata for each file instead of calling stat() multiple times
    for (int i = 0; i < num_files; i++) {
        struct file_metadata *file = get_from_hash(hash, (*files)[i].name);
        if (file != NULL) {
            (*files)[i].size = file->size;
            (*files)[i].modification_time = file->modification_time;
        } else {
            (*files)[i].size = get_file_size((*files)[i].name);
            (*files)[i].modification_time = get_file_modification_time((*files)[i].name);
        }
    }
}

// Function to handle concurrent access from multiple threads and design the function to ensure thread safety and avoid race conditions.
void handle_concurrent_access(file_metadata **files, int num_files) {
    // Use a mutex to protect the array of file metadata structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each file and update its metadata in a thread-safe manner
    for (int i = 0; i < num_files; i++) {
        pthread_mutex_lock(&mutex);
        (*files)[i].modification_time = get_file_modification_time((*files)[i].name);
        pthread_mutex_unlock(&mutex);
    }
}

// Function to optimize memory allocation and access patterns to handle high-volume data efficiently.
void optimize_memory(file_metadata **files, int num_files) {
    // Use a pool of pre-allocated file metadata structures to reduce the number of malloc() and free() calls
    struct file_metadata *pool = (struct file_metadata *)malloc(num_files * sizeof(struct file_metadata));

    // Loop through each file and allocate its metadata from the pool instead of calling malloc() multiple times
    for (int i = 0; i < num_files; i++) {
        (*files)[i] = &pool[i];
    }
}

// Function to support persistence of metadata to a file, enabling read and write operations.
void persist_metadata(file_metadata **files, int num_files) {
    // Use a file descriptor to open the metadata file for reading and writing
    int fd = open("metadata.txt", O_RDWR | O_CREAT, 0644);

    // Loop through each file and write its metadata to the file
    for (int i = 0; i < num_files; i++) {
        char *filename = (*files)[i].name;
        size_t filesize = (*files)[i].size;
        time_t modification_time = (*files)[i].modification_time;
        write(fd, &filename, sizeof(char *));
        write(fd, &filesize, sizeof(size_t));
        write(fd, &modification_time, sizeof(time_t));
    }
}
