#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 100000

typedef struct {
    long *offset;
    int key;
} record;

record* allocate_records(int num_offsets, int num_keys) {
    if (num_keys > MAX_KEYS) {
        printf("Error: Number of keys exceeds maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for offset values
    long *offsets = malloc(sizeof(long) * num_offsets);
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize offset values with sequential numbers starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Allocate memory for key values
    int *keys = malloc(sizeof(int) * num_keys);
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return NULL;
    }

    // Initialize key values with unique random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % MAX_KEYS + 1;
    }

    // Allocate memory for record structures
    record *records = malloc(sizeof(record) * num_offsets);
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record structures with offset and key values
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Shuffle the order of the record structures to ensure that the initial order is not preserved
    int *shuffled_indices = malloc(sizeof(int) * num_offsets);
    if (shuffled_indices == NULL) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Generate a random permutation of the record structures using the Fisher-Yates shuffle algorithm
    for (int i = 0; i < num_offsets; i++) {
        int j = rand() % (i + 1);
        if (j != i) {
            shuffled_indices[i] = shuffled_indices[j];
            shuffled_indices[j] = i;
        } else {
            shuffled_indices[i] = i;
        }
    }

    // Update the record structures with the shuffled indices
    for (int i = 0; i < num_offsets; i++) {
        records[shuffled_indices[i]].offset = &offsets[i];
        records[shuffled_indices[i]].key = keys[i];
    }

    // Free the temporary buffer used for shuffling
    free(shuffled_indices);

    return records;
}
