const int MAX_CAPACITY = 10000;
const int MAX_SHUFFLE_BUFFER_SIZE = 1000;
const int MAX_LEAF_NODES = 1000;

// Define a structure for the records in the octree
struct Record {
    int value;
};

// Define an octree structure with a fixed number of leaf nodes
struct Octree {
    // Allocate memory for the array of records
    std::vector<Record> records;

    // Allocate memory for the octree structure itself
    std::unique_ptr<Octree> next;
};

// Define a function to initialize an octree with records
std::unique_ptr<Octree> initialize_octree_with_records(int feature_size, int num_leaf_nodes, int data_capacity) {
    // Check if the provided data capacity exceeds the maximum allowed value
    if (data_capacity > MAX_CAPACITY) {
        std::cerr << "Error: Provided data capacity exceeds maximum allowed value." << std::endl;
        return nullptr;
    }

    // Check if the number of leaf nodes exceeds the maximum allowed value
    if (num_leaf_nodes > MAX_LEAF_NODES) {
        std::cerr << "Error: Provided number of leaf nodes exceeds maximum allowed value." << std::endl;
        return nullptr;
    }

    // Allocate memory for the array of records
    std::vector<Record> records(data_capacity);

    // Initialize each record with a random integer value within the specified range
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);
    for (auto& record : records) {
        record.value = dis(gen);
    }

    // Shuffle the order of the records in the array using a temporary buffer limited to MAX_SHUFFLE_BUFFER_SIZE elements
    std::vector<Record> shuffle_buffer(MAX_SHUFFLE_BUFFER_SIZE);
    for (int i = 0; i < data_capacity; i += MAX_SHUFFLE_BUFFER_SIZE) {
        // Copy a subset of the records into the temporary buffer
        std::copy(records.begin() + i, records.begin() + std::min(i + MAX_SHUFFLE_BUFFER_SIZE, data_capacity), shuffle_buffer.begin());

        // Shuffle the records in the temporary buffer
        std::shuffle(shuffle_buffer.begin(), shuffle_buffer.end(), gen);

        // Copy the shuffled records back into the original array
        std::copy(shuffle_buffer.begin(), shuffle_buffer.end(), records.begin() + i);
    }

    // Allocate memory for the octree structure itself
    std::unique_ptr<Octree> octree = std::make_unique<Octree>();

    // Initialize the octree with the allocated array of records
    octree->records = std::move(records);

    // Set the number of leaf nodes in the octree
    octree->num_leaf_nodes = num_leaf_nodes;

    return octree;
}
