// Structure to represent a transaction
typedef struct {
    time_t timestamp;
    unsigned long id;
    bool status;
} Transaction;

// Function to dynamically allocate memory for an array of transactions
Transaction* allocTransactions(size_t numTransactions) {
    // Allocate memory for the array of transactions
    Transaction* transactions = (Transaction*)malloc(numTransactions * sizeof(Transaction));
    if (!transactions) {
        return NULL;
    }

    // Initialize each transaction with sample data
    for (size_t i = 0; i < numTransactions; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].id = i + 1;
        transactions[i].status = false;
    }

    return transactions;
}

// Function to free the allocated memory for an array of transactions
void freeTransactions(Transaction* transactions) {
    if (transactions) {
        free(transactions);
    }
}

// Function to get a transaction by its ID
Transaction* getTransactionById(Transaction* transactions, unsigned long id) {
    for (size_t i = 0; i < numTransactions; i++) {
        if (transactions[i].id == id) {
            return &transactions[i];
        }
    }
    return NULL;
}

// Function to modify a transaction by its ID
void modifyTransactionById(Transaction* transactions, unsigned long id, bool status) {
    Transaction* transaction = getTransactionById(transactions, id);
    if (transaction) {
        transaction->status = status;
    }
}
