    free(profiles);
}

// Function to add a new activity to a profile's activities list and log the change
void add_activity(Profile *profile, char *activity) {
    // Allocate memory for the new activity
    char **new_activities = (char**)malloc((profile->num_activities + 1) * sizeof(char*));

    // Copy the existing activities to the new array
    for (int i = 0; i < profile->num_activities; i++) {
        new_activities[i] = profile->activities[i];
    }

    // Add the new activity to the end of the list
    new_activities[profile->num_activities] = activity;

    // Update the profile's activities list and log the change
    free(profile->activities);
    profile->activities = new_activities;
