}

// Function to remove an activity from a profile's activities list and log the change
void remove_activity(Profile *profile, char *activity) {
    // Find the index of the activity in the list
    int index = -1;
    for (int i = 0; i < profile->num_activities; i++) {
        if (strcmp(profile->activities[i], activity) == 0) {
            index = i;
            break;
        }
    }

    // If the activity is found, remove it from the list and log the change
    if (index != -1) {
        char **new_activities = (char**)malloc((profile->num_activities - 1) * sizeof(char*));
        for (int i = 0; i < index; i++) {
            new_activities[i] = profile->activities[i];
        }
        for (int i = index + 1; i < profile->num_activities - 1; i++) {
            new_activities[i] = profile->activities[i + 1];
        }
        free(profile->activities);
        profile->activities = new_activities;
        printf("Removed activity '%s' from user %lu\n", activity, profile->id);
    } else {
        printf("Activity '%s' not found in user %lu\n", activity, profile->id);
