    float quality_factor;
    bool valid;
} sensorData;

// Define a function to dynamically allocate memory for arrays
void allocateMemory(int numSensors, int maxNumReadings, int *numCategories, char **categoryIdentifiers) {
    // Allocate memory for the arrays
    double *values = (double *)malloc(sizeof(double) * numSensors);
    char *identifiers = (char *)malloc(sizeof(char) * numSensors);
    sensorData *sensorDataArray = (sensorData *)malloc(sizeof(sensorData) * maxNumReadings);
    char *errorMessages = (char *)malloc(sizeof(char) * 1024);
    char *statusMessages = (char *)malloc(sizeof(char) * 1024);

    // Check for memory allocation failures and handle them appropriately
    if (!values || !identifiers || !sensorDataArray || !errorMessages || !statusMessages) {
        printf("Memory allocation failed. Reason: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize the arrays with random values and timestamps
    for (int i = 0; i < numSensors; i++) {
        values[i] = rand() / (double)RAND_MAX;
        identifiers[i] = categoryIdentifiers[i % *numCategories];
        sensorDataArray[i].value = values[i];
        sensorDataArray[i].identifier = identifiers[i];
        sensorDataArray[i].timestamp = time(NULL);
        sensorDataArray[i].quality_factor = 1.0;
        sensorDataArray[i].valid = true;
    }

    // Deallocate memory when done
    free(values);
    free(identifiers);
    free(sensorDataArray);
    free(errorMessages);
    free(statusMessages);
}

// Define a function to deallocate all allocated memory
void deallocateMemory() {
    // Deallocate memory for the arrays
    free(values);
    free(identifiers);
    free(sensorDataArray);
    free(errorMessages);
    free(statusMessages);
}
