#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Custom allocator to track memory usage and deallocations
struct MemoryAllocator {
    struct MemoryBlock* blocks;
    size_t blockCount;
    size_t totalSize;
};

struct MemoryBlock {
    void* data;
    size_t size;
    bool allocated;
};

void initMemoryAllocator(struct MemoryAllocator* allocator) {
    allocator->blocks = NULL;
    allocator->blockCount = 0;
    allocator->totalSize = 0;
}

void* allocateMemory(struct MemoryAllocator* allocator, size_t size) {
    // Check if there is enough space in the existing blocks
    for (size_t i = 0; i < allocator->blockCount; ++i) {
        struct MemoryBlock* block = &allocator->blocks[i];
        if (block->size >= size && !block->allocated) {
            block->allocated = true;
            return block->data;
        }
    }

    // If there is not enough space, allocate a new block
    struct MemoryBlock* newBlock = malloc(sizeof(struct MemoryBlock));
    if (newBlock == NULL) {
        return NULL;
    }
    newBlock->data = malloc(size);
    if (newBlock->data == NULL) {
        free(newBlock);
        return NULL;
    }
    newBlock->size = size;
    newBlock->allocated = true;
    allocator->blocks = realloc(allocator->blocks, sizeof(struct MemoryBlock) * (allocator->blockCount + 1));
    if (allocator->blocks == NULL) {
        free(newBlock->data);
        free(newBlock);
        return NULL;
    }
    allocator->blocks[allocator->blockCount++] = *newBlock;
    allocator->totalSize += size;
    return newBlock->data;
}

void deallocateMemory(struct MemoryAllocator* allocator, void* data) {
    // Find the block that contains the given data and mark it as free
    for (size_t i = 0; i < allocator->blockCount; ++i) {
        struct MemoryBlock* block = &allocator->blocks[i];
        if (data >= block->data && data < block->data + block->size) {
            block->allocated = false;
            return;
        }
    }
}

void printMemoryUsage(struct MemoryAllocator* allocator) {
    printf("Total memory usage: %zu bytes\n", allocator->totalSize);
    for (size_t i = 0; i < allocator->blockCount; ++i) {
        struct MemoryBlock* block = &allocator->blocks[i];
        if (block->allocated) {
            printf("Block %zu: %zu bytes allocated\n", i, block->size);
        } else {
            printf("Block %zu: %zu bytes free\n", i, block->size);
        }
    }
}

// Function to manage dynamic memory allocation and initialization for multiple components in a scalable, distributed system
void* allocateDataPoints(struct MemoryAllocator* allocator, size_t numSensors, size_t maxNumDataPoints) {
    // Check if the configuration file is missing or malformed
    if (numSensors == 0 || maxNumDataPoints == 0) {
        return NULL;
    }

    // Allocate memory for the data points and initialize them
    size_t totalSize = sizeof(struct dataPoint) * numSensors * maxNumDataPoints;
    void* data = allocateMemory(allocator, totalSize);
    if (data == NULL) {
        return NULL;
    }
    struct dataPoint* points = data;
    for (size_t i = 0; i < numSensors * maxNumDataPoints; ++i) {
        points[i].temperature = 0.0f;
        points[i].sensorId = '\0';
        points[i].timestamp = 0;
        points[i].telemetryPacket = NULL;
        points[i].eventStatus = EVENT_STATUS_UNKNOWN;
    }

    // If the specified number of sensors exceeds the available list, use a circular buffer mechanism to reuse identifiers efficiently
    if (numSensors > maxNumDataPoints) {
        size_t numReusable = numSensors - maxNumDataPoints;
        for (size_t i = 0; i < numReusable; ++i) {
            points[maxNumDataPoints + i].sensorId = '\0';
        }
    }

    // Implement a strategy to manage the circular buffer, optimizing for speed and fairness among different sensors
    size_t currentIndex = 0;
    for (size_t i = 0; i < numSensors; ++i) {
        points[currentIndex].sensorId = 'A' + i;
        currentIndex = (currentIndex + 1) % maxNumDataPoints;
    }

    // Log memory allocation failures with the function name, line number, and reason for failure
    if (data == NULL) {
        printf("Memory allocation failed in allocateDataPoints()\n");
    }

    return data;
}

// Function to deallocate all allocated memory
void deallocateAll(struct MemoryAllocator* allocator, void* data) {
    // Free the memory allocated by allocateDataPoints()
    if (data != NULL) {
        free(data);
    }

    // Free any additional blocks that were allocated by allocateMemory()
    for (size_t i = 0; i < allocator->blockCount; ++i) {
        struct MemoryBlock* block = &allocator->blocks[i];
        if (block->data != NULL && block->allocated) {
            free(block->data);
        }
    }
}
