        printf("Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the offsets and keys arrays
    long *offsets = malloc(sizeof(long) * num_offsets);
    int *keys = malloc(sizeof(int) * num_keys);
    if (offsets == NULL || keys == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
