        offsets[i] = i;
    }

    // Generate unique random keys within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        while (!is_unique(keys, i, key)) {
            key = rand() % (max_key - min_key + 1) + min_key;
        }
        keys[i] = key;
    }

    // Allocate memory for the records array and initialize it with pointers to offsets and keys
    record *records = malloc(sizeof(record) * num_offsets);
    if (records == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i];
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    int *shuffled_indices = malloc(sizeof(int) * num_offsets);
    if (shuffled_indices == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        shuffled_indices[i] = i;
    }
    shuffle(shuffled_indices, num_offsets);
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[shuffled_indices[i]];
        records[i].key = keys[shuffled_indices[i]];
    }

    // Free the temporary buffers used for shuffling
    free(shuffled_indices);

    return records;
}

int is_unique(int *keys, int i, int key) {
    for (int j = 0; j < i; j++) {
        if (keys[j] == key) {
            return 0;
        }
    }
    return 1;
}

void shuffle(int *arr, int n) {
    // Fisher-Yates shuffle algorithm
    for (int i = 0; i < n - 1; i++) {
        int j = i + rand() / (RAND_MAX / (n - i) + 1);
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }
}
