int init_connection_pool(size_t max_connections, size_t num_requests) {
    if (max_connections > MAX_CONNECTIONS || num_requests > MAX_LOG_ENTRIES) {
        printf("Error: Invalid configuration. Exiting...\n");
        exit(1);
    }

    sock_t* sockets = allocate_memory(sizeof(sock_t) * max_connections);
    log_entry_t* log_entries = allocate_memory(sizeof(log_entry_t) * num_requests);
    connection_record* connections = allocate_memory(sizeof(connection_record) * max_connections);

    for (size_t i = 0; i < max_connections; i++) {
        sockets[i].fd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockets[i].fd == -1) {
            printf("Error: Failed to create socket. Exiting...\n");
            exit(1);
        }
    }

    for (size_t i = 0; i < num_requests; i++) {
        log_entries[i].timestamp = time(NULL);
        log_entries[i].request = NULL;
        log_entries[i].response = NULL;
    }

    for (size_t i = 0; i < max_connections; i++) {
        connections[i].socket = &sockets[i];
        connections[i].log_entry = &log_entries[i];
    }

    return connections;
}

void deallocate_connection_pool(connection_record* connections) {
    for (size_t i = 0; i < MAX_CONNECTIONS; i++) {
        close(connections[i].socket->fd);
    }
    deallocate_memory(connections);
}

int init_log_records(size_t num_requests) {
