        printf("Error: Invalid configuration. Exiting...\n");
        exit(1);
    }

    log_entry_t* log_entries = allocate_memory(sizeof(log_entry_t) * num_requests);

    for (size_t i = 0; i < num_requests; i++) {
        log_entries[i].timestamp = time(NULL);
        log_entries[i].request = NULL;
        log_entries[i].response = NULL;
    }

    return log_entries;
}

void deallocate_log_records(log_entry_t* log_entries) {
    deallocate_memory(log_entries);
}

int init_connection_records(size_t max_connections, size_t num_requests) {
    if (max_connections > MAX_CONNECTIONS || num_requests > MAX_LOG_ENTRIES) {
        printf("Error: Invalid configuration. Exiting...\n");
        exit(1);
    }

    connection_record* connections = allocate_memory(sizeof(connection_record) * max_connections);

    for (size_t i = 0; i < max_connections; i++) {
        connections[i].socket = NULL;
        connections[i].log_entry = NULL;
    }

    return connections;
}

void deallocate_connection_records(connection_record* connections) {
