int init_shuffle_buffer(size_t num_requests) {
    if (num_requests > MAX_SHUFFLE_BUFFER_SIZE) {
        printf("Error: Invalid configuration. Exiting...\n");
        exit(1);
    }

    int* shuffle_buffer = allocate_memory(sizeof(int) * num_requests);

    for (size_t i = 0; i < num_requests; i++) {
        shuffle_buffer[i] = i;
    }

    return shuffle_buffer;
}

void deallocate_shuffle_buffer(int* shuffle_buffer) {
    deallocate_memory(shuffle_buffer);
}

int init_load_balancer(size_t max_connections, size_t num_requests) {
    if (max_connections > MAX_CONNECTIONS || num_requests > MAX_LOG_ENTRIES) {
        printf("Error: Invalid configuration. Exiting...\n");
        exit(1);
    }

    int* load_balancer = allocate_memory(sizeof(int) * max_connections);

    for (size_t i = 0; i < max_connections; i++) {
        load_balancer[i] = i % num_requests;
    }

    return load_balancer;
}

void deallocate_load_balancer(int* load_balancer) {
    deallocate_memory(load_balancer);
}
