        widgets[i].text_label = "Default Label";
        widgets[i].event_handler = NULL;
    }

    // Allocate memory for an array of file metadata structures
    file_metadata* files = (file_metadata*)malloc(num_files * sizeof(file_metadata));
    if (!files) {
