struct record {
    int key;
};

void allocate_memory(long* offset_array, int* key_array, struct record** record_array, size_t num_records) {
    // Allocate memory for the offset array
    offset_array = (long*)malloc(num_records * sizeof(long));
    if (!offset_array) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the key array
    key_array = (int*)malloc(num_records * sizeof(int));
    if (!key_array) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the record array
    record_array = (struct record**)malloc(num_records * sizeof(struct record*));
    if (!record_array) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize the random number generator
    srand(time(NULL));

    // Initialize the offset and key arrays with random values within a specified range
    for (size_t i = 0; i < num_records; i++) {
        offset_array[i] = rand() % 1000000;
        key_array[i] = rand() % 1000000;
        record_array[i] = malloc(sizeof(struct record));
        if (!record_array[i]) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            free(offset_array);
            free(key_array);
            free(record_array);
            return;
        }
        record_array[i]->key = rand() % 1000000;
    }
}
