    }

    // Close the default theme file
    fclose(fp);

    // Initialize the theme cache with the default theme
    struct ThemeCacheEntry* entry = malloc(sizeof(struct ThemeCacheEntry));
    entry->offset = buffer;
    entry->key = 0;
    addToThemeCache(entry);
}

// Function to add a new theme cache entry
void addToThemeCache(struct ThemeCacheEntry* entry) {
    // Check if the cache is full
    if (themeCacheFull()) {
        printf("Error: theme cache is full\n");
        return;
    }

    // Add the new entry to the cache
    themeCache[cacheIndex] = entry;
    cacheIndex++;
}

// Function to check if the theme cache is full
int themeCacheFull() {
    return cacheIndex == CACHE_SIZE;
}

// Function to retrieve a theme from the cache
struct ThemeCacheEntry* getFromThemeCache(int key) {
    // Check if the cache is empty
    if (cacheIndex == 0) {
        printf("Error: theme cache is empty\n");
        return NULL;
    }

    // Search for the entry with the specified key
    int i = 0;
    while (i < cacheIndex && themeCache[i]->key != key) {
        i++;
    }

    // Return the entry if found, otherwise return NULL
    if (i == cacheIndex) {
        printf("Error: theme with key %d not found\n", key);
        return NULL;
    } else {
        return themeCache[i];
    }
}

// Function to update a user's password
void updatePassword(char* newPassword) {
    // Validate the new password strength according to predefined criteria
    if (!validatePasswordStrength(newPassword)) {
        printf("Error: invalid password strength\n");
        return;
