// Function to validate a password strength according to predefined criteria
int validatePasswordStrength(char* password) {
    // Check if the password is at least 8 characters long
    if (strlen(password) < 8) {
        printf("Error: password must be at least 8 characters long\n");
        return 0;
    }

    // Check if the password contains at least one uppercase letter, one lowercase letter, and one number
    int hasUpper = 0, hasLower = 0, hasNumber = 0;
    for (int i = 0; i < strlen(password); i++) {
        char c = password[i];
        if (c >= 'A' && c <= 'Z') {
            hasUpper = 1;
        } else if (c >= 'a' && c <= 'z') {
            hasLower = 1;
        } else if (c >= '0' && c <= '9') {
            hasNumber = 1;
        }
    }
    if (!hasUpper || !hasLower || !hasNumber) {
        printf("Error: password must contain at least one uppercase letter, one lowercase letter, and one number\n");
        return 0;
    }

    // Check if the password contains at most two consecutive identical characters
    int hasConsecutive = 0;
    for (int i = 1; i < strlen(password); i++) {
        char c1 = password[i - 1], c2 = password[i];
        if (c1 == c2) {
            hasConsecutive = 1;
            break;
        }
    }
    if (hasConsecutive) {
        printf("Error: password must not contain more than two consecutive identical characters\n");
        return 0;
    }

    // Check if the password contains at most three repeating characters
    int hasRepeating = 0;
    for (int i = 1; i < strlen(password); i++) {
        char c1 = password[i - 1], c2 = password[i];
        if (c1 == c2) {
            hasRepeating = 1;
            break;
        }
    }
    if (hasRepeating) {
        printf("Error: password must not contain more than three repeating characters\n");
        return 0;
    }

    // Check if the password contains at most two identical sequences of four or more characters
    int hasSequence = 0;
    for (int i = 1; i < strlen(password); i++) {
        char c1 = password[i - 1], c2 = password[i];
        if (c1 == c2) {
            hasSequence = 1;
            break;
        }
    }
    if (hasSequence) {
        printf("Error: password must not contain more than two identical sequences of four or more characters\n");
        return 0;
    }

    // Check if the password contains at most one character from a list of disallowed characters
    char* disallowed = "!@#$%^&*()_+-=[]{}|;':\"<>,./?`~";
    for (int i = 0; i < strlen(disallowed); i++) {
        if (strchr(password, disallowed[i])) {
            printf("Error: password must not contain any of the following characters: %s\n", disallowed);
            return 0;
        }
    }

    // Check if the password is at least 8 characters long and contains at least one uppercase letter, one lowercase letter, and one number
    if (strlen(password) < 8 || !hasUpper || !hasLower || !hasNumber) {
        printf("Error: password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, and one number\n");
        return 0;
    }

    // Password is valid
    return 1;
}

