<?php

// Define constants for database connection parameters
define('DB_HOST', 'localhost');
define('DB_USERNAME', 'username');
define('DB_PASSWORD', 'password');
define('DB_DATABASE', 'database');

// Function to authenticate a user and retrieve their password hash
function authenticateUser($username, $password) {
    // Connect to the database
    $conn = new mysqli(DB_HOST, DB_USERNAME, DB_PASSWORD, DB_DATABASE);
    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Prepare and execute a query to retrieve the user's password hash
    $stmt = $conn->prepare("SELECT password FROM users WHERE username = ?");
    $stmt->bind_param("s", $username);
    $stmt->execute();
    $result = $stmt->get_result();

    // Check if the user exists in the database
    if ($result->num_rows == 0) {
        return NULL;
    }

    // Retrieve the user's password hash and close the connection
    $passwordHash = $result->fetch_assoc()['password'];
    $conn->close();

    // Return the user's password hash
    return $passwordHash;
}

// Function to update a user's password
function updatePassword($username, $newPassword) {
    // Connect to the database
    $conn = new mysqli(DB_HOST, DB_USERNAME, DB_PASSWORD, DB_DATABASE);
    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Prepare and execute a query to update the user's password hash
    $stmt = $conn->prepare("UPDATE users SET password = ? WHERE username = ?");
    $stmt->bind_param("ss", $newPassword, $username);
    $stmt->execute();

    // Close the connection
    $conn->close();
}
