void* allocate_memory(size_t num_offsets, size_t num_keys, size_t num_records) {
    // Calculate the total size of the memory block required
    size_t total_size = (num_offsets * sizeof(long)) + (num_keys * sizeof(int)) + (num_records * sizeof(record));

    // Allocate the memory block using malloc()
    void* mem_block = malloc(total_size);

    // Initialize the random number generator seed for reproducible results
    srand(time(NULL));

    // Initialize the offset values
    long* offsets = (long*)mem_block;
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % 1000;
    }

    // Initialize the key values
    int* keys = (int*)((char*)mem_block + num_offsets * sizeof(long));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000;
    }

    // Initialize the record structures
    record* records = (record*)((char*)mem_block + (num_offsets * sizeof(long)) + (num_keys * sizeof(int)));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
        records[i].flag = 'A';
    }

    // Validate the memory block is correctly initialized and accessible
