        if (offsets[i] < 0 || offsets[i] > 1000) {
            printf("Offset value %d is out of range\n", i);
            return NULL;
        }
    }
    for (int i = 0; i < num_keys; i++) {
        if (keys[i] < 0 || keys[i] > 1000) {
            printf("Key value %d is out of range\n", i);
            return NULL;
        }
    }
    for (int i = 0; i < num_records; i++) {
        if (records[i].value < 0 || records[i].value > 1000) {
