#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define MAX_RECORDS 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 100000

typedef struct {
    int socket;
    char* request_handler;
    char* response_buffer;
} network_client_t;

typedef struct {
    long offset;
    int key;
    double timestamp;
} record_t;

typedef struct {
    pthread_mutex_t mutex;
    int num_connections;
    int num_records;
    network_client_t* clients;
    record_t* records;
    char* shuffle_buffer;
} connection_pool_t;

connection_pool_t* create_connection_pool(int num_connections, int num_records) {
    if (num_connections > MAX_CONNECTIONS || num_records > MAX_RECORDS) {
        printf("Invalid configuration: number of connections or records exceeds maximum allowed value\n");
        return NULL;
    }

    connection_pool_t* pool = malloc(sizeof(connection_pool_t));
    if (!pool) {
        printf("Failed to allocate memory for connection pool\n");
        return NULL;
    }

    pool->num_connections = num_connections;
    pool->num_records = num_records;
    pool->clients = malloc(sizeof(network_client_t) * num_connections);
    if (!pool->clients) {
        printf("Failed to allocate memory for network clients\n");
        free(pool);
        return NULL;
    }

    pool->records = malloc(sizeof(record_t) * num_records);
    if (!pool->records) {
        printf("Failed to allocate memory for records\n");
        free(pool->clients);
        free(pool);
        return NULL;
    }

    pool->shuffle_buffer = malloc(sizeof(char) * MAX_SHUFFLE_BUFFER_SIZE);
    if (!pool->shuffle_buffer) {
        printf("Failed to allocate memory for shuffle buffer\n");
        free(pool->records);
        free(pool->clients);
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);

    return pool;
}

void destroy_connection_pool(connection_pool_t* pool) {
    if (!pool) {
        return;
    }

    free(pool->shuffle_buffer);
    free(pool->records);
    free(pool->clients);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

int allocate_memory(connection_pool_t* pool) {
    if (!pool) {
        return -1;
    }

    for (int i = 0; i < pool->num_connections; i++) {
        network_client_t* client = &pool->clients[i];
        client->socket = socket(AF_INET, SOCK_STREAM, 0);
        if (client->socket == -1) {
            printf("Failed to allocate memory for socket\n");
            return -1;
        }
    }

    for (int i = 0; i < pool->num_records; i++) {
        record_t* record = &pool->records[i];
        record->offset = rand() % MAX_OFFSET;
        record->key = rand() % MAX_KEY;
        record->timestamp = time(NULL);
    }

    return 0;
}

int deallocate_memory(connection_pool_t* pool) {
    if (!pool) {
        return -1;
    }

    for (int i = 0; i < pool->num_connections; i++) {
        network_client_t* client = &pool->clients[i];
        close(client->socket);
    }

    free(pool->shuffle_buffer);
    free(pool->records);
    free(pool->clients);

    return 0;
}

int manage_memory(connection_pool_t* pool) {
    if (!pool) {
        return -1;
    }

    int num_connections = pool->num_connections;
    int num_records = pool->num_records;

    // Allocate memory for network clients and records
    allocate_memory(pool);

    // Initialize shuffle buffer with random indices
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        pool->shuffle_buffer[i] = rand() % num_records;
    }

    return 0;
}

void* manage_connections(void* args) {
    connection_pool_t* pool = (connection_pool_t*)args;
    if (!pool) {
        return NULL;
    }

    while (1) {
        // Acquire lock on mutex
        pthread_mutex_lock(&pool->mutex);

        // Check for any new connections or disconnections
        for (int i = 0; i < pool->num_connections; i++) {
            network_client_t* client = &pool->clients[i];
            if (client->socket == -1) {
                continue;
            }

            // Handle new connections
            if (client->socket == 0) {
                client->socket = socket(AF_INET, SOCK_STREAM, 0);
                if (client->socket == -1) {
                    printf("Failed to allocate memory for socket\n");
                    continue;
                }
            }

            // Handle disconnections
            else if (client->socket > 0 && client->socket < MAX_CONNECTIONS) {
                close(client->socket);
                client->socket = -1;
            }
        }

        // Release lock on mutex
        pthread_mutex_unlock(&pool->mutex);
    }
}

void* manage_records(void* args) {
    connection_pool_t* pool = (connection_pool_t*)args;
    if (!pool) {
        return NULL;
    }

    while (1) {
        // Acquire lock on mutex
        pthread_mutex_lock(&pool->mutex);

        // Shuffle record indices in shuffle buffer
        for (int i = 0; i < pool->num_records; i++) {
            int j = rand() % pool->num_records;
            char temp = pool->shuffle_buffer[i];
            pool->shuffle_buffer[i] = pool->shuffle_buffer[j];
            pool->shuffle_buffer[j] = temp;
        }

        // Release lock on mutex
        pthread_mutex_unlock(&pool->mutex);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        printf("Usage: %s <num_connections> <num_records>\n", argv[0]);
        return -1;
    }

    int num_connections = atoi(argv[1]);
    int num_records = atoi(argv[2]);

    connection_pool_t* pool = create_connection_pool(num_connections, num_records);
    if (!pool) {
        printf("Failed to create connection pool\n");
        return -1;
    }

    // Manage memory for network clients and records
    manage_memory(pool);

    // Start threads for managing connections and records
    pthread_t conn_thread, rec_thread;
    pthread_create(&conn_thread, NULL, manage_connections, pool);
    pthread_create(&rec_thread, NULL, manage_records, pool);

    // Wait for threads to finish
    pthread_join(conn_thread, NULL);
    pthread_join(rec_thread, NULL);

    // Deallocate memory for connection pool
    destroy_connection_pool(pool);

    return 0;
}
