}

int get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (int)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
}

void assign_unique_key(cache_entry_t* entry) {
    int current_time = get_current_time();
    sprintf(entry->key, "entry%d", current_time);
}

int validate_configuration(int num_entries, int request_processing_interval, size_t combined_memory_block_size) {
    if (num_entries > MAX_ENTRIES) {
        printf("Error: Number of entries exceeds maximum allowed value\n");
        return 0;
    }

    if (request_processing_interval < 1) {
        printf("Error: Request processing interval must be greater than or equal to 1\n");
        return 0;
    }

    if (combined_memory_block_size > MAX_ENTRIES * sizeof(cache_entry_t)) {
        printf("Error: Combined memory block size exceeds maximum allowed value\n");
        return 0;
    }

    return 1;
}

void manage_eviction_queue(cache_t* cache) {
    int evict_queue_size = cache->num_entries - cache->num_entries / 4;
    if (evict_queue_size > MAX_EVICT_QUEUE_SIZE) {
        evict_queue_size = MAX_EVICT_QUEUE_SIZE;
    }

    for (int i = 0; i < evict_queue_size; i++) {
        cache->evict_queue[i] = cache->entries[i].key;
    }
}

