// Define the function to manage dynamic memory allocation and initialization for networked data processing
void initialize_data_processing(int num_units, int unit_size) {
    // Validate the input parameters
    if (num_units <= 0 || unit_size <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the array of data processing units
    stream_metadata* units = malloc(sizeof(stream_metadata) * num_units);
    if (units == NULL) {
        printf("Failed to allocate memory for data processing units\n");
        return;
    }

    // Initialize the metadata for each unit
    for (int i = 0; i < num_units; i++) {
        units[i].socket_fd = -1;
        units[i].data_buffer = NULL;
        units[i].buffer_size = 0;
        units[i].is_active = false;
    }

    // Allocate memory for the data buffer for each unit
    for (int i = 0; i < num_units; i++) {
        units[i].data_buffer = malloc(unit_size);
        if (units[i].data_buffer == NULL) {
