    // Initialize the memory usage monitoring mechanisms
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Start the data processing threads
    for (int i = 0; i < num_units; i++) {
        pthread_create(&threads[i], NULL, process_data, &units[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_units; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up the memory usage monitoring mechanisms
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    // Free the allocated memory for the data processing units and the data buffer
    free(units);
}

// Define the function to process data in a separate thread
void* process_data(void* args) {
    stream_metadata* unit = (stream_metadata*)args;

    // Initialize the network socket connection for the unit
    if (unit->socket_fd == -1) {
        printf("Failed to initialize network socket\n");
        return NULL;
    }

    // Set up the data buffer for the unit
    if (unit->data_buffer == NULL) {
        printf("Failed to allocate memory for data buffer\n");
        return NULL;
    }

    // Set up the callback functions for error handling and data processing events
    if (unit->error_callback == NULL || unit->data_callback == NULL) {
        printf("Failed to set up callback functions\n");
        return NULL;
    }

    // Start the data processing loop
    while (true) {
        // Read data from the network socket
        int bytes_read = read(unit->socket_fd, unit->data_buffer, unit->buffer_size);
        if (bytes_read < 0) {
            printf("Failed to read data from network socket\n");
            break;
        } else if (bytes_read == 0) {
            // Handle the scenario where the data source is intermittent or unavailable
            printf("Data source is unavailable, waiting for next update\n");
            sleep(1);
            continue;
        }

        // Process the received data
        unit->data_callback(unit->data_buffer, bytes_read);
    }

    // Clean up the network socket connection and the data buffer
    close(unit->socket_fd);
    free(unit->data_buffer);

    return NULL;
}
