    for (int i = 0; i < num_devices; i++) {
        devices[i].id = malloc(16 * sizeof(char));
        if (!devices[i].id) {
            perror("Failed to allocate memory for device ID");
            return NULL;
        }
        sprintf(devices[i].id, "device%d", i);
        devices[i].capacity = 1000;
        devices[i].last_updated = time(NULL);
    }

    // Initialize a bloom filter to efficiently detect duplicates
    bloom_filter_t* bloom_filter = (bloom_filter_t*)malloc(sizeof(bloom_filter_t));
    if (!bloom_filter) {
        perror("Failed to allocate memory for bloom filter");
        return NULL;
    }
    bloom_filter->bits = malloc(num_devices * sizeof(unsigned long));
    if (!bloom_filter->bits) {
        perror("Failed to allocate memory for bloom filter bits");
        return NULL;
    }
    bloom_filter->num_bits = num_devices;

    // Initialize a red-black tree to maintain ordered device data based on their last updated time
    rb_tree_t* rb_tree = (rb_tree_t*)malloc(sizeof(rb_tree_t));
    if (!rb_tree) {
        perror("Failed to allocate memory for red-black tree");
        return NULL;
    }
    rb_tree->data = devices;
    rb_tree->size = num_devices;

    // Initialize a logging system to track all operations performed on the device data
    logging_system_t* logging_system = (logging_system_t*)malloc(sizeof(logging_system_t));
    if (!logging_system) {
        perror("Failed to allocate memory for logging system");
        return NULL;
    }
    logging_system->log_file = "device_data.log";
    logging_system->log_fp = fopen(logging_system->log_file, "a+");
    if (!logging_system->log_fp) {
        perror("Failed to open log file for writing");
        return NULL;
    }

    // Return the initialized array of devices and the logging system
    return devices;
}

// Function to populate the data structures with information from a distributed data feed
void populate_data(device_t* devices, int num_devices, bloom_filter_t* bloom_filter, rb_tree_t* rb_tree, logging_system_t* logging_system) {
    // Loop through each device in the distributed data feed and update the corresponding device in the array of devices
    for (int i = 0; i < num_devices; i++) {
        // Check if the device is a duplicate using the bloom filter
        if (!bloom_filter_check(bloom_filter, devices[i].id)) {
            // Add the device to the red-black tree based on its last updated time
            rb_tree_insert(rb_tree, &devices[i]);
            // Log the successful update of the device data
            logging_system_log(logging_system, "Successfully updated device %s with capacity %d and last updated time %ld", devices[i].id, devices[i].capacity, devices[i].last_updated);
        } else {
            // Log the failed checksum validation of the device data
            logging_system_log(logging_system, "Failed to validate checksum for device %s with capacity %d and last updated time %ld", devices[i].id, devices[i].capacity, devices[i].last_updated);
        }
    }
}

// Function to handle connection failures gracefully and provide a mechanism to free all allocated memory once the task is complete
void cleanup(device_t* devices, int num_devices, bloom_filter_t* bloom_filter, rb_tree_t* rb_tree, logging_system_t* logging_system) {
    // Free the memory allocated for the array of devices and the logging system
    free(devices);
    free(logging_system->log_fp);
    free(logging_system);

    // Free the memory allocated for the bloom filter and red-black tree
    free(bloom_filter->bits);
    free(rb_tree->data);
}

// Function to periodically update the stored data to reflect current device states, considering network latency and data freshness
void update_data(device_t* devices, int num_devices, bloom_filter_t* bloom_filter, rb_tree_t* rb_tree, logging_system_t* logging_system) {
    // Loop through each device in the red-black tree and update its last updated time if necessary
    for (int i = 0; i < num_devices; i++) {
        // Check if the device has been updated since the last update
        if (rb_tree->data[i].last_updated != devices[i].last_updated) {
            // Update the device's capacity and last updated time in the array of devices
            devices[i].capacity = rb_tree->data[i].capacity;
            devices[i].last_updated = rb_tree->data[i].last_updated;
            // Log the successful update of the device data
            logging_system_log(logging_system, "Successfully updated device %s with capacity %d and last updated time %ld", devices[i].id, devices[i].capacity, devices[i].last_updated);
        } else {
            // Log that the device has not been updated since the last update
            logging_system_log(logging_system, "Device %s with capacity %d and last updated time %ld has not been updated since the last update", devices[i].id, devices[i].capacity, devices[i].last_updated);
        }
    }
}

// Function to extract specific keywords related to system health from device messages using a regular expression pattern defined at the top of the file
void extract_keywords(device_t* devices, int num_devices, bloom_filter_t* bloom_filter, rb_tree_t* rb_tree, logging_system_t* logging_system) {
    // Loop through each device in the array of devices and extract keywords related to system health from its message
    for (int i = 0; i < num_devices; i++) {
        // Check if the device's message contains any keywords related to system health using the regular expression pattern defined at the top of the file
        if (regex_match(devices[i].message, KEYWORD_PATTERN)) {
            // Log that a keyword has been found in the device's message
            logging_system_log(logging_system, "Found keyword %s in device %s with capacity %d and last updated time %ld", devices[i].id, devices[i].capacity, devices[i].last_updated);
        } else {
            // Log that no keywords have been found in the device's message
            logging_system_log(logging_system, "No keywords found in device %s with capacity %d and last updated time %ld", devices[i].id, devices[i].capacity, devices[i].last_updated);
        }
    }
}
