#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdio.h>
#include <stdbool.h>

// Define a structure for sensor data
typedef struct {
    char* id;
    float accuracy;
    time_t timestamp;
} sensor;

// Define a hash table to store the sensor data
static sensor** sensors = NULL;
static size_t num_sensors = 0;

// Function to allocate memory for an array of sensor structures
sensor** alloc_sensors(size_t n) {
    // Allocate memory for the array of pointers
    sensor** arr = malloc(n * sizeof(sensor*));
    if (!arr) {
        printf("Error: Failed to allocate memory for sensor array\n");
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    for (size_t i = 0; i < n; i++) {
        arr[i] = NULL;
    }

    return arr;
}

// Function to free memory allocated by alloc_sensors()
void free_sensors(sensor** sensors, size_t n) {
    // Free each pointer in the array
    for (size_t i = 0; i < n; i++) {
        if (sensors[i]) {
            free(sensors[i]);
        }
    }

    // Free the array of pointers
    free(sensors);
}

// Function to add a new sensor to the hash table
bool add_sensor(const char* id, float accuracy, time_t timestamp) {
    // Check if the sensor ID already exists in the hash table
    for (size_t i = 0; i < num_sensors; i++) {
        if (strcmp(id, sensors[i]->id) == 0) {
            return false;
        }
    }

    // Allocate memory for the new sensor structure
    sensor* new_sensor = malloc(sizeof(sensor));
    if (!new_sensor) {
        printf("Error: Failed to allocate memory for new sensor\n");
        return false;
    }

    // Initialize the new sensor structure
    new_sensor->id = strdup(id);
    new_sensor->accuracy = accuracy;
    new_sensor->timestamp = timestamp;

    // Add the new sensor to the hash table
    sensors[num_sensors++] = new_sensor;

    return true;
}

// Function to remove a sensor from the hash table
bool remove_sensor(const char* id) {
    // Find the index of the sensor in the hash table
    size_t i = 0;
    for (; i < num_sensors; i++) {
        if (strcmp(id, sensors[i]->id) == 0) {
            break;
        }
    }

    // If the sensor was not found in the hash table, return false
    if (i == num_sensors) {
        return false;
    }

    // Free the memory allocated for the sensor structure
    free(sensors[i]);

    // Shift all subsequent sensors down one index
    for (size_t j = i; j < num_sensors - 1; j++) {
        sensors[j] = sensors[j + 1];
    }

    // Decrement the number of sensors in the hash table
    num_sensors--;

    return true;
}

// Function to retrieve a sensor from the hash table by ID
sensor* get_sensor(const char* id) {
    // Find the index of the sensor in the hash table
    size_t i = 0;
    for (; i < num_sensors; i++) {
        if (strcmp(id, sensors[i]->id) == 0) {
            break;
        }
    }

    // If the sensor was not found in the hash table, return NULL
    if (i == num_sensors) {
        return NULL;
    }

    return sensors[i];
}

// Function to update a sensor's measurement accuracy and timestamp
bool update_sensor(const char* id, float accuracy, time_t timestamp) {
    // Find the index of the sensor in the hash table
    size_t i = 0;
    for (; i < num_sensors; i++) {
        if (strcmp(id, sensors[i]->id) == 0) {
            break;
        }
    }

    // If the sensor was not found in the hash table, return false
    if (i == num_sensors) {
        return false;
    }

    // Update the sensor's measurement accuracy and timestamp
    sensors[i]->accuracy = accuracy;
    sensors[i]->timestamp = timestamp;

    return true;
}

// Function to clear all allocated resources before terminating the function
void terminate() {
    // Free the memory allocated for the hash table
    free_sensors(sensors, num_sensors);

    // Set the number of sensors to 0
    num_sensors = 0;
}
