void* allocate_and_initialize_memory(int num_offsets, int num_keys) {
    // Allocate memory for long integer values
    long *offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return NULL;
    }

    // Initialize long integer values with sequential numbers starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Allocate memory for int keys
