    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }

    // Ensure that the total number of keys does not exceed MAX_KEYS
    if (num_keys > MAX_KEYS) {
        printf("Error: Too many keys\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Allocate memory for record structures
