        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record structures with pointers to one of the long offset values and one of the int keys
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = &offsets[i];
        records[i].key = keys[i % num_keys];
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    int *shuffle_buffer = (int*)malloc(MAX_SHUFFLE_BUFFER_SIZE * sizeof(int));
    if (!shuffle_buffer) {
        printf("Error: Failed to allocate memory for shuffle buffer\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Optimize the shuffle algorithm to minimize cache misses and ensure efficient scaling with large numbers of records
    for (int i = 0; i < num_offsets; i++) {
        int random_index = rand() % num_offsets;
        while (shuffle_buffer[random_index] != -1) {
            random_index = rand() % num_offsets;
        }
        shuffle_buffer[i] = random_index;
    }

    // Reassign keys if any key is not unique after initial assignment
    for (int i = 0; i < num_offsets; i++) {
        int random_index = rand() % num_offsets;
        while (shuffle_buffer[random_index] != -1) {
            random_index = rand() % num_offsets;
        }
        records[i].key = keys[random_index];
    }

    // Free shuffle buffer memory
    free(shuffle_buffer);

    return records;
}

