use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

struct Logger {
    level: LogLevel,
    format: LogFormat,
    aggregator: Option<Aggregator>,
}

impl Logger {
    fn new(level: LogLevel, format: LogFormat) -> Self {
        Self {
            level,
            format,
            aggregator: None,
        }
    }

    fn with_aggregator(self, aggregator: Aggregator) -> Self {
        Self {
            aggregator: Some(aggregator),
            ..self
        }
    }

    fn log(&self, message: &str) {
        let mut aggregator = self.aggregator.as_ref().unwrap();
        let mut lock = aggregator.lock().unwrap();
        match self.level {
            LogLevel::Error => lock.error(message),
            LogLevel::Warn => lock.warn(message),
            LogLevel::Info => lock.info(message),
            LogLevel::Debug => lock.debug(message),
            LogLevel::Trace => lock.trace(message),
        }
    }
}

struct Aggregator {
    log_level: LogLevel,
    log_format: LogFormat,
    external_service: Option<ExternalService>,
}

impl Aggregator {
    fn new(log_level: LogLevel, log_format: LogFormat) -> Self {
        Self {
            log_level,
            log_format,
            external_service: None,
        }
    }

    fn with_external_service(self, external_service: ExternalService) -> Self {
        Self {
            external_service: Some(external_service),
            ..self
        }
    }

    fn error(&mut self, message: &str) {
        match self.log_level {
            LogLevel::Error => println!("{}", message),
            _ => (),
        }
        if let Some(external_service) = self.external_service.as_ref() {
            external_service.error(message);
        }
    }

    fn warn(&mut self, message: &str) {
        match self.log_level {
            LogLevel::Warn => println!("{}", message),
            _ => (),
        }
        if let Some(external_service) = self.external_service.as_ref() {
            external_service.warn(message);
        }
    }

    fn info(&mut self, message: &str) {
        match self.log_level {
            LogLevel::Info => println!("{}", message),
            _ => (),
        }
        if let Some(external_service) = self.external_service.as_ref() {
            external_service.info(message);
        }
    }

    fn debug(&mut self, message: &str) {
        match self.log_level {
            LogLevel::Debug => println!("{}", message),
            _ => (),
        }
        if let Some(external_service) = self.external_service.as_ref() {
            external_service.debug(message);
        }
    }

    fn trace(&mut self, message: &str) {
        match self.log_level {
            LogLevel::Trace => println!("{}", message),
            _ => (),
        }
        if let Some(external_service) = self.external_service.as_ref() {
            external_service.trace(message);
        }
    }
}

struct ExternalService {
    url: String,
    timeout: Duration,
}

impl ExternalService {
    fn new(url: &str) -> Self {
        Self {
            url: url.to_string(),
            timeout: Duration::from_secs(10),
        }
    }

    fn error(&self, message: &str) {
        println!("{}", message);
    }

    fn warn(&self, message: &str) {
        println!("{}", message);
    }

    fn info(&self, message: &str) {
        println!("{}", message);
    }

    fn debug(&self, message: &str) {
        println!("{}", message);
    }

    fn trace(&self, message: &str) {
        println!("{}", message);
    }
}

enum LogLevel {
    Error,
    Warn,
    Info,
    Debug,
    Trace,
}

enum LogFormat {
    Text,
    Json,
}

fn main() {
    let logger = Logger::new(LogLevel::Info, LogFormat::Text)
        .with_aggregator(Aggregator::new(LogLevel::Error, LogFormat::Json));
    logger.log("Hello, world!");
}
