} HashTable;

// Function to initialize the hash table
void initHashTable(HashTable *ht, size_t capacity) {
    ht->keys = malloc(capacity * sizeof(int));
    ht->capacity = capacity;
    ht->count = 0;
    pthread_mutex_init(&ht->mutex, NULL);
}

// Function to add a key to the hash table
bool addKey(HashTable *ht, int key) {
    bool success = false;
    pthread_mutex_lock(&ht->mutex);
    if (ht->count < ht->capacity) {
        ht->keys[ht->count++] = key;
        success = true;
    } else {
        printf("Error: Hash table is full\n");
    }
    pthread_mutex_unlock(&ht->mutex);
    return success;
}

// Function to check if a key exists in the hash table
bool containsKey(HashTable *ht, int key) {
    bool found = false;
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < ht->count; i++) {
        if (ht->keys[i] == key) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&ht->mutex);
    return found;
}

// Function to allocate memory for the arrays and initialize them
Record *initArrays(size_t offsetSize, size_t keySize, size_t recordSize, size_t maxMemory) {
    // Calculate the total memory required for the arrays
    size_t totalMemory = offsetSize * sizeof(long) + keySize * sizeof(int) + recordSize * sizeof(Record);
    if (totalMemory > maxMemory) {
        printf("Error: Total memory exceeds maximum limit\n");
        return NULL;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(offsetSize * sizeof(long));
    int *keys = malloc(keySize * sizeof(int));
    Record *records = malloc(recordSize * sizeof(Record));

    // Initialize the hash table to track keys
    HashTable ht;
    initHashTable(&ht, keySize);

    // Generate random values for the arrays and ensure no duplicates in the hash table
    srand(time(NULL));
    for (size_t i = 0; i < offsetSize; i++) {
        offsets[i] = rand() % maxMemory;
        if (!addKey(&ht, keys[i])) {
            printf("Error: Hash table is full\n");
            break;
        }
    }
    for (size_t i = 0; i < recordSize; i++) {
        records[i].key = rand() % maxMemory;
        if (!containsKey(&ht, records[i].key)) {
            printf("Error: Duplicate key found\n");
            break;
        }
    }

    // Clean up the hash table and return the pointer to the first element of the record array
    pthread_mutex_destroy(&ht.mutex);
    free(ht.keys);
    return records;
}
