    string* label_array = (string*)malloc(label_size);
    float* score_array = (float*)malloc(score_size);

    // Check for memory allocation failure
    if (!offset_array || !key_array || !record_array || !label_array || !score_array) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Initialize the arrays with random values
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % (max_key - min_key + 1) + min_key;
        key_array[i] = rand() % (max_key - min_key + 1) + min_key;
        record_array[i].key = key_array[i];
        record_array[i].status = 'A';
        record_array[i].timestamp = time(NULL);
        label_array[i] = generate_random_string(label_len);
        score_array[i] = (float)rand() / RAND_MAX;
    }

    // Free the memory allocated for the arrays
    free(offset_array);
    free(key_array);
    free(record_array);
    free(label_array);
    free(score_array);
}

// Function to generate a random string of specified length
string generate_random_string(int len) {
    char* str = (char*)malloc(len + 1);
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }
    str[len] = '\0';
    return str;
}
