#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the metadata flag enum
enum MetadataFlag { ACTIVE, INACTIVE, INVALID };

// Define the function to initialize the arrays
Record* init_arrays(int num_records, int max_size, int range) {
    // Check if the number of records is valid
    if (num_records <= 0 || max_size <= 0 || range <= 0) {
        return NULL;
    }

    // Allocate memory for the arrays
    Record* records = malloc(sizeof(Record) * num_records);
    int* metadata = malloc(sizeof(int) * num_records);
    long* offsets = malloc(sizeof(long) * num_records);

    // Check if memory allocation failed
    if (records == NULL || metadata == NULL || offsets == NULL) {
        free(records);
        free(metadata);
        free(offsets);
        return NULL;
    }

    // Initialize the arrays
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % range + 1;
        offsets[i] = rand() % max_size + 1;
        metadata[i] = ACTIVE;
    }

    // Create a hash table to track the keys
    HashTable* key_table = create_hash_table(num_records);

    // Check if the hash table creation failed
    if (key_table == NULL) {
        free(records);
        free(metadata);
        free(offsets);
        return NULL;
    }

    // Add each key to the hash table
    for (int i = 0; i < num_records; i++) {
        if (!add_key(key_table, records[i].key)) {
            free(records);
            free(metadata);
            free(offsets);
            destroy_hash_table(key_table);
            return NULL;
        }
    }

    // Check if the total allocated memory exceeds the limit
    size_t total_size = sizeof(Record) * num_records + sizeof(int) * num_records + sizeof(long) * num_records;
    if (total_size > max_size) {
        free(records);
        free(metadata);
        free(offsets);
        destroy_hash_table(key_table);
        return NULL;
    }

    // Return the pointers to the arrays and a status indicating success
    return records;
}

// Define the hash table data structure
typedef struct {
    int size;
    int capacity;
    int* keys;
    void** values;
} HashTable;

// Define the function to create a new hash table
HashTable* create_hash_table(int capacity) {
    // Check if the capacity is valid
    if (capacity <= 0) {
        return NULL;
    }

    // Allocate memory for the hash table
    HashTable* table = malloc(sizeof(HashTable));

    // Check if memory allocation failed
    if (table == NULL) {
        return NULL;
    }

    // Initialize the hash table
    table->size = 0;
    table->capacity = capacity;
    table->keys = malloc(sizeof(int) * capacity);
    table->values = malloc(sizeof(void*) * capacity);

    // Check if memory allocation failed
    if (table->keys == NULL || table->values == NULL) {
        free(table);
        return NULL;
    }

    // Return the new hash table
    return table;
}

// Define the function to add a key to the hash table
bool add_key(HashTable* table, int key) {
    // Check if the key is already in the table
    for (int i = 0; i < table->size; i++) {
        if (table->keys[i] == key) {
            return false;
        }
    }

    // Add the key to the hash table
    table->keys[table->size] = key;
    table->values[table->size] = NULL;
    table->size++;

    // Check if the hash table needs to be resized
    if (table->size >= table->capacity) {
        resize_hash_table(table);
    }

    // Return success
    return true;
}

// Define the function to resize the hash table
void resize_hash_table(HashTable* table) {
    // Check if the hash table is empty
    if (table->size == 0) {
        return;
    }

    // Calculate the new capacity
    int new_capacity = table->capacity * 2;

    // Allocate memory for the new hash table
    HashTable* new_table = create_hash_table(new_capacity);

    // Check if memory allocation failed
    if (new_table == NULL) {
        return;
    }

    // Copy the keys and values from the old hash table to the new one
    for (int i = 0; i < table->size; i++) {
        add_key(new_table, table->keys[i]);
        new_table->values[new_table->size - 1] = table->values[i];
    }

    // Free the old hash table
    free(table->keys);
    free(table->values);
    free(table);

    // Update the hash table pointer
    table = new_table;
}

// Define the function to destroy a hash table
void destroy_hash_table(HashTable* table) {
    // Check if the hash table is empty
    if (table->size == 0) {
        return;
    }

    // Free the keys and values
    free(table->keys);
    free(table->values);

    // Free the hash table structure
    free(table);
}
