            printf("Error: Failed to set decryption key and IV\n");
            exit(1);
        }

        // Decrypt the ciphertext
        if (!EVP_DecryptUpdate(&ctx, plaintext, &plaintext_len, ciphertext, len)) {
            printf("Error: Failed to decrypt ciphertext\n");
            exit(1);
        }

        // Output the decrypted plaintext
