// Function to insert a record into the linked list
void insert_record(linked_list_t *list, long *offset) {
    // Check if the linked list is full
    if (list->count == 10000) {
        fprintf(stderr, "Error: linked list is full\n");
        exit(1);
    }
    record_t *new_record = init_record(offset);
    // Check if the new record has a duplicate key value
    if (list->head != NULL) {
        record_t *current = list->head;
        while (current != NULL) {
            if (current->key == new_record->key) {
                fprintf(stderr, "Error: duplicate key value detected\n");
                exit(1);
            }
            current = current->next;
        }
    }
    // Insert the new record into the linked list
    if (list->head == NULL) {
        list->head = new_record;
        list->tail = new_record;
    } else {
        list->tail->next = new_record;
        list->tail = new_record;
    }
    list->count++;
}

