    }
}

// Thread-safe function to add a new node to the graph
void add_node(struct node* new_node) {
    pthread_mutex_lock(&graph_mutex);

    // Check if the graph is full
    if (num_nodes == MAX_NODES) {
        printf("Error: Graph is full\n");
        return;
    }

    // Add the new node to the end of the list
    nodes[num_nodes] = new_node;
    num_nodes++;

    pthread_mutex_unlock(&graph_mutex);
}

// Thread-safe function to remove a node from the graph
void remove_node(struct node* node) {
    pthread_mutex_lock(&graph_mutex);

    // Find the index of the node in the list
    int i;
    for (i = 0; i < num_nodes; i++) {
        if (nodes[i] == node) {
            break;
        }
    }

    // Check if the node was found
    if (i == num_nodes) {
        printf("Error: Node not found\n");
        return;
    }

    // Remove the node from the list
    for (int j = i; j < num_nodes - 1; j++) {
        nodes[j] = nodes[j + 1];
    }
    num_nodes--;

    pthread_mutex_unlock(&graph_mutex);
}

// Thread-safe function to update the status of a node in the graph
void update_status(struct node* node, char new_status) {
    pthread_mutex_lock(&graph_mutex);

    // Find the index of the node in the list
    int i;
    for (i = 0; i < num_nodes; i++) {
        if (nodes[i] == node) {
            break;
        }
    }

    // Check if the node was found
    if (i == num_nodes) {
        printf("Error: Node not found\n");
        return;
    }

    // Update the status of the node
    nodes[i]->status = new_status;

    pthread_mutex_unlock(&graph_mutex);
}

// Thread-safe function to update the timestamp of a node in the graph
void update_timestamp(struct node* node, double new_timestamp) {
    pthread_mutex_lock(&graph_mutex);

    // Find the index of the node in the list
    int i;
    for (i = 0; i < num_nodes; i++) {
        if (nodes[i] == node) {
            break;
        }
    }

    // Check if the node was found
    if (i == num_nodes) {
        printf("Error: Node not found\n");
        return;
    }

    // Update the timestamp of the node
    nodes[i]->timestamp = new_timestamp;

    pthread_mutex_unlock(&graph_mutex);
}

// Thread-safe function to update the weight of a node in the graph
void update_weight(struct node* node, double new_weight) {
    pthread_mutex_lock(&graph_mutex);

    // Find the index of the node in the list
    int i;
    for (i = 0; i < num_nodes; i++) {
        if (nodes[i] == node) {
            break;
        }
    }

    // Check if the node was found
    if (i == num_nodes) {
        printf("Error: Node not found\n");
        return;
    }

    // Update the weight of the node
    nodes[i]->weight = new_weight;

    pthread_mutex_unlock(&graph_mutex);
}

// Thread-safe function to traverse the graph and perform an operation on each node
void traverse(void (*operation)(struct node*)) {
    pthread_mutex_lock(&graph_mutex);

    // Traverse the list of nodes and perform the operation on each one
    for (int i = 0; i < num_nodes; i++) {
        operation(nodes[i]);
    }

    pthread_mutex_unlock(&graph_mutex);
}
