    // Calculate the total memory required for the arrays
    size_t total_mem = (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(record_t));

    // Allocate the memory in a way that minimizes fragmentation and maximizes cache efficiency
    void *mem = mmap(NULL, total_mem, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    // Initialize the offset array
    long *offset = mem;
    for (size_t i = 0; i < num_records; i++) {
        offset[i] = i * sizeof(record_t);
    }

    // Initialize the key array
    int *key = (int *)((char *)mem + total_mem / 2);
    for (size_t i = 0; i < num_records; i++) {
        key[i] = rand() % 100;
    }

    // Initialize the record array
