    size_t total_mem_avail = info.totalram * info.mem_unit;
    size_t used_mem = (char *)mem - (char *)NULL;
    if (used_mem > 0.9 * total_mem_avail) {
        printf("Memory usage is high: %lu%%\n", (used_mem * 100) / total_mem_avail);
    }

    // Return the number of successfully initialized records
    return num_records;
}
