void allocateMemory(int numTransactions, int offsetRange, double amountRange, char** merchantNames) {
    // Initialize the random number generator with a fixed seed for consistent test results
    srand(1234);

    // Allocate memory for the long offset values array
    long* offsets = (long*)malloc(numTransactions * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the merchant names array
    char** names = (char**)malloc(numTransactions * sizeof(char*));
    if (!names) {
        printf("Error: Failed to allocate memory for names\n");
        exit(1);
    }

    // Allocate memory for the transaction details array
    struct transactionDetails* transactions = (struct transactionDetails*)malloc(numTransactions * sizeof(struct transactionDetails));
    if (!transactions) {
        printf("Error: Failed to allocate memory for transactions\n");
        exit(1);
    }

    // Initialize the offset values array with random numbers within the specified range
    for (int i = 0; i < numTransactions; i++) {
        offsets[i] = rand() % offsetRange + 1;
    }

    // Initialize the merchant names array with randomly selected names from the predefined list
    for (int i = 0; i < numTransactions; i++) {
        names[i] = merchantNames[rand() % (sizeof(merchantNames) / sizeof(char*))];
    }

    // Initialize the transaction details array with random amounts within the specified range and randomly selected flags
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].transactionID = rand() % offsetRange + 1;
        transactions[i].amount = (double)rand() / RAND_MAX * amountRange;
        transactions[i].description = "Transaction Description";
        transactions[i].flag = 'P'; // Initialize the flag to a specific state
    }

    // Validate that the memory is correctly initialized and accessible
    for (int i = 0; i < numTransactions; i++) {
        if (!offsets[i] || !names[i] || !transactions[i].transactionID || !transactions[i].amount || !transactions[i].description) {
            printf("Error: Memory initialization failed\n");
            exit(1);
        }
    }

    // Handle potential endianness and alignment issues across different platforms
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].transactionID = htonl(transactions[i].transactionID);
        transactions[i].amount = htond(transactions[i].amount);
    }

    // Reset the random number generator for consistent test results
    srand(1234);
}
