}

// Define the function to initialize the arrays with random values
void init_arrays(Record **records, int num_records) {
    // Loop through each record and set its value to a random integer within a given range
    for (int i = 0; i < num_records; i++) {
        records[i]->key = rand() % 100 + 1;
        records[i]->performance_metric = (double)rand() / RAND_MAX * 100.0;
        records[i]->transaction_type = 'A';
        records[i]->transaction_id = i + 1;
    }
