        } else if (strcmp(option, "GCM") == 0) {
            cipher = EVP_aes_128_gcm();
        } else if (strcmp(option, "CTR") == 0) {
            cipher = EVP_aes_128_ctr();
        }

        // Initialize the AES key and IV using the OpenSSL library
        unsigned char *key = NULL;
        unsigned char *iv = NULL;
        if (EVP_BytesToKey(cipher, EVP_sha256(), NULL, NULL, 1, &key, &iv) <= 0) {
            printf("Error: Failed to generate AES key and IV\n");
            exit(1);
        }

        // Encrypt the records using the AES algorithm
        for (int i = 0; i < num_records; i++) {
            unsigned char *plaintext = NULL;
            int plaintext_len = 0;
            if (!EVP_EncryptUpdate(cipher, &plaintext, &plaintext_len, records[i]->key, sizeof(int))) {
                printf("Error: Failed to encrypt record %d\n", i);
                exit(1);
            }
        }
    } else {
        printf("Error: Invalid option provided\n");
        exit(1);
    }
}

// Define the main function
int main(int argc, char *argv[]) {
    // Check if the command line argument is valid
    if (argc != 2) {
        printf("Error: Invalid number of arguments provided\n");
        exit(1);
    }

    // Declare variables for the arrays and the number of records
    Record *records = NULL;
    int num_records = 0;

    // Dynamically allocate memory for the arrays
    allocate_memory(&records, &num_records);

    // Initialize the arrays with random values
    init_arrays(records, num_records);

    // Perform the specific operation based on the command line option
    perform_operation(argv[1]);

    // Free the memory allocated for the arrays
    free(records);

    return 0;
}
