// Define constants for maximum memory usage and number of keys
#define MAX_MEMORY 10000000
#define MAX_NUM_KEYS 1000000

// Define a structure to represent a record
typedef struct {
    int value;
    long *offset;
    bool status;
} Record;

// Function to dynamically allocate memory for multiple components
void allocateMemory(int num_keys) {
    // Validate the number of keys to prevent memory overflow
    if (num_keys > MAX_NUM_KEYS) {
        printf("Error: Number of keys exceeds maximum allowed value.\n");
        return;
    }

    // Allocate memory for an array of long offset values with a fixed size of 10,000 elements
    long *offsets = (long *)malloc(sizeof(long) * 10000);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets.\n");
        return;
    }

    // Allocate memory for an array of int keys with a size determined by the user-specified parameter num_keys
    int *keys = (int *)malloc(sizeof(int) * num_keys);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys.\n");
        free(offsets);
        return;
    }

    // Allocate memory for an array of record structures
    Record *records = (Record *)malloc(sizeof(Record) * num_keys);
    if (!records) {
        printf("Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the status flags in each record to false
    for (int i = 0; i < num_keys; i++) {
        records[i].status = false;
    }

    // Generate unique random numbers within a specified range for each key
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int value = rand() % MAX_MEMORY + 1;
        while (records[i].status) {
            value = rand() % MAX_MEMORY + 1;
        }
        records[i].value = value;
        records[i].status = true;
    }

    // Populate the pointers in each record to reference the corresponding elements in the 'long' offset array
    for (int i = 0; i < num_keys; i++) {
        records[i].offset = &offsets[records[i].value - 1];
    }

    // Print the keys, their corresponding random values, status flags, and referenced offset values for validation
    printf("Keys: ");
    for (int i = 0; i < num_keys; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Random Values: ");
    for (int i = 0; i < num_keys; i++) {
        printf("%ld ", records[i].value);
    }
    printf("\n");
    printf("Status Flags: ");
    for (int i = 0; i < num_keys; i++) {
        printf("%d ", records[i].status);
    }
    printf("\n");
    printf("Referenced Offset Values: ");
    for (int i = 0; i < num_keys; i++) {
        printf("%ld ", *records[i].offset);
    }
    printf("\n");
}
