typedef struct Node {
    Record data;
    struct Node *next;
} Node;

// Define the binary search tree node structure
typedef struct BSTNode {
    int key;
    long *offset;
    struct BSTNode *left, *right;
} BSTNode;

// Function to dynamically allocate memory for multiple data structures
void allocateMemory(int numRecords) {
    // Allocate memory for the array of offset values
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the variable-size array of keys
    int *keys = (int *)malloc(numRecords * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        exit(1);
    }

