        record.offset = &offsets[i]; // Initialize the offset pointer to point to the corresponding element in the array of offsets
        if (head == NULL) {
            head = current = malloc(sizeof(Node));
        } else {
            current->next = malloc(sizeof(Node));
            current = current->next;
