    BSTNode *root = NULL;
    for (int i = 0; i < numRecords; i++) {
        Record record = head->data;
        if (root == NULL) {
            root = malloc(sizeof(BSTNode));
            root->key = record.key;
            root->offset = record.offset;
            root->left = root->right = NULL;
        } else {
            BSTNode *current = root;
            while (1) {
                if (record.key < current->key) {
                    if (current->left == NULL) {
                        current->left = malloc(sizeof(BSTNode));
                        current->left->key = record.key;
                        current->left->offset = record.offset;
                        current->left->left = current->left->right = NULL;
                        break;
                    } else {
                        current = current->left;
                    }
                } else if (record.key > current->key) {
                    if (current->right == NULL) {
                        current->right = malloc(sizeof(BSTNode));
                        current->right->key = record.key;
                        current->right->offset = record.offset;
                        current->right->left = current->right->right = NULL;
                        break;
                    } else {
                        current = current->right;
                    }
                } else {
                    // Handle duplicate keys by appending a unique suffix to the key value
                    record.key += 10000;
                    if (current->left == NULL) {
                        current->left = malloc(sizeof(BSTNode));
                        current->left->key = record.key;
                        current->left->offset = record.offset;
                        current->left->left = current->left->right = NULL;
                        break;
                    } else {
                        current = current->left;
                    }
                }
            }
        }
    }

    // Initialize the offset values in the linked list and binary search tree
    for (int i = 0; i < numRecords; i++) {
        Record record = head->data;
        *record.offset = i;
        if (root != NULL) {
            BSTNode *current = root;
            while (1) {
                if (record.key == current->key) {
                    *current->offset = i;
                    break;
                } else if (record.key < current->key) {
                    if (current->left != NULL) {
                        current = current->left;
                    } else {
                        break;
                    }
                } else if (record.key > current->key) {
                    if (current->right != NULL) {
                        current = current->right;
                    } else {
                        break;
                    }
                }
            }
        }
        head = head->next;
    }

    // Validate the integrity of both the linked list and binary search tree
    validateList(head);
    validateTree(root);
}

// Function to validate the integrity of the linked list
void validateList(Node *head) {
    Node *current = head;
    while (current != NULL) {
        if (current->data.offset == NULL || *current->data.offset < 0 || *current->data.offset >= numRecords) {
            printf("Error: Invalid offset value in linked list\n");
            exit(1);
        }
        current = current->next;
    }
}

// Function to validate the integrity of the binary search tree
void validateTree(BSTNode *root) {
    if (root == NULL) {
        return;
    }
    int minKey = root->key;
    int maxKey = root->key;
    int sumKeys = 0;
    int numNodes = 1;
    BSTNode *current = root;
    while (1) {
        if (current->left != NULL && current->left->key < minKey) {
            minKey = current->left->key;
        }
        if (current->right != NULL && current->right->key > maxKey) {
            maxKey = current->right->key;
        }
        sumKeys += current->key;
        numNodes++;
        if (current->left == NULL && current->right == NULL) {
            break;
        } else if (current->left != NULL && current->right != NULL) {
            current = current->left;
        } else if (current->left == NULL) {
            current = current->right;
        } else {
            current = current->left;
        }
    }
    if (minKey < 0 || maxKey >= numRecords || sumKeys != numRecords * (numRecords + 1) / 2) {
        printf("Error: Invalid tree structure\n");
        exit(1);
    }
}

