// Function to manage memory for user profiles and generate certificates in PEM format from OAuth requests
void manage_profiles(struct profile_data** profiles, int num_profiles) {
    // Allocate memory for the three arrays: user names, profile IDs, and profile data
    char** user_names = (char**)malloc(num_profiles * sizeof(char*));
    int* profile_ids = (int*)malloc(num_profiles * sizeof(int));
    struct profile_data* profile_data = (struct profile_data*)malloc(num_profiles * sizeof(struct profile_data));

    // Populate each profile data structure with random age values between 18 and 65, assign unique profile IDs, and dynamically allocate memory for each user name with a length randomly chosen between 3 and 15 characters
    srand(time(NULL));
    for (int i = 0; i < num_profiles; i++) {
        int age = rand() % 58 + 18;
        profile_data[i].age = age;
        profile_ids[i] = i + 1;
        user_names[i] = (char*)malloc(rand() % 13 + 3);
        for (int j = 0; j < strlen(user_names[i]); j++) {
            user_names[i][j] = 'a' + rand() % 26;
        }
    }

    // Handle potential memory allocation failures gracefully and manage resources efficiently
    if (user_names == NULL || profile_ids == NULL || profile_data == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Take an OAuth request as input and return a certificate in PEM format
    char* oauth_request = "oauth_request";
    char* private_key = "private_key";
    char* certificate = "certificate";
    char* pem_file = (char*)malloc(strlen(private_key) + strlen(certificate) + 1);
    strcpy(pem_file, private_key);
    strcat(pem_file, "\n");
    strcat(pem_file, certificate);

    // Fetch the private key and certificate from a location specified in the OAuth request and combine them into a single PEM file
    if (strcmp(oauth_request, "fetch") == 0) {
        printf("Fetching private key and certificate...\n");
        FILE* pem_file_ptr = fopen(pem_file, "wb+");
        if (pem_file_ptr == NULL) {
            printf("Error: Unable to open PEM file for writing.\n");
            exit(1);
        }
        fwrite(private_key, strlen(private_key), 1, pem_file_ptr);
        fwrite("\n", 1, 1, pem_file_ptr);
        fwrite(certificate, strlen(certificate), 1, pem_file_ptr);
        fclose(pem_file_ptr);
    } else {
        printf("Invalid OAuth request. Exiting...\n");
        exit(1);
    }

    // Free memory for the three arrays: user names, profile IDs, and profile data
    free(user_names);
    free(profile_ids);
    free(profile_data);
}
