// Define a struct to represent a transaction detail
struct transactionDetails {
    int transactionID;
    double amount;
    char* description;
    char flag;
};

// Define an array of merchant names
const char* merchantNames[] = {"Merchant 1", "Merchant 2", "Merchant 3"};

// Define a function to allocate memory for the three arrays
void allocateMemory(int numTransactions, int* offsetArray, char** merchantNameArray, struct transactionDetails* transactionDetailArray) {
    // Allocate memory for the offset array
    offsetArray = (int*)malloc(numTransactions * sizeof(int));
    if (!offsetArray) {
        printf("Error: Failed to allocate memory for offset array\n");
        exit(1);
    }

    // Allocate memory for the merchant name array
    merchantNameArray = (char**)malloc(numTransactions * sizeof(char*));
    if (!merchantNameArray) {
        printf("Error: Failed to allocate memory for merchant name array\n");
        exit(1);
    }

    // Allocate memory for the transaction detail array
    transactionDetailArray = (struct transactionDetails*)malloc(numTransactions * sizeof(struct transactionDetails));
    if (!transactionDetailArray) {
        printf("Error: Failed to allocate memory for transaction detail array\n");
        exit(1);
    }
}

// Define a function to initialize the arrays with random values
void initArrays(int numTransactions, int* offsetArray, char** merchantNameArray, struct transactionDetails* transactionDetailArray) {
    // Initialize the offset array with random values within the specified range
    for (int i = 0; i < numTransactions; i++) {
        offsetArray[i] = rand() % 10000 + 1;
    }

    // Initialize the merchant name array with random values from the predefined list
    for (int i = 0; i < numTransactions; i++) {
        int index = rand() % (sizeof(merchantNames) / sizeof(merchantNames[0]));
        merchantNameArray[i] = strdup(merchantNames[index]);
    }

    // Initialize the transaction detail array with random values within the specified range
    for (int i = 0; i < numTransactions; i++) {
        transactionDetailArray[i].transactionID = rand() % 10000 + 1;
        transactionDetailArray[i].amount = (double)rand() / RAND_MAX * 10000.0;
        transactionDetailArray[i].description = "Transaction Description";
        transactionDetailArray[i].flag = 'P';
    }
}

// Define a function to deallocate memory for the three arrays
void deallocateMemory(int* offsetArray, char** merchantNameArray, struct transactionDetails* transactionDetailArray) {
    // Deallocate memory for the offset array
    free(offsetArray);

    // Deallocate memory for the merchant name array
    for (int i = 0; i < numTransactions; i++) {
        free(merchantNameArray[i]);
    }
    free(merchantNameArray);

    // Deallocate memory for the transaction detail array
    free(transactionDetailArray);
}

// Define a function to handle concurrent access and ensure thread safety
void manageMemory(int numTransactions, int* offsetArray, char** merchantNameArray, struct transactionDetails* transactionDetailArray) {
    // Use a mutex to synchronize access to the arrays
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Allocate memory for the three arrays
    allocateMemory(numTransactions, offsetArray, merchantNameArray, transactionDetailArray);

    // Initialize the arrays with random values
    initArrays(numTransactions, offsetArray, merchantNameArray, transactionDetailArray);

    // Deallocate memory for the three arrays
    deallocateMemory(offsetArray, merchantNameArray, transactionDetailArray);

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

