// Define the record structure
typedef struct {
    int value;
    long *offset_ptr;
    bool status_flag;
} Record;

// Define the function to dynamically allocate and initialize memory for multiple components
void init_components(int num_keys, size_t max_memory) {
    // Validate the input parameters
    if (num_keys <= 0 || num_keys > MAX_NUM_KEYS) {
        fprintf(stderr, "Invalid number of keys: %d\n", num_keys);
        return;
    }
    if (max_memory == 0) {
        fprintf(stderr, "Maximum memory footprint is not set\n");
        return;
    }

    // Allocate memory for the arrays of 'long' offset values and 'int' keys
    long *offset_array = malloc(sizeof(long) * 10000);
    int *key_array = malloc(sizeof(int) * num_keys);
    if (offset_array == NULL || key_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the arrays with random numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < 10000; i++) {
        offset_array[i] = rand() % MAX_OFFSET_VALUE + MIN_OFFSET_VALUE;
    }
    for (int i = 0; i < num_keys; i++) {
        key_array[i] = rand() % MAX_KEY_VALUE + MIN_KEY_VALUE;
    }

    // Allocate memory for the array of 'record' structures
    Record *records = malloc(sizeof(Record) * num_keys);
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Populate the records with unique random numbers and pointers to corresponding elements in the 'long' offset array
    for (int i = 0; i < num_keys; i++) {
        int key = key_array[i];
        long *offset_ptr = &(offset_array[key % 10000]);
        records[i].value = rand() % MAX_VALUE + MIN_VALUE;
        records[i].offset_ptr = offset_ptr;
        records[i].status_flag = true;
    }

    // Free the memory allocated for the arrays of 'long' offset values and 'int' keys
    free(offset_array);
    free(key_array);
}
