// Define a struct to represent a time-series data point
typedef struct {
    long timestamp;
    double value;
    int status;
} DataPoint;

// Define a function to allocate memory for an array of DataPoints
DataPoint* allocate_data_points(int num_points, long min_timestamp, long max_timestamp) {
    // Calculate the size of the array based on the number of data points and the range of timestamps
    int size = (max_timestamp - min_timestamp + 1) * sizeof(DataPoint);

    // Allocate memory for the array using malloc()
    DataPoint* data_points = (DataPoint*)malloc(size);

    // Check if memory allocation failed
    if (!data_points) {
        fprintf(stderr, "Error: Failed to allocate memory for data points\n");
        return NULL;
    }

    // Initialize the status flag of each DataPoint to 0 (success)
    for (int i = 0; i < num_points; i++) {
        data_points[i].status = 0;
    }

    // Generate random timestamps within the specified range and assign them to the DataPoints
    srand(time(NULL));
    for (int i = 0; i < num_points; i++) {
        data_points[i].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
    }

    // Generate random numeric values within the specified range and assign them to the DataPoints
    double mean = 0.0, stddev = 1.0;
    for (int i = 0; i < num_points; i++) {
        data_points[i].value = normal_distribution(mean, stddev);
    }

    // Set the status flag of each DataPoint to 1 if it failed to be generated
    for (int i = 0; i < num_points; i++) {
        if (!data_points[i].timestamp || !data_points[i].value) {
            data_points[i].status = 1;
        }
    }

    return data_points;
}

// Define a function to free memory for an array of DataPoints
void free_data_points(DataPoint* data_points, int num_points) {
    // Check if the input is valid
    if (!data_points || !num_points) {
        return;
    }

    // Free the memory allocated for the array using free()
    free(data_points);
}

// Define a function to generate a random numeric value within a normal distribution
double normal_distribution(double mean, double stddev) {
    // Generate a random number within a normal distribution using Box-Muller transform
    double u1 = (double)rand() / RAND_MAX;
    double u2 = (double)rand() / RAND_MAX;
    double rand_stddev = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);

    // Return the generated value within the specified range
    return mean + stddev * rand_stddev;
}

// Define a function to fill an array of DataPoints with random data points
void fill_data_points(DataPoint* data_points, int num_points, long min_timestamp, long max_timestamp) {
    // Check if the input is valid
    if (!data_points || !num_points || !min_timestamp || !max_timestamp) {
        return;
    }

    // Generate random timestamps within the specified range and assign them to the DataPoints
    srand(time(NULL));
    for (int i = 0; i < num_points; i++) {
        data_points[i].timestamp = min_timestamp + rand() % (max_timestamp - min_timestamp);
    }

    // Generate random numeric values within the specified range and assign them to the DataPoints
    double mean = 0.0, stddev = 1.0;
    for (int i = 0; i < num_points; i++) {
        data_points[i].value = normal_distribution(mean, stddev);
    }

    // Set the status flag of each DataPoint to 1 if it failed to be generated
    for (int i = 0; i < num_points; i++) {
        if (!data_points[i].timestamp || !data_points[i].value) {
            data_points[i].status = 1;
        }
    }
}

// Define a function to retrieve the status flag of a DataPoint
int get_status(DataPoint* data_point) {
    // Check if the input is valid
    if (!data_point) {
        return -1;
    }

    // Return the status flag of the DataPoint
    return data_point->status;
}

// Define a function to retrieve the timestamp of a DataPoint
long get_timestamp(DataPoint* data_point) {
    // Check if the input is valid
    if (!data_point) {
        return -1;
    }

    // Return the timestamp of the DataPoint
    return data_point->timestamp;
}

// Define a function to retrieve the numeric value of a DataPoint
