#define MAX_KEYS 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 100000
#define MIN_KEY 0
#define MAX_KEY 1000000

typedef struct {
    long* offset;
    int key;
} record;

void* allocate_memory(size_t size) {
    void* ptr = NULL;
    while (ptr == NULL) {
        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr == MAP_FAILED) {
            perror("mmap");
            return NULL;
        }
    }
    return ptr;
}

void* initialize_memory(size_t size, void* ptr) {
    memset(ptr, 0, size);
    return ptr;
}

record* allocate_records(int num_offsets, int num_keys) {
    if (num_keys > MAX_KEYS) {
        fprintf(stderr, "Error: number of keys exceeds maximum allowed value\n");
        return NULL;
    }

    size_t record_size = sizeof(record);
    size_t offset_size = num_offsets * sizeof(long);
    size_t key_size = num_keys * sizeof(int);
    size_t total_size = record_size + offset_size + key_size;

    void* ptr = allocate_memory(total_size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        return NULL;
    }

    record* records = initialize_memory(total_size, ptr);
    long* offsets = (long*)((char*)records + record_size);
    int* keys = (int*)((char*)offsets + offset_size);

    for (int i = 0; i < num_keys; i++) {
        keys[i] = MIN_KEY + rand() % (MAX_KEY - MIN_KEY);
    }

    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i * sizeof(long);
    }

    for (int i = 0; i < num_keys; i++) {
        int key = keys[i];
        long offset = offsets[key];
        records[i].offset = &offsets[key];
        records[i].key = key;
    }

    return records;
}

void shuffle_records(record* records, int num_records) {
    for (int i = 0; i < num_records - 1; i++) {
        int j = i + rand() % (num_records - i);
        record tmp = records[i];
        records[i] = records[j];
        records[j] = tmp;
    }
}

void* thread_func(void* arg) {
    int num_offsets = *((int*)arg);
    int num_keys = *((int*)arg + 1);
    record* records = allocate_records(num_offsets, num_keys);
