        fprintf(stderr, "Usage: %s [--help] [-c num_offsets] [-o output_file]\n", argv[0]);
        return 1;
    }

    int num_offsets = 0;
    char* output_file = NULL;
    for (int i = 1; i < argc - 1; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            fprintf(stderr, "Usage: %s [--help] [-c num_offsets] [-o output_file]\n", argv[0]);
            return 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            num_offsets = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0) {
            output_file = argv[++i];
        }
    }

    if (num_offsets <= 0 || num_offsets > MAX_KEYS) {
        fprintf(stderr, "Error: invalid number of offsets\n");
        return 1;
    }

    int num_keys = num_offsets * sizeof(long);
    record* records = allocate_records(num_offsets, num_keys);
    if (records == NULL) {
        fprintf(stderr, "Error: failed to allocate records\n");
        return 1;
    }

    shuffle_records(records, num_keys);

