#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the data structures used in the event management system
typedef struct record {
    int key;
    long *offset;
} record_t;

typedef struct node {
    int key;
    long offset;
    struct node *left, *right;
} node_t;

typedef struct hash_table {
    int size;
    int count;
    record_t **records;
} hash_table_t;

// Define the functions used in the event management system
void init_event_management_system(int max_size) {
    // Initialize the linked list of records
    record_t *head = NULL;
    int count = 0;

    // Initialize the binary search tree
    node_t *root = NULL;

    // Initialize the hash table
    hash_table_t *hash_table = (hash_table_t *)malloc(sizeof(hash_table_t));
    hash_table->size = max_size;
    hash_table->count = 0;
    hash_table->records = (record_t **)malloc(max_size * sizeof(record_t *));

    // Initialize the cache
    record_t *cache[100];
    int cache_count = 0;
}

void insert_event(int key, long offset) {
    // Check if the key already exists in the hash table
    if (hash_table_find(key)) {
        // If it does, append a unique suffix to the key value
        key += count++;
    }

    // Create a new record and add it to the linked list
    record_t *new_record = (record_t *)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = head;
    head = new_record;

    // Insert the record into the binary search tree
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    new_node->key = key;
    new_node->offset = offset;
    new_node->left = NULL;
    new_node->right = NULL;
    insert_bst(root, new_node);

    // Insert the record into the hash table
    hash_table_insert(hash_table, key, offset);

    // Add the record to the cache
    cache[cache_count++] = new_record;
}

void delete_event(int key) {
    // Find the record in the linked list and binary search tree
    record_t *record = find_record(head, key);
    node_t *node = find_bst(root, key);

    // Remove the record from the linked list and binary search tree
    remove_from_list(head, record);
    remove_from_bst(root, node);

    // Remove the record from the hash table
    hash_table_delete(hash_table, key);

    // Free the memory used by the record
    free(record->offset);
    free(record);
}

void update_event(int key, long offset) {
    // Find the record in the linked list and binary search tree
    record_t *record = find_record(head, key);
    node_t *node = find_bst(root, key);

    // Update the offset value in the record
    record->offset = offset;

    // Update the offset value in the binary search tree
    node->offset = offset;
}

void print_events() {
    // Print all events in the linked list and binary search tree
    printf("Events:\n");
    for (record_t *record = head; record != NULL; record = record->next) {
        printf("%d: %ld\n", record->key, record->offset);
    }
}

void print_bst() {
    // Print all events in the binary search tree
    printf("Binary Search Tree:\n");
    print_bst(root);
}

void print_hash_table() {
    // Print all events in the hash table
    printf("Hash Table:\n");
    for (int i = 0; i < hash_table->count; i++) {
        record_t *record = hash_table->records[i];
        printf("%d: %ld\n", record->key, record->offset);
    }
}

// Define the functions used to manage the linked list and binary search tree
void insert_bst(node_t **root, node_t *new_node) {
    // Check if the root is NULL
    if (*root == NULL) {
        *root = new_node;
        return;
    }

    // Compare the key values and insert the new node accordingly
    int compare = new_node->key - (*root)->key;
    if (compare < 0) {
        insert_bst(&(*root)->left, new_node);
    } else if (compare > 0) {
        insert_bst(&(*root)->right, new_node);
    } else {
        // If the key already exists, append a unique suffix to the key value
        new_node->key += count++;
        insert_bst(&(*root)->left, new_node);
    }
}

void remove_from_list(record_t **head, record_t *record) {
    // Check if the head is NULL
    if (*head == NULL) {
        return;
    }

    // Find the record in the linked list and remove it
    if (*head == record) {
        *head = record->next;
        return;
    }

    record_t *current = *head;
    while (current->next != NULL && current->next != record) {
        current = current->next;
    }

    if (current->next == record) {
        current->next = record->next;
    }
}

void remove_from_bst(node_t **root, node_t *node) {
    // Check if the root is NULL
    if (*root == NULL) {
        return;
    }

    // Find the node in the binary search tree and remove it
    if (*root == node) {
        *root = NULL;
        return;
    }

    int compare = node->key - (*root)->key;
    if (compare < 0) {
        remove_from_bst(&(*root)->left, node);
    } else if (compare > 0) {
        remove_from_bst(&(*root)->right, node);
    } else {
        // If the key already exists, append a unique suffix to the key value
        node->key += count++;
        remove_from_bst(&(*root)->left, node);
    }
}

// Define the functions used to manage the hash table
void hash_table_insert(hash_table_t *hash_table, int key, long offset) {
    // Check if the hash table is full
    if (hash_table->count == hash_table->size) {
        return;
    }

    // Find an empty slot in the hash table and insert the record
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] == NULL) {
            hash_table->records[i] = (record_t *)malloc(sizeof(record_t));
            hash_table->records[i]->key = key;
            hash_table->records[i]->offset = offset;
            hash_table->count++;
            break;
        }
    }
}

void hash_table_delete(hash_table_t *hash_table, int key) {
    // Check if the hash table is empty
    if (hash_table->count == 0) {
        return;
    }

    // Find the record in the hash table and delete it
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] != NULL && hash_table->records[i]->key == key) {
            free(hash_table->records[i]);
            hash_table->records[i] = NULL;
            hash_table->count--;
            break;
        }
    }
}

void hash_table_find(int key) {
    // Check if the hash table is empty
    if (hash_table->count == 0) {
        return;
    }

    // Find the record in the hash table and return it
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->records[i] != NULL && hash_table->records[i]->key == key) {
            return hash_table->records[i];
        }
    }
}
