typedef struct DataObject {
    char *string;
    int integer;
    NestedStructure *nested;
} DataObject;

typedef struct NestedStructure {
    char *string;
} NestedStructure;

void* allocate_memory(size_t size) {
    void *ptr = NULL;
    while (ptr == NULL) {
        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
    return ptr;
}

void initialize_data_object(DataObject *obj, int index) {
