    obj->integer = rand() % MAX_VALUE;
    obj->nested = (NestedStructure *)allocate_memory(sizeof(NestedStructure));
    obj->nested->string = obj->string;
}

void shuffle_data_objects(DataObject *objs, int num_objects) {
    for (int i = 0; i < SHUFFLE_ITERATIONS; i++) {
        for (int j = 0; j < num_objects - 1; j++) {
            int index1 = rand() % num_objects;
            int index2 = rand() % num_objects;
            DataObject temp = objs[index1];
            objs[index1] = objs[index2];
            objs[index2] = temp;
        }
    }
}

void* initialize_data_objects(int num_objects) {
