    DataObject *objs = (DataObject *)allocate_memory(sizeof(DataObject) * num_objects);
    for (int i = 0; i < num_objects; i++) {
        initialize_data_object(&objs[i], i);
    }

    shuffle_data_objects(objs, num_objects);
    return objs;
}

