            exit(EXIT_FAILURE);
        }
    }
    return ptr;
}

void initialize_data_object_threadsafe(DataObject *obj, int index) {
    obj->string = (char *)allocate_memory_threadsafe(strlen(names[index]) + 1);
    strcpy(obj->string, names[index]);
    obj->integer = rand() % MAX_VALUE;
    obj->nested = (NestedStructure *)allocate_memory_threadsafe(sizeof(NestedStructure));
    obj->nested->string = obj->string;
}

void* initialize_data_objects_threadsafe(int num_objects) {
    if (num_objects > MAX_OBJECTS) {
        fprintf(stderr, "Error: Number of objects exceeds maximum allowed value\n");
        return NULL;
    }

    DataObject *objs = (DataObject *)allocate_memory_threadsafe(sizeof(DataObject) * num_objects);
    for (int i = 0; i < num_objects; i++) {
        initialize_data_object_threadsafe(&objs[i], i);
    }

    return objs;
}

void monitor_memory_usage() {
    struct sysinfo info;
    if (sysinfo(&info) != 0) {
        perror("sysinfo");
        exit(EXIT_FAILURE);
    }
    if (info.freeram > (info.totalram * 0.75)) {
        fprintf(stderr, "Warning: Memory usage is high\n");
    }
}

void print_usage() {
    printf("Usage: ./program [options]\n");
    printf("\t-h --help\t\tPrint this help message and exit\n");
    printf("\t-c --count <num>\tSet the number of objects to allocate (default: 1000)\n");
    printf("\t-o --output <file>\tWrite output to file instead of stdout\n");
}

int main(int argc, char **argv) {
    int num_objects = 1000;
    char *output_file = NULL;

    // Parse command line options
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            print_usage();
            return 0;
        } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "--count")) {
            num_objects = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
            output_file = argv[++i];
        }
    }

    // Initialize data objects
    DataObject *objs = initialize_data_objects(num_objects);
    if (objs == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data objects\n");
        return 1;
    }

    // Shuffle data objects
    shuffle_data_objects(objs, num_objects);

    // Monitor memory usage
    monitor_memory_usage();

    // Write output to file or stdout
    if (output_file != NULL) {
        FILE *fp = fopen(output_file, "w");
        if (fp == NULL) {
            perror("fopen");
            return 1;
        }
        for (int i = 0; i < num_objects; i++) {
            fprintf(fp, "%s %d %p\n", objs[i].string, objs[i].integer, objs[i].nested);
        }
        fclose(fp);
    } else {
        for (int i = 0; i < num_objects; i++) {
            printf("%s %d %p\n", objs[i].string, objs[i].integer, objs[i].nested);
        }
    }

    // Clean up
    free(objs);

    return 0;
}
