    collection coll;
    coll.records = NULL;
    coll.num_records = 0;
    coll.max_records = 100000;
    coll.min_offset = 0;
    coll.max_offset = 5000000;
    coll.min_key = 0;
    coll.max_key = 1000000;
    coll.min_value = 0;
    coll.max_value = 1000000;
    pthread_mutex_init(&coll.mutex, NULL);

    // Add records to the collection
    for (int i = 0; i < 100000; i++) {
        long offset = rand() % coll.max_offset + coll.min_offset;
        int key = rand() % coll.max_key + coll.min_key;
        int value = rand() % coll.max_value + coll.min_value;
        add_record(&coll, offset, key, value);
    }

    // Cleanup the collection
    cleanup(&coll);

    return 0;
}
