void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Define a function to reallocate memory for the arrays
void *reallocate_memory(void *ptr, size_t size) {
    void *new_ptr = realloc(ptr, size);
    if (!new_ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return new_ptr;
}

// Define a function to populate the arrays with random values
void populate_arrays(long *offset_arr, int *key_arr, record_t **record_arr, size_t num_records) {
    // Generate random offset values within the specified range
    for (size_t i = 0; i < num_records; i++) {
        offset_arr[i] = generate_random(0, MAX_OFFSET);
    }

    // Generate random key values within the specified range
    for (size_t i = 0; i < num_records; i++) {
        key_arr[i] = generate_random(MIN_KEY, MAX_KEY);
    }

    // Allocate memory for the record structures
    *record_arr = allocate_memory(num_records * sizeof(**record_arr));

    // Populate the record structures with random values within the specified range
    for (size_t i = 0; i < num_records; i++) {
        (*record_arr)[i].value = generate_random(MIN_VALUE, MAX_VALUE);
    }
}

