        private readonly int _minValue;
        private readonly int _maxValue;
        private readonly bool _isInclusive;

        public MemoryInitializer(int minValue, int maxValue, bool isInclusive)
        {
            _minValue = minValue;
            _maxValue = maxValue;
            _isInclusive = isInclusive;
            _random = new Random();
        }

        public string GetCurrentRange()
        {
            return $"{_minValue} to {_maxValue}, inclusive: {_isInclusive}";
        }

        public void InitializeArray(int[] array)
        {
            for (int i = 0; i < array.Length; i++)
            {
                array[i] = GetRandomInt();
            }
        }

        public void InitializeOffsetArray(long[] offsetArray)
        {
            for (int i = 0; i < offsetArray.Length; i++)
            {
                offsetArray[i] = GetRandomLong();
            }
        }

        public void InitializeKeyArray(int[] keyArray)
        {
            for (int i = 0; i < keyArray.Length; i++)
            {
                keyArray[i] = GetRandomInt();
            }
        }

        private int GetRandomInt()
        {
            return _random.Next(_minValue, _maxValue + (_isInclusive ? 1 : 0));
        }

        private long GetRandomLong()
        {
            return (long)_random.NextDouble() * (long)(_maxValue - _minValue) + _minValue;
        }
    }
}
