using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace MemoryInitializer
{
    public class MemoryInitializer
    {
        private int minValue;
        private int maxValue;
        private bool isInclusive;
        private Random random;

        public MemoryInitializer(int minValue, int maxValue, bool isInclusive = false, int seed = 0)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
            this.isInclusive = isInclusive;
            this.random = new Random(seed);
        }

        public string GetCurrentRange()
        {
            return $"{this.minValue} - {this.maxValue} ({this.isInclusive ? "inclusive" : "exclusive"})";
        }

        public int GetRandomInt()
        {
            return this.random.Next(this.minValue, this.maxValue + (this.isInclusive ? 1 : 0));
        }

        public float GetRandomFloat()
        {
            return (float)this.random.NextDouble();
        }

        public void InitializeRecords<T>(T[] records, int count = -1) where T : struct
        {
            if (count == -1)
                count = records.Length;

            for (int i = 0; i < count; i++)
            {
                records[i] = GetRandomInt();
            }
        }

        public void AllocateOffsets(long[] offsets, int count = -1)
        {
            if (count == -1)
                count = offsets.Length;

            for (int i = 0; i < count; i++)
            {
                offsets[i] = GetRandomInt();
            }
        }

        public void AllocateKeys(int[] keys, int count = -1)
        {
            if (count == -1)
                count = keys.Length;

            for (int i = 0; i < count; i++)
            {
                keys[i] = GetRandomInt();
            }
        }

        public void ValidateAndSanitizeConfiguration()
        {
            if (this.minValue > this.maxValue)
            {
                throw new ArgumentException("Invalid range specified: minValue must be less than or equal to maxValue");
            }

            if (this.seed < 0 || this.seed > int.MaxValue)
            {
                throw new ArgumentException("Invalid seed specified: seed must be a positive integer");
            }
        }
    }
}
