using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace MemoryInitializer
{
    public class MemoryInitializer
    {
        private int minValue;
        private int maxValue;
        private bool isInclusive;
        private Random random;

        public MemoryInitializer(int minValue, int maxValue, bool isInclusive = false, int seed = 0)
        {
            this.minValue = minValue;
            this.maxValue = maxValue;
            this.isInclusive = isInclusive;
            this.random = new Random(seed);
        }

        public string GetCurrentRange()
        {
            return $"{this.minValue} - {this.maxValue}";
        }

        public int GetRandomInt()
        {
            if (this.isInclusive)
            {
                return this.random.Next(this.minValue, this.maxValue + 1);
            }
            else
            {
                return this.random.Next(this.minValue, this.maxValue);
            }
        }

        public float GetRandomFloat()
        {
            return (float)this.random.NextDouble();
        }

        public void InitializeRecords(int[] records)
        {
            for (int i = 0; i < records.Length; i++)
            {
                records[i] = this.GetRandomInt();
            }
        }

        public void AllocateOffsets(long[] offsets)
        {
            for (int i = 0; i < offsets.Length; i++)
            {
                offsets[i] = this.GetRandomLong();
            }
        }

        public void AllocateKeys(int[] keys)
        {
            for (int i = 0; i < keys.Length; i++)
            {
                keys[i] = this.GetRandomInt();
            }
        }

        private long GetRandomLong()
        {
            return (long)(this.random.NextDouble() * (double)int.MaxValue);
        }

        public void ValidateAndSanitizeConfiguration(int minValue, int maxValue, bool isInclusive = false, int seed = 0)
        {
            if (minValue > maxValue)
            {
                throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
            }

            if (seed < 0)
            {
                throw new ArgumentException("Seed must be non-negative.");
            }
        }
    }
