#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold the record values
typedef struct {
    int value;
} record_t;

// Define a structure to hold the collection state
typedef struct {
    long *offsets; // array of long offset values
    int *keys; // array of int keys
    record_t **records; // array of record structures
    size_t num_records; // number of active records
    size_t capacity; // total capacity of the collection
} collection_t;

// Define a mutex to protect concurrent access to the collection
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate memory for the collection
void alloc_collection(collection_t *coll, size_t capacity) {
    coll->offsets = malloc(capacity * sizeof(long));
    coll->keys = malloc(capacity * sizeof(int));
    coll->records = malloc(capacity * sizeof(record_t*));
    coll->num_records = 0;
    coll->capacity = capacity;
}

// Define a function to populate the collection with random values within a specified range
void populate_collection(collection_t *coll, int min, int max) {
    for (size_t i = 0; i < coll->capacity; i++) {
        long offset = rand() % (max - min + 1) + min;
        int key = rand() % (max - min + 1) + min;
        record_t *record = malloc(sizeof(record_t));
        record->value = rand() % (max - min + 1) + min;
        coll->offsets[i] = offset;
        coll->keys[i] = key;
        coll->records[i] = record;
    }
}

// Define a function to update the value of a record in the collection
void update_record(collection_t *coll, int index, int new_value) {
    pthread_mutex_lock(&mutex);
    coll->records[index]->value = new_value;
    pthread_mutex_unlock(&mutex);
}

// Define a function to query the current size of the collection
size_t get_collection_size(collection_t *coll) {
    return coll->num_records;
}

// Define a function to serialize the collection state to disk for persistence across sessions
void serialize_collection(collection_t *coll, FILE *file) {
    fwrite(&coll->offsets, sizeof(long), coll->capacity, file);
    fwrite(&coll->keys, sizeof(int), coll->capacity, file);
    for (size_t i = 0; i < coll->num_records; i++) {
        record_t *record = coll->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
    }
}

// Define a function to deserialize the collection state from disk for persistence across sessions
void deserialize_collection(collection_t *coll, FILE *file) {
    size_t num_records = fread(&coll->offsets, sizeof(long), coll->capacity, file);
    size_t num_keys = fread(&coll->keys, sizeof(int), coll->capacity, file);
    for (size_t i = 0; i < num_records; i++) {
        record_t *record = malloc(sizeof(record_t));
        fread(&record->value, sizeof(int), 1, file);
        coll->records[i] = record;
    }
}

// Define a function to garbage collect unused memory in the collection
void gc_collection(collection_t *coll) {
    size_t num_records = get_collection_size(coll);
    for (size_t i = 0; i < num_records; i++) {
        if (!coll->records[i]) {
            free(coll->offsets[i]);
            free(coll->keys[i]);
            coll->num_records--;
        }
    }
}

// Define a function to track the total size of the allocated memory
void track_memory(collection_t *coll) {
    size_t num_records = get_collection_size(coll);
    for (size_t i = 0; i < num_records; i++) {
        coll->offsets[i] += sizeof(long);
        coll->keys[i] += sizeof(int);
        coll->records[i]->value += sizeof(int);
    }
}

// Define a function to query the total size of the allocated memory
size_t get_memory_usage(collection_t *coll) {
    return coll->offsets + coll->keys + coll->records;
}

// Define a function to trigger garbage collection based on configurable thresholds
void trigger_gc(collection_t *coll, int threshold) {
    if (get_memory_usage(coll) > threshold) {
        gc_collection(coll);
    }
}
