void handle_allocation_failure(record_t **records, int *num_records, int *max_records) {
    // Reallocate memory for records array with a new size that is twice the current size
    *records = (record_t *)realloc(*records, (*max_records * 2) * sizeof(record_t));
    if (*records == NULL) {
        printf("Error: Failed to reallocate memory for records\n");
        return;
    }

    // Initialize new elements in the array with default values
    memset(*records + *max_records, 0, (*max_records * 2 - *max_records) * sizeof(record_t));
    *num_records = *max_records;
    *max_records *= 2;

    // Log successful reallocation of memory for records array
    printf("Successfully reallocated memory for %d records\n", *max_records);
}

// Define function to manage memory efficiently and prevent memory leaks
void free_arrays(record_t **records, int *num_records) {
    // Free memory allocated for records array
    free(*records);
    *records = NULL;
    *num_records = 0;

    // Log successful deallocation of memory for records array
    printf("Successfully freed memory for %d records\n", *num_records);
}

// Define function to validate the integrity of the timestamp, error code, and data length arrays
void validate_arrays(record_t **records, int num_records) {
    // Loop to validate each record's timestamp, error code, and data length array
    for (int i = 0; i < num_records; i++) {
        if ((*records)[i].timestamp == 0 || (*records)[i].error_code != ERROR_NONE || (*records)[i].data_length == 0) {
            printf("Error: Invalid timestamp, error code, or data length for record %d\n", i);
        }
    }
}

// Define function to allow users to query the current state of the record structures
void print_records(record_t **records, int num_records) {
    // Loop to print each record's key, offset, timestamp, error code, data length, and access frequency
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Key=%d, Offset=%ld, Timestamp=%lu, Error Code=%d, Data Length=%zu, Access Frequency=%lu\n",
               i, (*records)[i].key, (*records)[i].offset, (*records)[i].timestamp, (*records)[i].error_code,
               (*records)[i].data_length, (*records)[i].access_frequency);
    }
}

// Define function to support compression of the data structures to save memory and improve I/O operations
void compress_arrays(record_t **records, int *num_records) {
    // Loop to compress each record's key, offset, timestamp, error code, data length, and access frequency
    for (int i = 0; i < *num_records; i++) {
        (*records)[i].key = compress((*records)[i].key);
        (*records)[i].offset = compress((*records)[i].offset);
        (*records)[i].timestamp = compress((*records)[i].timestamp);
        (*records)[i].error_code = compress((*records)[i].error_code);
        (*records)[i].data_length = compress((*records)[i].data_length);
        (*records)[i].access_frequency = compress((*records)[i].access_frequency);
    }
}

// Define function to support an external configuration file that defines the initial size of the arrays, the random value range, and the threshold for dynamic resizing
void configure_arrays(record_t **records, int *num_records, int *max_records) {
    // Read configuration file and set values for initial size of arrays, random value range, and threshold for dynamic resizing
    FILE *config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error: Failed to open configuration file\n");
        return;
    }
    int init_size = 0;
    int rand_min = 0;
    int rand_max = 0;
    int resize_threshold = 0;
    fscanf(config_file, "%d %d %d %d", &init_size, &rand_min, &rand_max, &resize_threshold);
    if (init_size <= 0 || rand_min < 1 || rand_max < 1 || resize_threshold < 1) {
        printf("Error: Invalid values in configuration file\n");
        return;
    }
    *num_records = init_size;
    *max_records = init_size;
    fclose(config_file);
}

// Define function to support a user-defined comparator function to facilitate custom sorting and querying of the record structures based on various criteria
void sort_records(record_t **records, int num_records, int (*comparator)(const void *, const void *)) {
