            sleep(1);
        }
    }
}

// Define a function to check for unused memory and free it up if necessary
void free_unused_memory(record_t **record_array, int num_records) {
    // Iterate through the record array and free any unused memory
    for (int i = 0; i < num_records; i++) {
        if (record_array[i] == NULL) {
            free(record_array[i]);
        }
    }
}

// Define a function to check the current memory usage and return true if there is unused memory, false otherwise
int check_memory_usage(record_t **record_array, int num_records) {
