void insert_session_id(media_streaming_platform *platform, uint32_t session_id) {
    // Check if the array is full and needs to be reallocated
    if (platform->session_ids->size == platform->session_ids->capacity) {
        size_t new_capacity = platform->session_ids->capacity * 2;
        uint32_t *new_data = (uint32_t *)realloc(platform->session_ids->data, new_capacity * sizeof(uint32_t));
        if (!new_data) {
            printf("Error: Failed to allocate memory for session IDs\n");
            exit(1);
        }
        platform->session_ids->data = new_data;
        platform->session_ids->capacity = new_capacity;
    }

    // Insert the session ID into the array
    platform->session_ids->data[platform->session_ids->size++] = session_id;
}

void insert_media_info(media_streaming_platform *platform, uint32_t session_id, int video_resolution, int playback_duration) {
    // Check if the hash table is full and needs to be reallocated
    if (platform->hash_table->size == platform->hash_table->capacity) {
        size_t new_capacity = platform->hash_table->capacity * 2;
        media_info **new_data = (media_info **)realloc(platform->hash_table->data, new_capacity * sizeof(media_info *));
        if (!new_data) {
            printf("Error: Failed to allocate memory for hash table\n");
            exit(1);
        }
        platform->hash_table->data = new_data;
        platform->hash_table->capacity = new_capacity;
    }

    // Insert the media info into the hash table
    media_info *new_entry = (media_info *)malloc(sizeof(media_info));
    if (!new_entry) {
        printf("Error: Failed to allocate memory for media info\n");
        exit(1);
    }
    new_entry->timestamp = 0;
    new_entry->session_id = session_id;
    new_entry->video_resolution = video_resolution;
    new_entry->playback_duration = playback_duration;
    platform->hash_table->data[platform->hash_table->size++] = new_entry;
}

void validate_media_streaming_platform(media_streaming_platform *platform) {
    // Validate the integrity of the timestamp array
    for (int i = 0; i < platform->timestamps->size - 1; i++) {
        if (platform->timestamps->data[i] >= platform->timestamps->data[i + 1]) {
            printf("Error: Timestamp array is not sorted\n");
            exit(1);
        }
    }

    // Validate the integrity of the session ID array
    for (int i = 0; i < platform->session_ids->size - 1; i++) {
        if (platform->session_ids->data[i] >= platform->session_ids->data[i + 1]) {
            printf("Error: Session ID array is not sorted\n");
            exit(1);
        }
    }

    // Validate the integrity of the hash table
    for (int i = 0; i < platform->hash_table->size - 1; i++) {
        if (platform->hash_table->data[i]->timestamp >= platform->hash_table->data[i + 1]->timestamp) {
            printf("Error: Hash table is not sorted\n");
            exit(1);
        }
    }
}

void clear_media_streaming_platform(media_streaming_platform *platform) {
    // Free the memory allocated for the data structures
    free(platform->timestamps->data);
    free(platform->session_ids->data);
    free(platform->hash_table->data);
}
