        fwrite(&edge->id, sizeof(int), 1, file);
        fwrite(&edge->target->id, sizeof(int), 1, file);
        fwrite(edge->data, sizeof(void*), 1, file);
    }
    pthread_mutex_unlock(&graph_mutex);
}

// Function to deserialize the graph state from disk for persistence across sessions
Graph* deserialize_graph(FILE* file) {
    Graph* graph = malloc(sizeof(Graph));
    if (graph == NULL) {
        return NULL;
    }
    fread(&graph->num_nodes, sizeof(int), 1, file);
    fread(&graph->num_edges, sizeof(int), 1, file);
    graph->nodes = malloc(graph->num_nodes * sizeof(Node*));
    if (graph->nodes == NULL) {
        free(graph);
        return NULL;
    }
    for (int i = 0; i < graph->num_nodes; i++) {
        Node* node = malloc(sizeof(Node));
        if (node == NULL) {
            free(graph->nodes);
            free(graph);
            return NULL;
        }
        fread(&node->id, sizeof(int), 1, file);
        fread(node->data, sizeof(void*), 1, file);
        graph->nodes[i] = node;
    }
    graph->edges = malloc(graph->num_edges * sizeof(Edge*));
    if (graph->edges == NULL) {
        free(graph->nodes);
        free(graph);
        return NULL;
    }
    for (int i = 0; i < graph->num_edges; i++) {
        Edge* edge = malloc(sizeof(Edge));
        if (edge == NULL) {
            free(graph->edges);
            free(graph->nodes);
            free(graph);
            return NULL;
        }
        fread(&edge->id, sizeof(int), 1, file);
        fread(&edge->target->id, sizeof(int), 1, file);
        fread(edge->data, sizeof(void*), 1, file);
        graph->edges[i] = edge;
    }
    return graph;
}
