#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

// Define the maximum number of transactions to be processed
#define MAX_TRANSACTIONS 100000

// Define the minimum and maximum transaction amounts
