// Define the number of merchant names in the list
#define NUM_MERCHANT_NAMES (sizeof(MERCHANT_NAMES) / sizeof(MERCHANT_NAMES[0]))

// Define the structure for transaction details
typedef struct {
    int transactionId;
    double amount;
    char* description;
    char flag;
} TransactionDetails;

// Define the function to manage dynamic memory allocation for transactions
void manageTransactions(int numTransactions) {
    // Initialize the random number generator with a seed based on the current time
    srand(time(NULL));

    // Allocate memory for the offset array
    long* offsets = (long*)malloc(numTransactions * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the merchant name array
    char** merchantNames = (char**)malloc(numTransactions * sizeof(char*));
    if (!merchantNames) {
        printf("Error: Failed to allocate memory for merchant name array\n");
        free(offsets);
        return;
    }

