        offsets[i] = rand() % MAX_TRANSACTIONS + MIN_TRANSACTION_ID;
        merchantNames[i] = MERCHANT_NAMES[rand() % NUM_MERCHANT_NAMES];
    }

    // Initialize the transaction details array
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].transactionId = offsets[i];
        transactions[i].amount = rand() % MAX_AMOUNT + MIN_AMOUNT;
        transactions[i].description = "Purchase";
        transactions[i].flag = 'N';
    }

    // Free the memory allocated for the offset and merchant name arrays
    free(offsets);
    free(merchantNames);

    // Print the transaction details array
    printf("Transaction Details:\n");
    for (int i = 0; i < numTransactions; i++) {
        printf("%d: %s - $%.2f\n", transactions[i].transactionId, transactions[i].description, transactions[i].amount);
    }

    // Free the memory allocated for the transaction details array
    free(transactions);
}

int main() {
    manageTransactions(MAX_TRANSACTIONS);
    return 0;
}
