typedef struct {
    int value;
    long *offset_ptr;
    bool status;
    int key;
} record;

record* initialize_records(int num_keys, int min_value, int max_value) {
    if (num_keys <= 0 || num_keys > MAX_NUM_KEYS) {
        return NULL;
    }

    // Allocate memory for the records and offset array
    record *records = malloc(sizeof(record) * num_keys);
    long *offsets = malloc(sizeof(long) * 10000);
    if (records == NULL || offsets == NULL) {
        free(records);
        free(offsets);
        return NULL;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < 10000; i++) {
        offsets[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize the records with random values within the specified range and unique keys
    for (int i = 0; i < num_keys; i++) {
        int key = i + 1;
        long offset = offsets[i];
        bool status = true;
        record *record = &records[i];
        record->value = rand() % (max_value - min_value + 1) + min_value;
        record->offset_ptr = &offsets[i];
        record->status = status;
        record->key = key;
    }

    // Free the offset array if it is not needed anymore
    free(offsets);

    return records;
}
