#include <assert.h>

// Define the record structure
typedef struct {
    int value;
    long *offset_ptr;
    bool status;
    int key;
} Record;

// Define the function to dynamically allocate and initialize memory for multiple components
void init_records(int num_keys, int range_min, int range_max) {
    // Validate the input parameters
    if (num_keys <= 0 || num_keys > 10000) {
        printf("Invalid number of keys: %d\n", num_keys);
        return;
    }
    if (range_min >= range_max) {
        printf("Invalid range: [%d, %d]\n", range_min, range_max);
        return;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(10000 * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));
    Record *records = malloc(num_keys * sizeof(Record));

    // Initialize the arrays
    for (int i = 0; i < 10000; i++) {
        offsets[i] = -1;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = -1;
        records[i].offset_ptr = &offsets[i];
        records[i].status = false;
        records[i].key = -1;
    }

    // Generate random numbers within the specified range for each record's integer field
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int value = rand() % (range_max - range_min + 1) + range_min;
        records[i].value = value;
        keys[i] = value;
    }

    // Use a hash-based approach to track used numbers for optimal performance under concurrent access scenarios
    int *used_numbers = malloc(range_max - range_min + 1);
    memset(used_numbers, 0, sizeof(int) * (range_max - range_min + 1));

    // Populate the status flags based on conditions related to the key values
