    int i;
    for (i = 0; i < size; i++) {
        entry_t* new_entry = malloc(sizeof(entry_t));
        new_entry->offset = i;
        new_entry->next = NULL;
        if (head == NULL) {
            head = tail = new_entry;
        } else {
            tail->next = new_entry;
            tail = new_entry;
