        head = tail = new_entry;
    } else {
        tail->next = new_entry;
        tail = new_entry;
    }

    // Update the hash table with the new entry
    int bucket_index = hash(key);
    bucket_t* bucket = &buckets[bucket_index];
    if (bucket->count == bucket->size) {
