    bucket->entries[bucket->count++] = new_entry;

    // Release locks and return
    pthread_mutex_unlock(&list_lock);
    pthread_mutex_unlock(&table_lock);
}

// Define a function for searching for a specific node by its key and returning the corresponding value if found
double search(char* key) {
    // Acquire lock for both the linked list and hash table
