void init_sequence_numbers(int max_memory) {
    // Calculate the number of elements in the hash table based on the maximum allowed memory footprint
    int num_elements = (max_memory / sizeof(data_packet)) * 2;
    sequence_numbers = malloc(num_elements * sizeof(int));
