        if (linked_list.entries[i]->offset == offset) {
            // Merge the new entry with the existing one
            linked_list.entries[i]->value = value;
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Add the new entry to the end of the linked list
    linked_list.count++;
    linked_list.entries = (entry_t**)realloc(linked_list.entries, sizeof(entry_t*) * linked_list.count);
    linked_list.entries[i] = new_entry;
    pthread_mutex_unlock(&mutex);
}

void* search_node(char* key) {
    pthread_mutex_lock(&mutex);
    int i;
    for (i = 0; i < linked_list.count; i++) {
        if (!strcmp(linked_list.entries[i]->key, key)) {
            // Return the corresponding value if found
            pthread_mutex_unlock(&mutex);
            return linked_list.entries[i]->value;
        }
    }
    // If not found, return an error indicating a duplicate key
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void resize_buckets(int new_size) {
    pthread_mutex_lock(&mutex);
    bucket_t* new_buckets = (bucket_t*)malloc(sizeof(bucket_t) * new_size);
    int i, j;
    for (i = 0; i < new_size; i++) {
        new_buckets[i].size = BUCKET_SIZE;
        new_buckets[i].count = 0;
        new_buckets[i].entries = (entry_t**)malloc(sizeof(entry_t*) * BUCKET_SIZE);
    }
    // Transfer the entries from the old buckets to the new ones
    for (i = 0; i < bucket_count; i++) {
        for (j = 0; j < buckets[i].count; j++) {
            int hash = hash_function(buckets[i].entries[j]->key);
            int index = hash % new_size;
            if (new_buckets[index].count == BUCKET_SIZE) {
                // Resize the bucket if it's full
                new_buckets[index].size *= 2;
                new_buckets[index].entries = (entry_t**)realloc(new_buckets[index].entries, sizeof(entry_t*) * new_buckets[index].size);
            }
            new_buckets[index].count++;
            new_buckets[index].entries[j] = buckets[i].entries[j];
        }
    }
    // Free the old buckets and replace them with the new ones
    for (i = 0; i < bucket_count; i++) {
        free(buckets[i].entries);
    }
    free(buckets);
    buckets = new_buckets;
    pthread_mutex_unlock(&mutex);
}

// Define the functions for managing the hash table and node references in a multi-threaded environment
void insert_node(char* key, double value) {
    pthread_mutex_lock(&mutex);
    int hash = hash_function(key);
    int index = hash % bucket_count;
    if (buckets[index].count == BUCKET_SIZE) {
        // Resize the bucket if it's full
        resize_buckets(bucket_count * 2);
        index = hash % bucket_count;
    }
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->key = key;
    new_node->value = value;
    new_node->refcount = 1;
    buckets[index].entries[buckets[index].count] = new_node;
    buckets[index].count++;
    pthread_mutex_unlock(&mutex);
}

void remove_node(char* key) {
    pthread_mutex_lock(&mutex);
    int hash = hash_function(key);
    int index = hash % bucket_count;
    int i;
    for (i = 0; i < buckets[index].count; i++) {
        if (!strcmp(buckets[index].entries[i]->key, key)) {
            // Decrement the reference count and free the node if it's no longer used
            buckets[index].entries[i]->refcount--;
            if (buckets[index].entries[i]->refcount == 0) {
                free(buckets[index].entries[i]);
                buckets[index].entries[i] = NULL;
            }
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}
