#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the data structures used in the hash table
typedef struct node {
    char* key;
    double value;
} node_t;

typedef struct entry {
    long offset;
    struct entry* next;
} entry_t;

typedef struct bucket {
    int size; // number of nodes in the bucket
    int max_size; // maximum number of nodes that can be stored in the bucket
    node_t** nodes; // array of pointers to nodes
} bucket_t;

// Define the hash table structure
typedef struct {
    int num_buckets; // total number of buckets in the hash table
    int num_nodes; // total number of nodes across all buckets
    bucket_t* buckets; // array of buckets
} hash_table_t;

// Function to create a new node with the given key and value
node_t* create_node(char* key, double value) {
    node_t* node = malloc(sizeof(node_t));
    assert(node != NULL);
    node->key = strdup(key);
    node->value = value;
    return node;
}

// Function to create a new entry with the given offset and next pointer
entry_t* create_entry(long offset, struct entry* next) {
    entry_t* entry = malloc(sizeof(entry_t));
    assert(entry != NULL);
    entry->offset = offset;
    entry->next = next;
    return entry;
}

// Function to create a new bucket with the given size and maximum size
bucket_t* create_bucket(int size, int max_size) {
    bucket_t* bucket = malloc(sizeof(bucket_t));
    assert(bucket != NULL);
    bucket->size = size;
    bucket->max_size = max_size;
    bucket->nodes = malloc(sizeof(node_t*) * max_size);
    assert(bucket->nodes != NULL);
    return bucket;
}

// Function to create a new hash table with the given number of buckets
hash_table_t* create_hash_table(int num_buckets) {
    hash_table_t* hash_table = malloc(sizeof(hash_table_t));
    assert(hash_table != NULL);
    hash_table->num_buckets = num_buckets;
    hash_table->num_nodes = 0;
    hash_table->buckets = malloc(sizeof(bucket_t*) * num_buckets);
    assert(hash_table->buckets != NULL);
    for (int i = 0; i < num_buckets; i++) {
        hash_table->buckets[i] = create_bucket(0, MAX_SIZE);
    }
    return hash_table;
}

// Function to insert a new node into the hash table
void insert_node(hash_table_t* hash_table, char* key, double value) {
    // Calculate the bucket index for the given key
    int bucket_index = hash_function(key);
    // Create a new node with the given key and value
    node_t* node = create_node(key, value);
    // Check if the bucket is full
    if (hash_table->buckets[bucket_index]->size == hash_table->buckets[bucket_index]->max_size) {
        // Reallocate all buckets to double the size
        for (int i = 0; i < hash_table->num_buckets; i++) {
            bucket_t* bucket = hash_table->buckets[i];
            int new_size = bucket->max_size * 2;
            node_t** new_nodes = malloc(sizeof(node_t*) * new_size);
            assert(new_nodes != NULL);
            for (int j = 0; j < bucket->size; j++) {
                new_nodes[j] = bucket->nodes[j];
            }
            free(bucket->nodes);
            bucket->nodes = new_nodes;
            bucket->max_size = new_size;
        }
    }
    // Insert the node into the bucket
    hash_table->buckets[bucket_index]->nodes[hash_table->buckets[bucket_index]->size++] = node;
    hash_table->num_nodes++;
}

// Function to update an existing node in the hash table
void update_node(hash_table_t* hash_table, char* key, double value) {
    // Calculate the bucket index for the given key
    int bucket_index = hash_function(key);
    // Find the node with the matching key
    node_t* node = find_node(hash_table->buckets[bucket_index], key);
    if (node != NULL) {
        // Update the value of the node
        node->value = value;
    } else {
        // Insert a new node with the given key and value
        insert_node(hash_table, key, value);
    }
}

// Function to delete a node from the hash table by its key
void delete_node(hash_table_t* hash_table, char* key) {
    // Calculate the bucket index for the given key
    int bucket_index = hash_function(key);
    // Find the node with the matching key
    node_t* node = find_node(hash_table->buckets[bucket_index], key);
    if (node != NULL) {
        // Remove the node from the bucket
        for (int i = 0; i < hash_table->buckets[bucket_index]->size - 1; i++) {
            if (hash_table->buckets[bucket_index]->nodes[i] == node) {
                hash_table->buckets[bucket_index]->nodes[i] = hash_table->buckets[bucket_index]->nodes[i + 1];
                break;
            }
        }
        hash_table->buckets[bucket_index]->size--;
        hash_table->num_nodes--;
    }
}

// Function to search for a node in the hash table by its key and return its value if found
double* find_node(hash_table_t* hash_table, char* key) {
    // Calculate the bucket index for the given key
    int bucket_index = hash_function(key);
    // Find the node with the matching key
    node_t* node = find_node(hash_table->buckets[bucket_index], key);
    if (node != NULL) {
        return &node->value;
    } else {
        return NULL;
    }
}

// Function to calculate the hash value for a given key
int hash_function(char* key) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % hash_table->num_buckets;
}

// Function to find a node in a bucket by its key
node_t* find_node(bucket_t* bucket, char* key) {
    for (int i = 0; i < bucket->size; i++) {
        if (strcmp(bucket->nodes[i]->key, key) == 0) {
            return bucket->nodes[i];
        }
    }
    return NULL;
}
