#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

// Node structure for the array of nodes
typedef struct node {
    char* key;
    double value;
} node_t;

// Entry structure for the linked list of entries
typedef struct entry {
    long offset;
    struct entry* next;
    int refcount;
} entry_t;

// Bucket structure for the hash table
typedef struct bucket {
    node_t** nodes;
    size_t capacity;
    size_t count;
} bucket_t;

// Global variables for managing the hash table and buckets
static bucket_t* buckets = NULL;
static size_t num_buckets = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new node into the hash table
void insert(char* key, double value) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the bucket for the given key
    size_t index = hash(key) % num_buckets;
    bucket_t* bucket = &buckets[index];

    // Check if the bucket is full and needs to be resized
    if (bucket->count == bucket->capacity) {
        resize_bucket(bucket);
    }

    // Allocate a new node for the given key and value
    node_t* node = malloc(sizeof(node_t));
    node->key = strdup(key);
    node->value = value;

    // Insert the node into the bucket
    bucket->nodes[bucket->count++] = node;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing node in the hash table
void update(char* key, double value) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the bucket for the given key
    size_t index = hash(key) % num_buckets;
    bucket_t* bucket = &buckets[index];

    // Check if the bucket is full and needs to be resized
    if (bucket->count == bucket->capacity) {
        resize_bucket(bucket);
    }

    // Find the node for the given key in the bucket
    size_t i;
    for (i = 0; i < bucket->count; i++) {
        if (strcmp(key, bucket->nodes[i]->key) == 0) {
            break;
        }
    }

    // Update the value of the found node
    if (i < bucket->count) {
        bucket->nodes[i]->value = value;
    } else {
        // Allocate a new node for the given key and value
        node_t* node = malloc(sizeof(node_t));
        node->key = strdup(key);
        node->value = value;

        // Insert the node into the bucket
        bucket->nodes[bucket->count++] = node;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to delete a node from the hash table by key
void delete(char* key) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the bucket for the given key
    size_t index = hash(key) % num_buckets;
    bucket_t* bucket = &buckets[index];

    // Find the node for the given key in the bucket
    size_t i;
    for (i = 0; i < bucket->count; i++) {
        if (strcmp(key, bucket->nodes[i]->key) == 0) {
            break;
        }
    }

    // Delete the found node from the bucket
    if (i < bucket->count) {
        free(bucket->nodes[i]);
        bucket->nodes[i] = NULL;
        bucket->count--;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to search for a node in the hash table by key and return its value if found
double search(char* key) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Find the bucket for the given key
    size_t index = hash(key) % num_buckets;
    bucket_t* bucket = &buckets[index];

    // Find the node for the given key in the bucket
    size_t i;
    for (i = 0; i < bucket->count; i++) {
        if (strcmp(key, bucket->nodes[i]->key) == 0) {
            break;
        }
    }

    // Return the value of the found node
    double value = 0.0;
    if (i < bucket->count) {
        value = bucket->nodes[i]->value;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return value;
}

// Function to resize a bucket when it is full
void resize_bucket(bucket_t* bucket) {
    // Double the capacity of the bucket
    size_t new_capacity = bucket->capacity * 2;

    // Allocate a new array for the nodes in the bucket
    node_t** new_nodes = malloc(new_capacity * sizeof(node_t*));

    // Copy the existing nodes to the new array
    size_t i;
    for (i = 0; i < bucket->count; i++) {
        new_nodes[i] = bucket->nodes[i];
    }

    // Free the old array of nodes
    free(bucket->nodes);

    // Update the bucket with the new array and capacity
    bucket->nodes = new_nodes;
    bucket->capacity = new_capacity;
}

// Function to resize all buckets when the occupancy rate exceeds 75%
void resize_buckets() {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if any bucket needs to be resized
    size_t i;
    for (i = 0; i < num_buckets; i++) {
        if (buckets[i].count > buckets[i].capacity * 0.75) {
            resize_bucket(&buckets[i]);
        }
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to globally reallocate buckets when each bucket reaches its capacity limit of 128 nodes
void reallocate_buckets() {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if any bucket needs to be reallocated
    size_t i;
    for (i = 0; i < num_buckets; i++) {
        if (buckets[i].count == buckets[i].capacity) {
            break;
        }
    }

    // Reallocate the buckets if necessary
    if (i < num_buckets) {
        size_t new_num_buckets = num_buckets * 2;
        bucket_t* new_buckets = malloc(new_num_buckets * sizeof(bucket_t));

        // Copy the existing buckets to the new array
        for (i = 0; i < num_buckets; i++) {
            new_buckets[i] = buckets[i];
        }

        // Free the old array of buckets
        free(buckets);

        // Update the global variables with the new array and number of buckets
        buckets = new_buckets;
        num_buckets = new_num_buckets;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to track the total number of nodes across all buckets and entries
size_t get_total_nodes() {
    size_t total = 0;

    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Calculate the total number of nodes in all buckets and entries
    size_t i;
    for (i = 0; i < num_buckets; i++) {
        total += buckets[i].count;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return total;
}
