    TRANSACTION_TYPE_DEPOSIT,
    TRANSACTION_TYPE_WITHDRAWAL,
    TRANSACTION_TYPE_TRANSFER
} transactionType;

// Define the error level enum
typedef enum {
    ERROR_LEVEL_NONE,
    ERROR_LEVEL_LOW,
    ERROR_LEVEL_MEDIUM,
    ERROR_LEVEL_HIGH
} errorLevel;

// Define the transaction node struct
struct transactionNode {
    unsigned long id;
    double amount;
    time_t timestamp;
    transactionType type;
    errorLevel level;
};

// Define the linked list of transaction nodes
struct transactionList {
    struct transactionNode *head;
    struct transactionNode *tail;
};

// Define the caching mechanism for frequently accessed transaction IDs
struct cache {
    unsigned long capacity;
    unsigned long size;
    unsigned long *ids;
};

// Define the logger interface
struct logger {
    void (*log)(const char *message);
};

// Define the function to dynamically allocate memory for and initialize the data structures
void initDataStructures(unsigned long seed, const char *configFilePath) {
    // Load the configuration file
    FILE *configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        printf("Error: unable to open config file\n");
        exit(1);
    }

    // Read the configuration parameters from the file
    unsigned long transactionRange;
    unsigned long maxTransactions;
    double errorThreshold;
    char *cacheConfig;
    if (fscanf(configFile, "%lu %lu %lf %s", &transactionRange, &maxTransactions, &errorThreshold, cacheConfig) != 4) {
        printf("Error: unable to read configuration parameters\n");
        exit(1);
    }

    // Close the configuration file
    fclose(configFile);

    // Initialize the linked list of transaction nodes
    struct transactionList *transactionList = malloc(sizeof(struct transactionList));
    if (transactionList == NULL) {
        printf("Error: unable to allocate memory for transaction list\n");
        exit(1);
    }
    transactionList->head = NULL;
    transactionList->tail = NULL;

    // Initialize the caching mechanism
    struct cache *cache = malloc(sizeof(struct cache));
    if (cache == NULL) {
        printf("Error: unable to allocate memory for cache\n");
        exit(1);
    }
    cache->capacity = 10;
    cache->size = 0;
    cache->ids = malloc(sizeof(unsigned long) * cache->capacity);
    if (cache->ids == NULL) {
        printf("Error: unable to allocate memory for cache IDs\n");
        exit(1);
    }

    // Initialize the random number generator
    srand(seed);

    // Populate the linked list of transaction nodes with random values within the specified range
    unsigned long id = 0;
    while (id < maxTransactions) {
        struct transactionNode *node = malloc(sizeof(struct transactionNode));
        if (node == NULL) {
            printf("Error: unable to allocate memory for transaction node\n");
            exit(1);
        }
        node->id = id;
        node->amount = rand() % transactionRange + 1;
        node->timestamp = time(NULL);
        node->type = (transactionType)((rand() % 3) + 1);
        node->level = ERROR_LEVEL_NONE;
        if (id == 0) {
            transactionList->head = node;
            transactionList->tail = node;
        } else {
            transactionList->tail->next = node;
            transactionList->tail = node;
        }
        id++;
    }

    // Populate the caching mechanism with frequently accessed transaction IDs
    unsigned long *ids = malloc(sizeof(unsigned long) * cache->capacity);
    if (ids == NULL) {
        printf("Error: unable to allocate memory for cache IDs\n");
        exit(1);
    }
    for (int i = 0; i < cache->capacity; i++) {
        ids[i] = rand() % maxTransactions + 1;
    }
    cache->ids = ids;

    // Start the background thread for asynchronous processing of transactions
    pthread_t thread;
    if (pthread_create(&thread, NULL, processTransactions, transactionList) != 0) {
        printf("Error: unable to create background thread\n");
        exit(1);
    }
}

// Define the function to deallocate all allocated memory when the function is done
void cleanupDataStructures() {
    // Deallocate the linked list of transaction nodes
    struct transactionList *transactionList = malloc(sizeof(struct transactionList));
    if (transactionList == NULL) {
        printf("Error: unable to allocate memory for transaction list\n");
