import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class RecordManager {
    private static final int DEFAULT_MAX_RECORDS = 10000;
    private static final int DEFAULT_TEMPERATURE_RANGE = 50;
    private static final int DEFAULT_ALERT_THRESHOLD = 30;
    private static final int DEFAULT_CACHE_SIZE = 1000;

    private long[] offsetValues;
    private int[] keyValues;
    private Record[] records;
    private AtomicInteger recordCount = new AtomicInteger(0);
    private ReentrantLock lock = new ReentrantLock();

    public RecordManager() {
        this.offsetValues = new long[DEFAULT_MAX_RECORDS];
        this.keyValues = new int[DEFAULT_MAX_RECORDS];
        this.records = new Record[DEFAULT_MAX_RECORDS];
    }

    public void init(int seed, String configFilePath) {
        // Handle edge cases where the configuration file is missing or malformed
        if (configFilePath == null || !new File(configFilePath).exists()) {
            log.error("Configuration file not found or invalid");
            return;
        }

        // Load configuration from file
        Config config = new Config();
        try {
            config.load(configFilePath);
        } catch (IOException e) {
            log.error("Failed to load configuration", e);
            return;
        }

        // Initialize offset and key arrays
        this.offsetValues = new long[config.getMaxRecords()];
        this.keyValues = new int[config.getMaxRecords()];

        // Initialize record array
        this.records = new Record[config.getMaxRecords()];

        // Initialize random number generator with seed
        Random rand = new Random(seed);

        // Populate arrays with random values within temperature range
        for (int i = 0; i < config.getMaxRecords(); i++) {
            this.offsetValues[i] = rand.nextInt(config.getTemperatureRange());
            this.keyValues[i] = rand.nextInt(config.getMaxRecords());
        }

        // Initialize record count
        this.recordCount.set(config.getMaxRecords());
    }

    public void addRecord(int value, long timestamp) {
        lock.lock();
        try {
            if (this.recordCount.get() >= DEFAULT_MAX_RECORDS) {
                log.warn("Reached maximum number of records");
                return;
            }

            // Populate record with random value within temperature range
            int randValue = rand.nextInt(config.getTemperatureRange());

            // Populate record with unique timestamp
            long currentTime = System.currentTimeMillis();

            // Populate record with appropriate data type and alert level
            DataType dataType = getDataType(value);
            AlertLevel alertLevel = getAlertLevel(dataType, value);

            // Add record to array
            this.records[this.recordCount.get()] = new Record(randValue, currentTime, dataType, alertLevel);

            // Increment record count
            this.recordCount.incrementAndGet();
        } finally {
            lock.unlock();
        }
    }

    public void deallocateMemory() {
        // Deallocate memory for offset and key arrays
        this.offsetValues = null;
        this.keyValues = null;

        // Deallocate memory for record array
        this.records = null;
    }

    private DataType getDataType(int value) {
        if (value < 0) {
            return DataType.NEGATIVE;
        } else if (value > 0) {
            return DataType.POSITIVE;
        } else {
            return DataType.ZERO;
        }
    }

    private AlertLevel getAlertLevel(DataType dataType, int value) {
        if (dataType == DataType.NEGATIVE && value < DEFAULT_ALERT_THRESHOLD) {
            return AlertLevel.CRITICAL;
        } else if (dataType == DataType.POSITIVE && value > DEFAULT_ALERT_THRESHOLD) {
            return AlertLevel.WARNING;
        } else {
            return AlertLevel.NORMAL;
        }
    }
}
