// Define the data structures to hold the offset, key, record, and tag values
typedef struct {
    long offset;
    int key;
    record_t record;
    string_t tag;
} record_info_t;

// Define the function to dynamically allocate memory for the arrays
int allocate_memory(size_t num_records, size_t *offset_array, size_t *key_array, record_info_t **record_array, string_t **tag_array) {
    // Calculate the total size of the memory to be allocated
    size_t total_size = (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(record_info_t)) + (num_records * sizeof(string_t));

    // Allocate the memory using mmap
    void *mem = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    // Initialize the offset array
    size_t *offset = mem;
    for (size_t i = 0; i < num_records; i++) {
        offset[i] = i * sizeof(record_info_t);
    }

    // Initialize the key array
    int *key = (int *)((char *)mem + (num_records * sizeof(long)));
    for (size_t i = 0; i < num_records; i++) {
        key[i] = rand() % 100;
    }

    // Initialize the record array
    record_info_t *record = (record_info_t *)((char *)mem + (num_records * sizeof(long)) + (num_records * sizeof(int)));
    for (size_t i = 0; i < num_records; i++) {
        record[i].key = key[i];
        record[i].record.value = rand() % 100;
        record[i].tag = generate_string(10);
    }

    // Initialize the tag array
    string_t *tag = (string_t *)((char *)mem + (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(record_info_t)));
    for (size_t i = 0; i < num_records; i++) {
        tag[i] = generate_string(10);
    }

    // Set the output parameters
    *offset_array = offset;
    *key_array = key;
    *record_array = record;
    *tag_array = tag;

    return 0;
}

