// Define the data structures to be used
typedef struct {
    double performanceMetric;
    float temperatureReading;
    char transactionType;
    char sensorIdentifier;
    unsigned long transactionID;
} combinedRecord;

typedef enum {
    TRANSACTION_TYPE_A,
    TRANSACTION_TYPE_B,
    TRANSACTION_TYPE_C,
    TRANSACTION_TYPE_D
} transactionType;

// Define the configuration file format
struct configFile {
    double performanceMetricRange[2];
    float temperatureRange[2];
    int transactionRange[2];
    int maxNumberOfRecords;
    int errorThresholdLevels[3];
    char cacheConfigurations[3][2];
};

// Define the logger interface
struct logger {
    void (*log)(const char* message);
};

// Define the caching mechanism
struct cache {
    combinedRecord** records;
    int capacity;
    int size;
    int head;
    int tail;
    int evictionPolicy;
};

// Define the function to dynamically allocate memory for and initialize multiple data structures
void initDataStructures(const char* configFilePath, struct logger* logger) {
    // Load the configuration file
    struct configFile config = loadConfigFile(configFilePath);

    // Initialize the combined record array
    combinedRecord** records = (combinedRecord**)malloc(sizeof(combinedRecord*) * config.maxNumberOfRecords);
    for (int i = 0; i < config.maxNumberOfRecords; i++) {
        records[i] = (combinedRecord*)malloc(sizeof(combinedRecord));
        records[i]->performanceMetric = generateRandomDouble(config.performanceMetricRange);
        records[i]->temperatureReading = generateRandomFloat(config.temperatureRange);
        records[i]->transactionType = generateTransactionType();
        records[i]->sensorIdentifier = generateSensorIdentifier();
        records[i]->transactionID = generateTransactionID(config.startingID, config.incrementValue);
    }

    // Initialize the transaction ID cache
    struct cache* transactionIDCache = (struct cache*)malloc(sizeof(struct cache));
    transactionIDCache->records = (combinedRecord**)malloc(sizeof(combinedRecord*) * config.maxNumberOfRecords);
    transactionIDCache->capacity = config.maxNumberOfRecords;
    transactionIDCache->size = 0;
    transactionIDCache->head = 0;
    transactionIDCache->tail = 0;
    transactionIDCache->evictionPolicy = LRU_EVICTION;

    // Initialize the error message string array
    char** errorMessages = (char**)malloc(sizeof(char*) * config.maxNumberOfRecords);
    for (int i = 0; i < config.maxNumberOfRecords; i++) {
        errorMessages[i] = (char*)malloc(sizeof(char) * ERROR_MESSAGE_LENGTH);
        strcpy(errorMessages[i], "");
    }

    // Initialize the background thread for asynchronous processing of transactions
    pthread_t backgroundThread;
    pthread_create(&backgroundThread, NULL, processTransactions, (void*)records);

    // Export combined records to a specified output file in a structured format
    exportCombinedRecords(records, config.outputFilePath, config.outputFormat);

    // Deallocate all allocated memory when the function is done
    free(records);
    free(transactionIDCache->records);
    for (int i = 0; i < config.maxNumberOfRecords; i++) {
        free(errorMessages[i]);
    }
    free(errorMessages);
}

// Load the configuration file from disk
struct configFile loadConfigFile(const char* configFilePath) {
    struct configFile config;
    FILE* configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        printf("Error: unable to open configuration file\n");
        exit(1);
    }
    fscanf(configFile, "%lf %lf %d %d %d", &config.performanceMetricRange[0], &config.performanceMetricRange[1], &config.transactionRange[0], &config.transactionRange[1], &config.maxNumberOfRecords);
    fscanf(configFile, "%d %d %d", &config.errorThresholdLevels[0], &config.errorThresholdLevels[1], &config.errorThresholdLevels[2]);
    for (int i = 0; i < 3; i++) {
