    }
    fclose(configFile);
    return config;
}

// Generate a random double precision floating-point number within the specified range
double generateRandomDouble(double* range) {
    return (range[0] + ((double)rand() / RAND_MAX) * (range[1] - range[0]));
}

// Generate a random float temperature reading within the specified range
float generateRandomFloat(float* range) {
    return (range[0] + ((float)rand() / RAND_MAX) * (range[1] - range[0]));
}

// Generate a unique transaction ID using the provided starting ID and increment value
unsigned long generateTransactionID(unsigned long startingID, unsigned long incrementValue) {
    return startingID + ((unsigned long)rand() / RAND_MAX) * incrementValue;
}

// Generate a random transaction type from the provided list of valid types
char generateTransactionType() {
    int index = (int)(rand() % 4);
    switch (index) {
        case 0: return TRANSACTION_TYPE_A;
        case 1: return TRANSACTION_TYPE_B;
        case 2: return TRANSACTION_TYPE_C;
        default: return TRANSACTION_TYPE_D;
    }
}

// Generate a random sensor identifier from the provided list of valid identifiers
char generateSensorIdentifier() {
    int index = (int)(rand() % 3);
    switch (index) {
        case 0: return 'A';
        case 1: return 'B';
        default: return 'C';
    }
}

// Process transactions in the background thread
