#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <json-c/json.h>
#include <openssl/evp.h>

typedef struct {
    long offset;
    int key;
    record *records;
} MoSTState;

bool allocateAndInitializeRecords(const char *filePath, const char *jsonString, int maxRecords) {
    // Load state object from file and validate OAuth2 access token details
    json_object *json = json_tokener_parse(jsonString);
    if (!json || !json_is_object(json)) {
        return false;
    }

    const char *accessToken = json_object_get_string(json, "access_token");
    int expiresIn = json_object_get_int(json, "expires_in");
    const char *tokenType = json_object_get_string(json, "token_type");
    const char *clientId = json_object_get_string(json, "client_id");
    const char *refreshToken = json_object_get_string(json, "refresh_token");

    if (!accessToken || !expiresIn || !tokenType || !clientId) {
        return false;
    }

    // Verify that the token type is 'Bearer' and the expires in field is a positive integer
    if (strcmp(tokenType, "Bearer") != 0 || expiresIn <= 0) {
        return false;
    }

    // Verify that the client ID matches an allowed list of clients
    const char *allowedClients[] = {"client1", "client2"};
    bool isAllowedClient = false;
    for (int i = 0; i < sizeof(allowedClients) / sizeof(char*); i++) {
        if (!strcmp(clientId, allowedClients[i])) {
            isAllowedClient = true;
            break;
        }
    }
    if (!isAllowedClient) {
        return false;
    }

    // Check if the access token has expired based on the current system time and the expires in value
    time_t now = time(NULL);
    if (now > expiresIn) {
        return false;
    }

    // Initialize EVP_CIPHER structure based on cipher mode specified in JSON object
    const char *cipherMode = json_object_get_string(json, "cipher_mode");
    if (!cipherMode) {
        return false;
    }
    EVP_CIPHER *cipher = NULL;
    if (!strcmp(cipherMode, "AES-128-CBC")) {
        cipher = EVP_aes_128_cbc();
    } else if (!strcmp(cipherMode, "AES-192-CBC")) {
        cipher = EVP_aes_192_cbc();
    } else if (!strcmp(cipherMode, "AES-256-CBC")) {
        cipher = EVP_aes_256_cbc();
    } else {
        return false;
    }

    // Load state object from file and validate it is an instance of the MoSTState class
    FILE *file = fopen(filePath, "r");
    if (!file) {
        return false;
    }
    MoSTState *state = NULL;
    ObjectInputStream stream(file);
    state = (MoSTState *)stream.readObject();
    if (!state || !state->isInstanceOf(MoSTState::class)) {
        fclose(file);
        return false;
    }
    fclose(file);

    // Allocate memory for arrays of long, int, and record structures
    long *offsets = (long *)malloc(maxRecords * sizeof(long));
    int *keys = (int *)malloc(maxRecords * sizeof(int));
    record **records = (record **)malloc(maxRecords * sizeof(record*));
    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return false;
    }

    // Set the value of each record's int field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < maxRecords; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            free(records);
            return false;
        }
        records[i]->value = rand() % 1000;
    }

    // Free any allocated memory before returning
    free(offsets);
    free(keys);
    for (int i = 0; i < maxRecords; i++) {
        free(records[i]);
    }
    free(records);

    return true;
}
