#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define a structure to store transaction details
typedef struct {
    int transaction_id;
    double amount;
    char* description;
} transactionDetails;

// Define a function to manage memory and data for the high-throughput transaction processing system
void manageMemory(int numTransactions, int numMerchants) {
    // Allocate memory for an array of transactionDetails structures
    transactionDetails* transactions = (transactionDetails*)malloc(numTransactions * sizeof(transactionDetails));
    if (!transactions) {
        printf("Error: Failed to allocate memory for %d transactions\n", numTransactions);
        return;
    }

    // Allocate memory for an array of merchant names
    char** merchants = (char**)malloc(numMerchants * sizeof(char*));
    if (!merchants) {
        printf("Error: Failed to allocate memory for %d merchants\n", numMerchants);
        free(transactions);
        return;
    }

    // Initialize the transactionDetails structures and merchant names
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].transaction_id = i + 1;
        transactions[i].amount = 0.0;
        transactions[i].description = NULL;
    }
    for (int i = 0; i < numMerchants; i++) {
        merchants[i] = malloc(256 * sizeof(char));
        if (!merchants[i]) {
            printf("Error: Failed to allocate memory for merchant name %d\n", i);
            free(transactions);
            free(merchants);
            return;
        }
    }

    // Populate the transactionDetails structures and merchant names
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].amount = 10.0;
        strcpy(merchants[i % numMerchants], "Merchant #");
        char temp[256];
        sprintf(temp, "%d", i + 1);
        strcat(merchants[i % numMerchants], temp);
    }

    // Process the transactions concurrently using pthreads
    pthread_t threads[numTransactions];
    for (int i = 0; i < numTransactions; i++) {
        pthread_create(&threads[i], NULL, processTransaction, &transactions[i]);
    }
    for (int i = 0; i < numTransactions; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free the memory allocated for the transactionDetails structures and merchant names
    free(transactions);
    for (int i = 0; i < numMerchants; i++) {
        free(merchants[i]);
    }
    free(merchants);
}

// Define a function to process a single transaction concurrently using pthreads
void* processTransaction(void* arg) {
    // Cast the argument to a pointer to a transactionDetails structure
    transactionDetails* transaction = (transactionDetails*)arg;

    // Perform some processing on the transaction
    printf("Processing transaction %d with amount %.2f and description '%s'\n", transaction->transaction_id, transaction->amount, transaction->description);

    // Return NULL to indicate that the thread has completed its task
    return NULL;
