#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <limits.h>

typedef struct {
    int value;
    long *offset_ptr;
    bool status;
    int key;
} record;

record* allocate_records(int num_keys, size_t max_memory) {
    if (num_keys <= 0 || num_keys > INT_MAX) {
        return NULL;
    }

    // Calculate the required memory for the records and offset array
    size_t record_size = sizeof(record);
    size_t offset_array_size = sizeof(long) * 10000;
    size_t total_memory = record_size * num_keys + offset_array_size;

    // Check if the required memory exceeds the maximum allowed memory footprint
    if (total_memory > max_memory) {
        return NULL;
    }

    // Allocate memory for the records and offset array
    record *records = malloc(record_size * num_keys);
    long *offset_array = malloc(offset_array_size);

    if (records == NULL || offset_array == NULL) {
        free(records);
        free(offset_array);
        return NULL;
    }

    // Initialize the records and offset array
    for (int i = 0; i < num_keys; i++) {
        record *record = &records[i];
        record->value = generate_random_number(1, 100);
        record->offset_ptr = &offset_array[i];
        record->status = false;
        record->key = i;
    }

    // Generate unique random numbers for each record's integer field
    srand(time(NULL));
    int used_numbers[100] = {0};
    for (int i = 0; i < num_keys; i++) {
        int random_number = generate_random_number(1, 100);
        while (used_numbers[random_number]) {
            random_number = generate_random_number(1, 100);
        }
        used_numbers[random_number] = true;
        records[i].value = random_number;
    }

    return records;
}

int generate_random_number(int min, int max) {
    return rand() % (max - min + 1) + min;
}
