// Define the range of random numbers to generate
#define RANDOM_NUMBER_RANGE 1000000

// Define the structure for a record
typedef struct {
    int value;
    long* offset;
    bool status;
    int key;
} Record;

// Function to dynamically allocate and initialize memory for multiple components
void init_memory(int num_keys) {
    // Validate the number of keys to ensure it does not exceed predefined limits
    if (num_keys > MAX_NUM_KEYS || num_keys <= 0) {
        printf("Invalid number of keys: %d\n", num_keys);
        return;
    }

    // Calculate the size of the offset array based on the number of keys
    int offset_array_size = sizeof(long) * num_keys;

    // Allocate memory for the offset array
    long* offsets = (long*)malloc(offset_array_size);
    if (!offsets) {
        printf("Failed to allocate memory for offset array\n");
        return;
    }

    // Initialize the offset array with random numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = rand() % RANDOM_NUMBER_RANGE + 1;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(sizeof(int) * num_keys);
    if (!keys) {
        printf("Failed to allocate memory for key array\n");
        free(offsets);
        return;
    }

    // Initialize the key array with unique random numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % RANDOM_NUMBER_RANGE + 1;
    }

    // Allocate memory for the record array
    Record* records = (Record*)malloc(sizeof(Record) * num_keys);
    if (!records) {
        printf("Failed to allocate memory for record array\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with values from the offset and key arrays
    for (int i = 0; i < num_keys; i++) {
        records[i].value = offsets[i];
        records[i].offset = &offsets[i];
        records[i].status = false;
        records[i].key = keys[i];
    }

    // Free the memory for the offset and key arrays, as they are no longer needed
    free(offsets);
    free(keys);

    // Return the initialized record array
    return records;
}
