    for (int i = 0; i < num_keys; i++) {
        record_array[i].status = false;
        record_array[i].key = key_array[i];
    }

    // Allocate memory for the offset pointers and initialize them to point to the corresponding elements in the offset array
    long *offset_ptr_array = (long *)malloc(sizeof(long) * num_keys);
    for (int i = 0; i < num_keys; i++) {
        offset_ptr_array[i] = &offset_array[record_array[i].value - 1];
    }

    // Set the offset pointers in each record to point to the corresponding elements in the offset array
    for (int i = 0; i < num_keys; i++) {
        record_array[i].offset_ptr = &offset_ptr_array[i];
    }

    // Free the memory allocated for the arrays of long offset values and integers
    free(offset_array);
    free(key_array);

    // Return the initialized record array
    return record_array;
}

// Define a custom dynamic memory pool to manage memory allocations efficiently
struct mempool {
    void *mem;
    size_t size;
};

// Define a function to allocate memory from the custom dynamic memory pool
void *allocate(size_t size) {
    // Check if the requested size is within the maximum allowed size for the pool
    if (size > MAX_POOL_SIZE) {
        printf("Requested size exceeds maximum pool size\n");
        return NULL;
    }

    // Allocate memory from the pool
    struct mempool *mempool = malloc(sizeof(struct mempool));
    mempool->mem = malloc(size);
    mempool->size = size;

    // Return a pointer to the allocated memory
    return mempool->mem;
}

// Define a function to free memory from the custom dynamic memory pool
void deallocate(void *ptr) {
    // Check if the requested pointer is within the pool
    struct mempool *mempool = (struct mempool *)ptr;
    if (mempool->size > MAX_POOL_SIZE || mempool->mem != ptr) {
        printf("Invalid memory deallocation request\n");
        return;
    }

    // Free the allocated memory from the pool
    free(mempool->mem);
    free(mempool);
}

// Define a function to monitor the usage of the custom dynamic memory pool
void monitor_usage() {
    // Calculate the current usage of the pool
    size_t used_size = 0;
    for (struct mempool *mempool = malloc(sizeof(struct mempool)); mempool != NULL; mempool = mempool->next) {
        used_size += mempool->size;
    }

    // Print the current usage of the pool and trigger an alert if necessary
    printf("Memory usage: %zu\n", used_size);
    if (used_size > MAX_POOL_SIZE * 0.8) {
        printf("Memory usage exceeds 80%% of maximum pool size\n");
    }
}

// Define a function to handle errors during memory allocation and recovery
void handle_error(int error_code, const char *message) {
    // Print the error message and retry the operation if necessary
    printf("Error %d: %s\n", error_code, message);
    if (error_code == ENOMEM) {
        printf("Retrying memory allocation...\n");
        return;
    }
}
