import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.ReentrantLock;

public class RecordManager {
    private static final int DEFAULT_MAX_RECORDS = 10000;
    private static final int DEFAULT_TEMPERATURE_RANGE = 20;
    private static final int DEFAULT_ALERT_THRESHOLD = 30;
    private static final int DEFAULT_CACHE_SIZE = 1000;

    private long[] offsetValues;
    private int[] keyValues;
    private Record[] records;
    private AtomicInteger recordCount = new AtomicInteger(0);
    private ReentrantLock lock = new ReentrantLock();

    public RecordManager() {
        this.offsetValues = new long[DEFAULT_MAX_RECORDS];
        this.keyValues = new int[DEFAULT_MAX_RECORDS];
        this.records = new Record[DEFAULT_MAX_RECORDS];
    }

    public void init(int seed, String configFilePath) {
        // Handle edge cases where the configuration file is missing or malformed
        if (configFilePath == null || !new File(configFilePath).exists()) {
            log.error("Configuration file not found or invalid");
            return;
        }

        // Load configuration from file
        Config config = new Config();
        try {
            config.load(configFilePath);
        } catch (IOException e) {
            log.error("Failed to load configuration", e);
            return;
        }

        // Initialize random number generator with seed
        Random rng = new Random(seed);

        // Initialize offset and key arrays
        for (int i = 0; i < DEFAULT_MAX_RECORDS; i++) {
            offsetValues[i] = rng.nextLong();
            keyValues[i] = rng.nextInt();
        }

        // Initialize record array
        for (int i = 0; i < DEFAULT_MAX_RECORDS; i++) {
            records[i] = new Record(rng.nextInt(), System.currentTimeMillis(), DataType.TEMPERATURE, AlertLevel.NORMAL);
        }
    }

    public void addRecord(int value) {
        // Handle edge cases where the record count exceeds the maximum number of records
        if (recordCount.get() >= DEFAULT_MAX_RECORDS) {
            log.warn("Maximum number of records reached, ignoring new record");
            return;
        }

        // Acquire lock to prevent concurrent modification of arrays
        lock.lock();

        try {
            // Generate random offset and key values
            int offset = rng.nextInt(DEFAULT_TEMPERATURE_RANGE);
            int key = rng.nextInt();

            // Check if the generated key is already in use, if so reuse it
            while (keyValues[key] != 0) {
                key = rng.nextInt();
            }

            // Populate record array with new values
            records[recordCount.get()] = new Record(value, System.currentTimeMillis(), DataType.TEMPERATURE, AlertLevel.NORMAL);
            offsetValues[recordCount.get()] = offset;
            keyValues[recordCount.get()] = key;

            // Increment record count
            recordCount.incrementAndGet();
        } finally {
            lock.unlock();
        }
    }

    public void deallocateMemory() {
        // Deallocate memory for offset and key arrays
        offsetValues = null;
        keyValues = null;

        // Deallocate memory for record array
        records = null;
    }
}
