    if (!transactions) {
        printf("Error: Failed to allocate memory for transaction details array\n");
        free(offsets);
        free(merchantNames);
        return;
    }

    // Initialize the offset array with random values within the specified range
    for (int i = 0; i < numTransactions; i++) {
        offsets[i] = rand() % (MAX_TRANSACTION_ID - MIN_TRANSACTION_ID + 1) + MIN_TRANSACTION_ID;
    }

    // Initialize the merchant name array with random values from the list of names
    for (int i = 0; i < numTransactions; i++) {
        int index = rand() % NUM_MERCHANT_NAMES;
        merchantNames[i] = MERCHANT_NAMES[index];
    }

    // Initialize the transaction details array with random values within the specified range
    for (int i = 0; i < numTransactions; i++) {
        transactions[i].transactionId = offsets[i];
        transactions[i].amount = rand() % (MAX_AMOUNT - MIN_AMOUNT + 1) + MIN_AMOUNT;
        transactions[i].description = "Test Transaction";
        transactions[i].flag = 'P';
