    int event_type;
    size_t allocated_memory;
    size_t used_memory;
} Log;

void generate_configuration(const char* filename, const Dictionary* parameters) {
    // Allocate memory for the arrays
    Record** records = (Record**)malloc(sizeof(Record*) * 3);
    Batch* batches = (Batch*)malloc(sizeof(Batch) * 10);

    // Initialize the log structure
    Log log;
    log.event_type = EVENT_TYPE_ALLOCATION;
    log.allocated_memory = 0;
    log.used_memory = 0;

    // Populate the arrays with data
    for (int i = 0; i < 10; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        batches[i].records = records;
        batches[i].count = 3;
        log.allocated_memory += sizeof(Record) * 3;
        log.used_memory += sizeof(Record) * 3;

        for (int j = 0; j < 3; j++) {
            records[j]->value = pow(2, i + j);
            records[j]->id = i * 10 + j;
            records[j]->name = (char*)malloc(sizeof(char) * 10);
            sprintf(records[j]->name, "%d", records[j]->id);
            log.allocated_memory += sizeof(char) * 10;
            log.used_memory += sizeof(char) * 10;
        }
    }

    // Validate for memory leaks
    if (log.allocated_memory != log.used_memory) {
        printf("Memory leak detected!\n");
    }

    // Write the generated configuration to a file
    FILE* fp = fopen(filename, "w");
    if (!fp) {
        perror("fopen");
        return;
    }

    for (int i = 0; i < 10; i++) {
        fprintf(fp, "%d\n", batches[i].count);
        for (int j = 0; j < batches[i].count; j++) {
            fprintf(fp, "%f %d %s\n", batches[i].records[j]->value, batches[i].records[j]->id, batches[i].records[j]->name);
        }
    }

    // Modify the file with a Python script
    char* command = "python modify_file.py";
    char* args[] = {"modify_file.py", filename};
    int status = system(command, args);
    if (status != 0) {
        printf("Error executing sed commands\n");
    }

    // Free the memory
    for (int i = 0; i < 10; i++) {
        free(batches[i].records);
        free(batches[i].log.name);
    }
    free(batches);
    free(records);
}
