    for (size_t i = 0; i < num_records; i++) {
        records[i].value = calculateValue(i);
        records[i].id = i + 1;
        records[i].name = (char *)malloc(strlen("Name") + 1);
        strcpy(records[i].name, "Name");
    }
}

// Function to calculate the double value for each record based on a mathematical function
double calculateValue(size_t i) {
    return (i * 2.0) / 3.0;
}

// Function to manage memory allocations efficiently and track all allocation and deallocation events in a log structure
void manageMemory() {
    struct Log log = {0, 0};
    for (size_t i = 0; i < num_records; i++) {
        // Allocate memory for the record name
        records[i].name = (char *)malloc(strlen("Name") + 1);
        if (!records[i].name) {
            printf("Error: Failed to allocate memory for record %zu\n", i);
            exit(1);
        }
        log.num_allocs++;
    }
    // Deallocate memory for the record name when no longer needed
    for (size_t i = 0; i < num_records; i++) {
