long calculateTotalMemoryUsage(int num_offsets, int num_keys) {
    // Calculate the size of the offset array
    long offset_size = sizeof(long) * num_offsets;

    // Calculate the size of the key array
    long key_size = sizeof(int) * num_keys;

    // Calculate the size of the record array
    long record_size = sizeof(Record) * num_keys;

    // Calculate the total memory usage required
    long total_memory_usage = offset_size + key_size + record_size;

    // Check if the total estimated memory usage exceeds the maximum memory limit
    if (total_memory_usage > MAX_MEMORY) {
        printf("Error: Total estimated memory usage exceeds maximum memory limit\n");
        exit(1);
    }

    return total_memory_usage;
}

// Function to allocate memory for and initialize an array of long integers, representing offset values
long* allocateOffsets(int num_offsets) {
    // Allocate memory for the offset array
    long* offsets = (long*)malloc(sizeof(long) * num_offsets);

    // Initialize each element in the offset array to a random value within the range defined by min_value and max_value
