    }

    return offsets;
}

// Function to allocate memory for and initialize an array of int integers, serving as keys
int* allocateKeys(int num_keys) {
    // Allocate memory for the key array
    int* keys = (int*)malloc(sizeof(int) * num_keys);

    // Initialize each element in the key array to a unique and non-negative value
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (num_keys - i) + i;
    }

    return keys;
}

// Function to allocate memory for an array of record structures, where each structure contains an int field named value and a pointer to an offset array from point 1
Record* allocateRecords(int num_keys, long* offsets) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(sizeof(Record) * num_keys);

    // Initialize each element in the record array with a random value within the range defined by min_value and max_value, and set the offset pointer to the corresponding index in the offset array
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].offset = &offsets[i];
    }

    return records;
}

// Function to free all allocated memory
void freeMemory(long* offsets, int* keys, Record* records) {
