    free(offsets);

    // Free the key array
    free(keys);

    // Free the record array
    free(records);
}

// Function to verify that all resources have been released correctly after cleanup
void verifyMemoryReleased() {
    // Check if any memory has been leaked
    if (malloc_trim(0) != 0) {
        printf("Error: Memory leak detected\n");
        exit(1);
    }
}

// Function to set the value field of each record using a linear transformation of the key index
void setRecordValues(int* keys, long* offsets, Record* records, int num_keys) {
    // Iterate over each element in the key array and corresponding element in the offset array
    for (int i = 0; i < num_keys; i++) {
        // Calculate the linear transformation of the key index using the scale factor and offset index
        int value = (keys[i] * SCALE_FACTOR) + offsets[i];

        // Set the value field of the corresponding record element to the calculated value
        records[i].value = value;
    }
}

