import java.util.Random;

public class ServiceManager {
    private static final int MIN_DELAY = 1000; // 1 second
    private static final int MAX_DELAY = 60000; // 1 minute

    public static void main(String[] args) {
        Random random = new Random();
        while (true) {
            try {
                // Start the service with a random delay between 1 second and 1 minute
                int delay = random.nextInt(MAX_DELAY - MIN_DELAY + 1) + MIN_DELAY;
                Thread.sleep(delay);

                // Stop the service and send a message to the messaging system
                System.out.println("Stopping service...");
                MessagingSystem.sendMessage("Service stopped");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}
```
