    if (num_entries < 0) {
        printf("Error: Invalid number of entries\n");
        return;
    }

    // Reallocate memory for entries
    Entry* new_entries = realloc(entries, sizeof(Entry) * num_entries);
    if (!new_entries) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Initialize new entries with random data
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        new_entries[i].name = malloc(10 * sizeof(char));
        if (!new_entries[i].name) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        strcpy(new_entries[i].name, "Name");
        new_entries[i].priority_level = rand() % 10;
        new_entries[i].score = (double)rand() / RAND_MAX;
    }

    // Free old memory and assign new pointer
    free(entries);
    entries = new_entries;
}

// Define function to serialize collection of entries to file
void serialize_entries(Entry* entries, int num_entries, const char* filename) {
    // Validate input number of entries and filename
    if (num_entries < 0 || !filename) {
        printf("Error: Invalid input\n");
        return;
    }

    // Open file for writing
    FILE* fp = fopen(filename, "wb");
    if (!fp) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Write entries to file
    for (int i = 0; i < num_entries; i++) {
        fwrite(&entries[i], sizeof(Entry), 1, fp);
    }

    // Close file
    fclose(fp);
}

// Define function to deserialize collection of entries from file
void deserialize_entries(Entry* entries, int num_entries, const char* filename) {
    // Validate input number of entries and filename
    if (num_entries < 0 || !filename) {
        printf("Error: Invalid input\n");
        return;
    }

    // Open file for reading
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }

    // Read entries from file
    for (int i = 0; i < num_entries; i++) {
        fread(&entries[i], sizeof(Entry), 1, fp);
    }

    // Close file
    fclose(fp);
}

// Define function to sort collection of entries based on name
void sort_by_name(Entry* entries, int num_entries) {
    // Validate input number of entries
    if (num_entries < 0) {
        printf("Error: Invalid number of entries\n");
        return;
    }

    // Sort entries by name
    qsort(entries, num_entries, sizeof(Entry), compare_by_name);
}

// Define function to sort collection of entries based on priority level
void sort_by_priority(Entry* entries, int num_entries) {
    // Validate input number of entries
    if (num_entries < 0) {
        printf("Error: Invalid number of entries\n");
        return;
    }

    // Sort entries by priority level
    qsort(entries, num_entries, sizeof(Entry), compare_by_priority);
}

// Define function to sort collection of entries based on score
void sort_by_score(Entry* entries, int num_entries) {
    // Validate input number of entries
    if (num_entries < 0) {
        printf("Error: Invalid number of entries\n");
        return;
    }

    // Sort entries by score
    qsort(entries, num_entries, sizeof(Entry), compare_by_score);
}

// Define function to set priority level for all entries
void set_priority_level(Entry* entries, int num_entries, int priority_level) {
    // Validate input number of entries and priority level
    if (num_entries < 0 || priority_level < 0) {
        printf("Error: Invalid input\n");
        return;
    }

    // Set priority level for all entries
    for (int i = 0; i < num_entries; i++) {
        entries[i].priority_level = priority_level;
    }
}

// Define function to set score for all entries
void set_score(Entry* entries, int num_entries, double score) {
    // Validate input number of entries and score
    if (num_entries < 0 || score < 0.0) {
        printf("Error: Invalid input\n");
        return;
    }

    // Set score for all entries
    for (int i = 0; i < num_entries; i++) {
        entries[i].score = score;
    }
}

// Define function to check memory usage and log warning if necessary
void check_memory_usage(Entry* entries, int num_entries) {
    // Validate input number of entries
    if (num_entries < 0) {
        printf("Error: Invalid number of entries\n");
        return;
    }

    // Check memory usage and log warning if necessary
    size_t total_memory = sizeof(Entry) * num_entries;
    if (total_memory > MAX_MEMORY_USAGE) {
        printf("Warning: Memory usage exceeds %zu bytes\n", MAX_MEMORY_USAGE);
    }
}
