#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define the entry structure
typedef struct {
    char* name;
    int priority_level;
} entry;

// Define the function to manage dynamic memory allocation for entries
void allocate_entries(int num_entries, char** allowed_names, int max_name_length) {
    // Validate input parameters
    if (num_entries <= 0 || !allowed_names || max_name_length < 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the entries
    entry* entries = malloc(sizeof(entry) * num_entries);
    if (!entries) {
        printf("Failed to allocate memory for entries\n");
        return;
    }

    // Initialize the priority levels of each entry
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        int random_priority = rand() % 100 + 1;
        entries[i].priority_level = random_priority;
    }

    // Iterate over each entry and validate its name
    for (int i = 0; i < num_entries; i++) {
        char* name = entries[i].name;
        int name_length = strlen(name);

        // Check if the name is within the maximum allowed length
        if (name_length > max_name_length) {
            printf("Name %s exceeds maximum allowed length\n", name);
            continue;
        }

        // Check if the name contains any special characters
        for (int j = 0; j < name_length; j++) {
            char c = name[j];
            if (!isalnum(c) && c != ' ') {
                printf("Name %s contains special characters\n", name);
                continue;
            }
        }

        // Check if the name is in the allowed list
        int match_found = 0;
        for (int j = 0; j < num_allowed_names; j++) {
            char* allowed_name = allowed_names[j];
            int distance = levenshtein_distance(name, allowed_name);
            if (distance <= max_levenshtein_distance) {
                match_found = 1;
                break;
            }
        }

        // If no match is found, log a warning and attempt to insert the closest matching name
        if (!match_found) {
            printf("No match found for name %s\n", name);
            char* closest_name = find_closest_name(name, allowed_names, num_allowed_names);
            if (closest_name) {
                entries[i].name = closest_name;
                printf("Using closest matching name %s for entry %d\n", closest_name, i);
            } else {
                printf("Failed to insert entry %d with name %s\n", i, name);
            }
        }
    }

    // Free the memory allocated for the entries
    free(entries);
}

// Define a function to calculate the Levenshtein distance between two strings
int levenshtein_distance(char* str1, char* str2) {
    int len1 = strlen(str1);
    int len2 = strlen(str2);
    if (len1 == 0 || len2 == 0) {
        return 0;
    }

    // Initialize the distance matrix
    int** distances = malloc(sizeof(int*) * (len1 + 1));
    for (int i = 0; i <= len1; i++) {
        distances[i] = malloc(sizeof(int) * (len2 + 1));
    }

    // Initialize the first row and column of the distance matrix
    for (int i = 0; i <= len1; i++) {
        distances[i][0] = i;
    }
    for (int j = 0; j <= len2; j++) {
        distances[0][j] = j;
    }

    // Calculate the Levenshtein distance between the two strings
    for (int i = 1; i <= len1; i++) {
        for (int j = 1; j <= len2; j++) {
            int cost = str1[i - 1] == str2[j - 1] ? 0 : 1;
            distances[i][j] = min(distances[i - 1][j] + 1, distances[i][j - 1] + 1, distances[i - 1][j - 1] + cost);
        }
    }

    // Return the Levenshtein distance between the two strings
    int distance = distances[len1][len2];
    free(distances);
    return distance;
}

