char* find_closest_name(char* name, char** allowed_names, int num_allowed_names) {
    // Initialize the minimum Levenshtein distance and its corresponding index
    int min_distance = INT_MAX;
    int closest_index = -1;

    // Iterate over each allowed name and calculate its Levenshtein distance to the input name
    for (int i = 0; i < num_allowed_names; i++) {
        char* allowed_name = allowed_names[i];
        int distance = levenshtein_distance(name, allowed_name);
        if (distance < min_distance) {
            min_distance = distance;
            closest_index = i;
        }
    }

    // Return the closest matching name or NULL if no match is found
    return closest_index == -1 ? NULL : allowed_names[closest_index];
}
