// Define the entry structure
typedef struct {
    char* name;
    int priority_level;
    double score;
} entry;

// Define the collection structure
typedef struct {
    entry** entries;
    size_t capacity;
    size_t count;
} collection;

// Initialize a new collection with a specified number of entries
collection* init_collection(size_t num_entries) {
    // Check if the number of entries exceeds the maximum allowable limit
    assert(num_entries <= MAX_ENTRIES);

    // Allocate memory for the collection structure and the array of entry pointers
    collection* col = malloc(sizeof(collection));
    col->entries = malloc(sizeof(entry*) * num_entries);

    // Initialize the capacity and count fields
    col->capacity = num_entries;
    col->count = 0;

    return col;
}

// Add a new entry to the collection, resizing if necessary
void add_entry(collection* col, char* name, int priority_level, double score) {
    // Check if the number of entries exceeds the current capacity
    if (col->count == col->capacity) {
        // Double the capacity and reallocate memory for the entry pointers array
        size_t new_capacity = col->capacity * 2;
        col->entries = realloc(col->entries, sizeof(entry*) * new_capacity);
        col->capacity = new_capacity;
    }

    // Allocate memory for the new entry and assign its fields
    entry* new_entry = malloc(sizeof(entry));
    new_entry->name = strdup(name);
    new_entry->priority_level = priority_level;
    new_entry->score = score;

    // Add the new entry to the end of the array
    col->entries[col->count++] = new_entry;
}

// Remove an entry from the collection by its index
void remove_entry(collection* col, size_t index) {
    // Check if the index is valid
    assert(index < col->count);

    // Shift all entries after the specified index to the left
    for (size_t i = index; i < col->count - 1; i++) {
        col->entries[i] = col->entries[i + 1];
    }

    // Decrement the count field and free the memory of the removed entry
    col->count--;
    free(col->entries[index]);
}

// Sort the entries in the collection based on a specified field (name, priority_level, or score)
void sort_entries(collection* col, int field) {
    // Check if the field is valid
    assert(field == 0 || field == 1 || field == 2);

    // Define a comparison function for sorting based on the specified field
    int compare(const void* a, const void* b) {
        entry* e1 = *(entry**)a;
        entry* e2 = *(entry**)b;
        if (field == 0) {
            return strcmp(e1->name, e2->name);
        } else if (field == 1) {
            return e1->priority_level - e2->priority_level;
        } else {
            return e1->score - e2->score;
        }
    }

    // Sort the entries using the comparison function
    qsort(col->entries, col->count, sizeof(entry*), compare);
}

// Serialize the collection to a file
void serialize_collection(collection* col, FILE* fp) {
    // Check if the serialization file size does not exceed the specified limit
    assert(fp != NULL && ftell(fp) + sizeof(entry*) * col->count <= MAX_FILE_SIZE);

    // Write the number of entries to the file
    fwrite(&col->count, sizeof(size_t), 1, fp);

    // Write each entry to the file
    for (size_t i = 0; i < col->count; i++) {
        entry* e = col->entries[i];
        fwrite(e->name, strlen(e->name) + 1, 1, fp);
        fwrite(&e->priority_level, sizeof(int), 1, fp);
        fwrite(&e->score, sizeof(double), 1, fp);
    }
}

// Deserialize the collection from a file
void deserialize_collection(collection* col, FILE* fp) {
    // Check if the serialization file size does not exceed the specified limit
    assert(fp != NULL && ftell(fp) + sizeof(entry*) * col->count <= MAX_FILE_SIZE);

    // Read the number of entries from the file
    fread(&col->count, sizeof(size_t), 1, fp);

    // Allocate memory for the collection structure and the array of entry pointers
    col->entries = malloc(sizeof(entry*) * col->count);

    // Read each entry from the file and allocate memory for it
    for (size_t i = 0; i < col->count; i++) {
        entry* e = malloc(sizeof(entry));
        fread(e->name, strlen(e->name) + 1, 1, fp);
        fread(&e->priority_level, sizeof(int), 1, fp);
        fread(&e->score, sizeof(double), 1, fp);
        col->entries[i] = e;
    }
}

// Periodically monitor and log memory usage to trigger resource cleanup when necessary
void monitor_memory() {
    // Check if the application exceeds a defined memory threshold
    if (get_memory_usage() > MAX_MEMORY) {
        // Trigger resource cleanup and reset the memory usage counter
        cleanup_resources();
        set_memory_usage(0);
    }
}
