        (*tasks)[i].description = (char*)malloc(256 * sizeof(char));
        if ((*tasks)[i].description == NULL) {
            fprintf(stderr, "Failed to allocate memory for task description\n");
            return;
        }
        srand((unsigned int)time(NULL));
        char* desc = (char*)malloc(256 * sizeof(char));
        if (desc == NULL) {
            fprintf(stderr, "Failed to allocate memory for task description\n");
            return;
        }
        strcpy((*tasks)[i].description, desc);
    }

    // Initialize each task with a valid timestamp and thread identifier
    for (size_t i = 0; i < num_tasks; i++) {
        (*tasks)[i].timestamp = time(NULL);
        (*tasks)[i].thread_id = pthread_self();
    }
}

// Define a function to release all allocated memory
void free_tasks(task_t** tasks) {
    // Release the memory for each task
    for (size_t i = 0; i < num_tasks; i++) {
        free((*tasks)[i].description);
    }
    free(*tasks);
}
