void initialize_arrays(int num_tasks, char *log_dir) {
    // Allocate memory for task info and resource usage arrays
    struct task_info **task_infos = malloc(num_tasks * sizeof(struct task_info));
    struct resource_usage **resource_usages = malloc(num_tasks * sizeof(struct resource_usage));

    // Initialize task info and resource usage arrays
    for (int i = 0; i < num_tasks; i++) {
        // Generate unique task name based on naming convention
        char task_name[128];
        sprintf(task_name, "/home/user/Tasks/task-%d", i);

        // Allocate memory for task info and resource usage
        struct task_info *task_info = malloc(sizeof(struct task_info));
        struct resource_usage *resource_usage = malloc(sizeof(struct resource_usage));

        // Initialize task info and resource usage fields
