        resource_usage->last_updated = time(NULL);

        // Add task info and resource usage to linked list of process statuses
        struct process_status *process_status = malloc(sizeof(struct process_status));
        process_status->task_info = task_info;
        process_status->resource_usage = resource_usage;
        process_status->next = NULL;

        // Add process status to linked list of process statuses
        if (process_statuses == NULL) {
            process_statuses = process_status;
        } else {
            struct process_status *current = process_statuses;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = process_status;
        }
    }

    // Free memory for task info and resource usage arrays if allocation fails
    if (task_infos == NULL || resource_usages == NULL) {
        free(task_infos);
        free(resource_usages);
        return;
    }

    // Update CPU usage and memory consumption fields of each resource usage record
    for (int i = 0; i < num_tasks; i++) {
        struct task_info *task_info = task_infos[i];
        struct resource_usage *resource_usage = resource_usages[i];

