        double memory_consumption = (double)rand() / RAND_MAX;

        resource_usage->cpu_usage = cpu_usage;
        resource_usage->memory_consumption = memory_consumption;
        resource_usage->last_updated = time(NULL);
    }

    // Log any errors encountered during memory allocation and initialization processes to a separate log file in the specified directory
    FILE *log_file = fopen("error.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    // Log any errors encountered during memory allocation and initialization processes to a separate log file in the specified directory
    for (int i = 0; i < num_tasks; i++) {
        struct task_info *task_info = task_infos[i];
        struct resource_usage *resource_usage = resource_usages[i];

        if (task_info == NULL || resource_usage == NULL) {
            fprintf(log_file, "Error: Failed to allocate memory for task %d\n", i);
        } else {
            fprintf(log_file, "Task %d initialized with CPU usage %.2f and memory consumption %.2f\n", i, resource_usage->cpu_usage, resource_usage->memory_consumption);
