#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the file status enum
enum file_status { ACTIVE, INACTIVE, ERROR };

// Define the struct for storing file information
struct file_entry {
    float float_value;
    double double_value;
    char* path;
    int metadata;
    enum file_status status;
};

// Function to dynamically allocate memory for and initialize an array of structs
struct file_entry* init_file_array(int num_entries, int timeout) {
    // Allocate memory for the array of structs
    struct file_entry* entries = (struct file_entry*)malloc(num_entries * sizeof(struct file_entry));
    if (!entries) {
        fprintf(stderr, "Error: Failed to allocate memory for file entry array\n");
        return NULL;
    }

    // Initialize the structs with random values and unique file paths
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        entries[i].float_value = (float)rand() / RAND_MAX;
        entries[i].double_value = (double)rand() / RAND_MAX;
        char* path = (char*)malloc(1024);
        if (!path) {
            fprintf(stderr, "Error: Failed to allocate memory for file path\n");
            free(entries);
            return NULL;
        }
        snprintf(path, 1024, "/home/user/Projects/%d.txt", i);
        entries[i].path = path;
        entries[i].metadata = i;
        entries[i].status = ACTIVE;
    }

    // Set the timeout for checking file statuses
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        fprintf(stderr, "Error: Failed to allocate memory for mutex\n");
        free(entries);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);
    int* timeouts = (int*)malloc(num_entries * sizeof(int));
    if (!timeouts) {
        fprintf(stderr, "Error: Failed to allocate memory for timeouts\n");
        free(entries);
        return NULL;
    }
    for (int i = 0; i < num_entries; i++) {
        timeouts[i] = timeout;
    }

    // Return the initialized array of structs and mutex
    return entries;
}

// Function to check the status of each file entry and change its status to INACTIVE if it has not been accessed within a certain time frame, as defined by a timeout parameter.
void check_file_statuses(struct file_entry* entries, int num_entries, int timeout) {
    // Lock the mutex to prevent concurrent access to the array of structs
    pthread_mutex_lock(mutex);

    // Iterate over each entry and check its status
    for (int i = 0; i < num_entries; i++) {
        if (timeouts[i] > 0) {
            timeouts[i]--;
        } else {
            entries[i].status = INACTIVE;
        }
    }

    // Unlock the mutex to allow other threads to access the array of structs
    pthread_mutex_unlock(mutex);
}

// Function to free memory allocated for an array of structs
void free_file_array(struct file_entry* entries, int num_entries) {
    // Free the memory allocated for the array of structs
    for (int i = 0; i < num_entries; i++) {
        free(entries[i].path);
    }
    free(entries);
}
