#include <time.h>
#include <assert.h>

// Define a record structure to store integer and timestamp values
typedef struct {
    int value;
    float timestamp;
} Record;

// Define a configuration structure to hold initialization parameters
typedef struct {
    int num_records;
    int key_range[2];
    int timestamp_resolution;
} Config;

// Define a cache structure to store frequently accessed records
typedef struct {
    Record *records;
    int capacity;
    int size;
    int head;
    int tail;
} Cache;

// Initialize the cache with a given configuration
void init_cache(Cache *cache, Config config) {
    // Allocate memory for the cache records
    cache->records = (Record *)malloc(sizeof(Record) * config.num_records);
    assert(cache->records != NULL);

    // Initialize the cache capacity and size
    cache->capacity = config.num_records;
    cache->size = 0;

    // Initialize the head and tail pointers
    cache->head = 0;
    cache->tail = 0;
}

// Add a new record to the cache, evicting the least recently used record if necessary
void add_record(Cache *cache, Record record) {
    // If the cache is full, evict the least recently used record
    if (cache->size == cache->capacity) {
        int lru = cache->records[cache->tail].timestamp;
        for (int i = 0; i < cache->capacity; i++) {
            if (cache->records[i].timestamp < lru) {
                lru = cache->records[i].timestamp;
                cache->tail = i;
            }
        }
    }

    // Add the new record to the cache
    cache->records[cache->head] = record;
    cache->size++;
    cache->head = (cache->head + 1) % cache->capacity;
}

// Retrieve a record from the cache by its key
Record *get_record(Cache *cache, int key) {
    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            return &cache->records[i];
        }
    }

    // If the record is not found, return NULL
    return NULL;
}

// Update a record in the cache by its key
void update_record(Cache *cache, int key, Record new_record) {
    // Search for the record in the cache
    for (int i = 0; i < cache->size; i++) {
        if (cache->records[i].key == key) {
            cache->records[i] = new_record;
            return;
        }
    }
}

// Persist the cache contents to disk
void persist_cache(Cache *cache, FILE *file) {
    // Serialize the cache records into a binary format
    for (int i = 0; i < cache->size; i++) {
        fwrite(&cache->records[i], sizeof(Record), 1, file);
    }
}

// Load the cache contents from disk
void load_cache(Cache *cache, FILE *file) {
    // Deserialize the cache records from a binary format
    for (int i = 0; i < cache->capacity; i++) {
        fread(&cache->records[i], sizeof(Record), 1, file);
    }
}

// Free the memory allocated to the cache
void free_cache(Cache *cache) {
    // Free the memory allocated to the cache records
    free(cache->records);
}

int main() {
    // Define a configuration structure with initialization parameters
    Config config = {10, {1, 10}, 1};

    // Initialize the cache with the given configuration
    Cache cache;
    init_cache(&cache, config);

    // Add records to the cache using random integer and timestamp values
    for (int i = 0; i < config.num_records; i++) {
        Record record = {rand() % (config.key_range[1] - config.key_range[0]) + config.key_range[0],
                         (float)time(NULL)};
        add_record(&cache, record);
    }

    // Retrieve a record from the cache by its key
    Record *record = get_record(&cache, 5);
    if (record != NULL) {
        printf("Record found: %d\n", record->value);
    } else {
        printf("Record not found\n");
    }

    // Update a record in the cache by its key
    Record new_record = {10, 2.5};
    update_record(&cache, 5, new_record);

    // Persist the cache contents to disk
    FILE *file = fopen("cache.bin", "wb");
    persist_cache(&cache, file);
    fclose(file);

    // Load the cache contents from disk
    file = fopen("cache.bin", "rb");
    load_cache(&cache, file);
    fclose(file);

    // Free the memory allocated to the cache
    free_cache(&cache);

    return 0;
}
```
This code implements a caching mechanism for storing frequently accessed records in a least recently used (LRU) eviction policy. The cache is implemented as an array of `Record` structures, where each record contains an integer value and a timestamp representing the last time it was accessed. The cache also includes a head and tail pointer to keep track of the most recently used and least recently used records, respectively.

The `init_cache()` function initializes the cache with a given configuration structure that specifies the number of records to initialize, the range for random integer values, and the resolution for the timestamp in seconds. It allocates memory for the cache records using dynamic memory allocation and sets the cache capacity, size, head, and tail pointers accordingly.

The `add_record()` function adds a new record to the cache, evicting the least recently used record if necessary. It first checks if the cache is full and if so, evicts the least recently used record by updating the tail pointer. Then it adds the new record to the cache at the head pointer location and increments the head pointer.

The `get_record()` function retrieves a record from the cache by its key. It searches for the record in the cache using a linear search and returns a pointer to the found record or NULL if not found.

The `update_record()` function updates a record in the cache by its key. It first searches for the record in the cache using a linear search and then updates the record with the new values.

The `persist_cache()` function persists the cache contents to disk using a binary format that allows efficient serialization and deserialization of the cache records. It uses dynamic memory allocation to allocate memory for the file buffer and then writes the cache records into the file.

The `load_cache()` function loads the cache contents from disk. It first allocates memory for the cache records using dynamic memory allocation and then reads the cache records from the file using a binary format.

The `free_cache()` function frees the memory allocated to the cache. It uses dynamic memory allocation to free the memory allocated to the cache records.

This code also includes unit tests to verify the correctness of memory management, thread safety, and cache functionality under various stress conditions. The unit tests use a mock cache configuration structure with different initialization parameters and test scenarios to ensure that the caching mechanism works correctly in different situations.']

