// Custom memory pool to reduce allocation overhead
struct MemoryPool {
    size_t capacity;
    void* buffer;
};

void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->buffer = malloc(capacity);
}

void* allocate(struct MemoryPool* pool, size_t size) {
    if (pool->capacity < size) {
        return NULL;
    }
    void* ptr = pool->buffer;
    pool->buffer += size;
    pool->capacity -= size;
    return ptr;
}

void freeMemoryPool(struct MemoryPool* pool) {
    free(pool->buffer);
}

