// Function to initialize arrays and sort records
void init_arrays(int num_records, int min_key, int max_key, int seed) {
    // Allocate memory for arrays
    long *offset_arr = malloc(num_records * sizeof(long));
    int *key_arr = malloc(num_records * sizeof(int));
    record_t *record_arr = malloc(num_records * sizeof(record_t));

    // Check for memory allocation failures
    if (offset_arr == NULL || key_arr == NULL || record_arr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return;
    }

    // Initialize arrays with random values within specified range
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        offset_arr[i] = rand() % (max_key - min_key + 1) + min_key;
        key_arr[i] = rand() % (max_key - min_key + 1) + min_key;
        record_arr[i].key = key_arr[i];
        record_arr[i].offset = offset_arr[i];
    }

    // Sort records based on key values in ascending order
    qsort(record_arr, num_records, sizeof(record_t), compare_records);

    // Print sorted records
    for (int i = 0; i < num_records; i++) {
        printf("%d %ld\n", record_arr[i].key, record_arr[i].offset);
    }

    // Free memory allocated for arrays
    free(offset_arr);
    free(key_arr);
    free(record_arr);
}

// Comparison function for sorting records based on key values
int compare_records(const void *a, const void *b) {
    record_t *ra = (record_t *) a;
    record_t *rb = (record_t *) b;
    return ra->key - rb->key;
}

