        fprintf(stderr, "Error: Invalid number of records\n");
        return 1;
    }
    int min_key = atoi(argv[2]);
    if (min_key < 0) {
        fprintf(stderr, "Error: Minimum key value must be non-negative\n");
        return 1;
    }
    int max_key = atoi(argv[3]);
    if (max_key <= min_key) {
        fprintf(stderr, "Error: Maximum key value must be greater than minimum key value\n");
