Event* initEvents(int numEvents, int seed) {
    // Check if the input is within a reasonable range
    if (numEvents < 0 || numEvents > 100000) {
        printf("Invalid number of events: %d\n", numEvents);
        return NULL;
    }

    // Allocate memory for the events
    Event *events = malloc(sizeof(Event) * numEvents);
    if (events == NULL) {
        printf("Failed to allocate memory for events\n");
        return NULL;
    }

    // Initialize each event with a random timestamp, ID, and message
    srand(seed);
    for (int i = 0; i < numEvents; i++) {
        events[i].timestamp = time(NULL) + rand() % 100000;
        events[i].id = rand() % 100000;
        events[i].message = malloc(256);
        if (events[i].message == NULL) {
            printf("Failed to allocate memory for message\n");
            return NULL;
        }
        snprintf(events[i].message, 256, "Event %d: %s", events[i].id, generateMessage());
    }

    // Sort the events based on their timestamps in chronological order
    qsort(events, numEvents, sizeof(Event), compareEvents);

    return events;
}

// Function to free the memory allocated for the events
void cleanupEvents(Event *events) {
    if (events == NULL) {
        return;
    }

    // Free each event's message and then the event itself
    for (int i = 0; i < numEvents; i++) {
        free(events[i].message);
        events[i].message = NULL;
    }
    free(events);
    events = NULL;
}

// Function to generate a random message with a maximum length of 256 characters
char *generateMessage() {
    char *message = malloc(256);
    if (message == NULL) {
        printf("Failed to allocate memory for message\n");
        return NULL;
    }

    // Generate a random string with a maximum length of 256 characters
    for (int i = 0; i < 256; i++) {
        message[i] = 'a' + rand() % 26;
    }

    return message;
}

// Comparison function to sort events based on their timestamps in chronological order
int compareEvents(const void *event1, const void *event2) {
    Event *e1 = (Event *) event1;
    Event *e2 = (Event *) event2;
    return e1->timestamp - e2->timestamp;
}
