// Define the log structure
typedef struct Log {
    time_t timestamp;
    unsigned long id;
    enum Severity severity;
    char *message;
} Log;

// Define the severity levels
enum Severity {
    CRITICAL,
    ERROR,
    WARNING,
    INFO,
    DEBUG
};

// Function to initialize the log collection
void initLogCollection(int numLogs) {
    // Check if the input is within a reasonable range
    assert(numLogs > 0 && numLogs <= 1000);

    // Allocate memory for the log collection
    Log *logs = (Log *)malloc(sizeof(Log) * numLogs);
    if (!logs) {
        printf("Error: Failed to allocate memory for log collection\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the logs with default values
    for (int i = 0; i < numLogs; i++) {
        logs[i].timestamp = time(NULL);
        logs[i].id = i + 1;
        logs[i].severity = INFO;
        logs[i].message = NULL;
    }

    // Set the seed for the random number generator
    srand(time(NULL));
}

// Function to add a new log entry to the collection
void addLogEntry(Log *log) {
    // Check if the input is within a reasonable range
    assert(log->severity >= CRITICAL && log->severity <= DEBUG);

    // Allocate memory for the message
    char *message = (char *)malloc(strlen(log->message) + 1);
    if (!message) {
        printf("Error: Failed to allocate memory for log message\n");
        exit(EXIT_FAILURE);
    }

    // Copy the message from the input
    strcpy(message, log->message);

    // Add the new log entry to the collection
    logs[log->id - 1].timestamp = time(NULL);
    logs[log->id - 1].severity = log->severity;
    logs[log->id - 1].message = message;
}

// Function to filter logs based on a specified severity level
void filterLogs(enum Severity severity) {
    // Check if the input is within a reasonable range
    assert(severity >= CRITICAL && severity <= DEBUG);

    // Filter the logs based on the specified severity level
    for (int i = 0; i < numLogs; i++) {
        if (logs[i].severity == severity) {
            printf("Log %d: %lu - %s\n", i + 1, logs[i].id, logs[i].message);
        }
    }
}

// Function to sort the logs based on their timestamps and severity levels
void sortLogs() {
    // Sort the logs based on their timestamps in chronological order
    for (int i = 0; i < numLogs - 1; i++) {
        for (int j = i + 1; j < numLogs; j++) {
            if (logs[i].timestamp > logs[j].timestamp) {
                Log temp = logs[i];
                logs[i] = logs[j];
                logs[j] = temp;
            }
        }
    }

    // Sort the logs based on their severity levels in descending order for logs with the same timestamp
    for (int i = 0; i < numLogs - 1; i++) {
        if (logs[i].timestamp == logs[i + 1].timestamp) {
            if (logs[i].severity > logs[i + 1].severity) {
                Log temp = logs[i];
                logs[i] = logs[i + 1];
                logs[i + 1] = temp;
            }
        }
    }
}

// Function to clean up the log collection
void cleanupLogCollection() {
    // Free the memory allocated for the log collection
    free(logs);
}
