        printf("Invalid number of audits. Must be between 1 and %d.\n", MAX_NUM_AUDITS);
        return;
    }
    Audit *audits = (Audit *)malloc(numAudits * sizeof(Audit));
    if (!audits) {
        printf("Memory allocation failed. Exiting...\n");
        exit(1);
    }

    // Set the seed for the random number generator
    srand(seed);

    // Initialize the audit structures with default values
    for (int i = 0; i < numAudits; i++) {
        audits[i].timestamp = time(NULL);
        audits[i].transactionID = rand();
        audits[i].operationType = NORMAL;
        audits[i].description = NULL;
        audits[i].statusCode = 0;
    }

    // Dynamically create the audit descriptions based on a format string
    char *formatString = "Audit %d: Transaction ID %lu, Operation Type %s, Description %s, Status Code %d";
    for (int i = 0; i < numAudits; i++) {
        // Generate a random operation type and description
        audits[i].operationType = rand() % 2 == 0 ? CRITICAL : NORMAL;
        char *description = generateDescription(audits[i].operationType);
        audits[i].description = (char *)malloc((strlen(description) + 1) * sizeof(char));
        strcpy(audits[i].description, description);
    }

    // Sort the audits based on timestamps and operation types
    qsort(audits, numAudits, sizeof(Audit), compareAudits);

    // Print the sorted audits
    for (int i = 0; i < numAudits; i++) {
        printf(formatString, i + 1, audits[i].transactionID,
            audits[i].operationType == CRITICAL ? "Critical" : "Normal",
            audits[i].description, audits[i].statusCode);
    }

    // Clean up the memory allocated for the audit structures and descriptions
    for (int i = 0; i < numAudits; i++) {
        free(audits[i].description);
    }
    free(audits);
}

// Generate a random description based on an operation type
char *generateDescription(enum OperationType operationType) {
    if (operationType == CRITICAL) {
        return "Critical error occurred";
    } else {
        return "Normal operation";
    }
}

// Compare two audits based on their timestamps and operation types
int compareAudits(const void *a, const void *b) {
    Audit *audit1 = (Audit *)a;
    Audit *audit2 = (Audit *)b;
    if (audit1->timestamp < audit2->timestamp) {
        return -1;
    } else if (audit1->timestamp > audit2->timestamp) {
        return 1;
    } else {
        if (audit1->operationType == CRITICAL && audit2->operationType != CRITICAL) {
            return -1;
        } else if (audit1->operationType != CRITICAL && audit2->operationType == CRITICAL) {
            return 1;
        } else {
            return 0;
        }
    }
}
