// Function to dynamically allocate memory for four arrays: one for storing double precision floating-point numbers, another for storing char strings (each string with a maximum length of 256 characters), a third for storing struct point objects, each containing two float coordinates, and a fourth for storing custom struct node objects, each containing a pointer to a child struct node and a char value.
void *allocate_memory(size_t num_doubles, size_t num_strings, size_t num_points, size_t num_nodes) {
    // Calculate the total amount of memory needed for all arrays
    size_t total_size = (num_doubles * sizeof(double)) + (num_strings * 256) + (num_points * sizeof(point_t)) + (num_nodes * sizeof(node_t));

    // Allocate memory for the four arrays using a custom memory pool
    struct mempool *mempool = malloc(sizeof(struct mempool));
    mempool->memory = calloc(total_size, 1);
    mempool->capacity = total_size;
    mempool->used = 0;

    // Initialize the four arrays using the allocated memory
    double *doubles = (double *)mempool->memory;
    char **strings = (char **)((void *)doubles + num_doubles * sizeof(double));
    point_t *points = (point_t *)((void *)strings + num_strings * 256);
    node_t *nodes = (node_t *)((void *)points + num_points * sizeof(point_t));

    // Initialize the arrays with random values, ensuring that no two strings have the same content and that no two struct node objects share the same parent-child relationship
    srand(time(NULL));
    for (size_t i = 0; i < num_doubles; i++) {
        doubles[i] = (double)rand() / RAND_MAX;
    }
    for (size_t i = 0; i < num_strings; i++) {
        strings[i] = malloc(256);
        for (size_t j = 0; j < 256; j++) {
            strings[i][j] = (char)rand() % 256;
        }
    }
    for (size_t i = 0; i < num_points; i++) {
        points[i].x = (float)rand() / RAND_MAX;
        points[i].y = (float)rand() / RAND_MAX;
    }
    for (size_t i = 0; i < num_nodes; i++) {
        nodes[i].points = malloc(sizeof(point_t));
        nodes[i].points->x = (float)rand() / RAND_MAX;
        nodes[i].points->y = (float)rand() / RAND_MAX;
        nodes[i].child = NULL;
    }

    // Free up memory in case of unexpected termination or errors
    atexit(free_memory);

    return mempool;
}

// Function to free up memory allocated by the allocate_memory function
void free_memory(struct mempool *mempool) {
    for (size_t i = 0; i < mempool->used; i++) {
        if (mempool->memory[i] != NULL) {
            free(mempool->memory[i]);
        }
    }
    free(mempool);
}
