// Define the struct for file entries
typedef struct {
    float float_value;
    double double_value;
    char* path;
    int metadata;
    enum file_status status;
} file_entry;

// Define the enum for file statuses
enum file_status {
    ACTIVE,
    INACTIVE,
    ERROR
};

// Define the function to initialize the file entries
void init_file_entries(int num_entries, int timeout) {
    // Allocate memory for the file entries
    file_entry* entries = (file_entry*)malloc(num_entries * sizeof(file_entry));
    if (!entries) {
        printf("Error: Failed to allocate memory for file entries\n");
        return;
    }

    // Initialize the file entries
    for (int i = 0; i < num_entries; i++) {
        // Set the float and double values to random values within a specified range
        entries[i].float_value = (float)rand() / RAND_MAX * 10.0f;
        entries[i].double_value = (double)rand() / RAND_MAX * 10.0;

        // Assign a unique file path to each entry
        char* path = (char*)malloc(256);
        if (!path) {
            printf("Error: Failed to allocate memory for file path\n");
            return;
        }
        sprintf(path, "/home/user/Projects/%d.txt", i);
        entries[i].path = path;

        // Set the status to ACTIVE
        entries[i].status = ACTIVE;
    }

    // Initialize the mutex for synchronizing access to the file entries
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Start a thread to periodically check the status of each file entry and change its status to INACTIVE if it has not been accessed within the specified timeout
    pthread_t thread;
    int rc = pthread_create(&thread, NULL, check_file_entries, (void*)entries);
    if (rc) {
        printf("Error: Failed to create thread for checking file entries\n");
        return;
    }

    // Wait for the thread to finish
    rc = pthread_join(thread, NULL);
    if (rc) {
        printf("Error: Failed to join thread for checking file entries\n");
        return;
    }

    // Free the memory allocated for the file entries and mutex
    free(entries);
    pthread_mutex_destroy(&mutex);
}

// Define the function to check the status of each file entry and change its status to INACTIVE if it has not been accessed within the specified timeout
void* check_file_entries(void* args) {
    // Get the pointer to the file entries
    file_entry* entries = (file_entry*)args;

    // Initialize the mutex for synchronizing access to the file entries
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each file entry and check its status
    for (int i = 0; i < num_entries; i++) {
        // Lock the mutex to synchronize access to the file entry
        pthread_mutex_lock(&mutex);

        // Check if the file entry has not been accessed within the specified timeout
        time_t current_time = time(NULL);
        if (current_time - entries[i].last_accessed > timeout) {
            // Change the status of the file entry to INACTIVE
            entries[i].status = INACTIVE;
        }

        // Unlock the mutex to release access to the file entry
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory allocated for the mutex
    pthread_mutex_destroy(&mutex);
}
