#include <stdlib.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
    struct record *next;
} record_t;

record_t* create_circular_linked_list() {
    // Allocate memory for the arrays of offsets and keys
    long *offsets = malloc(1000 * sizeof(long));
    int *keys = malloc(1000 * sizeof(int));
    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays\n");
        return NULL;
    }

    // Populate the arrays with unique values between 0 and 10000
    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 10000;
    }

    // Allocate memory for the linked list of records
    record_t *head = malloc(sizeof(record_t));
    if (head == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for linked list\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the head node of the linked list
    head->offset = offsets[0];
    head->key = keys[0];
    head->timestamp = time(NULL);
    head->next = NULL;

    // Allocate memory for each record and populate it with the corresponding offset and key values
    for (int i = 1; i < 1000; i++) {
        record_t *node = malloc(sizeof(record_t));
        if (node == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            free(offsets);
            free(keys);
            return NULL;
        }
        node->offset = offsets[i];
        node->key = keys[i];
        node->timestamp = time(NULL);
        node->next = head;
        head = node;
    }

    // Set the last node to point back to the first node to create a circular linked list
    record_t *last = head;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = head;

    free(offsets);
    free(keys);
    return head;
}
```
This function first allocates memory for two arrays of `long` and `int` integers to store the unique offset and key values, respectively. It then populates these arrays with random values between 0 and 10000 using the `rand()` function from `<stdlib.h>`.

