#include <stdlib.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    double timestamp;
    struct record *next;
} Record;

Record* initialize_list(int num_records, int min_offset, int max_offset, int min_key, int max_key) {
    // Initialize a random seed for generating unique offsets and keys
    srand(time(NULL));

    // Allocate memory for the list head and tail pointers
    Record *head = malloc(sizeof(Record));
    Record *tail = head;

    // Generate unique offsets and keys within the specified range
    int offset, key;
    while (num_records-- > 0) {
        do {
            offset = min_offset + rand() % (max_offset - min_offset);
            key = min_key + rand() % (max_key - min_key);
        } while (search_list(head, offset, key));

        // Allocate memory for the new record and initialize its fields
        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            // Handle memory allocation failure gracefully by returning NULL
            free(head);
            return NULL;
        }
        new_record->offset = offset;
        new_record->key = key;
        new_record->timestamp = time(NULL);
        new_record->next = NULL;

        // Add the new record to the end of the list
        tail->next = new_record;
        tail = new_record;
    }

    return head;
}

// Search for a matching offset and key in the list
bool search_list(Record *head, long offset, int key) {
    while (head != NULL) {
        if (head->offset == offset && head->key == key) {
            return true;
        }
        head = head->next;
    }
    return false;
}
