// Define the enum for file status
enum file_status {
    ACTIVE,
    INACTIVE,
    ERROR
};

// Function to initialize the arrays and set values
void init_arrays(float* float_arr, double* double_arr, char** path_arr, file_entry** entry_arr, enum file_status* status_arr) {
    // Allocate memory for each array
    float_arr = (float*)malloc(10 * sizeof(float));
    double_arr = (double*)malloc(10 * sizeof(double));
    path_arr = (char**)malloc(10 * sizeof(char*));
    entry_arr = (file_entry**)malloc(10 * sizeof(file_entry*));
    status_arr = (enum file_status*)malloc(10 * sizeof(enum file_status));

    // Initialize each array with a random value within the specified range
    for (int i = 0; i < 10; i++) {
        float_arr[i] = (float)rand() / RAND_MAX;
        double_arr[i] = (double)rand() / RAND_MAX;
        path_arr[i] = (char*)malloc(256 * sizeof(char));
        sprintf(path_arr[i], "/home/user/Projects/%d.txt", i);
        entry_arr[i] = (file_entry*)malloc(sizeof(file_entry));
        status_arr[i] = ACTIVE;
    }

    // Set the value of each entry's float and double fields to a random value within a specified range
    for (int i = 0; i < 10; i++) {
        entry_arr[i]->float_value = float_arr[i];
        entry_arr[i]->double_value = double_arr[i];
    }

    // Assign a unique file path to each entry
    for (int i = 0; i < 10; i++) {
        entry_arr[i]->path = path_arr[i];
    }

    // Set the status of each entry to ACTIVE
    for (int i = 0; i < 10; i++) {
        entry_arr[i]->status = ACTIVE;
    }
}

// Function to check the status of each file entry and change its status to INACTIVE if it has not been accessed within a certain time frame, as defined by a timeout parameter
void check_status(file_entry** entry_arr, int num_entries, int timeout) {
    // Get the current time in seconds
    time_t curr_time = time(NULL);

    // Iterate over each entry and check its status
    for (int i = 0; i < num_entries; i++) {
        if (entry_arr[i]->status == ACTIVE && curr_time - entry_arr[i]->last_accessed > timeout) {
            // If the entry has not been accessed within the specified time frame, change its status to INACTIVE
            entry_arr[i]->status = INACTIVE;
        }
    }
}

// Function to handle memory allocation failures gracefully
