typedef struct node {
    record data;
    struct node* next;
} node;

// Function to initialize the circular linked list with 1500 unique records
node* init_list(int num_records, int min_offset, int max_offset, int min_key, int max_key) {
    // Allocate memory for the head of the list
    node* head = (node*)malloc(sizeof(node));
    if (!head) {
        printf("Error: Failed to allocate memory for the head of the list\n");
        return NULL;
    }

    // Initialize the head of the list with a random offset and key
    head->data.offset = (long)(min_offset + (max_offset - min_offset) * rand() / RAND_MAX);
    head->data.key = (int)(min_key + (max_key - min_key) * rand() / RAND_MAX);
    head->data.timestamp = time(NULL);

    // Allocate memory for the rest of the list
    node* current = head;
    for (int i = 1; i < num_records; i++) {
        current->next = (node*)malloc(sizeof(node));
        if (!current->next) {
            printf("Error: Failed to allocate memory for the next node in the list\n");
            return NULL;
        }
        current = current->next;
    }

    // Initialize the rest of the list with unique offsets and keys
    int offset_range = max_offset - min_offset + 1;
    int key_range = max_key - min_key + 1;
    for (int i = 0; i < num_records; i++) {
        current->data.offset = (long)(min_offset + (offset_range * rand() / RAND_MAX));
        current->data.key = (int)(min_key + (key_range * rand() / RAND_MAX));
        current->data.timestamp = time(NULL);
        current = current->next;
    }

    return head;
}

// Function to add a new record to the circular linked list
void add_record(node* head, long offset, int key) {
    // Check if the list is empty
    if (!head) {
        printf("Error: The list is empty\n");
        return;
    }

    // Find the last node in the list
    node* current = head;
    while (current->next) {
        current = current->next;
    }

    // Allocate memory for the new record
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for the new node\n");
        return;
    }

    // Initialize the new record with the given offset and key
    new_node->data.offset = offset;
    new_node->data.key = key;
    new_node->data.timestamp = time(NULL);

    // Add the new record to the end of the list
    current->next = new_node;
}

// Function to remove a record from the circular linked list
void remove_record(node* head, long offset, int key) {
    // Check if the list is empty
    if (!head) {
        printf("Error: The list is empty\n");
        return;
    }

    // Find the node with the given offset and key
    node* current = head;
    while (current->next && current->data.offset != offset || current->data.key != key) {
        current = current->next;
    }

    // Check if the record was found
    if (!current->next) {
        printf("Error: The record with the given offset and key was not found\n");
        return;
    }

    // Remove the node from the list
    current->next = current->next->next;
}

// Function to print the records in the circular linked list
void print_records(node* head) {
    // Check if the list is empty
    if (!head) {
        printf("Error: The list is empty\n");
        return;
    }

    // Print the records in the list
    node* current = head;
    while (current->next) {
        printf("%ld %d %f\n", current->data.offset, current->data.key, current->data.timestamp);
        current = current->next;
    }
}
