// Define the log collection structure
typedef struct {
    LogEntry **entries;
    size_t capacity;
    size_t count;
} LogCollection;

// Initialize a new log collection with the given initial capacity
LogCollection* init_log_collection(size_t capacity) {
    assert(capacity > 0);
    LogCollection *collection = malloc(sizeof(LogCollection));
    if (!collection) {
        return NULL;
    }
    collection->entries = calloc(capacity, sizeof(LogEntry*));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    return collection;
}

// Add a new log entry to the collection
int add_log_entry(LogCollection *collection, time_t timestamp, unsigned int id, int priority, char *message) {
    assert(collection != NULL);
    if (collection->count >= collection->capacity) {
        return -1;
    }
    LogEntry *entry = malloc(sizeof(LogEntry));
    if (!entry) {
        return -2;
    }
    entry->timestamp = timestamp;
    entry->id = id;
    entry->priority = priority;
    entry->message = strdup(message);
    collection->entries[collection->count++] = entry;
    return 0;
}

// Sort the log entries in chronological order and then by priority level in ascending order
void sort_log_entries(LogCollection *collection) {
    assert(collection != NULL);
    qsort(collection->entries, collection->count, sizeof(LogEntry*), compare_log_entries);
}

// Compare two log entries based on their timestamps and priority levels
int compare_log_entries(const void *a, const void *b) {
    LogEntry *entry1 = *(LogEntry**)a;
    LogEntry *entry2 = *(LogEntry**)b;
    if (entry1->timestamp < entry2->timestamp) {
        return -1;
    } else if (entry1->timestamp > entry2->timestamp) {
        return 1;
    } else {
        if (entry1->priority < entry2->priority) {
            return -1;
        } else if (entry1->priority > entry2->priority) {
            return 1;
        } else {
            return 0;
        }
    }
}

// Free the memory allocated for a log collection
void free_log_collection(LogCollection *collection) {
    assert(collection != NULL);
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->entries[i]->message);
        free(collection->entries[i]);
    }
    free(collection->entries);
    free(collection);
}

