    // Acquire the distributed lock to prevent race conditions
    if (lockingMechanism.acquireLock("record_allocation") != 0) {
        loggingService.log("Failed to acquire distributed lock for record allocation");
        return;
    }

    // Allocate memory for the records
    *records = allocator.allocate(sizeof(Record) * count);
    if (*records == NULL) {
        loggingService.log("Failed to allocate memory for records");
        lockingMechanism.releaseLock("record_allocation");
        return;
    }

    // Initialize the records with random values within a specified range
    for (size_t i = 0; i < count; i++) {
        (*records)[i].key = rand() % 1000000 + 1;
        (*records)[i].offset = rand() % 1000000 + 1;
