// Define the record structure
typedef struct {
    int key;
    float timestamp;
} Record;

// Define the configuration structure
typedef struct {
    int num_records;
    int int_range[2];
    int float_resolution;
} Config;

// Define the cache structure
typedef struct {
    int size;
    int capacity;
    Record* records;
    int* offsets;
    int* keys;
    float* timestamps;
} Cache;

// Initialize the cache with a given configuration
Cache* init_cache(Config config) {
    // Allocate memory for the cache structure
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) {
        return NULL;
    }

    // Set the initial size and capacity of the cache
    cache->size = 0;
    cache->capacity = config.num_records;

    // Allocate memory for the record array, offset array, key array, and timestamp array
    cache->records = (Record*)malloc(sizeof(Record) * config.num_records);
    cache->offsets = (int*)malloc(sizeof(int) * config.num_records);
    cache->keys = (int*)malloc(sizeof(int) * config.num_records);
    cache->timestamps = (float*)malloc(sizeof(float) * config.num_records);

    // Check for memory allocation errors
    if (!cache->records || !cache->offsets || !cache->keys || !cache->timestamps) {
        free(cache->records);
        free(cache->offsets);
        free(cache->keys);
        free(cache->timestamps);
        return NULL;
    }

    // Initialize the record array, offset array, key array, and timestamp array
    for (int i = 0; i < config.num_records; i++) {
        cache->records[i].key = rand() % (config.int_range[1] - config.int_range[0]) + config.int_range[0];
        cache->offsets[i] = i * sizeof(Record);
        cache->keys[i] = i;
        cache->timestamps[i] = (float)time(NULL) / config.float_resolution;
    }

    return cache;
}

// Add a new record to the cache
void add_record(Cache* cache, Record record) {
    // Check if the cache is full
    if (cache->size == cache->capacity) {
        // Evict the least recently used record from the cache
        int lru = 0;
        for (int i = 1; i < cache->size; i++) {
            if (cache->timestamps[i] < cache->timestamps[lru]) {
                lru = i;
            }
        }
        // Remove the evicted record from the cache
        remove_record(cache, lru);
    }

    // Add the new record to the cache
    cache->records[cache->size] = record;
    cache->offsets[cache->size] = cache->size * sizeof(Record);
    cache->keys[cache->size] = cache->size;
    cache->timestamps[cache->size] = (float)time(NULL) / config.float_resolution;
    cache->size++;
}

// Remove a record from the cache
void remove_record(Cache* cache, int index) {
    // Check if the index is valid
    if (index < 0 || index >= cache->size) {
        return;
    }

    // Shift all records after the specified index to fill the gap
    for (int i = index + 1; i < cache->size; i++) {
        cache->records[i - 1] = cache->records[i];
        cache->offsets[i - 1] = cache->offsets[i];
        cache->keys[i - 1] = cache->keys[i];
        cache->timestamps[i - 1] = cache->timestamps[i];
    }

    // Decrement the size of the cache
    cache->size--;
}

// Update a record in the cache
void update_record(Cache* cache, int index, Record record) {
    // Check if the index is valid
    if (index < 0 || index >= cache->size) {
        return;
    }

    // Update the record at the specified index
    cache->records[index] = record;
}

// Retrieve a record from the cache
Record get_record(Cache* cache, int index) {
    // Check if the index is valid
    if (index < 0 || index >= cache->size) {
        return NULL;
    }

    // Return the record at the specified index
    return cache->records[index];
}

// Persist the cache contents to disk
void persist_cache(Cache* cache, FILE* file) {
    // Check if the cache is empty
    if (cache->size == 0) {
        return;
    }

    // Write the number of records in the cache to the file
    fwrite(&cache->size, sizeof(int), 1, file);

    // Write each record in the cache to the file
    for (int i = 0; i < cache->size; i++) {
        Record record = cache->records[i];
        fwrite(&record.key, sizeof(int), 1, file);
        fwrite(&record.timestamp, sizeof(float), 1, file);
    }
}

// Load the cache contents from disk
void load_cache(Cache* cache, FILE* file) {
    // Check if the cache is empty
    if (cache->size == 0) {
        return;
    }

    // Read the number of records in the cache from the file
    fread(&cache->size, sizeof(int), 1, file);

    // Read each record in the cache from the file
    for (int i = 0; i < cache->size; i++) {
        Record record;
        fread(&record.key, sizeof(int), 1, file);
        fread(&record.timestamp, sizeof(float), 1, file);
        add_record(cache, record);
    }
}
