// Define the function that will be used to dynamically allocate memory for and initialize the data structures, including the log entries
void init_all_data_structures(struct process_status* process_status, struct task_info* task_info) {
    // Initialize the resource usage records
    init_resource_usage(process_status);

    // Initialize the task info records
    init_task_info(process_status);

    // Initialize the scheduling policy records
    init_scheduling_policy(process_status);

    // Initialize the log entry records
    init_log_entries(process_status, task_info);
}

// Define the function that will be used to update the resource usage and scheduling policies periodically
void update_all_data_structures(struct process_status* process_status, struct task_info* task_info) {
    // Update the resource usage and scheduling policies for each task in the process status
    struct task_info* current_task = process_status->task_info_list;
    while (current_task != NULL) {
        update_resource_usage(process_status, current_task);
        current_task = current_task->next;
