// Define a function for initializing the memory pool
void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->free = capacity;
    pool->buffer = malloc(capacity);
}

// Define a function for allocating memory in the memory pool
void* allocateMemoryPool(struct MemoryPool* pool, size_t size) {
    if (pool->free < size) {
        // Reallocate the buffer to accommodate the new allocation
        pool->buffer = realloc(pool->buffer, pool->capacity + size);
        pool->capacity += size;
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    pool->free -= size;
    return ptr;
}

// Define a function for freeing memory in the memory pool
void freeMemoryPool(struct MemoryPool* pool, void* ptr) {
    size_t offset = (char*)ptr - (char*)pool->buffer;
    assert(offset < pool->capacity);
    pool->used -= offset;
    pool->free += offset;
