// Define a struct to represent a record in the hash table
typedef struct Record {
    char* identifier;
    float score;
    time_t timestamp;
} Record;

// Define a struct to represent the hash table
typedef struct HashTable {
    int num_buckets;
    int num_records;
    Record** buckets;
} HashTable;

// Function to dynamically allocate memory for a hash table with variable-sized buckets
HashTable* create_hash_table(int num_buckets) {
    // Check if the number of buckets is within the valid range
    if (num_buckets < 16 || num_buckets > 4096) {
        return NULL;
    }

    // Allocate memory for the hash table struct and initialize it
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->num_buckets = num_buckets;
    table->num_records = 0;
    table->buckets = calloc(num_buckets, sizeof(Record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    // Initialize each bucket with a null pointer
    for (int i = 0; i < num_buckets; i++) {
        table->buckets[i] = NULL;
    }

    return table;
}

// Function to dynamically allocate memory for a record and initialize it
Record* create_record(char* identifier, float score, time_t timestamp) {
    // Allocate memory for the record struct and initialize it
    Record* record = malloc(sizeof(Record));
    if (!record) {
        return NULL;
    }
    record->identifier = strdup(identifier);
    record->score = score;
    record->timestamp = timestamp;

    return record;
}

// Function to generate a random identifier within the specified range
char* generate_identifier(int min, int max) {
    // Generate a random integer between the minimum and maximum values
    int rand_num = (rand() % (max - min + 1)) + min;

    // Convert the random integer to a string
    char* identifier = malloc(sizeof(char) * 5);
    sprintf(identifier, "%d", rand_num);

    return identifier;
}

// Function to generate a weighted linear transformation of the identifier's length and frequency
float calculate_score(char* identifier) {
    // Calculate the length of the identifier
    int len = strlen(identifier);

    // Calculate the frequency of the identifier
    float freq = 0;
    for (int i = 0; i < len; i++) {
        if (identifier[i] == 'e') {
            freq++;
        }
    }

    // Calculate the weighted linear transformation of the length and frequency
    float score = len * freq;

    return score;
}

// Function to insert a new record into the hash table
void insert_record(HashTable* table, char* identifier, float score, time_t timestamp) {
    // Check if the hash table is null or if the number of records exceeds the maximum capacity
    if (!table || table->num_records >= table->num_buckets * 2) {
        return;
    }

    // Generate a random identifier within the specified range
    char* rand_identifier = generate_identifier(0, 10000);

    // Calculate the weighted linear transformation of the identifier's length and frequency
    float rand_score = calculate_score(rand_identifier);

    // Insert the new record into the hash table
    Record* record = create_record(rand_identifier, rand_score, timestamp);
    int bucket_index = (record->identifier % table->num_buckets);
    if (!table->buckets[bucket_index]) {
        table->buckets[bucket_index] = record;
    } else {
        Record* current = table->buckets[bucket_index];
        while (current->next) {
            current = current->next;
        }
        current->next = record;
    }

    // Update the number of records in the hash table
    table->num_records++;
}

// Function to retrieve a record from the hash table by identifier
Record* get_record(HashTable* table, char* identifier) {
    // Check if the hash table is null or if the identifier is null
    if (!table || !identifier) {
        return NULL;
    }

    // Calculate the bucket index for the given identifier
    int bucket_index = (identifier % table->num_buckets);

    // Search for the record in the hash table
    Record* current = table->buckets[bucket_index];
    while (current) {
        if (!strcmp(current->identifier, identifier)) {
            return current;
        }
        current = current->next;
    }

    // Return null if the record is not found
    return NULL;
}

// Function to update a record in the hash table by identifier
void update_record(HashTable* table, char* identifier, float score, time_t timestamp) {
    // Check if the hash table is null or if the identifier is null
    if (!table || !identifier) {
        return;
    }

    // Calculate the bucket index for the given identifier
    int bucket_index = (identifier % table->num_buckets);

    // Search for the record in the hash table
    Record* current = table->buckets[bucket_index];
    while (current) {
        if (!strcmp(current->identifier, identifier)) {
            current->score = score;
            current->timestamp = timestamp;
            return;
        }
        current = current->next;
    }
}

// Function to delete a record from the hash table by identifier
void delete_record(HashTable* table, char* identifier) {
    // Check if the hash table is null or if the identifier is null
    if (!table || !identifier) {
        return;
    }

    // Calculate the bucket index for the given identifier
    int bucket_index = (identifier % table->num_buckets);

    // Search for the record in the hash table
    Record* current = table->buckets[bucket_index];
    while (current) {
        if (!strcmp(current->identifier, identifier)) {
            // Remove the record from the linked list
            if (current == table->buckets[bucket_index]) {
                table->buckets[bucket_index] = current->next;
            } else {
                Record* previous = current->previous;
                previous->next = current->next;
            }

            // Free the memory allocated for the record
            free(current);

            // Update the number of records in the hash table
            table->num_records--;

            return;
        }
        current = current->next;
    }
}

// Function to retrieve all records from the hash table
void get_all_records(HashTable* table, Record** records) {
    // Check if the hash table is null or if the records array is null
    if (!table || !records) {
        return;
    }

    // Initialize the number of records in the array
    int num_records = 0;

    // Iterate over each bucket in the hash table
    for (int i = 0; i < table->num_buckets; i++) {
        Record* current = table->buckets[i];
        while (current) {
            records[num_records++] = current;
            current = current->next;
        }
    }
}
```
