void populate_activity_logs(user_profile_t* profiles, size_t num_profiles, time_t start_time, time_t end_time) {
    // Loop through each profile and generate random timestamps within the specified date range
    for (size_t i = 0; i < num_profiles; i++) {
        size_t num_logs = rand() % 10 + 1;
        profiles[i].activity_logs = (time_t*)malloc(num_logs * sizeof(time_t));
        if (!profiles[i].activity_logs) {
            continue;
        }

        for (size_t j = 0; j < num_logs; j++) {
            profiles[i].activity_logs[j] = start_time + rand() % (end_time - start_time);
        }
    }
}

