    // Update the name, email, and phone number fields
    strcpy(profile->name, name);
    strcpy(profile->email, email);
    strcpy(profile->phone_number, phone_number);
}

// Define a function to update the activity logs for a user profile
void update_activity_logs(user_profile_t* profile, time_t start_time, time_t end_time) {
    // Loop through each log and check if it falls within the specified date range
    size_t num_logs = 0;
    for (size_t i = 0; i < profile->num_activity_logs; i++) {
        if (profile->activity_logs[i] >= start_time && profile->activity_logs[i] <= end_time) {
            num_logs++;
        }
    }

    // If no logs are found, return
    if (num_logs == 0) {
        return;
    }

    // Allocate memory for the updated activity logs
    time_t* updated_logs = (time_t*)malloc(num_logs * sizeof(time_t));
    if (!updated_logs) {
        return;
    }

    // Copy the updated logs to the new array
    size_t j = 0;
    for (size_t i = 0; i < profile->num_activity_logs; i++) {
        if (profile->activity_logs[i] >= start_time && profile->activity_logs[i] <= end_time) {
            updated_logs[j++] = profile->activity_logs[i];
        }
    }

    // Free the old activity logs and assign the new ones
    free(profile->activity_logs);
    profile->activity_logs = updated_logs;
}
