    transaction_record transactions[100]; // Array of transaction records
} product_inventory;

// Define the function to manage memory allocation and initialization for the dynamic product inventory system
void init_product_inventory(product_inventory *inv) {
    // Allocate memory for the product inventory structure
    inv = (product_inventory *)malloc(sizeof(product_inventory));
    if (!inv) {
        printf("Error: Failed to allocate memory for product inventory\n");
        return;
    }

    // Initialize the product inventory structure with default values
    inv->id = 0;
    strcpy(inv->name, "");
    inv->price = 0.0f;
    inv->quantity = 0;
    for (int i = 0; i < 100; i++) {
        inv->transactions[i].date = "";
        inv->transactions[i].amount = 0.0f;
    }
}

// Define the function to add a new product to the inventory
void add_product(product_inventory *inv, int id, char name[], float price) {
    // Check if the product ID is already in use
    for (int i = 0; i < inv->id; i++) {
        if (inv->transactions[i].id == id) {
            printf("Error: Product ID %d is already in use\n", id);
            return;
        }
    }

    // Add the new product to the inventory
    inv->id++;
    inv->name[inv->id] = name;
    inv->price[inv->id] = price;
    inv->quantity[inv->id] = 0;
}

// Define the function to update an existing product in the inventory
void update_product(product_inventory *inv, int id, char name[], float price) {
    // Check if the product ID exists in the inventory
    for (int i = 0; i < inv->id; i++) {
        if (inv->transactions[i].id == id) {
            strcpy(inv->name[i], name);
            inv->price[i] = price;
            return;
        }
    }

    // If the product ID is not found, print an error message
    printf("Error: Product ID %d does not exist in inventory\n", id);
