#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structures to be managed by the function
typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

typedef struct {
    int value;
    char metadata[10];
} RecordStruct;

// Define the function to manage memory allocation and initialization for multiple data structures
void init_data_structures(int num_records, int range_start, int range_end) {
    // Validate input parameters
    if (num_records <= 0 || range_start < 0 || range_end < 0 || range_start > range_end) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for the data structures
    OffsetStruct *offset_struct = malloc(num_records * sizeof(OffsetStruct));
    KeyStruct *key_struct = malloc(num_records * sizeof(KeyStruct));
    RecordStruct *record_struct = malloc(num_records * sizeof(RecordStruct));

    // Initialize the data structures
    for (int i = 0; i < num_records; i++) {
        offset_struct[i].offset = rand() % (range_end - range_start + 1) + range_start;
        key_struct[i].key = rand() % (range_end - range_start + 1) + range_start;
        record_struct[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    // Check for memory allocation errors
    if (!offset_struct || !key_struct || !record_struct) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offset_struct);
        free(key_struct);
        free(record_struct);
        return;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Populate the record structures with unique random values within the specified range
    for (int i = 0; i < num_records; i++) {
        // Acquire the lock to prevent concurrent modifications
        pthread_mutex_lock(&mutex);

        // Generate a new random value within the specified range
        int new_value = rand() % (range_end - range_start + 1) + range_start;

        // Check if the new value overlaps with any existing values
        bool overlap = false;
        for (int j = 0; j < i; j++) {
            if (new_value == record_struct[j].value) {
                overlap = true;
                break;
            }
        }

        // If the new value overlaps, generate a new one until it doesn't
        while (overlap) {
            new_value = rand() % (range_end - range_start + 1) + range_start;
            overlap = false;
            for (int j = 0; j < i; j++) {
                if (new_value == record_struct[j].value) {
                    overlap = true;
                    break;
                }
            }
        }

        // Update the record structure with the new value
        record_struct[i].value = new_value;

        // Release the lock
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory allocated for the data structures
    free(offset_struct);
    free(key_struct);
    free(record_struct);
}
