#include <string.h>
#include <time.h>

#define MAX_KEYS 1000000
#define MIN_KEY 0
#define MAX_KEY 1000000
#define MAX_OFFSETS 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 1000000

typedef struct {
    int key;
    long offset;
} record;

record* allocate_records(int num_keys, int num_offsets) {
    // Allocate memory for the records array
    record* records = (record*)malloc(sizeof(record) * num_keys);
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the keys and offsets arrays
    int* keys = (int*)malloc(sizeof(int) * num_keys);
    long* offsets = (long*)malloc(sizeof(long) * num_offsets);
    if (!keys || !offsets) {
        printf("Error: Failed to allocate memory for keys and offsets\n");
        free(records);
        return NULL;
    }

    // Initialize the keys array with unique random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY);
        while (key == keys[i] || key == offsets[i]) {
            // If the generated key is not unique, retry with a different algorithm
            key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY);
        }
        keys[i] = key;
    }

    // Initialize the offsets array with sequential numbers starting from 0
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Populate the records array with unique random values within the specified range
    for (int i = 0; i < num_keys; i++) {
        int key = keys[i];
        long offset = offsets[i];
        record* rec = &records[i];
        rec->key = key;
        rec->offset = offset;
    }

    // Shuffle the order of the records in the array to ensure that the initial order is not preserved
    int* shuffled_indices = (int*)malloc(sizeof(int) * num_keys);
    if (!shuffled_indices) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }
    for (int i = 0; i < num_keys; i++) {
        shuffled_indices[i] = i;
    }
    int shuffle_buffer_size = MIN(num_keys, MAX_SHUFFLE_BUFFER_SIZE);
    for (int i = 0; i < num_keys - 1; i++) {
        int j = i + rand() % (num_keys - i);
        if (i != j) {
            int temp = shuffled_indices[i];
            shuffled_indices[i] = shuffled_indices[j];
            shuffled_indices[j] = temp;
        }
    }
    for (int i = 0; i < num_keys; i++) {
        int index = shuffled_indices[i];
        record* rec = &records[index];
        records[i] = *rec;
    }
    free(shuffled_indices);

    return records;
}
