// Define a function to allocate memory for the memory block
memory_block* allocate_memory(int num_records, int range) {
    // Calculate the total size of the combined memory block
    int total_size = sizeof(long) * num_records + sizeof(int) * num_records + sizeof(record *) * num_records;

    // Allocate memory for the memory block using malloc
    memory_block* mem_block = (memory_block*)malloc(total_size);

    // Initialize the offsets, keys, and records arrays in the memory block
    mem_block->offsets = (long*)mem_block;
    mem_block->keys = (int*)(mem_block->offsets + num_records);
    mem_block->records = (record**)(mem_block->keys + num_records);

    // Initialize the offsets and keys arrays to random values within the specified range
    for (int i = 0; i < num_records; i++) {
        mem_block->offsets[i] = rand() % range;
        mem_block->keys[i] = rand() % range;
    }

    // Initialize the records array to point to the corresponding keys and offsets
    for (int i = 0; i < num_records; i++) {
        mem_block->records[i] = &(mem_block->keys[i]);
        mem_block->records[i]->offset = &(mem_block->offsets[i]);
