    int shuffle_buffer[MAX_SHUFFLE_BUFFER_SIZE];
    for (int i = 0; i < num_offsets; i++) {
        shuffle_buffer[i] = i;
    }
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        int j = rand() % (num_offsets - i) + i;
        if (j != i) {
            int temp = shuffle_buffer[i];
            shuffle_buffer[i] = shuffle_buffer[j];
            shuffle_buffer[j] = temp;
        }
    }
    for (int i = 0; i < num_offsets; i++) {
        records[shuffle_buffer[i]].offset = offsets + i;
        records[shuffle_buffer[i]].key = keys[i];
    }

    return records;
}

int keyExists(int *keys, int index, int key) {
