    // Allocate memory for product inventories
    inv->inventory = (ProductInventory *)malloc(sizeof(ProductInventory) * 1000);
    assert(inv->inventory != NULL);

    // Initialize product inventory data structures
    for (int i = 0; i < 1000; i++) {
        inv->inventory[i].id = -1;
        strcpy(inv->inventory[i].name, "");
        inv->inventory[i].price = 0.0f;
        inv->inventory[i].quantity = 0;
