    assert(inv->categories != NULL);

    // Initialize category data structures
    for (int i = 0; i < 100; i++) {
        inv->categories[i].id = -1;
        strcpy(inv->categories[i].name, "");
        inv->categories[i].parent_id = -1;
    }
