    // Check if product with given ID already exists in inventory
    for (int i = 0; i < inv->num_products; i++) {
        if (inv->inventory[i].id == id) {
            return; // product already exists, do nothing
        }
    }

    // Find an empty slot in the inventory array and initialize it with new product data
    for (int i = 0; i < inv->num_products; i++) {
        if (inv->inventory[i].id == -1) {
            inv->inventory[i].id = id;
            strcpy(inv->inventory[i].name, name);
            inv->inventory[i].price = price;
            break;
        }
    }
}

