// Define the task structure
typedef struct {
    int priority;
    char* description;
    time_t timestamp;
    pthread_t thread_id;
    double performance_metric;
} task;

// Define the initialization modes
#define INIT_MODE_CUSTOM 0
#define INIT_MODE_RANDOM 1

// Define the custom key-value store API
typedef struct {
    char* key;
    void* value;
} kv_store_entry;

// Define the CSV file format
#define CSV_FILE_FORMAT "description,priority,timestamp,thread_id,performance_metric\n"

// Define the logging mechanism
typedef struct {
    char* log_file;
    FILE* log_fp;
} logging_info;

// Function to dynamically allocate memory for and initialize a list of tasks
task* init_tasks(int num_tasks, int init_mode) {
    // Allocate memory for the task list
    task* tasks = (task*)malloc(num_tasks * sizeof(task));
    if (!tasks) {
        printf("Error: Failed to allocate memory for task list\n");
        return NULL;
    }

    // Initialize each task structure with default values
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].priority = 0;
        tasks[i].description = NULL;
        tasks[i].timestamp = time(NULL);
        tasks[i].thread_id = pthread_self();
        tasks[i].performance_metric = 0.0;
    }

    // Initialize the custom key-value store
    kv_store_entry* kv_store = (kv_store_entry*)malloc(num_tasks * sizeof(kv_store_entry));
    if (!kv_store) {
        printf("Error: Failed to allocate memory for custom key-value store\n");
        free(tasks);
        return NULL;
    }

    // Initialize the logging mechanism
    logging_info* log = (logging_info*)malloc(sizeof(logging_info));
    if (!log) {
        printf("Error: Failed to allocate memory for logging information\n");
        free(tasks);
        free(kv_store);
        return NULL;
    }

    // Initialize the log file and file pointer
    char* log_file = (char*)malloc(1024 * sizeof(char));
    if (!log_file) {
        printf("Error: Failed to allocate memory for log file name\n");
        free(tasks);
        free(kv_store);
        free(log);
        return NULL;
    }
    sprintf(log_file, "task_list.log");
    FILE* log_fp = fopen(log_file, "w+");
    if (!log_fp) {
        printf("Error: Failed to open log file for writing\n");
        free(tasks);
        free(kv_store);
        free(log);
        return NULL;
    }

    // Initialize the task list with custom values or random values
    if (init_mode == INIT_MODE_CUSTOM) {
        // Custom initialization mode
        printf("Custom initialization mode selected\n");
        for (int i = 0; i < num_tasks; i++) {
            tasks[i].priority = get_custom_value(1, 10);
            tasks[i].description = get_custom_string(1024);
            tasks[i].timestamp = time(NULL);
            tasks[i].thread_id = pthread_self();
            tasks[i].performance_metric = get_custom_value(0.0, 100.0);
        }
    } else if (init_mode == INIT_MODE_RANDOM) {
        // Random initialization mode
        printf("Random initialization mode selected\n");
        for (int i = 0; i < num_tasks; i++) {
            tasks[i].priority = rand() % 10 + 1;
            tasks[i].description = get_random_string(1024);
            tasks[i].timestamp = time(NULL);
            tasks[i].thread_id = pthread_self();
            tasks[i].performance_metric = rand() % 100.0;
        }
    } else {
        // Invalid initialization mode
        printf("Invalid initialization mode selected\n");
        free(tasks);
        free(kv_store);
        free(log);
        return NULL;
    }

    // Initialize the custom key-value store with task descriptions as keys and thread IDs as values
    for (int i = 0; i < num_tasks; i++) {
        kv_store[i].key = tasks[i].description;
        kv_store[i].value = &(tasks[i].thread_id);
    }

    // Initialize the logging information with the log file and file pointer
    log->log_file = log_file;
    log->log_fp = log_fp;

    return tasks;
}

// Function to release all allocated memory for a task list
void free_tasks(task* tasks) {
    // Release the task list memory
    free(tasks);

    // Release the custom key-value store memory
    free(kv_store);

    // Release the logging information memory
    free(log);
}

// Function to add a new task to the task list
void add_task(task* tasks, int num_tasks, task new_task) {
    // Check if the task list is full
    if (num_tasks == MAX_TASKS) {
        printf("Error: Task list is full\n");
        return;
    }

    // Add the new task to the end of the list
    tasks[num_tasks] = new_task;

    // Increment the number of tasks in the list
    num_tasks++;
}

// Function to remove a task from the task list
void remove_task(task* tasks, int num_tasks, char* description) {
    // Find the index of the task with the given description
    int i = 0;
    while (i < num_tasks && strcmp(tasks[i].description, description) != 0) {
        i++;
    }

    // Check if the task was found
    if (i == num_tasks) {
        printf("Error: Task not found\n");
        return;
    }

    // Remove the task from the list by shifting all tasks after it back one index
    for (int j = i; j < num_tasks - 1; j++) {
        tasks[j] = tasks[j + 1];
    }

    // Decrement the number of tasks in the list
    num_tasks--;
}

// Function to update a task's priority level
void update_priority(task* tasks, int num_tasks, char* description, int new_priority) {
    // Find the index of the task with the given description
    int i = 0;
    while (i < num_tasks && strcmp(tasks[i].description, description) != 0) {
        i++;
    }

    // Check if the task was found
    if (i == num_tasks) {
        printf("Error: Task not found\n");
        return;
    }

    // Update the priority level of the task
    tasks[i].priority = new_priority;
}

// Function to update a task's performance metric
void update_performance(task* tasks, int num_tasks, char* description, double new_performance) {
    // Find the index of the task with the given description
    int i = 0;
    while (i < num_tasks && strcmp(tasks[i].description, description) != 0) {
        i++;
    }

    // Check if the task was found
    if (i == num_tasks) {
        printf("Error: Task not found\n");
        return;
    }

    // Update the performance metric of the task
    tasks[i].performance_metric = new_performance;
}

// Function to retrieve a task from the task list by description
task* get_task(task* tasks, int num_tasks, char* description) {
    // Find the index of the task with the given description
    int i = 0;
    while (i < num_tasks && strcmp(tasks[i].description, description) != 0) {
        i++;
    }

    // Check if the task was found
    if (i == num_tasks) {
        printf("Error: Task not found\n");
        return NULL;
    }

    // Return a pointer to the task structure
    return &(tasks[i]);
}

// Function to retrieve all tasks from the task list
task* get_all_tasks(task* tasks, int num_tasks) {
    // Create a new array of tasks with the same size as the original list
    task* all_tasks = (task*)malloc(num_tasks * sizeof(task));
    if (!all_tasks) {
        printf("Error: Failed to allocate memory for all tasks\n");
        return NULL;
    }

    // Copy all tasks from the original list to the new array
    for (int i = 0; i < num_tasks; i++) {
        all_tasks[i] = tasks[i];
    }

    return all_tasks;
}

// Function to export the task list to a CSV file
void export_to_csv(task* tasks, int num_tasks, char* csv_file) {
    // Open the CSV file for writing
    FILE* csv_fp = fopen(csv_file, "w+");
    if (!csv_fp) {
        printf("Error: Failed to open CSV file for writing\n");
        return;
    }

    // Write the header row to the CSV file
    fprintf(csv_fp, "%s", CSV_FILE_FORMAT);

    // Write each task to the CSV file
    for (int i = 0; i < num_tasks; i++) {
        fprintf(csv_fp, "%s,%d,%ld,%lu,%f\n", tasks[i].description, tasks[i].priority, tasks[i].timestamp, tasks[i].thread_id, tasks[i].performance_metric);
    }

    // Close the CSV file
    fclose(csv_fp);
}

// Function to import tasks from a CSV file
void import_from_csv(task* tasks, int num_tasks, char* csv_file) {
    // Open the CSV file for reading
    FILE* csv_fp = fopen(csv_file, "r");
    if (!csv_fp) {
        printf("Error: Failed to open CSV file for reading\n");
        return;
    }

    // Read each line of the CSV file and parse it into a task structure
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, csv_fp)) != -1) {
        // Parse the line into a task structure
        task new_task;
        char* token = strtok(line, ",");
        new_task.description = token;
        token = strtok(NULL, ",");
        new_task.priority = atoi(token);
        token = strtok(NULL, ",");
        new_task.timestamp = atol(token);
        token = strtok(NULL, ",");
        new_task.thread_id = (unsigned long)strtoul(token, NULL, 10);
        token = strtok(NULL, ",");
        new_task.performance_metric = atof(token);

        // Add the task to the list
        add_task(tasks, num_tasks, new_task);
    }

    // Close the CSV file
    fclose(csv_fp);
}

// Function to verify the integrity of the data structures after initialization
void verify_integrity(task* tasks, int num_tasks) {
    // Check if any tasks have duplicate descriptions
    for (int i = 0; i < num_tasks - 1; i++) {
        for (int j = i + 1; j < num_tasks; j++) {
            if (strcmp(tasks[i].description, tasks[j].description) == 0) {
                printf("Error: Duplicate task description found\n");
                return;
            }
        }
    }
}

// Function to release all allocated memory for a task list and custom key-value store
void free_all(task* tasks, int num_tasks) {
    // Release the task list memory
    free(tasks);

    // Release the custom key-value store memory
    free(kv_store);
}
