    pthread_mutex_unlock(&(entries->mutex));
}

// Function to remove a file entry from the collection
void remove_file_entry(struct file_entries* entries, size_t index) {
    // Acquire the mutex for synchronizing access to the collection of file entries
    pthread_mutex_lock(&(entries->mutex));

    // Check if the specified index is valid
    if (index >= entries->num_entries) {
        printf("Error: Invalid index specified for removing a file entry\n");
        pthread_mutex_unlock(&(entries->mutex));
        return;
    }

    // Deallocate memory for the removed file entry
    free(entries->entries[index]);

    // Shift all subsequent file entries to fill the gap
    for (size_t i = index + 1; i < entries->num_entries; i++) {
        entries->entries[i - 1] = entries->entries[i];
    }

    // Decrement the number of file entries
    entries->num_entries--;

    // Release the mutex for synchronizing access to the collection of file entries
    pthread_mutex_unlock(&(entries->mutex));
}

