    pthread_mutex_lock(&(entries->mutex));

    // Check if the specified index is valid
    if (index >= entries->num_entries) {
        printf("Error: Invalid index specified for updating a file entry\n");
        pthread_mutex_unlock(&(entries->mutex));
        return;
    }

    // Update the file entry with the new values
    entries->entries[index]->float_value = float_value;
    entries->entries[index]->double_value = double_value;
    entries->entries[index]->metadata = metadata;

    // Release the mutex for synchronizing access to the collection of file entries
    pthread_mutex_unlock(&(entries->mutex));
}

// Function to retrieve a file entry from the collection
struct file_entry* get_file_entry(struct file_entries* entries, size_t index) {
    // Acquire the mutex for synchronizing access to the collection of file entries
    pthread_mutex_lock(&(entries->mutex));

    // Check if the specified index is valid
    if (index >= entries->num_entries) {
        printf("Error: Invalid index specified for retrieving a file entry\n");
        pthread_mutex_unlock(&(entries->mutex));
        return NULL;
    }

    // Return the file entry at the specified index
    struct file_entry* entry = entries->entries[index];

    // Release the mutex for synchronizing access to the collection of file entries
    pthread_mutex_unlock(&(entries->mutex));

    return entry;
}

// Function to periodically check the status of each entry and transition it to INACTIVE if it has not been accessed within a specified timeout period
void check_file_entry_status(struct file_entries* entries, size_t timeout) {
    // Acquire the mutex for synchronizing access to the collection of file entries
    pthread_mutex_lock(&(entries->mutex));

    // Iterate over each file entry and check its status
    for (size_t i = 0; i < entries->num_entries; i++) {
        struct file_entry* entry = entries->entries[i];
        if (entry->status == ACTIVE && entry->last_accessed + timeout <= time(NULL)) {
            // Transition the file entry to INACTIVE if it has not been accessed within the specified timeout period
            entry->status = INACTIVE;
        }
    }

    // Release the mutex for synchronizing access to the collection of file entries
    pthread_mutex_unlock(&(entries->mutex));
}
