```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <limits.h>

#define MAX_OFFSETS 1000000
#define MAX_KEYS 1000000
#define MIN_KEY 0
#define MAX_KEY 1000000
#define MAX_SHUFFLE_BUFFER_SIZE 1000000

typedef struct {
    long offset;
    int key;
} record;

record* allocate_records(int num_offsets, int num_keys) {
    // Allocate memory for the records
    record* records = (record*)malloc(sizeof(record) * num_offsets);
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the offset values
    long* offsets = (long*)malloc(sizeof(long) * num_offsets);
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        free(records);
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i;
    }

    // Initialize the key values
    int* keys = (int*)malloc(sizeof(int) * num_keys);
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(records);
        free(offsets);
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        int key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        while (!unique_key(keys, i, key)) {
            key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        }
        keys[i] = key;
    }

    // Initialize the record structures
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Shuffle the order of the records
    int* shuffled_indices = (int*)malloc(sizeof(int) * num_offsets);
    if (!shuffled_indices) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }
    for (int i = 0; i < num_offsets; i++) {
        shuffled_indices[i] = i;
    }
    shuffle(shuffled_indices, num_offsets);
    for (int i = 0; i < num_offsets; i++) {
        records[i].offset = offsets[shuffled_indices[i]];
        records[i].key = keys[shuffled_indices[i]];
    }

    // Free the temporary memory
    free(shuffled_indices);

    return records;
}

// Check if a key is unique in an array of ints
bool unique_key(int* keys, int index, int key) {
    for (int i = 0; i < index; i++) {
        if (keys[i] == key) {
            return false;
        }
    }
    return true;
}

// Shuffle an array of integers using the Fisher-Yates algorithm
void shuffle(int* arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        int j = i + rand() % (n - i);
        swap(&arr[i], &arr[j]);
    }
}

// Swap two integers
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}
