// Define a struct to represent a user profile
typedef struct {
    char *username;
    int num_emails;
    char **emails;
    char *preference;
} Profile;

// Define a function to initialize the profiles with sample data
void init_profiles(Profile *profiles, int num_profiles, int email_limit) {
    // Initialize the profiles with sample data
    for (int i = 0; i < num_profiles; i++) {
        Profile profile = {
            .username = "user" + i,
            .num_emails = rand() % email_limit + 1,
            .emails = malloc(profile.num_emails * sizeof(char *)),
            .preference = "option" + (i % 3)
        };
        for (int j = 0; j < profile.num_emails; j++) {
            profile.emails[j] = malloc(16);
            sprintf(profile.emails[j], "email%d@example.com", i * 10 + j);
        }
        profiles[i] = profile;
    }
}

// Define a function to track and report the average number of email addresses per profile
void track_average(Profile *profiles, int num_profiles) {
    // Calculate the total number of email addresses across all profiles
    int total_emails = 0;
    for (int i = 0; i < num_profiles; i++) {
        total_emails += profiles[i].num_emails;
    }
    // Calculate the average number of email addresses per profile
    float average_emails = (float)total_emails / (float)num_profiles;
    printf("Average number of email addresses per profile: %.2f\n", average_emails);
}

// Define a function to track and report the most frequent preference encountered during initialization
void track_preference(Profile *profiles, int num_profiles) {
    // Initialize a map to store the frequency of each preference
    char **preferences = malloc(3 * sizeof(char *));
    for (int i = 0; i < 3; i++) {
        preferences[i] = malloc(8);
        sprintf(preferences[i], "option%d", i);
    }
    // Iterate over the profiles and increment the frequency of each preference
    for (int i = 0; i < num_profiles; i++) {
        char *preference = profiles[i].preference;
        int index = -1;
        for (int j = 0; j < 3; j++) {
            if (strcmp(preferences[j], preference) == 0) {
                index = j;
                break;
            }
        }
        if (index != -1) {
            preferences[index][7]++;
        } else {
            preferences[3][7]++;
        }
    }
    // Find the most frequent preference and print it
    int max_freq = 0;
    char *most_frequent = "option0";
    for (int i = 0; i < 3; i++) {
        if (preferences[i][7] > max_freq) {
            max_freq = preferences[i][7];
            most_frequent = preferences[i];
        }
    }
    printf("Most frequent preference: %s\n", most_frequent);
}

