#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
} record_t;

// Define the function to dynamically manage memory allocation and initialization for an array of long offset values, an array of int keys, and an array of record structures
void dynamic_memory_management(int num_records, int random_value_range, bool parallel_processing, bool logging, bool monitoring) {
    // Declare variables to store the arrays of long offset values, int keys, and record structures
    long *offset_values = NULL;
    int *keys = NULL;
    record_t *records = NULL;

    // Allocate memory for the arrays of long offset values, int keys, and record structures
    if ((offset_values = (long *)malloc(num_records * sizeof(long))) == NULL) {
        printf("Error: Failed to allocate memory for the array of long offset values\n");
        return;
    }
    if ((keys = (int *)malloc(num_records * sizeof(int))) == NULL) {
        printf("Error: Failed to allocate memory for the array of int keys\n");
        free(offset_values);
        return;
    }
    if ((records = (record_t *)malloc(num_records * sizeof(record_t))) == NULL) {
        printf("Error: Failed to allocate memory for the array of record structures\n");
        free(offset_values);
        free(keys);
        return;
    }

    // Initialize the arrays of long offset values, int keys, and record structures with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offset_values[i] = rand() % random_value_range;
        keys[i] = rand() % random_value_range;
        records[i].value = rand() % random_value_range;
    }

    // If parallel processing is enabled, create a mutex to synchronize access to the arrays of long offset values, int keys, and record structures
    pthread_mutex_t *mutex = NULL;
    if (parallel_processing) {
        mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
        if ((mutex == NULL) || (pthread_mutex_init(mutex, NULL) != 0)) {
            printf("Error: Failed to create a mutex for synchronizing access to the arrays of long offset values, int keys, and record structures\n");
            free(offset_values);
            free(keys);
            free(records);
            return;
        }
    }

    // If logging is enabled, create a file stream for writing log messages
    FILE *log_file = NULL;
    if (logging) {
        log_file = fopen("dynamic_memory_management.log", "w");
        if (log_file == NULL) {
            printf("Error: Failed to open the log file\n");
            free(offset_values);
            free(keys);
            free(records);
            return;
        }
    }

    // If monitoring is enabled, create a thread for monitoring system resources and creating alerts when necessary
    pthread_t monitor_thread = 0;
    if (monitoring) {
        if ((pthread_create(&monitor_thread, NULL, monitor_system_resources, NULL)) != 0) {
            printf("Error: Failed to create a thread for monitoring system resources\n");
            free(offset_values);
            free(keys);
            free(records);
            return;
        }
    }

    // If parallel processing is enabled, create threads for each record structure and synchronize access to the arrays of long offset values, int keys, and record structures using the mutex
    if (parallel_processing) {
        pthread_t *threads = (pthread_t *)malloc(num_records * sizeof(pthread_t));
        for (int i = 0; i < num_records; i++) {
            if ((pthread_create(&threads[i], NULL, process_record, &records[i])) != 0) {
                printf("Error: Failed to create a thread for processing record %d\n", i);
                free(offset_values);
                free(keys);
                free(records);
                return;
            }
        }
        for (int i = 0; i < num_records; i++) {
            pthread_join(threads[i], NULL);
        }
        free(threads);
    } else {
        // Process each record structure sequentially and synchronize access to the arrays of long offset values, int keys, and record structures using the mutex
        for (int i = 0; i < num_records; i++) {
            pthread_mutex_lock(mutex);
            process_record(&records[i]);
            pthread_mutex_unlock(mutex);
        }
    }

    // If logging is enabled, write log messages to the file stream
    if (logging) {
        fclose(log_file);
    }

    // If monitoring is enabled, join the monitor thread and free the mutex
    if (monitoring) {
        pthread_join(monitor_thread, NULL);
        pthread_mutex_destroy(mutex);
        free(mutex);
    }

    // Free the arrays of long offset values, int keys, and record structures
    free(offset_values);
    free(keys);
    free(records);
}

// Define a function to process each record structure in parallel using a mutex for synchronization
void *process_record(void *arg) {
    // Cast the argument to a pointer to a record structure and declare variables to store the long offset value, int key, and record structure
    record_t *record = (record_t *)arg;
    long offset_value = 0;
    int key = 0;

    // Lock the mutex before accessing the arrays of long offset values, int keys, and record structures
    pthread_mutex_lock(mutex);

    // Access the arrays of long offset values, int keys, and record structures using the mutex
    for (int i = 0; i < num_records; i++) {
        offset_value += offset_values[i];
        key += keys[i];
        record->value += records[i].value;
    }

    // Unlock the mutex after accessing the arrays of long offset values, int keys, and record structures
    pthread_mutex_unlock(mutex);

    return NULL;
}

// Define a function to monitor system resources and create alerts when necessary
void *monitor_system_resources(void *arg) {
    // Declare variables to store the current CPU usage, memory usage, and disk usage
    float cpu_usage = 0.0f;
    long memory_usage = 0L;
    long disk_usage = 0L;

    // Loop indefinitely to monitor system resources and create alerts when necessary
    while (1) {
        // Get the current CPU usage, memory usage, and disk usage
        cpu_usage = get_cpu_usage();
        memory_usage = get_memory_usage();
        disk_usage = get_disk_usage();

        // If the CPU usage exceeds a certain threshold or the memory usage exceeds a certain threshold, create an alert
        if ((cpu_usage > 80.0f) || (memory_usage > 80L * 1024L * 1024L)) {
            printf("Alert: CPU usage is %f%% and memory usage is %ld MB\n", cpu_usage, memory_usage / 1024L);
        }

        // If the disk usage exceeds a certain threshold, create an alert
        if (disk_usage > 80L * 1024L * 1024L) {
            printf("Alert: Disk usage is %ld MB\n", disk_usage / 1024L);
        }

        // Sleep for a certain amount of time before checking the system resources again
        sleep(60);
    }
}
