// Define a function to update or remove a record from the array
void update_record(Record* records, int index, int key, long offset) {
    // Check if the specified index is within the bounds of the array
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Error: Invalid record index %d\n", index);
        return;
    }

    // Update the key and offset for the specified record
    records[index].key = key;
    records[index].offset = offset;
}

// Define a function to remove a record from the array
void remove_record(Record* records, int index) {
    // Check if the specified index is within the bounds of the array
    if (index < 0 || index >= num_records) {
        fprintf(stderr, "Error: Invalid record index %d\n", index);
        return;
    }

    // Shift all records after the specified index to fill the gap
    for (int i = index + 1; i < num_records; i++) {
        records[i - 1] = records[i];
    }

    // Decrement the number of records by one
