    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 100 + 1;
    }

    // Allocate memory for the key array
    int* keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for key array\n");
        free(offsets);
        return;
