// Define a struct to represent product data
struct product_data {
    float price;
    int stock_quantity;
    char* category;
};

// Define a struct to represent inventory records
struct record {
    int value;
    char* key;
    double value;
    time_t timestamp;
};

// Define a struct to represent the cache
struct cache {
    struct product_data* products;
    struct record* records;
    size_t capacity;
    size_t size;
};

// Define a function to generate a random integer within a specified range
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Define a function to generate a random string of length n
char* rand_string(size_t n) {
    char* str = malloc(n * sizeof(char));
    for (int i = 0; i < n; i++) {
        str[i] = 'a' + rand() % ('z' - 'a');
    }
    return str;
}

// Define a function to initialize the inventory and product records
void init_inventory(struct cache* cache) {
    // Allocate memory for the product names, IDs, and data structures
    cache->products = malloc(5 * sizeof(char*));
    cache->records = malloc(5 * sizeof(struct record));

    // Initialize the product names and IDs
    for (int i = 0; i < 5; i++) {
        cache->products[i] = rand_string(rand_range(5, 20));
        cache->records[i].value = rand_range(1, 100);
        cache->records[i].key = malloc(sizeof(char) * (strlen(cache->products[i]) + 1));
        strcpy(cache->records[i].key, cache->products[i]);
    }
}

// Define a function to update the inventory and product records
void update_inventory(struct cache* cache) {
    // Update the product data structures with new values
    for (int i = 0; i < 5; i++) {
        cache->records[i].value += rand_range(-1, 1);
        if (cache->records[i].value < 0) {
            cache->records[i].value = 0;
        } else if (cache->records[i].value > 100) {
            cache->records[i].value = 100;
        }
    }
}

// Define a function to free all allocated memory at the end of operation
void cleanup(struct cache* cache) {
    // Free the product names and IDs
    for (int i = 0; i < 5; i++) {
        free(cache->products[i]);
        free(cache->records[i].key);
    }
    // Free the memory allocated for the product data structures and records
    free(cache->products);
    free(cache->records);
}
