// Custom allocator for memory management
void* custom_alloc(size_t size) {
    // Implement a custom allocation strategy that minimizes memory fragmentation and ensures efficient garbage collection
    // Use a combination of malloc, calloc, realloc, and free to allocate memory in a way that adheres to the total memory usage constraint of 20 MB
    return malloc(size);
}

// Custom deallocator for memory management
void custom_dealloc(void* ptr) {
    // Implement a custom deallocation strategy that ensures efficient garbage collection and minimizes memory fragmentation
    free(ptr);
}

// Struct for storing event data
typedef struct {
    int key;
    long offset;
    double timestamp;
} event_t;

// Function to generate random values within a range
int rand_range(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to validate timestamps and handle out-of-range values
void validate_timestamp(double* timestamp, double start_date, double end_date) {
    // Check if the timestamp is within the valid range
    if (*timestamp < start_date || *timestamp > end_date) {
        // Log the out-of-range value for monitoring purposes
        printf("Out-of-range timestamp: %f\n", *timestamp);
        // Set the message to a default placeholder
        *timestamp = 0;
    }
}

// Function to validate event references and handle invalid references
void validate_event(event_t* event, double* timestamps, int num_timestamps) {
    // Check if the event reference is valid
    if (event->offset < 0 || event->offset >= num_timestamps) {
        // Log a warning for invalid references
        printf("Invalid event reference: %d\n", event->offset);
        // Set the message to a default placeholder
        event->timestamp = 0;
    } else {
        // Validate the timestamp reference and handle out-of-range values
        validate_timestamp(&event->timestamp, timestamps[event->offset], timestamps[num_timestamps - 1]);
    }
}

