#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

// Define the structure for an item in the cache
typedef struct Item {
    int id;
    float value;
    char* string;
} Item;

// Define the configuration structure for the cache
typedef struct CacheConfig {
    size_t numItems;
    int minId, maxId;
    float minValue, maxValue;
    size_t maxStringLength;
} CacheConfig;

// Define the cache structure
typedef struct Cache {
    Item* items;
    size_t capacity;
    size_t numItems;
    bool persisted;
} Cache;

// Initialize a new cache with the given configuration
Cache* initCache(const CacheConfig* config) {
    // Allocate memory for the cache structure
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) {
        return NULL;
    }

    // Allocate memory for the item array
    cache->items = malloc(config->numItems * sizeof(Item));
    if (!cache->items) {
        free(cache);
        return NULL;
    }

    // Initialize the cache structure
    cache->capacity = config->numItems;
    cache->numItems = 0;
    cache->persisted = false;

    // Populate each item with random values within the specified ranges and resolutions
    for (size_t i = 0; i < config->numItems; ++i) {
        Item* item = &cache->items[i];
        item->id = rand() % (config->maxId - config->minId + 1) + config->minId;
        item->value = (float)(rand() % (int)(config->maxValue - config->minValue + 1)) / RAND_MAX + config->minValue;
        item->string = malloc(config->maxStringLength * sizeof(char));
        if (!item->string) {
            free(cache);
            return NULL;
        }
        for (size_t j = 0; j < config->maxStringLength; ++j) {
            item->string[j] = rand() % ('Z' - 'A') + 'A';
        }
    }

    // Return the initialized cache structure
    return cache;
}

// Add an item to the cache, evicting the least frequently used item if necessary
void addItem(Cache* cache, const Item* item) {
    // Check if the cache is full and needs to be resized
    if (cache->numItems == cache->capacity) {
        // Evict the least frequently used item from the cache
        size_t lfu = 0;
        for (size_t i = 1; i < cache->numItems; ++i) {
            if (cache->items[lfu].frequency < cache->items[i].frequency) {
                lfu = i;
            }
        }
        free(cache->items[lfu].string);
        memmove(&cache->items[lfu], &cache->items[lfu + 1], (cache->numItems - lfu - 1) * sizeof(Item));
        --cache->numItems;
    }

    // Add the new item to the cache
    Item* newItem = &cache->items[cache->numItems++];
    memcpy(newItem, item, sizeof(Item));
}

// Update an existing item in the cache with a new value
void updateItem(Cache* cache, const Item* item) {
    // Find the index of the item to be updated
    size_t i;
    for (i = 0; i < cache->numItems; ++i) {
        if (cache->items[i].id == item->id) {
            break;
        }
    }

    // Update the item's value and frequency
    Item* updatedItem = &cache->items[i];
    updatedItem->value = item->value;
    ++updatedItem->frequency;
}

// Retrieve an item from the cache by its ID
const Item* getItem(Cache* cache, int id) {
    // Find the index of the item with the given ID
    size_t i;
    for (i = 0; i < cache->numItems; ++i) {
        if (cache->items[i].id == id) {
            break;
        }
    }

    // Return NULL if the item is not found
    if (i == cache->numItems) {
        return NULL;
    }

    // Update the item's frequency and return it
    Item* retrievedItem = &cache->items[i];
    ++retrievedItem->frequency;
    return retrievedItem;
}

// Persist the cache contents to disk
void persistCache(Cache* cache) {
    // Open a file for writing
    FILE* file = fopen("cache.dat", "wb");
    if (!file) {
        printf("Error: failed to open cache file for writing\n");
        return;
    }

    // Write the cache contents to the file
    size_t numItems = cache->numItems;
    fwrite(&numItems, sizeof(size_t), 1, file);
    for (size_t i = 0; i < numItems; ++i) {
        Item* item = &cache->items[i];
        fwrite(item, sizeof(Item), 1, file);
    }

    // Close the file and mark the cache as persisted
    fclose(file);
    cache->persisted = true;
}

// Load the cache contents from disk
void loadCache(Cache* cache) {
    // Open a file for reading
    FILE* file = fopen("cache.dat", "rb");
    if (!file) {
        printf("Error: failed to open cache file for reading\n");
        return;
    }

    // Read the number of items in the cache from the file
    size_t numItems;
    fread(&numItems, sizeof(size_t), 1, file);

    // Allocate memory for the item array and read each item from the file
    cache->items = malloc(numItems * sizeof(Item));
    if (!cache->items) {
        free(cache);
        return;
    }
    cache->capacity = numItems;
    cache->numItems = 0;
    for (size_t i = 0; i < numItems; ++i) {
        Item* item = &cache->items[i];
        fread(item, sizeof(Item), 1, file);
    }

    // Close the file and mark the cache as loaded
    fclose(file);
    cache->persisted = true;
}

// Free the memory allocated for the cache
void freeCache(Cache* cache) {
    if (cache) {
        for (size_t i = 0; i < cache->numItems; ++i) {
            free(cache->items[i].string);
        }
        free(cache->items);
        free(cache);
    }
}
