    for (size_t i = 0; i < num_tasks; ++i) {
        struct task_info* task = &tasks[i];
        struct scheduling_policy* policy = task->policy;

        // Adjust the priority threshold based on system load
        if (get_system_load() > policy->priority_threshold) {
            policy->priority_threshold++;
        } else if (get_system_load() < policy->priority_threshold && policy->priority_threshold > 0) {
