#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the Task structure
typedef struct {
    int priority;
    char* description;
    time_t timestamp;
    pthread_t thread_id;
} Task;

// Define the list of tasks
Task* tasks = NULL;
size_t task_count = 0;
size_t task_capacity = 0;

// Define the maximum length for the description string
#define MAX_DESCRIPTION_LENGTH 128

// Define the synchronization mechanism for concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Initialize the list of tasks with a default capacity
void init_tasks(size_t capacity) {
    task_capacity = capacity;
    tasks = (Task*)malloc(task_capacity * sizeof(Task));
}

// Add a new task to the list
void add_task(int priority, char* description, time_t timestamp, pthread_t thread_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the list is full and needs to be resized
    if (task_count == task_capacity) {
        task_capacity *= 2;
        tasks = (Task*)realloc(tasks, task_capacity * sizeof(Task));
    }

    // Add the new task to the list
    tasks[task_count].priority = priority;
    tasks[task_count].description = strndup(description, MAX_DESCRIPTION_LENGTH);
    tasks[task_count].timestamp = timestamp;
    tasks[task_count].thread_id = thread_id;
    task_count++;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Remove a task from the list by its index
void remove_task(size_t index) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= task_count) {
        printf("Invalid index\n");
        return;
    }

    // Remove the task from the list
    Task* task = &tasks[index];
    free(task->description);
    memmove(&tasks[index], &tasks[index + 1], (task_count - index - 1) * sizeof(Task));
    task_count--;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Update a task in the list by its index
void update_task(size_t index, int priority, char* description, time_t timestamp, pthread_t thread_id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= task_count) {
        printf("Invalid index\n");
        return;
    }

    // Update the task in the list
    Task* task = &tasks[index];
    task->priority = priority;
    strncpy(task->description, description, MAX_DESCRIPTION_LENGTH);
    task->timestamp = timestamp;
    task->thread_id = thread_id;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Get a task from the list by its index
Task* get_task(size_t index) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= task_count) {
        printf("Invalid index\n");
        return NULL;
    }

    // Get the task from the list
    Task* task = &tasks[index];

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);

    return task;
}

// Verify the integrity of the data structures after initialization
void verify_integrity() {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (task_count == 0) {
        printf("List is empty\n");
        return;
    }

    // Iterate over each task in the list and verify its integrity
    for (size_t i = 0; i < task_count; i++) {
        Task* task = &tasks[i];
        if (task->description == NULL) {
            printf("Task %zu has a null description\n", i);
        } else if (strlen(task->description) > MAX_DESCRIPTION_LENGTH) {
            printf("Task %zu has an excessively long description\n", i);
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Safely release all allocated memory
void free_tasks() {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Iterate over each task in the list and free its description
    for (size_t i = 0; i < task_count; i++) {
        Task* task = &tasks[i];
        free(task->description);
    }

    // Free the tasks array
    free(tasks);

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}
