int init_file_entries(struct file_entry** entries, int num_entries) {
    // Initialize random seed for generating random values
    srand(time(NULL));

    // Allocate memory for the arrays
    *entries = (struct file_entry*)malloc(num_entries * sizeof(struct file_entry));
    if (*entries == NULL) {
        fprintf(stderr, "Failed to allocate memory for file entries\n");
        return 0;
    }

    // Initialize the arrays with random values and unique file paths
    for (int i = 0; i < num_entries; i++) {
        (*entries)[i].float_value = ((float)rand() / RAND_MAX) * 10.0f;
        (*entries)[i].double_value = ((double)rand() / RAND_MAX) * 10.0;
        (*entries)[i].index = i;
        (*entries)[i].path = (char*)malloc(256 * sizeof(char));
        if ((*entries)[i].path == NULL) {
            fprintf(stderr, "Failed to allocate memory for file path\n");
            return 0;
        }
        snprintf((*entries)[i].path, 256, "/tmp/file_%d", i);
        (*entries)[i].exists = false;
    }

    // Check the existence of each file and update the exists flag accordingly
    for (int i = 0; i < num_entries; i++) {
        if (access((*entries)[i].path, F_OK) == 0) {
            (*entries)[i].exists = true;
        } else {
            (*entries)[i].exists = false;
        }
    }

    return num_entries;
}

void clear_old_entries(struct file_entry** entries, int num_entries) {
    // Clear the oldest entry from memory if it has been inactive for more than 10 minutes
    time_t current_time = time(NULL);
    for (int i = 0; i < num_entries; i++) {
        if ((current_time - (*entries)[i].index) > 600) {
            free((*entries)[i].path);
            (*entries)[i] = (*entries)[num_entries - 1];
            num_entries--;
        }
    }
}
