#include <condition_variable>
#include <atomic>

using namespace std;

struct transactionDetails {
    int transactionID;
    double amount;
    char* description;
};

struct record {
    int value;
};

class TransactionProcessor {
private:
    vector<transactionDetails> transactions;
    vector<char*> merchantNames;
    vector<long> offsets;
    vector<record> records;
    mutex mtx;
    condition_variable cv;
    atomic<bool> running;
    chrono::seconds cooldownPeriod = 9s;

public:
    TransactionProcessor() {
        running = true;
    }

    ~TransactionProcessor() {
        running = false;
        mtx.lock();
        cv.notify_all();
        mtx.unlock();
    }

    void processTransactions(int numThreads) {
        vector<thread> threads;
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this]() {
                while (running) {
                    mtx.lock();
                    if (!transactions.empty()) {
                        transactionDetails td = transactions.front();
                        transactions.erase(transactions.begin());
                        mtx.unlock();

                        // Process the transaction
                        processTransaction(td);
                    } else {
                        cv.wait(mtx);
                    }
                }
            });
        }

        for (auto& t : threads) {
            t.join();
        }
    }

    void addTransaction(transactionDetails td) {
        mtx.lock();
        transactions.push_back(td);
        cv.notify_all();
        mtx.unlock();
    }

    void processTransaction(transactionDetails td) {
        // Process the transaction
        cout << "Processing transaction: " << td.transactionID << endl;

        // Select an attack for the character to use with a cooldown period
        if (cooldownPeriod.count() > 0) {
            chrono::seconds remaining = cooldownPeriod - chrono::duration_cast<chrono::seconds>(chrono::steady_clock::now() - lastAttackTime);
            if (remaining.count() > 0) {
                cout << "Waiting for " << remaining.count() << " seconds before selecting an attack" << endl;
                this_thread::sleep_for(remaining);
            }
        }

        // Select a random attack from the list of available attacks
        int attackIndex = rand() % 2;
        cout << "Selected attack: " << attackIndex << endl;
    }
};
