    // Create a new node for the record
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->record = record;
    newNode->next = NULL;

    // If the linked list is empty, set the head to the new node
    if (*head == NULL) {
        *head = newNode;
    } else {
        // Find the position where the new record should be inserted
        Node *current = *head;
        while (current->next != NULL && current->record->key <= record->key) {
            current = current->next;
        }

        // Insert the new node after the current node
        newNode->next = current->next;
        current->next = newNode;
    }
}

// Function to delete a record from the linked list based on its key value.
void deleteRecord(Node **head, int key) {
    // If the linked list is empty, do nothing
    if (*head == NULL) {
        return;
    }

    // Find the node with the matching key and remove it from the linked list
    Node *current = *head;
    while (current != NULL && current->record->key != key) {
        current = current->next;
    }
    if (current != NULL) {
        Node *previous = current->prev;
        previous->next = current->next;
        free(current);
    }
}

// Function to release all allocated memory.
void freeMemory(long **offsetArray, int **keyArray, Record **records) {
    // Free the offset array
    free(*offsetArray);

    // Free the key array
    free(*keyArray);

    // Free the records array
    free(*records);
}
