void init_records(int num_keys, int min_key, int max_key) {
    // Allocate memory for the offset array
    long *offsets = (long *)malloc(num_keys * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        offsets[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the key array
    int *keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize the key array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the record array
    Record *records = (Record *)malloc(num_keys * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    // Initialize a linked list to efficiently manage the records based on their key values
    Node *head = NULL;
    for (int i = 0; i < num_keys; i++) {
        Node *node = malloc(sizeof(Node));
        if (!node) {
            printf("Error: Failed to allocate memory for linked list node\n");
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        node->record = &records[i];
        node->next = head;
        head = node;
    }
}

// Function to release all allocated memory
void cleanup_records() {
    // Release the offset array
    free(offsets);

    // Release the key array
    free(keys);

    // Release the record array
    free(records);

    // Release the linked list
    Node *node = head;
    while (node) {
        Node *next = node->next;
        free(node);
        node = next;
    }
}

// Function to insert a new record into the linked list
void insert_record(int key, long offset) {
    // Create a new node for the record
    Node *node = malloc(sizeof(Node));
    if (!node) {
        printf("Error: Failed to allocate memory for linked list node\n");
        return;
    }

    // Initialize the node with the given key and offset values
    node->record->key = key;
    node->record->offset = offset;

    // Insert the node into the linked list
    if (head == NULL) {
        head = node;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Function to delete a record from the linked list
void delete_record(int key) {
