    Node *current = head;
    while (current != NULL && current->record->key != key) {
        current = current->next;
    }

    // If the node is found, delete it from the linked list
    if (current != NULL) {
        Node *previous = current->prev;
        Node *next = current->next;
        if (previous == NULL) {
            head = next;
        } else {
            previous->next = next;
        }
        free(current);
    }
}
