#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define a custom data structure to store records
typedef struct record {
    long offset;
    int key;
    int value;
    time_t timestamp;
    int source_id;
    int status_flag;
} record_t;

// Define a hash table to map keys to records
typedef struct hash_table {
    record_t **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} hash_table_t;

// Initialize the hash table with a given capacity
void init_hash_table(hash_table_t *ht, size_t capacity) {
    ht->records = malloc(capacity * sizeof(record_t*));
    ht->capacity = capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->mutex, NULL);
}

// Insert a record into the hash table
void insert_record(hash_table_t *ht, long offset, int key, int value) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ht->mutex);

    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        // Double the capacity of the hash table
        size_t new_capacity = ht->capacity * 2;
        record_t **new_records = realloc(ht->records, new_capacity * sizeof(record_t*));
        if (new_records == NULL) {
            // Handle error: out of memory
            pthread_mutex_unlock(&ht->mutex);
            return;
        }
        ht->records = new_records;
        ht->capacity = new_capacity;
    }

    // Generate a random value for the record's 'int' field
    int random_value = rand() % 100 + 1;

    // Create a new record and insert it into the hash table
    record_t *new_record = malloc(sizeof(record_t));
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = value;
    new_record->timestamp = time(NULL);
    new_record->source_id = 0;
    new_record->status_flag = 0;
    ht->records[ht->size++] = new_record;

    // Unlock the mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Delete a record from the hash table
void delete_record(hash_table_t *ht, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record with the given key
    size_t i;
    for (i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            break;
        }
    }

    // If the record was found, delete it from the hash table
    if (i < ht->size) {
        free(ht->records[i]);
        ht->size--;
        ht->records[i] = ht->records[ht->size];
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Look up a record in the hash table by key
record_t *lookup_record(hash_table_t *ht, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record with the given key
    size_t i;
    for (i = 0; i < ht->size; i++) {
        if (ht->records[i]->key == key) {
            break;
        }
    }

    // If the record was found, return a copy of it
    if (i < ht->size) {
        record_t *record = malloc(sizeof(record_t));
        memcpy(record, ht->records[i], sizeof(record_t));
        pthread_mutex_unlock(&ht->mutex);
        return record;
    }

    // If the record was not found, return NULL
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

// Release all allocated memory for the hash table
void free_hash_table(hash_table_t *ht) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ht->mutex);

    // Free each record in the hash table
    size_t i;
    for (i = 0; i < ht->size; i++) {
        free(ht->records[i]);
    }

    // Free the array of records and the mutex
    free(ht->records);
    pthread_mutex_destroy(&ht->mutex);
}
