void addTask(Task **tasks, int *taskCount) {
    // Allocate memory for the new task
    Task *newTask = (Task *)malloc(sizeof(Task));
    if (!newTask) {
        printf("Error: unable to allocate memory for new task\n");
        return;
    }

    // Read input from user
    printf("Enter name, priority, and due date for the new task: ");
    scanf("%s %d %d", newTask->name, &newTask->priority, &newTask->due_date);

    // Add the new task to the list of tasks
    *tasks = (Task *)realloc(*tasks, (*taskCount + 1) * sizeof(Task));
    if (!*tasks) {
        printf("Error: unable to reallocate memory for task list\n");
        return;
    }
    (*tasks)[*taskCount] = *newTask;
    (*taskCount)++;
}

// Function to update a task
void updateTask(Task **tasks, int *taskCount, int index) {
    // Check if the index is valid
    if (index < 0 || index >= *taskCount) {
        printf("Error: invalid task index\n");
        return;
    }

    // Read input from user
    printf("Enter new name, priority, and due date for the task at index %d: ", index);
    scanf("%s %d %d", (*tasks)[index].name, &(*tasks)[index].priority, &(*tasks)[index].due_date);
}

// Function to remove a task
void removeTask(Task **tasks, int *taskCount, int index) {
    // Check if the index is valid
    if (index < 0 || index >= *taskCount) {
        printf("Error: invalid task index\n");
        return;
    }

    // Remove the task from the list of tasks
    for (int i = index + 1; i < *taskCount; i++) {
        (*tasks)[i - 1] = (*tasks)[i];
    }
    (*taskCount)--;
}

// Function to search for a task by name or priority
