        printf("Error: invalid task name\n");
        return;
    }

    // Search for the task by name
    for (int i = 0; i < *taskCount; i++) {
        if (strcmp((*tasks)[i].name, name) == 0) {
            printf("Task found at index %d\n", i);
            return;
        }
    }

    // Search for the task by priority
    int priority = atoi(name);
    if (priority > 0 && priority <= 10) {
        for (int i = 0; i < *taskCount; i++) {
            if ((*tasks)[i].priority == priority) {
                printf("Task found at index %d\n", i);
                return;
            }
        }
    }

    // Task not found
