class SessionManager {
public:
    // Constructor
    SessionManager();

    // Destructor
    ~SessionManager();

    // Create a new session token for the given user ID and permissions.
    std::string createSessionToken(const std::string& userId, const std::vector<std::string>& permissions);

    // Validate a session token and return the associated user ID and permissions.
    std::tuple<std::string, std::vector<std::string>> validateSessionToken(const std::string& sessionToken);

    // Update the last access time for the given session token.
    void updateLastAccessTime(const std::string& sessionToken);

    // Remove a session token from the manager.
    void removeSessionToken(const std::string& sessionToken);

private:
    // Map of session tokens to user IDs and permissions.
    std::unordered_map<std::string, std::tuple<std::string, std::vector<std::string>>> sessionTokens_;

    // Map of user IDs to last access times.
    std::unordered_map<std::string, std::chrono::time_point<std::chrono::system_clock>> lastAccessTimes_;

    // Vector of all active session tokens.
    std::vector<std::string> activeSessionTokens_;

    // Mutex for thread safety.
    std::mutex mutex_;
};

// SessionManager.cpp
#include "SessionManager.h"

SessionManager::SessionManager() {
    // Initialize the session tokens map and last access times map.
    sessionTokens_ = std::unordered_map<std::string, std::tuple<std::string, std::vector<std::string>>>();
    lastAccessTimes_ = std::unordered_map<std::string, std::chrono::time_point<std::chrono::system_clock>>();
}

SessionManager::~SessionManager() {
    // Clear the session tokens map and last access times map.
    sessionTokens_.clear();
    lastAccessTimes_.clear();
}

std::string SessionManager::createSessionToken(const std::string& userId, const std::vector<std::string>& permissions) {
    // Generate a new session token and add it to the map.
    std::string sessionToken = generateSessionToken();
    sessionTokens_[sessionToken] = std::make_tuple(userId, permissions);

    // Update the last access time for the user ID.
    updateLastAccessTime(sessionToken);

    return sessionToken;
}

std::tuple<std::string, std::vector<std::string>> SessionManager::validateSessionToken(const std::string& sessionToken) {
    // Check if the session token is valid and return the associated user ID and permissions.
    auto it = sessionTokens_.find(sessionToken);
    if (it != sessionTokens_.end()) {
        return it->second;
    } else {
        throw std::invalid_argument("Invalid session token");
    }
}

void SessionManager::updateLastAccessTime(const std::string& sessionToken) {
    // Update the last access time for the given session token.
    auto it = sessionTokens_.find(sessionToken);
    if (it != sessionTokens_.end()) {
        lastAccessTimes_[it->first] = std::chrono::system_clock::now();
    } else {
        throw std::invalid_argument("Invalid session token");
    }
}

void SessionManager::removeSessionToken(const std::string& sessionToken) {
    // Remove the given session token from the map.
    auto it = sessionTokens_.find(sessionToken);
    if (it != sessionTokens_.end()) {
        sessionTokens_.erase(it);
    } else {
        throw std::invalid_argument("Invalid session token");
    }
}

