    int type;
    int quantity;
} resource_t;

// Define the function to manage memory for a dynamically sized collection of tasks
task_t *manage_memory(int num_tasks, int min_priority, int max_priority, int scale_factor, int total_task_duration_threshold, int max_resource_quantity, int max_memory) {
    // Check if the number of tasks is within the valid range
    if (num_tasks < 1 || num_tasks > 5000) {
        printf("Invalid number of tasks: %d\n", num_tasks);
        return NULL;
    }

    // Allocate memory for an array of task structures
    task_t *tasks = malloc(num_tasks * sizeof(task_t));
    if (tasks == NULL) {
        printf("Failed to allocate memory for tasks\n");
        return NULL;
    }

    // Initialize the tasks
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].name = malloc(16);
        if (tasks[i].name == NULL) {
            printf("Failed to allocate memory for task name\n");
            return NULL;
        }
        snprintf(tasks[i].name, 16, "Task %d", i + 1);
        tasks[i].priority = rand() % (max_priority - min_priority + 1) + min_priority;
        tasks[i].duration = (i * scale_factor) % total_task_duration_threshold;
    }

    // Check for circular dependencies
    for (int i = 0; i < num_tasks; i++) {
        for (int j = 0; j < num_tasks; j++) {
            if (i == j) continue;
            if (strcmp(tasks[i].name, tasks[j].name) == 0) {
                printf("Circular dependency found: %s\n", tasks[i].name);
                return NULL;
            }
        }
    }

    // Allocate memory for an array of resource structures
    resource_t *resources = malloc(num_tasks * sizeof(resource_t));
    if (resources == NULL) {
        printf("Failed to allocate memory for resources\n");
        return NULL;
    }

    // Assign resources to tasks based on their type and quantity
    int total_resource_quantity = 0;
    for (int i = 0; i < num_tasks; i++) {
        resources[i].type = rand() % 2 + 1;
        resources[i].quantity = rand() % (max_quantity - min_quantity + 1) + min_quantity;
        total_resource_quantity += resources[i].quantity;
    }

    // Check if the total resource quantity exceeds the maximum limit
    if (total_resource_quantity > max_resource_quantity) {
        printf("Total resource quantity exceeds maximum limit: %d\n", total_resource_quantity);
        return NULL;
    }

    // Transform the task priorities using a linear function
    for (int i = 0; i < num_tasks; i++) {
        tasks[i].priority = ((tasks[i].priority * scale_factor) + offset) % max_priority;
    }

    // Check if the transformed priorities exceed the maximum value
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].priority > max_priority) {
            printf("Transformed priority exceeds maximum value: %d\n", tasks[i].priority);
            return NULL;
        }
    }

    // Return a pointer to the array of tasks
    return tasks;
}
