// Define the entry structure
typedef struct {
    char* key;
    int value;
} entry_t;

// Define the list structure
typedef struct {
    entry_t** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} list_t;

// Initialize a new list with a given capacity
list_t* list_init(size_t capacity) {
    list_t* list = malloc(sizeof(list_t));
    if (!list) {
        return NULL;
    }
    list->entries = malloc(capacity * sizeof(entry_t*));
    if (!list->entries) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new entry to the list
void list_add(list_t* list, char* key, int value) {
    // Acquire the mutex lock
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->count == list->capacity) {
        // Double the capacity of the list
        size_t new_capacity = list->capacity * 2;
        entry_t** new_entries = realloc(list->entries, new_capacity * sizeof(entry_t*));
        if (!new_entries) {
            // Reallocation failed, release the mutex lock and return
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }

    // Create a new entry
    entry_t* new_entry = malloc(sizeof(entry_t));
    if (!new_entry) {
        // Memory allocation failed, release the mutex lock and return
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Set the key and value of the new entry
    new_entry->key = strdup(key);
    new_entry->value = value;

    // Add the new entry to the list
    list->entries[list->count++] = new_entry;

    // Release the mutex lock
    pthread_mutex_unlock(&list->mutex);
}

// Update an existing entry in the list
void list_update(list_t* list, char* key, int value) {
    // Acquire the mutex lock
    pthread_mutex_lock(&list->mutex);

    // Find the index of the entry with the given key
    size_t index = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(key, list->entries[i]->key) == 0) {
            index = i;
            break;
        }
    }

    // If the entry was found, update its value
    if (index < list->count) {
        list->entries[index]->value = value;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve an entry from the list by its key
entry_t* list_get(list_t* list, char* key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&list->mutex);

    // Find the index of the entry with the given key
    size_t index = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(key, list->entries[i]->key) == 0) {
            index = i;
            break;
        }
    }

    // If the entry was found, return it
    if (index < list->count) {
        pthread_mutex_unlock(&list->mutex);
        return list->entries[index];
    }

    // Release the mutex lock and return NULL
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Remove an entry from the list by its key
void list_remove(list_t* list, char* key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&list->mutex);

    // Find the index of the entry with the given key
    size_t index = 0;
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(key, list->entries[i]->key) == 0) {
            index = i;
            break;
        }
    }

    // If the entry was found, remove it from the list
    if (index < list->count) {
        free(list->entries[index]);
        for (size_t i = index + 1; i < list->count; i++) {
            list->entries[i - 1] = list->entries[i];
        }
        list->count--;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&list->mutex);
}

// Periodically prune old entries based on a configurable expiration policy
void list_prune(list_t* list, size_t expiration) {
    // Acquire the mutex lock
    pthread_mutex_lock(&list->mutex);

    // Iterate over the list and remove entries that are older than the expiration policy
    for (size_t i = 0; i < list->count; i++) {
        if (list->entries[i]->timestamp <= time(NULL) - expiration) {
            free(list->entries[i]);
            for (size_t j = i + 1; j < list->count; j++) {
                list->entries[j - 1] = list->entries[j];
            }
            list->count--;
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&list->mutex);
}
