#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent a record with an integer key and long integer offset
typedef struct {
    int key;
    long offset;
} Record;

// Define a data structure to store the records in a hash table
typedef struct {
    int size; // number of records in the table
    int capacity; // maximum number of records that can be stored in the table
    Record* records; // array of records
} HashTable;

// Initialize a new hash table with a given capacity
HashTable* init_hash_table(int capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (table == NULL) {
        return NULL;
    }
    table->size = 0;
    table->capacity = capacity;
    table->records = calloc(capacity, sizeof(Record));
    if (table->records == NULL) {
        free(table);
        return NULL;
    }
    return table;
}

// Insert a new record into the hash table with a given key and offset
void insert_record(HashTable* table, int key, long offset) {
    // Check if the table is full
    if (table->size == table->capacity) {
        // Double the capacity of the table
        table->capacity *= 2;
        Record* new_records = realloc(table->records, table->capacity * sizeof(Record));
        if (new_records == NULL) {
            return;
        }
        table->records = new_records;
    }
    // Insert the record into the table
    table->records[table->size].key = key;
    table->records[table->size].offset = offset;
    table->size++;
}

// Look up a record in the hash table by its key
Record* lookup_record(HashTable* table, int key) {
    // Calculate the index of the record in the table
    int index = key % table->capacity;
    while (table->records[index].key != 0 && table->records[index].key != key) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    // Return the record if it exists, or NULL otherwise
    return (table->records[index].key == key) ? &table->records[index] : NULL;
}

// Free the memory allocated for the hash table
void free_hash_table(HashTable* table) {
    free(table->records);
    free(table);
}

// Example usage of the functions
int main() {
    HashTable* table = init_hash_table(10);
    insert_record(table, 1, 100);
    insert_record(table, 2, 200);
    Record* record = lookup_record(table, 1);
    if (record != NULL) {
        printf("Record found: key=%d, offset=%ld\n", record->key, record->offset);
    } else {
        printf("Record not found\n");
    }
    free_hash_table(table);
    return 0;
}
```
