// Lock for synchronizing access to the linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to insert a new task into the linked list
void insertTask(int key, long offset, time_t creation_timestamp, int priority_level) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&lock);

    // Create a new node for the task
    Node* new_node = malloc(sizeof(Node));
    new_node->task.key = key;
    new_node->task.offset = offset;
    new_node->task.creation_timestamp = creation_timestamp;
    new_node->task.priority_level = priority_level;
    new_node->task.active = true;
    new_node->task.tag = NULL;
    new_node->task.ref_count = 0;

    // Insert the node into the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&lock);
}

// Function to delete a task from the linked list
