        // Delete the node from the linked list
        Node* previous = current;
        current = current->next;
        free(previous);
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&lock);
}

// Function to lookup a task in the linked list by key
Task* lookupTask(int key) {
    // Lock the mutex before accessing the linked list
    pthread_mutex_lock(&lock);

    // Find the node corresponding to the given key
    Node* current = head;
    while (current != NULL && current->task.key != key) {
        current = current->next;
    }

    // If the node is found, return a pointer to the task structure
    if (current != NULL) {
        Task* task = &(current->task);
        pthread_mutex_unlock(&lock);
        return task;
    } else {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
}

// Function to update the priority level of a task in the linked list
void updatePriorityLevel(int key, int new_priority_level) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&lock);

    // Find the node corresponding to the given key
    Node* current = head;
    while (current != NULL && current->task.key != key) {
        current = current->next;
    }

    // If the node is found, update its priority level and unlock the mutex
    if (current != NULL) {
        Task* task = &(current->task);
        task->priority_level = new_priority_level;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}

// Function to update the status of a task in the linked list
void updateStatus(int key, bool new_status) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&lock);

    // Find the node corresponding to the given key
    Node* current = head;
    while (current != NULL && current->task.key != key) {
        current = current->next;
    }

    // If the node is found, update its status and unlock the mutex
    if (current != NULL) {
        Task* task = &(current->task);
        task->active = new_status;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}

// Function to update the tag of a task in the linked list
void updateTag(int key, char* new_tag) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&lock);

    // Find the node corresponding to the given key
    Node* current = head;
    while (current != NULL && current->task.key != key) {
        current = current->next;
    }

    // If the node is found, update its tag and unlock the mutex
    if (current != NULL) {
        Task* task = &(current->task);
        free(task->tag);
        task->tag = new_tag;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}

// Function to update the reference count of a task in the linked list
void updateRefCount(int key, int new_ref_count) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&lock);

    // Find the node corresponding to the given key
    Node* current = head;
    while (current != NULL && current->task.key != key) {
        current = current->next;
    }

    // If the node is found, update its reference count and unlock the mutex
    if (current != NULL) {
        Task* task = &(current->task);
        task->ref_count = new_ref_count;
        pthread_mutex_unlock(&lock);
    } else {
        pthread_mutex_unlock(&lock);
    }
}
