#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_RECORDS 10000
#define MIN_FLOAT_VALUE -10.0f
#define MAX_FLOAT_VALUE 10.0f
#define MIN_DOUBLE_VALUE -10.0
#define MAX_DOUBLE_VALUE 10.0
#define STRING_IDENTIFIER_LENGTH 256
#define PREDEFINED_WORDS "apple", "banana", "cherry"

typedef struct {
    long offset;
    int key;
    float precision;
    double accuracy;
    int index;
    char *string_identifier;
    bool flag;
} record;

int main(int argc, char **argv) {
    // Parse command line options
    if (argc == 1 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [OPTION]...\n", argv[0]);
        printf("Options:\n");
        printf("  -c, --count=N    Number of records to initialize (default: 10000)\n");
        printf("  -o, --output=FILE Output file name (default: stdout)\n");
        return 0;
    }

    int count = MAX_RECORDS;
    char *output_file = NULL;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            count = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            output_file = argv[++i];
        }
    }

    // Initialize data structures
    record *records = malloc(count * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for records\n");
        return 1;
    }

    // Set random values for float and double fields
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i].precision = MIN_FLOAT_VALUE + ((float) rand() / RAND_MAX) * (MAX_FLOAT_VALUE - MIN_FLOAT_VALUE);
        records[i].accuracy = MIN_DOUBLE_VALUE + ((double) rand() / RAND_MAX) * (MAX_DOUBLE_VALUE - MIN_DOUBLE_VALUE);
    }

    // Generate unique file paths for each record
    char *file_paths[count];
    for (int i = 0; i < count; ++i) {
        file_paths[i] = malloc(STRING_IDENTIFIER_LENGTH + 1);
        if (file_paths[i] == NULL) {
            fprintf(stderr, "Error: failed to allocate memory for file path\n");
            return 1;
        }
        strcpy(file_paths[i], PREDEFINED_WORDS);
    }

    // Check existence of files and set flags accordingly
    for (int i = 0; i < count; ++i) {
        records[i].flag = access(file_paths[i], F_OK) == 0;
    }

    // Write output to file or stdout
    if (output_file != NULL) {
        FILE *out = fopen(output_file, "w");
        if (out == NULL) {
            fprintf(stderr, "Error: failed to open output file\n");
            return 1;
        }
        for (int i = 0; i < count; ++i) {
            fprintf(out, "%ld %d %.2f %.3lf %s %d %s\n", records[i].offset, records[i].key, records[i].precision, records[i].accuracy, file_paths[i], records[i].index, records[i].string_identifier);
        }
        fclose(out);
    } else {
        printf("%d\n", count);
        for (int i = 0; i < count; ++i) {
            printf("%ld %d %.2f %.3lf %s %d %s\n", records[i].offset, records[i].key, records[i].precision, records[i].accuracy, file_paths[i], records[i].index, records[i].string_identifier);
        }
    }

    // Clean up memory
    for (int i = 0; i < count; ++i) {
        free(file_paths[i]);
    }
    free(records);

    return 0;
}
