    if (output_file != NULL) {
        FILE* fp = fopen(output_file, "w");
        fprintf(fp, "%d\n", num_records);
        fclose(fp);
    } else {
        printf("%d\n", num_records);
    }

    // Free the memory for the offset values, keys, records, and string identifiers
    free(offset_values);
    free(keys);
    free(records);
    free(string_identifiers);

    return 0;
}

