        record->description = generate_random_string();
        record->active = generate_random_bool();
        for (int i = 0; i < LABELS_COUNT; i++) {
            record->labels[i] = generate_random_label(LABELS_FREQ_DISTRIBUTION);
        }
    }

    // Close input file if necessary
    if (input_fd != -1) {
        close(input_fd);
    }

    // Output results to file
    FILE* output_file = fopen(OUTPUT_FILE, "w");
    if (!output_file) {
        perror("Failed to open output file");
        return 1;
    }

    for (int i = 0; i < num_records; i++) {
        Record* record = &records[i];
        fprintf(output_file, "%d %f %lf %d %s %d", record->id, record->average, record->standard_deviation, record->count, record->description, record->active);
        for (int j = 0; j < LABELS_COUNT; j++) {
            fprintf(output_file, " %s", record->labels[j]);
        }
        fprintf(output_file, "\n");
    }

    // Clean up and return
    free(records);
    fclose(output_file);
    return 0;
}

float generate_random_float() {
    return (float)rand() / RAND_MAX * (MAX_RAND_VALUE - MIN_RAND_VALUE) + MIN_RAND_VALUE;
}

double generate_random_double() {
    return (double)rand() / RAND_MAX * (MAX_RAND_VALUE - MIN_RAND_VALUE) + MIN_RAND_VALUE;
}

int generate_random_int() {
    return rand() % MAX_RAND_VALUE;
}

char* generate_random_string() {
    char* str = malloc(10 * sizeof(char));
    if (!str) {
        perror("Failed to allocate memory for string");
        return NULL;
    }

    for (int i = 0; i < 10; i++) {
        str[i] = 'a' + rand() % 26;
    }

    return str;
}

char* generate_random_label(int freq_distribution) {
    int index = rand() % LABELS_COUNT;
    if (rand() % freq_distribution == 0) {
        index = LABELS_COUNT - 1;
    }
    return labels[index];
}
