typedef struct EventCollection {
    Event** events;
    size_t capacity;
    size_t count;
} EventCollection;

// Initialize an empty event collection with a given capacity
EventCollection* init_event_collection(size_t capacity) {
    EventCollection* collection = malloc(sizeof(EventCollection));
    if (!collection) {
        return NULL;
    }
    collection->events = calloc(capacity, sizeof(Event*));
    if (!collection->events) {
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    return collection;
}

// Add a new event to the collection
bool add_event(EventCollection* collection, uint64_t timestamp, int32_t type, char* identifier) {
    if (!collection || !identifier) {
        return false;
    }
    // Check if the collection is full
    if (collection->count == collection->capacity) {
        return false;
    }
    // Create a new event and add it to the collection
    Event* event = malloc(sizeof(Event));
    if (!event) {
        return false;
    }
    event->timestamp = timestamp;
    event->type = type;
    event->identifier = strdup(identifier);
    collection->events[collection->count++] = event;
    return true;
}

// Remove events older than a specified retention period from the collection
void remove_old_events(EventCollection* collection, uint64_t retention_period) {
    if (!collection || !retention_period) {
        return;
    }
    // Iterate over the events and remove those older than the retention period
    for (size_t i = 0; i < collection->count; ++i) {
        Event* event = collection->events[i];
        if (event->timestamp <= time(NULL) - retention_period) {
            free(event->identifier);
            free(event);
            --collection->count;
            // Shift the remaining events to fill the gap
            for (size_t j = i; j < collection->count; ++j) {
                collection->events[j] = collection->events[j + 1];
            }
            --i;
        }
    }
}

// Retrieve events within a specified time range from the collection
void retrieve_events(EventCollection* collection, uint64_t start_time, uint64_t end_time) {
    if (!collection || !start_time || !end_time) {
        return;
    }
    // Iterate over the events and print those within the specified time range
    for (size_t i = 0; i < collection->count; ++i) {
        Event* event = collection->events[i];
        if (event->timestamp >= start_time && event->timestamp <= end_time) {
            printf("Event %d: timestamp=%lu, type=%d, identifier=%s\n", i, event->timestamp, event->type, event->identifier);
        }
    }
}

// Free the memory allocated for the event collection
void free_event_collection(EventCollection* collection) {
    if (!collection) {
        return;
    }
    // Iterate over the events and free their memory
    for (size_t i = 0; i < collection->count; ++i) {
        Event* event = collection->events[i];
        free(event->identifier);
        free(event);
    }
    free(collection->events);
    free(collection);
}
