    SessionManager() {}

    void addSession(int userId, std::chrono::time_point<std::chrono::system_clock> startTime) {
        std::lock_guard<std::mutex> lock(mutex);
        sessions.push_back({userId, startTime, startTime, SessionState::Active});
        sessionMap[userId] = sessions.size() - 1;
    }

    void updateLastActivity(int userId) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = sessionMap.find(userId);
        if (it != sessionMap.end()) {
            sessions[it->second].lastActivity = std::chrono::system_clock::now();
        }
    }

    void expireSessions() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = sessions.begin(); it != sessions.end();) {
            if (it->lastActivity < std::chrono::system_clock::now() - threshold) {
                it = sessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    void retrieveSessions(std::chrono::time_point<std::chrono::system_clock> startTime, std::chrono::time_point<std::chrono::system_clock> endTime) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = sessions.begin(); it != sessions.end(); ++it) {
            if (it->startTime >= startTime && it->lastActivity <= endTime) {
                // do something with the session
            }
        }
    }
};
