namespace NetworkEventManager {
    class Event {
        public:
            Event(int timestamp, int eventType, int uniqueId, std::string metadata) :
                timestamp_(timestamp), eventType_(eventType), uniqueId_(uniqueId), metadata_(metadata) {}

            int getTimestamp() const { return timestamp_; }
            int getEventType() const { return eventType_; }
            int getUniqueId() const { return uniqueId_; }
            std::string getMetadata() const { return metadata_; }

        private:
            int timestamp_;
            int eventType_;
            int uniqueId_;
            std::string metadata_;
    };

    class NetworkEventManager {
        public:
            NetworkEventManager(int retentionPeriod) : retentionPeriod_(retentionPeriod) {}

            void addEvent(const Event& event) {
                std::lock_guard<std::mutex> lock(mutex_);
                events_.push_back(event);
            }

            void removeEventsOlderThan(int timestamp) {
                std::lock_guard<std::mutex> lock(mutex_);
                auto it = std::remove_if(events_.begin(), events_.end(), [timestamp](const Event& event) {
                    return event.getTimestamp() < timestamp;
                });
                events_.erase(it, events_.end());
            }

            void retrieveEventsWithinRange(int startTime, int endTime, std::vector<Event>& events) {
                std::lock_guard<std::mutex> lock(mutex_);
                for (const auto& event : events_) {
                    if (event.getTimestamp() >= startTime && event.getTimestamp() <= endTime) {
                        events.push_back(event);
                    }
                }
            }

            void setRetentionPeriod(int retentionPeriod) {
                std::lock_guard<std::mutex> lock(mutex_);
                retentionPeriod_ = retentionPeriod;
            }

        private:
            int retentionPeriod_;
            std::vector<Event> events_;
            std::mutex mutex_;
    };

    class RandomNumberGenerator {
        public:
            RandomNumberGenerator() : mt_(std::random_device{}()) {}

            int generateRandomNumber() {
                return mt_();
            }

        private:
            std::mt19937 mt_;
    };
}
