#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <ctime>

namespace ServerCore {
    class NetworkEventManager {
        private:
            std::vector<NetworkEvent*> events;
            std::mutex eventMutex;
            std::condition_variable eventCondVar;
            std::thread prunerThread;
            std::chrono::seconds retentionPeriod;
            std::random_device rd;
            std::mt19937 gen(rd());

        public:
            NetworkEventManager(std::chrono::seconds retentionPeriod) : retentionPeriod(retentionPeriod) {
                prunerThread = std::thread([this]() {
                    while (true) {
                        std::unique_lock<std::mutex> lock(eventMutex);
                        eventCondVar.wait_for(lock, retentionPeriod);
                        if (events.size() > 0) {
                            auto it = events.begin();
                            while (it != events.end()) {
                                if ((*it)->getTimestamp() < std::chrono::steady_clock::now() - retentionPeriod) {
                                    delete *it;
                                    it = events.erase(it);
                                } else {
                                    ++it;
                                }
                            }
                        }
                    }
                });
            }

            ~NetworkEventManager() {
                prunerThread.join();
            }

            void addEvent(NetworkEvent* event) {
                std::unique_lock<std::mutex> lock(eventMutex);
                events.push_back(event);
                eventCondVar.notify_all();
            }

            void removeEventsOlderThan(std::chrono::steady_clock::time_point timestamp) {
                std::unique_lock<std::mutex> lock(eventMutex);
                auto it = events.begin();
                while (it != events.end()) {
                    if ((*it)->getTimestamp() < timestamp) {
                        delete *it;
                        it = events.erase(it);
                    } else {
                        ++it;
                    }
                }
            }

            std::vector<NetworkEvent*> getEventsWithinRange(std::chrono::steady_clock::time_point start, std::chrono::steady_clock::time_point end) {
                std::unique_lock<std::mutex> lock(eventMutex);
                auto it = events.begin();
                while (it != events.end()) {
                    if ((*it)->getTimestamp() < start || (*it)->getTimestamp() > end) {
                        delete *it;
                        it = events.erase(it);
                    } else {
                        ++it;
                    }
                }
            }

            void setRetentionPeriod(std::chrono::seconds retentionPeriod) {
                this->retentionPeriod = retentionPeriod;
            }

            std::chrono::seconds getRetentionPeriod() {
                return retentionPeriod;
            }

            static std::mt19937& getRandomNumberGenerator() {
                return gen;
            }
    };
}
