    for (int i = 0; i < length; i++) {
        string[i] = 'a' + (rand() % 26);
    }
    return string;
}

// Define a function to check if an inventory item is valid
bool isValidItem(InventoryItem *item) {
    // Check if the item identifier is unique and does not exceed maximum length constraints
    if (item->identifier < 0 || item->identifier > MAX_IDENTIFIER_LENGTH) {
        return false;
    }

    // Check if the item price is within the specified range
    if (item->price < MIN_PRICE || item->price > MAX_PRICE) {
        return false;
    }

    // Check if the item weight is within the specified range
    if (item->weight < MIN_WEIGHT || item->weight > MAX_WEIGHT) {
        return false;
    }

    // Check if the item quantity is within the specified range
    if (item->quantity < MIN_QUANTITY || item->quantity > MAX_QUANTITY) {
        return false;
    }

    // Check if the item name length is within the specified range
    if (strlen(item->name) < MIN_NAME_LENGTH || strlen(item->name) > MAX_NAME_LENGTH) {
        return false;
    }

    // Check if the item stock availability is valid
    if (!item->stock_availability) {
