#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define MAX_RECORDS 100000
#define MIN_NODES 2
#define MAX_NODES 100
#define NODE_RANGE 98
#define LABEL_LENGTH 32

typedef struct {
    long offset;
    int key;
    float precision;
    double accuracy;
    int index;
    char* string;
    bool flag;
} record;

typedef struct {
    pthread_mutex_t mutex;
    record* records[MAX_RECORDS];
    int num_records;
} collection;

void init_collection(collection* col) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        col->records[i] = NULL;
    }
    col->num_records = 0;
}

void add_record(collection* col, record* rec) {
    pthread_mutex_lock(&col->mutex);
    if (col->num_records < MAX_RECORDS) {
        col->records[col->num_records++] = rec;
    } else {
        printf("Error: maximum number of records reached\n");
    }
    pthread_mutex_unlock(&col->mutex);
}

void remove_record(collection* col, int index) {
    pthread_mutex_lock(&col->mutex);
    if (index < 0 || index >= col->num_records) {
        printf("Error: invalid record index\n");
    } else {
        free(col->records[index]);
        col->records[index] = NULL;
        col->num_records--;
    }
    pthread_mutex_unlock(&col->mutex);
}

void print_collection(collection* col) {
    for (int i = 0; i < col->num_records; i++) {
        printf("Record %d: offset=%ld, key=%d, precision=%.2f, accuracy=%.3lf, index=%d, string=%s, flag=%d\n",
               i, col->records[i]->offset, col->records[i]->key, col->records[i]->precision,
               col->records[i]->accuracy, col->records[i]->index, col->records[i]->string,
               col->records[i]->flag);
    }
}

void* thread_func(void* arg) {
    collection* col = (collection*)arg;
    while (1) {
        pthread_mutex_lock(&col->mutex);
        if (col->num_records == 0) {
            pthread_mutex_unlock(&col->mutex);
            break;
        }
        int index = rand() % col->num_records;
        record* rec = col->records[index];
        printf("Thread %d: offset=%ld, key=%d, precision=%.2f, accuracy=%.3lf, index=%d, string=%s, flag=%d\n",
               pthread_self(), rec->offset, rec->key, rec->precision, rec->accuracy, rec->index, rec->string, rec->flag);
        remove_record(col, index);
        pthread_mutex_unlock(&col->mutex);
    }
}

int main(int argc, char* argv[]) {
    collection col;
    init_collection(&col);

    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [input file]\n", argv[0]);
        return 0;
    }

    int num_nodes = MIN_NODES;
    if (argc > 2 && strcmp(argv[2], "-n") == 0) {
        num_nodes = atoi(argv[3]);
        if (num_nodes < MIN_NODES || num_nodes > MAX_NODES) {
            printf("Error: invalid number of nodes\n");
            return 1;
        }
    }

    int node_range = NODE_RANGE;
    if (argc > 2 && strcmp(argv[2], "-r") == 0) {
        node_range = atoi(argv[3]);
        if (node_range < MIN_NODES || node_range > MAX_NODES) {
            printf("Error: invalid node range\n");
            return 1;
        }
    }

    int label_length = LABEL_LENGTH;
    if (argc > 2 && strcmp(argv[2], "-l") == 0) {
        label_length = atoi(argv[3]);
        if (label_length < MIN_NODES || label_length > MAX_NODES) {
            printf("Error: invalid label length\n");
            return 1;
        }
    }

    int num_records = 0;
    char* input_file = NULL;
    if (argc == 2) {
        input_file = argv[1];
        FILE* fp = fopen(input_file, "r");
        if (!fp) {
            printf("Error: unable to open file %s\n", input_file);
            return 1;
        }
        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            record* rec = malloc(sizeof(record));
            if (!rec) {
                printf("Error: unable to allocate memory for record\n");
                return 1;
            }
            char* token = strtok(line, ",");
            while (token != NULL) {
                switch (num_records % 7) {
                    case 0:
                        rec->offset = atol(token);
                        break;
                    case 1:
                        rec->key = atoi(token);
                        break;
                    case 2:
                        rec->precision = (float)atof(token);
                        break;
                    case 3:
                        rec->accuracy = atof(token);
                        break;
                    case 4:
                        rec->index = atoi(token);
                        break;
                    case 5:
                        rec->string = strdup(token);
                        break;
                    case 6:
                        rec->flag = (bool)atoi(token);
                        break;
                }
                token = strtok(NULL, ",");
            }
            add_record(&col, rec);
            num_records++;
        }
        fclose(fp);
    } else {
        printf("No input file specified\n");
    }

    pthread_t threads[num_nodes];
    for (int i = 0; i < num_nodes; i++) {
        if (pthread_create(&threads[i], NULL, thread_func, &col) != 0) {
            printf("Error: unable to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < num_nodes; i++) {
        if (pthread_join(threads[i], NULL) != 0) {
            printf("Error: unable to join thread %d\n", i);
            return 1;
        }
    }

    if (input_file) {
        printf("Number of records read from file: %d\n", num_records);
    } else {
        print_collection(&col);
    }

    return 0;
}
