        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        sprintf(records[i].string_buffer, "%d", records[i].value);
    }

    // Allocate memory for the linked list of record pointers and populate it with random integer values within a specified range
    struct record *head = NULL;
    for (int i = 0; i < 4; i++) {
        struct record *new_record = malloc(sizeof(struct record));
        new_record->value = rand() % (max_value - min_value + 1) + min_value;
