    // Allocate memory for the transaction object list
    Transaction **transactions = malloc(sizeof(Transaction *) * 3);
    if (transactions == NULL) {
        printf("Error: Failed to allocate memory for transactions\n");
        free(timestamps);
        free(identifiers);
        return;
    }

    // Initialize the timestamp and identifier arrays with values derived from the starting index and increment pattern
    for (int i = 0; i < 3; i++) {
        timestamps[i] = starting_index + i * increment;
        identifiers[i] = malloc(1024);
        if (identifiers[i] == NULL) {
