        for (int j = 0; j < 1024; j++) {
            identifiers[i][j] = 'a' + (rand() % 26);
        }
    }

    // Initialize the reference count for each transaction object to track how many times it is referenced in the structure
    for (int i = 0; i < 3; i++) {
        transactions[i]->ref_count = 1;
    }

    // Traverse the transaction object list and recursively traverse any linked list entries, ensuring that all pointers are valid and point to initialized transactions
    for (int i = 0; i < 3; i++) {
        if (transactions[i]->next != NULL) {
            init_data_structures(starting_index + increment * i, increment, transaction_id_range);
        }
    }

    // Implement error handling to manage allocation failures gracefully
    for (int i = 0; i < 3; i++) {
        if (transactions[i] == NULL) {
            printf("Error: Failed to allocate memory for transaction %d\n", i);
            free(timestamps);
            free(identifiers);
            return;
        }
    }
}

// Define a function to traverse the transaction object list and recursively traverse any linked list entries, ensuring that all pointers are valid and point to initialized transactions
void traverse_transactions(Transaction **transactions) {
    for (int i = 0; i < 3; i++) {
        if (transactions[i]->next != NULL) {
            traverse_transactions(&transactions[i]->next);
