#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the structure to hold a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the data structure to store records
typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} RecordStore;

// Initialize a new record store with a given capacity
void initRecordStore(RecordStore* rs, size_t capacity) {
    rs->records = (Record*)malloc(capacity * sizeof(Record));
    rs->capacity = capacity;
    rs->count = 0;
    pthread_mutex_init(&rs->mutex, NULL);
}

// Insert a new record into the record store
void insertRecord(RecordStore* rs, int key, long offset) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Check if the record already exists in the store
    for (size_t i = 0; i < rs->count; i++) {
        if (rs->records[i].key == key) {
            // Update the offset of the existing record
            rs->records[i].offset = offset;
            pthread_mutex_unlock(&rs->mutex);
            return;
        }
    }

    // Check if the store is full and needs to be compacted
    if (rs->count == rs->capacity) {
        // Compact the memory by moving all records to a new buffer
        Record* new_records = (Record*)malloc(2 * rs->capacity * sizeof(Record));
        for (size_t i = 0; i < rs->count; i++) {
            new_records[i] = rs->records[i];
        }
        free(rs->records);
        rs->records = new_records;
        rs->capacity *= 2;
    }

    // Insert the new record into the store
    rs->records[rs->count].key = key;
    rs->records[rs->count].offset = offset;
    rs->count++;

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);
}

// Lookup a record in the record store by its key
Record* lookupRecord(RecordStore* rs, int key) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Search for the record in the store
    for (size_t i = 0; i < rs->count; i++) {
        if (rs->records[i].key == key) {
            Record* record = &rs->records[i];
            pthread_mutex_unlock(&rs->mutex);
            return record;
        }
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);

    // Return NULL if the record is not found
    return NULL;
}

// Delete records from the record store based on a specified range of keys
void deleteRecords(RecordStore* rs, int start_key, int end_key) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Search for the first record to be deleted
    size_t i = 0;
    while (i < rs->count && rs->records[i].key <= start_key) {
        i++;
    }

    // Delete records in batches until the end key is reached
    while (i < rs->count && rs->records[i].key <= end_key) {
        Record* record = &rs->records[i];
        free(record);
        i++;
    }

    // Update the count of records in the store
    rs->count -= i;

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);
}

// Periodically compact the memory to free up unused space and minimize fragmentation
void compactMemory(RecordStore* rs) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Check if the store needs to be compacted
    if (rs->count < rs->capacity / 2) {
        // Compact the memory by moving all records to a new buffer
        Record* new_records = (Record*)malloc(rs->count * sizeof(Record));
        for (size_t i = 0; i < rs->count; i++) {
            new_records[i] = rs->records[i];
        }
        free(rs->records);
        rs->records = new_records;
        rs->capacity = rs->count;
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);
}

// Provide statistics on memory usage and performance metrics
void getStats(RecordStore* rs, size_t* memory_usage, double* average_access_time) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Calculate the memory usage of the store
    *memory_usage = rs->capacity * sizeof(Record);

    // Calculate the average access time for the store
    *average_access_time = 0;
    for (size_t i = 0; i < rs->count; i++) {
        *average_access_time += rs->records[i].offset;
    }
    *average_access_time /= rs->count;

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);
}

// Integrate with an external database for persistent storage of records
void integrateWithDatabase(RecordStore* rs, Database* db) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&rs->mutex);

    // Iterate over all records in the store and insert them into the database
    for (size_t i = 0; i < rs->count; i++) {
        Record* record = &rs->records[i];
        dbInsert(db, record->key, record->offset);
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&rs->mutex);
}
```
This code implements a record store that can efficiently manage a large collection of records with unique integer keys and associated long integer offsets. The data structure used is a dynamic array, which allows for quick access to records by key while maintaining overall memory efficiency. The function also includes a mechanism to periodically compact the memory to free up unused space, minimizing fragmentation over time. Additionally, the function supports batch deletion of records based on a specified range of keys and provides statistics on memory usage and performance metrics. The function can integrate with an external database for persistent storage of records, and it handles potential errors during this integration process gracefully.']

