    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--help")) {
            fprintf(stderr, "Usage: %s [options] [input_file]\n", argv[0]);
            return -1;
        } else if (!strcmp(argv[i], "-c")) {
            num_records = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-o")) {
            output_file = argv[++i];
        } else if (!strcmp(argv[i], "--seed")) {
            seed = atoi(argv[++i]);
        } else {
            fprintf(stderr, "Error: Invalid option %s\n", argv[i]);
            return -1;
        }
    }

    // Initialize the data structures
    offset_map_t *offset_map = (offset_map_t *)malloc(sizeof(offset_map_t));
    record_array_t *record_array = (record_array_t *)malloc(sizeof(record_array_t));
    if (!init_data_structures(offset_map, record_array, num_records, seed)) {
        fprintf(stderr, "Error: Failed to initialize data structures\n");
        return -1;
    }

    // Read the input file line by line and print the number of lines
    if (output_file) {
        FILE *input_file = fopen(argv[argc-1], "r");
        if (!input_file) {
            fprintf(stderr, "Error: Failed to open input file %s\n", argv[argc-1]);
            return -1;
        }

        int line_count = 0;
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, input_file)) != -1) {
            line_count++;
        }

        fprintf(stderr, "Number of lines in %s: %d\n", argv[argc-1], line_count);
    }

    // Clean up the data structures and return successfully
    free(offset_map->records);
    free(record_array->records);
    free(offset_map);
    free(record_array);
    return 0;
}
