            identifiers[i][j] = 'a' + (rand() % 26);
        }
    }

    // Allocate memory for the transaction array
    Transaction* transactions = (Transaction*)malloc(sizeof(Transaction) * 4);
    assert(transactions != NULL);

    // Initialize the transaction array with random transaction IDs within a specified range
