        transactions[i].id = rand() % 1000 + 1;
        transactions[i].buffer = (char*)malloc(1025 * sizeof(char));
        assert(transactions[i].buffer != NULL);
        for (int j = 0; j < 1024; j++) {
            transactions[i].buffer[j] = 'a' + (rand() % 26);
        }
    }

    // Allocate memory for the status log
    Transaction* status_log = (Transaction*)malloc(sizeof(Transaction) * 4);
    assert(status_log != NULL);

    // Initialize the status log with detailed information about each transaction
    for (int i = 0; i < 4; i++) {
        status_log[i].id = transactions[i].id;
        status_log[i].buffer = (char*)malloc(1025 * sizeof(char));
        assert(status_log[i].buffer != NULL);
        for (int j = 0; j < 1024; j++) {
            status_log[i].buffer[j] = 'a' + (rand() % 26);
        }
    }

    // Initialize the reference count for each transaction object to track how many times it is referenced across different parts of the system
    for (int i = 0; i < 4; i++) {
        transactions[i].ref_count = 0;
    }
}

// Define the function to free memory for and deinitialize four separate data structures: timestamp, identifier, transaction, and status log.
void deinit_data_structures() {
    // Free the memory for the timestamp array
    free(timestamps);

    // Free the memory for the identifier array
    for (int i = 0; i < 4; i++) {
        free(identifiers[i]);
    }
    free(identifiers);

    // Free the memory for the transaction array
    for (int i = 0; i < 4; i++) {
        free(transactions[i].buffer);
    }
    free(transactions);

    // Free the memory for the status log
    for (int i = 0; i < 4; i++) {
        free(status_log[i].buffer);
    }
    free(status_log);
}

// Define the function to update the reference count for each transaction object.
void update_reference_count(Transaction* transaction) {
    // Increment the reference count for the given transaction object
    transaction->ref_count++;
}

// Define the function to decrement the reference count for each transaction object.
void decrement_reference_count(Transaction* transaction) {
    // Decrement the reference count for the given transaction object
    transaction->ref_count--;
