Here is an example of a C function that manages a large-scale collection of records with unique integer keys and associated long integer offsets:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define the structure for a record
typedef struct {
    int key;
    long offset;
} Record;

// Define the data structure to store records
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} RecordManager;

// Initialize a new record manager with a given capacity
void init_record_manager(RecordManager *rm, size_t capacity) {
    rm->records = (Record *)malloc(capacity * sizeof(Record));
    rm->capacity = capacity;
    rm->count = 0;
    pthread_mutex_init(&rm->mutex, NULL);
}

// Insert a new record into the record manager
void insert_record(RecordManager *rm, int key, long offset) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Check if the record already exists
    for (size_t i = 0; i < rm->count; i++) {
        if (rm->records[i].key == key) {
            // Update the offset value if it already exists
            rm->records[i].offset = offset;
            pthread_mutex_unlock(&rm->mutex);
            return;
        }
    }

    // Insert a new record if it doesn't exist
    rm->records[rm->count++] = (Record){key, offset};

    // Unlock the mutex and return
    pthread_mutex_unlock(&rm->mutex);
}

// Look up a record by its key
Record *lookup_record(RecordManager *rm, int key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Search for the record with the given key
    for (size_t i = 0; i < rm->count; i++) {
        if (rm->records[i].key == key) {
            // Return a pointer to the found record
            pthread_mutex_unlock(&rm->mutex);
            return &rm->records[i];
        }
    }

    // If no record is found, return NULL
    pthread_mutex_unlock(&rm->mutex);
    return NULL;
}

// Update the offset value for a given range of keys
void update_offsets(RecordManager *rm, int start_key, int end_key, long offset) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Iterate over the records in the given range
    for (size_t i = 0; i < rm->count; i++) {
        if (rm->records[i].key >= start_key && rm->records[i].key <= end_key) {
            // Update the offset value for each record in the range
            rm->records[i].offset = offset;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&rm->mutex);
}

// Delete records by their keys
void delete_records(RecordManager *rm, int start_key, int end_key) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Iterate over the records in the given range
    for (size_t i = 0; i < rm->count; i++) {
        if (rm->records[i].key >= start_key && rm->records[i].key <= end_key) {
            // Remove each record from the array
            memmove(&rm->records[i], &rm->records[i + 1], sizeof(Record) * (rm->count - i));
            rm->count--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&rm->mutex);
}

// Periodically compact the memory to free up unused space
void compact_memory(RecordManager *rm) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Iterate over the records and remove any that are not in use
    for (size_t i = 0; i < rm->count; i++) {
        if (!rm->records[i].in_use) {
            memmove(&rm->records[i], &rm->records[i + 1], sizeof(Record) * (rm->count - i));
            rm->count--;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&rm->mutex);
}

// Provide statistics on memory usage and performance metrics
void get_stats(RecordManager *rm, RecordStats *stats) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&rm->mutex);

    // Calculate the number of records in use
    stats->num_records = rm->count;

    // Calculate the total memory usage
    stats->total_memory = sizeof(Record) * rm->capacity;

    // Unlock the mutex and return
    pthread_mutex_unlock(&rm->mutex);
}
