```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <atomic>

// Define the structure for a record
struct Record {
    int key;
    long offset;
};

// Define the hash table to store records
struct HashTable {
    struct Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

// Define the function to initialize the hash table
void initHashTable(struct HashTable* ht) {
    // Allocate memory for the hash table
    ht->records = (struct Record*)malloc(sizeof(struct Record) * 1000);
    if (!ht->records) {
        printf("Error: failed to allocate memory for hash table\n");
        exit(1);
    }
    // Initialize the capacity and size of the hash table
    ht->capacity = 1000;
    ht->size = 0;
    // Initialize the mutex for thread-safe access to the hash table
    pthread_mutex_init(&ht->mutex, NULL);
}

// Define the function to insert a record into the hash table
void insertRecord(struct HashTable* ht, int key, long offset) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Check if the hash table needs to be resized
    if (ht->size >= ht->capacity) {
        // Resize the hash table by doubling its capacity
        ht->records = (struct Record*)realloc(ht->records, sizeof(struct Record) * 2 * ht->capacity);
        if (!ht->records) {
            printf("Error: failed to resize hash table\n");
            exit(1);
        }
        // Update the capacity and size of the hash table
        ht->capacity = 2 * ht->capacity;
    }
    // Insert the record into the hash table
    ht->records[ht->size].key = key;
    ht->records[ht->size].offset = offset;
    ht->size++;
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Define the function to lookup a record in the hash table
struct Record* lookupRecord(struct HashTable* ht, int key) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Find the index of the record with the given key in the hash table
    size_t i = 0;
    while (i < ht->size && ht->records[i].key != key) {
        i++;
    }
    // If the record is found, return it
    if (i < ht->size) {
        struct Record* r = &ht->records[i];
        pthread_mutex_unlock(&ht->mutex);
        return r;
    }
    // Otherwise, return NULL
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

// Define the function to delete a record from the hash table
void deleteRecord(struct HashTable* ht, int key) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Find the index of the record with the given key in the hash table
    size_t i = 0;
    while (i < ht->size && ht->records[i].key != key) {
        i++;
    }
    // If the record is found, delete it and update the size of the hash table
    if (i < ht->size) {
        ht->size--;
        for (size_t j = i; j < ht->size; j++) {
            ht->records[j] = ht->records[j + 1];
        }
    }
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Define the function to compact the memory of the hash table
void compactHashTable(struct HashTable* ht) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Reallocate the memory for the hash table with a smaller size
    struct Record* newRecords = (struct Record*)realloc(ht->records, sizeof(struct Record) * ht->size);
    if (!newRecords) {
        printf("Error: failed to compact hash table\n");
        exit(1);
    }
    // Update the records and capacity of the hash table
    ht->records = newRecords;
    ht->capacity = ht->size;
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Define the function to periodically compact the memory of the hash table
void periodicCompaction(struct HashTable* ht) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Check if the hash table needs to be compacted
    if (ht->size < 0.5 * ht->capacity) {
        // Compact the memory of the hash table
        compactHashTable(ht);
    }
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Define the function to handle batch deletion of records from the hash table
void deleteRecords(struct HashTable* ht, int startKey, int endKey) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Find the indices of the records with the given key range in the hash table
    size_t i = 0;
    while (i < ht->size && ht->records[i].key <= startKey) {
        i++;
    }
    size_t j = i;
    while (j < ht->size && ht->records[j].key <= endKey) {
        j++;
    }
    // If the records are found, delete them and update the size of the hash table
    if (i < j) {
        ht->size -= j - i;
        for (size_t k = i; k < j; k++) {
            ht->records[k] = ht->records[k + 1];
        }
    }
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}

// Define the function to provide statistics on memory usage and performance metrics
void getStats(struct HashTable* ht, struct Stats* stats) {
    // Lock the mutex for thread-safe access to the hash table
    pthread_mutex_lock(&ht->mutex);
    // Update the statistics with the current size of the hash table and its capacity
    stats->size = ht->size;
    stats->capacity = ht->capacity;
    // Unlock the mutex for thread-safe access to the hash table
    pthread_mutex_unlock(&ht->mutex);
}
