#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// Define the data structure for each record
struct record {
    long offset;
    int key;
    float float_field;
    double double_field;
    int index;
    char string_field[1024];
    bool flag;
};

// Define the data structure for the hash table
struct hash_table {
    struct record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t *locks;
};

// Function to create a new hash table with a given capacity
struct hash_table* create_hash_table(size_t capacity) {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    ht->records = calloc(capacity, sizeof(struct record*));
    ht->locks = calloc(capacity, sizeof(pthread_mutex_t));
    for (size_t i = 0; i < capacity; i++) {
        pthread_mutex_init(&ht->locks[i], NULL);
    }
    ht->capacity = capacity;
    ht->size = 0;
    return ht;
}

// Function to insert a new record into the hash table
void insert(struct hash_table *ht, struct record *r) {
    size_t index = r->key % ht->capacity;
    pthread_mutex_lock(&ht->locks[index]);
    if (ht->records[index] == NULL || ht->records[index]->key != r->key) {
        ht->records[index] = r;
        ht->size++;
    } else {
        free(r);
    }
    pthread_mutex_unlock(&ht->locks[index]);
}

// Function to retrieve a record from the hash table by key
struct record* get(struct hash_table *ht, int key) {
    size_t index = key % ht->capacity;
    pthread_mutex_lock(&ht->locks[index]);
    struct record *r = ht->records[index];
    if (r != NULL && r->key == key) {
        pthread_mutex_unlock(&ht->locks[index]);
        return r;
    } else {
        pthread_mutex_unlock(&ht->locks[index]);
        return NULL;
    }
}

// Function to delete a record from the hash table by key
void delete(struct hash_table *ht, int key) {
    size_t index = key % ht->capacity;
    pthread_mutex_lock(&ht->locks[index]);
    struct record *r = ht->records[index];
    if (r != NULL && r->key == key) {
        free(r);
        ht->records[index] = NULL;
        ht->size--;
    }
    pthread_mutex_unlock(&ht->locks[index]);
}

// Function to resize the hash table when it reaches a certain threshold
void resize(struct hash_table *ht) {
    size_t new_capacity = ht->capacity * 2;
    struct record **new_records = calloc(new_capacity, sizeof(struct record*));
    pthread_mutex_t *new_locks = calloc(new_capacity, sizeof(pthread_mutex_t));
    for (size_t i = 0; i < new_capacity; i++) {
        pthread_mutex_init(&new_locks[i], NULL);
    }
    for (size_t i = 0; i < ht->capacity; i++) {
        struct record *r = ht->records[i];
        if (r != NULL) {
            size_t new_index = r->key % new_capacity;
            pthread_mutex_lock(&new_locks[new_index]);
            if (new_records[new_index] == NULL || new_records[new_index]->key != r->key) {
                new_records[new_index] = r;
            } else {
                free(r);
            }
            pthread_mutex_unlock(&new_locks[new_index]);
        }
    }
    for (size_t i = 0; i < ht->capacity; i++) {
        pthread_mutex_destroy(&ht->locks[i]);
    }
    free(ht->records);
    free(ht->locks);
    ht->records = new_records;
    ht->locks = new_locks;
    ht->capacity = new_capacity;
}

// Function to dynamically allocate memory for a record
struct record* alloc_record(int key) {
    struct record *r = malloc(sizeof(struct record));
    r->key = key;
    r->offset = rand() % 1000000000;
    r->float_field = (float)(rand() % 10000) / 100.0f;
    r->double_field = (double)(rand() % 10000) / 100.0;
    r->index = rand() % 10000;
    for (size_t i = 0; i < 1024; i++) {
        r->string_field[i] = 'a' + (rand() % 26);
    }
    r->flag = rand() % 2 == 0;
    return r;
}

// Function to populate a record with random values
void populate(struct record *r) {
    r->offset = rand() % 1000000000;
    r->float_field = (float)(rand() % 10000) / 100.0f;
    r->double_field = (double)(rand() % 10000) / 100.0;
    r->index = rand() % 10000;
    for (size_t i = 0; i < 1024; i++) {
        r->string_field[i] = 'a' + (rand() % 26);
    }
    r->flag = rand() % 2 == 0;
}

// Function to handle command line options
void handle_options(int argc, char **argv) {
    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (!strcmp(argv[i], "--help")) {
                printf("Usage: %s [options]\n", argv[0]);
                printf("Options:\n");
                printf("\t-c, --capacity=<int>\tSet the capacity of the hash table\n");
                printf("\t-o, --output=<file>\tWrite output to file\n");
            } else if (!strcmp(argv[i], "-c") || !strcmp(argv[i], "--capacity")) {
                i++;
                if (i < argc) {
                    int capacity = atoi(argv[i]);
                    if (capacity > 0) {
                        struct hash_table *ht = create_hash_table(capacity);
                        printf("Created hash table with capacity %d\n", capacity);
                    } else {
                        printf("Invalid capacity: %s\n", argv[i]);
                    }
                } else {
                    printf("Missing argument for --capacity\n");
                }
            } else if (!strcmp(argv[i], "-o") || !strcmp(argv[i], "--output")) {
                i++;
                if (i < argc) {
                    FILE *f = fopen(argv[i], "w");
                    if (f != NULL) {
                        printf("Writing output to %s\n", argv[i]);
                    } else {
                        printf("Error opening file: %s\n", argv[i]);
                    }
                } else {
                    printf("Missing argument for --output\n");
                }
            } else {
                printf("Invalid option: %s\n", argv[i]);
            }
        }
    }
}

// Main function to demonstrate the use of the hash table
int main(int argc, char **argv) {
    handle_options(argc, argv);
    struct hash_table *ht = create_hash_table(1000);
    for (size_t i = 0; i < 50000; i++) {
        struct record *r = alloc_record(i);
        populate(r);
        insert(ht, r);
    }
    for (size_t i = 0; i < 50000; i++) {
        struct record *r = get(ht, i);
        if (r != NULL) {
            printf("Record found: %d\n", r->key);
        } else {
            printf("Record not found: %d\n", i);
        }
    }
    for (size_t i = 0; i < 50000; i++) {
        delete(ht, i);
    }
    free(ht->records);
    free(ht->locks);
    free(ht);
    return 0;
}
