// Define the utility class for generating random values within specified ranges
class MemoryInitializer {
private:
    int minValue;
    int maxValue;
    unsigned long seed;
public:
    MemoryInitializer(int min, int max, unsigned long seed) : minValue(min), maxValue(max), seed(seed) {}
    int GetRandomInt() {
        return rand_r(&seed) % (maxValue - minValue + 1) + minValue;
    }
    double GetRandomDouble() {
        return ((double)rand_r(&seed)) / RAND_MAX;
    }
    void GetCurrentRange(int* min, int* max) {
        *min = minValue;
        *max = maxValue;
    }
};

// Define the function to manage the large-scale collection of interconnected records
void ManageRecords(HashTable* hashTable, LockFreeAlgorithm* lockFreeAlgorithm, MemoryInitializer* memoryInitializer) {
    // Initialize the hash table and lock-free algorithm
    hashTable->size = 0;
    hashTable->capacity = 1000000;
    hashTable->keys = (int*)malloc(hashTable->capacity * sizeof(int));
    hashTable->values = (struct Record**)malloc(hashTable->capacity * sizeof(struct Record*));
    lockFreeAlgorithm->mutex = PTHREAD_MUTEX_INITIALIZER;
    lockFreeAlgorithm->cond = PTHREAD_COND_INITIALIZER;

    // Populate the hash table with random records
    for (int i = 0; i < hashTable->capacity; i++) {
