        struct Record* record = (struct Record*)malloc(sizeof(struct Record));
        record->key = key;
        record->status = status;
        record->timestamp = timestamp;
        hashTable->keys[i] = key;
        hashTable->values[i] = record;
    }

    // Support concurrent access from multiple threads
    pthread_mutex_lock(&lockFreeAlgorithm->mutex);
    while (true) {
        // Check if there are any pending operations
        if (hashTable->size == 0) {
            break;
        }

        // Perform the next operation
        int key = hashTable->keys[0];
        struct Record* record = hashTable->values[key];
        switch (record->status) {
            case 'A':
                // Insert a new record with the same key
                int newKey = memoryInitializer->GetRandomInt();
                char newStatus = 'B';
                double newTimestamp = memoryInitializer->GetRandomDouble();
                struct Record* newRecord = (struct Record*)malloc(sizeof(struct Record));
                newRecord->key = newKey;
                newRecord->status = newStatus;
                newRecord->timestamp = newTimestamp;
                hashTable->keys[newKey] = newKey;
                hashTable->values[newKey] = newRecord;
                break;
            case 'B':
                // Update the record with a new status and timestamp
                int newStatus = memoryInitializer->GetRandomInt();
                double newTimestamp = memoryInitializer->GetRandomDouble();
                record->status = newStatus;
                record->timestamp = newTimestamp;
                break;
            case 'C':
                // Delete the record with the specified key
                int deleteKey = memoryInitializer->GetRandomInt();
                hashTable->keys[deleteKey] = 0;
                free(hashTable->values[deleteKey]);
                hashTable->values[deleteKey] = NULL;
                break;
        }

        // Update the size of the hash table and resizing thresholds
        hashTable->size--;
        if (hashTable->size < hashTable->capacity / 2) {
            int newCapacity = hashTable->capacity / 2;
            int* newKeys = (int*)realloc(hashTable->keys, newCapacity * sizeof(int));
            struct Record** newValues = (struct Record**)realloc(hashTable->values, newCapacity * sizeof(struct Record*));
            hashTable->keys = newKeys;
            hashTable->values = newValues;
            hashTable->capacity = newCapacity;
        }
    }
    pthread_mutex_unlock(&lockFreeAlgorithm->mutex);
}
