#define INITIAL_SIZE 10000 // 10,000 records
#define GROWTH_FACTOR 2 // Double the size of the identifier array when it reaches 80% capacity

// Define data structures for records and identifiers
typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    int id;
    long value;
} Identifier;

// Define a hash table to store the records
static Record* records = NULL;
static size_t num_records = 0;
static size_t max_records = INITIAL_SIZE;

// Define a lock for thread-safe access to the record manager
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize the record manager
void init_record_manager() {
    records = (Record*) malloc(sizeof(Record) * max_records);
    memset(records, 0, sizeof(Record) * max_records);
}

// Define a function to insert a new record into the record manager
void insert_record(int key, long offset) {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Check if the record already exists in the hash table
    Record* existing = find_record(key);
    if (existing != NULL) {
        // Update the offset value of the existing record
        existing->offset = offset;
    } else {
        // Insert a new record into the hash table
        records[num_records].key = key;
        records[num_records].offset = offset;
        num_records++;

        // Check if the hash table needs to be resized
        if (num_records >= max_records * 0.8) {
            resize_hash_table();
        }
    }

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);
}

// Define a function to find a record in the record manager by key
Record* find_record(int key) {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Search for the record in the hash table
    Record* existing = NULL;
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            existing = &records[i];
            break;
        }
    }

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);

    return existing;
}

// Define a function to update the offset value of a record in the record manager
void update_record(int key, long offset) {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Find the record in the hash table
    Record* existing = find_record(key);
    if (existing != NULL) {
        // Update the offset value of the existing record
        existing->offset = offset;
    } else {
        // Insert a new record into the hash table
        records[num_records].key = key;
        records[num_records].offset = offset;
        num_records++;

        // Check if the hash table needs to be resized
        if (num_records >= max_records * 0.8) {
            resize_hash_table();
        }
    }

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);
}

// Define a function to delete records from the record manager by key range
void delete_records(int start_key, int end_key) {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Search for the first record in the hash table with a key greater than or equal to the start key
    size_t i = 0;
    while (i < num_records && records[i].key < start_key) {
        i++;
    }

    // Delete all records with keys between the start and end keys
    while (i < num_records && records[i].key <= end_key) {
        // Remove the record from the hash table
        memmove(&records[i], &records[i + 1], sizeof(Record) * (num_records - i));
        num_records--;
    }

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);
}

// Define a function to compact the memory usage of the record manager
void compact_memory() {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Check if the hash table needs to be resized
    if (num_records < max_records * 0.2) {
        resize_hash_table();
    }

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);
}

// Define a function to resize the hash table when it reaches 80% capacity
void resize_hash_table() {
    // Acquire the lock for thread-safe access
    pthread_mutex_lock(&lock);

    // Calculate the new size of the hash table based on the growth factor and the current number of records
    max_records = (size_t) (max_records * GROWTH_FACTOR);

    // Reallocate memory for the hash table
    Record* new_records = (Record*) realloc(records, sizeof(Record) * max_records);
    if (new_records == NULL) {
        fprintf(stderr, "Error: Failed to resize hash table\n");
        exit(1);
    }

    // Update the pointer to the hash table and the number of records
    records = new_records;
    num_records = 0;

    // Release the lock for thread-safe access
    pthread_mutex_unlock(&lock);
}
