        entry.key = key;
        entry.value = value;
        add_cache_entry(cache, &entry);
    }

    // Close the input file and return the number of successfully initialized entries
    close(fd);
    return cache->num_entries;
}

// Function to add a new key-value pair to the cache
void add_cache_entry(cache_t *cache, cache_entry_t *entry) {
    // Acquire the mutex lock and check for errors
    if (semaphore_wait(&cache->mutex) == -1) {
        perror("Error acquiring mutex lock");
        return;
    }

    // Check if the cache is full and resize it if necessary
    if (cache->num_entries >= CACHE_SIZE) {
        resize_cache(cache);
    }

    // Add the new key-value pair to the cache
    cache->entries[cache->num_entries] = *entry;
    cache->num_entries++;

    // Release the mutex lock and signal the condition variable
    if (semaphore_post(&cache->mutex) == -1) {
        perror("Error releasing mutex lock");
        return;
    }
    semaphore_signal(&cache->cond);
}

// Function to resize the cache when it is full
void resize_cache(cache_t *cache) {
    // Create a new cache with twice the size of the current one
    int new_size = 2 * CACHE_SIZE;
    cache_entry_t *new_entries = (cache_entry_t *)malloc(sizeof(cache_entry_t) * new_size);
    if (new_entries == NULL) {
        perror("Error allocating memory for new cache");
        return;
    }

    // Copy the entries from the old cache to the new one
    int i;
    for (i = 0; i < CACHE_SIZE; i++) {
        new_entries[i] = cache->entries[i];
    }

    // Update the cache with the new entries and free the old ones
    free(cache->entries);
    cache->entries = new_entries;
    cache->num_entries = new_size;
}

// Function to retrieve a value from the cache given its key
char *get_value_from_cache(cache_t *cache, char *key) {
    // Acquire the mutex lock and check for errors
    if (semaphore_wait(&cache->mutex) == -1) {
        perror("Error acquiring mutex lock");
        return NULL;
