// Define the structure for a network event
typedef struct {
    long timestamp;
    char* identifier;
    int transaction_id;
    char* details;
} NetworkEvent;

// Define the structure for a linked list of transactions
typedef struct TransactionNode {
    int id;
    char* details;
    struct TransactionNode* next;
} TransactionNode;

// Define the global reference count for each transaction object
static pthread_mutex_t ref_count_lock = PTHREAD_MUTEX_INITIALIZER;
static int* ref_counts = NULL;

// Define the function to initialize and manage the collection of network events
void init_network_events(int max_events) {
    // Allocate memory for the reference count array
    ref_counts = (int*)malloc(max_events * sizeof(int));
    if (!ref_counts) {
        printf("Error: Failed to allocate memory for reference counts\n");
        exit(1);
    }

    // Initialize the reference count array
    for (int i = 0; i < max_events; i++) {
        ref_counts[i] = 0;
    }
}

// Define the function to add a new network event
void add_network_event(long timestamp, char* identifier, int transaction_id, char* details) {
    // Lock the reference count mutex
    pthread_mutex_lock(&ref_count_lock);

    // Check if there is space for a new event
    if (ref_counts[transaction_id] >= max_events) {
        printf("Error: No space for new network event\n");
        exit(1);
    }

    // Allocate memory for the new event
    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!new_event) {
        printf("Error: Failed to allocate memory for new network event\n");
        exit(1);
    }

    // Initialize the new event
    new_event->timestamp = timestamp;
    new_event->identifier = identifier;
    new_event->transaction_id = transaction_id;
    new_event->details = details;

    // Increment the reference count for the new event
    ref_counts[transaction_id]++;

    // Unlock the reference count mutex
    pthread_mutex_unlock(&ref_count_lock);
}

// Define the function to remove network events older than a specified threshold
void remove_network_events(long threshold) {
    // Lock the reference count mutex
    pthread_mutex_lock(&ref_count_lock);

    // Iterate over the reference counts and remove events that are older than the threshold
    for (int i = 0; i < max_events; i++) {
        if (ref_counts[i] > 0 && ref_counts[i]->timestamp <= threshold) {
            NetworkEvent* event = ref_counts[i];
            free(event);
            ref_counts[i]--;
        }
    }

    // Unlock the reference count mutex
    pthread_mutex_unlock(&ref_count_lock);
}

// Define the function to retrieve network events within a given time range
void get_network_events(long start, long end) {
    // Lock the reference count mutex
    pthread_mutex_lock(&ref_count_lock);

    // Iterate over the reference counts and retrieve events that are within the specified time range
    for (int i = 0; i < max_events; i++) {
        if (ref_counts[i] > 0 && ref_counts[i]->timestamp >= start && ref_counts[i]->timestamp <= end) {
            NetworkEvent* event = ref_counts[i];
            printf("Event: %ld, %s, %d, %s\n", event->timestamp, event->identifier, event->transaction_id, event->details);
        }
    }

    // Unlock the reference count mutex
    pthread_mutex_unlock(&ref_count_lock);
}

