// Custom allocation and deallocation functions for managing memory
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Failed to allocate memory (%s)\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_dealloc(void* ptr) {
    free(ptr);
}

// Struct for storing profile data
