    int age;
    char* location;
    enum status_type status;
};

// Function to allocate memory for and initialize arrays of long, int, and struct profile_data
void allocate_memory(size_t num_profiles, size_t max_age, size_t min_age, size_t max_location_length, size_t min_location_length) {
    // Allocate memory for the offset array
    long* offsets = custom_alloc(num_profiles * sizeof(long));

    // Initialize the offset array with random values within the specified range
    for (size_t i = 0; i < num_profiles; i++) {
        offsets[i] = rand() % (max_age - min_age + 1) + min_age;
    }

    // Allocate memory for the key array
    int* keys = custom_alloc(num_profiles * sizeof(int));

    // Initialize the key array with random values within the specified range
    for (size_t i = 0; i < num_profiles; i++) {
        keys[i] = rand() % INT_MAX;
    }

    // Allocate memory for the profile data array
    struct profile_data* profiles = custom_alloc(num_profiles * sizeof(struct profile_data));

    // Initialize each profile data structure with random age values, unique profile IDs, and dynamically allocated memory for user names
    for (size_t i = 0; i < num_profiles; i++) {
        profiles[i].age = rand() % (max_age - min_age + 1) + min_age;
        profiles[i].location = custom_alloc(rand() % (max_location_length - min_location_length + 1) + min_location_length);
        for (size_t j = 0; j < strlen(profiles[i].location); j++) {
            profiles[i].location[j] = 'a' + rand() % ('z' - 'a');
        }
        profiles[i].status = rand() % NUM_STATUS_TYPES;
    }
}

// Function to deallocate memory for the arrays of long, int, and struct profile_data
void deallocate_memory(long* offsets, int* keys, struct profile_data* profiles) {
    // Deallocate memory for the offset array
    custom_dealloc(offsets);

    // Deallocate memory for the key array
    custom_dealloc(keys);

    // Deallocate memory for each profile data structure and its dynamically allocated user name
    for (size_t i = 0; i < num_profiles; i++) {
        custom_dealloc(profiles[i].location);
    }

    // Deallocate memory for the profile data array
    custom_dealloc(profiles);
}

// Function to generate a certificate in PEM format from an OAuth request
char* generate_certificate(struct oauth_request* request) {
    // Fetch the private key and certificate from the specified location
    char* private_key = fetch_private_key(request->private_key_location);
    char* certificate = fetch_certificate(request->certificate_location);

    // Combine the private key and certificate into a single PEM file
    size_t pem_length = strlen(private_key) + strlen(certificate) + 1;
    char* pem = custom_alloc(pem_length * sizeof(char));
    snprintf(pem, pem_length, "%s\n%s", private_key, certificate);

    // Deallocate memory for the fetched private key and certificate
    custom_dealloc(private_key);
    custom_dealloc(certificate);

    return pem;
}
