char* generate_random_string(int min_length, int max_length) {
    char* str = (char*)malloc((max_length - min_length + 1) * sizeof(char));
    if (str == NULL) {
        printf("Error: Failed to allocate memory for random string\n");
        return NULL;
    }

    // Generate a random string of length between min_length and max_length
    int len = rand() % (max_length - min_length + 1) + min_length;
    for (int i = 0; i < len; i++) {
        str[i] = 'a' + rand() % 26;
    }
    str[len] = '\0';

    return str;
}

// Define a function to allocate memory for a string with a given length and value
char* allocate_string(int len, char* value) {
    char* str = (char*)malloc((len + 1) * sizeof(char));
    if (str == NULL) {
        printf("Error: Failed to allocate memory for string\n");
        return NULL;
    }

    // Copy the given value into the allocated memory
    for (int i = 0; i < len; i++) {
        str[i] = value[i];
    }
    str[len] = '\0';

    return str;
}

// Define a function to deallocate memory for a string with a given length and value
void deallocate_string(int len, char* value) {
    free(value);
}
