        }
        logs[i].metadata.context.status = rand() % 10;
        logs[i].metadata.context.timestamp = (float)time(NULL);
    }

    // Free the memory for the arrays of metric values, timestamps, and tags
    free(metrics);
    free(timestamps);
    for (int i = 0; i < num_logs; i++) {
        free(tags[i]);
    }
    free(tags);

    // Free the memory for additional metadata, such as error messages and severity levels
    for (int i = 0; i < num_logs; i++) {
