} temperature_buffer;

// Function to dynamically allocate memory for and initialize the data structures
void init_data_structures(size_t num_sensors, size_t num_readings, char *device_ids[], float min_temp, float max_temp) {
    // Allocate memory for the temperature readings array
    float *temperature_readings = (float *)malloc(num_readings * sizeof(float));
    if (!temperature_readings) {
        printf("Error: Failed to allocate memory for temperature readings\n");
        return;
    }

    // Allocate memory for the timestamp array
    struct timestamp *timestamps = (struct timestamp *)malloc(num_readings * sizeof(struct timestamp));
    if (!timestamps) {
        printf("Error: Failed to allocate memory for timestamps\n");
        free(temperature_readings);
        return;
    }

    // Allocate memory for the linked list of sensor data pointers
    sensor_data **sensor_data_list = (sensor_data **)malloc(num_sensors * sizeof(sensor_data *));
    if (!sensor_data_list) {
        printf("Error: Failed to allocate memory for sensor data list\n");
        free(temperature_readings);
        free(timestamps);
        return;
    }

    // Allocate memory for the hash table mapping device IDs to sensor data
    device_hash_table *device_id_map = (device_hash_table *)malloc(num_sensors * sizeof(device_hash_table));
    if (!device_id_map) {
        printf("Error: Failed to allocate memory for device ID map\n");
        free(temperature_readings);
        free(timestamps);
        free(sensor_data_list);
        return;
    }

    // Allocate memory for the circular buffer storing temperature readings
    temperature_buffer *temp_buf = (temperature_buffer *)malloc(sizeof(temperature_buffer));
    if (!temp_buf) {
        printf("Error: Failed to allocate memory for temperature buffer\n");
        free(temperature_readings);
        free(timestamps);
        free(sensor_data_list);
        free(device_id_map);
        return;
    }

    // Initialize the temperature readings array with random values within specified ranges
    for (size_t i = 0; i < num_readings; i++) {
        temperature_readings[i] = min_temp + ((float)rand() / RAND_MAX) * (max_temp - min_temp);
    }

    // Initialize the timestamp array with current time and microseconds
    for (size_t i = 0; i < num_readings; i++) {
        timestamps[i].seconds = time(NULL);
        timestamps[i].microseconds = rand() % 1000000;
    }

    // Initialize the linked list of sensor data pointers with NULL values
    for (size_t i = 0; i < num_sensors; i++) {
        sensor_data_list[i] = NULL;
    }

    // Initialize the hash table mapping device IDs to sensor data with NULL values
    for (size_t i = 0; i < num_sensors; i++) {
        device_id_map[i].device_id = NULL;
        device_id_map[i].sensor_data = NULL;
    }

    // Initialize the circular buffer with a capacity of num_readings and head and tail indices set to 0
    temp_buf->capacity = num_readings;
    temp_buf->head = 0;
    temp_buf->tail = 0;

    // Populate the temperature readings array, timestamp array, linked list of sensor data pointers, and hash table mapping device IDs to sensor data
    for (size_t i = 0; i < num_sensors; i++) {
        // Allocate memory for the current sensor data structure
        sensor_data *current_sensor_data = (sensor_data *)malloc(sizeof(sensor_data));
        if (!current_sensor_data) {
            printf("Error: Failed to allocate memory for current sensor data\n");
            free(temperature_readings);
            free(timestamps);
            free(sensor_data_list);
            free(device_id_map);
            return;
        }

        // Set the current sensor data structure's fields
        current_sensor_data->sensor_id = i;
        current_sensor_data->temperature = temperature_readings[i];
        current_sensor_data->timestamp = timestamps[i];
        current_sensor_data->ref_count = 0;

        // Add the current sensor data structure to the linked list of sensor data pointers
        sensor_data_list[i] = current_sensor_data;

        // Add the current sensor data structure to the hash table mapping device IDs to sensor data
        device_id_map[i].device_id = strdup(device_ids[i]);
        device_id_map[i].sensor_data = current_sensor_data;
    }
