    for (int i = 0; i < num_keys; i++) {
        records[i].value = rand() % max_value + 1;
    }

    // Check if the total memory usage exceeds the limit
    int total_memory_usage = sizeof(keys) + sizeof(offsets) + sizeof(records);
    if (total_memory_usage > MAX_MEMORY_USAGE) {
        printf("Error: Total memory usage exceeds the limit\n");
        free(keys);
        free(offsets);
        free(records);
        return;
    }

