    strcpy(r->buffer, buffer);
    r->flag = flag;
    r->cache = cache;
    r->next = NULL;
    pthread_mutex_lock(&ref_count_lock);
    ref_count[r]++;
    pthread_mutex_unlock(&ref_count_lock);
    return r;
}

// Function to free a record and decrement the reference count
