// Define the cache structure
typedef struct {
    cache_entry_t **entries;
    int num_entries;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} cache_t;

// Function to initialize the cache
int init_cache(cache_t *cache) {
    // Allocate memory for the cache entries
    cache->entries = (cache_entry_t **)malloc(CACHE_SIZE * sizeof(cache_entry_t *));
    if (!cache->entries) {
        return -1;
    }

    // Initialize the mutex and semaphore for thread safety
    pthread_mutex_init(&cache->mutex, NULL);
    semaphore_init(&cache->semaphore, 0, 1);

    // Read the input file and populate the cache entries
    FILE *input = fopen(INPUT_FILE, "r");
    if (!input) {
        return -2;
    }

    char line[256];
    while (fgets(line, sizeof(line), input)) {
        // Parse the key-value pair from the line
        char *key = strtok(line, ":");
        char *value = strtok(NULL, "\n");

        // Add the key-value pair to the cache
        cache_entry_t *entry = (cache_entry_t *)malloc(sizeof(cache_entry_t));
        entry->key = key;
        entry->value = value;
        cache->entries[cache->num_entries++] = entry;
    }

    fclose(input);

    return 0;
}

// Function to add a new entry to the cache
int add_entry(cache_t *cache, char *key, char *value) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if the key already exists in the cache
    int i;
    for (i = 0; i < cache->num_entries; i++) {
        if (!strcmp(key, cache->entries[i]->key)) {
            break;
        }
    }

    // If the key already exists, update its value
    if (i < cache->num_entries) {
        free(cache->entries[i]->value);
        cache->entries[i]->value = value;
    } else {
        // Otherwise, add a new entry to the cache
        cache_entry_t *entry = (cache_entry_t *)malloc(sizeof(cache_entry_t));
        entry->key = key;
        entry->value = value;
        cache->entries[cache->num_entries++] = entry;
    }

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);

    return 0;
}

// Function to get an entry from the cache
int get_entry(cache_t *cache, char *key, char **value) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if the key exists in the cache
    int i;
    for (i = 0; i < cache->num_entries; i++) {
        if (!strcmp(key, cache->entries[i]->key)) {
            break;
        }
    }

    // If the key does not exist, return -1
    if (i == cache->num_entries) {
        *value = NULL;
        pthread_mutex_unlock(&cache->mutex);
        return -1;
    }

    // Return the value of the entry
    *value = cache->entries[i]->value;

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);

    return 0;
}

// Function to invalidate a specific entry in the cache
int invalidate_entry(cache_t *cache, char *key) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&cache->mutex);

    // Check if the key exists in the cache
    int i;
    for (i = 0; i < cache->num_entries; i++) {
        if (!strcmp(key, cache->entries[i]->key)) {
            break;
        }
    }

    // If the key does not exist, return -1
    if (i == cache->num_entries) {
        pthread_mutex_unlock(&cache->mutex);
        return -1;
    }

    // Invalidate the entry by setting its value to NULL
    free(cache->entries[i]->value);
    cache->entries[i]->value = NULL;

    // Release the mutex
    pthread_mutex_unlock(&cache->mutex);

    return 0;
}

