#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>
#include <cstdlib>
#include <ctime>

namespace ServerCore {
    class NetworkEventManager {
        private:
            std::vector<NetworkEvent> events;
            std::mutex eventMutex;
            std::condition_variable eventCondVar;
            std::thread prunerThread;
            std::atomic<bool> running;
            std::chrono::seconds retentionPeriod;
            std::random_device rd;
            std::mt19937 gen;

        public:
            NetworkEventManager(std::chrono::seconds retentionPeriod) : retentionPeriod(retentionPeriod), running(true) {
                prunerThread = std::thread([this]() { this->pruneEvents(); });
            }

            ~NetworkEventManager() {
                running = false;
                prunerThread.join();
            }

            void addEvent(const NetworkEvent& event) {
                std::lock_guard<std::mutex> lock(eventMutex);
                events.push_back(event);
                eventCondVar.notify_all();
            }

            void removeEventsOlderThan(std::chrono::seconds retentionPeriod) {
                std::lock_guard<std::mutex> lock(eventMutex);
                events.remove_if([retentionPeriod](const NetworkEvent& event) {
                    return event.getTimestamp() < (std::chrono::steady_clock::now() - retentionPeriod);
                });
            }

            std::vector<NetworkEvent> getEventsWithinRange(std::chrono::seconds startTime, std::chrono::seconds endTime) {
                std::lock_guard<std::mutex> lock(eventMutex);
                return events.filter([startTime, endTime](const NetworkEvent& event) {
                    return (event.getTimestamp() >= startTime && event.getTimestamp() <= endTime);
                });
            }

        private:
            void pruneEvents() {
                while (running) {
                    std::this_thread::sleep_for(std::chrono::seconds(1));
                    removeEventsOlderThan(retentionPeriod);
                }
            }

            std::random_device rd;
            std::mt19937 gen;
    };
}
```
This code defines a `NetworkEventManager` class within the `ServerCore` namespace that manages a collection of network events in a high-performance server application. The class uses a Mersenne Twister random number generator to produce values used in event processing logic, and ensures thread-safe operations to allow concurrent access from multiple threads without data corruption or race conditions.

The `NetworkEventManager` class has the following member functions:

* `addEvent(const NetworkEvent& event)`: Adds a new network event to the collection.
* `removeEventsOlderThan(std::chrono::seconds retentionPeriod)`: Removes events older than the specified retention period from the collection.
