    int ref_count;
} Metadata;

typedef struct {
    pthread_rwlock_t lock;
} Lock;

// Define configuration parameters
#define STARTING_INDEX 0
#define INCREMENT_PATTERN 1
#define RANDOM_VALUE_RANGE 100
#define STRING_BUFFER_METHOD "random"

// Define event handler for cleanup events
