}

// Function to dynamically allocate memory for and initialize data structures
int init_data_structures() {
    int i;
    Offset* offset_array = NULL;
    Key* key_array = NULL;
    Record** record_array = NULL;
    Metadata** metadata_array = NULL;
    Lock* lock_array = NULL;

    // Allocate memory for data structures
    offset_array = (Offset*)malloc(sizeof(Offset) * 5);
    key_array = (Key*)malloc(sizeof(Key) * 5);
    record_array = (Record**)malloc(sizeof(Record*) * 5);
    metadata_array = (Metadata**)malloc(sizeof(Metadata*) * 5);
    lock_array = (Lock*)malloc(sizeof(Lock) * 5);

    // Initialize offset and key arrays with values derived from starting index and increment pattern
    for (i = 0; i < 5; i++) {
        offset_array[i].offset = STARTING_INDEX + INCREMENT_PATTERN * i;
        key_array[i].key = STARTING_INDEX + INCREMENT_PATTERN * i;
    }

    // Initialize record array with random integer values within specified range
    for (i = 0; i < 5; i++) {
        record_array[i] = (Record*)malloc(sizeof(Record));
        record_array[i]->value = rand() % RANDOM_VALUE_RANGE + 1;
        strcpy(record_array[i]->buffer, "");
        record_array[i]->next = NULL;
        record_array[i]->ref_count = 0;
    }

    // Initialize metadata array with timestamp and pointer to corresponding record
    for (i = 0; i < 5; i++) {
        metadata_array[i] = (Metadata*)malloc(sizeof(Metadata));
        metadata_array[i]->timestamp = time(NULL);
        metadata_array[i]->record = record_array[i];
        metadata_array[i]->ref_count = 0;
    }

    // Initialize lock array with read-write locks and spinlocks
    for (i = 0; i < 5; i++) {
        pthread_rwlock_init(&lock_array[i].lock, NULL);
    }

    // Clean up unused metadata structures periodically to optimize memory usage
    for (i = 0; i < 5; i++) {
        if (metadata_array[i]->ref_count == 0) {
            free(metadata_array[i]);
            metadata_array[i] = NULL;
        }
    }

    // Handle allocation failures gracefully
    if (offset_array == NULL || key_array == NULL || record_array == NULL || metadata_array == NULL || lock_array == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Populate string buffers with random alphanumeric characters
    for (i = 0; i < 5; i++) {
        if (STRING_BUFFER_METHOD == "random") {
            srand(time(NULL));
            int j;
            for (j = 0; j < 256; j++) {
                record_array[i]->buffer[j] = rand() % 26 + 'a';
            }
        } else if (STRING_BUFFER_METHOD == "empty") {
            strcpy(record_array[i]->buffer, "");
        }
    }

    // Ensure that each record is uniquely identifiable by its key and offset combination
    for (i = 0; i < 5; i++) {
        if (key_array[i].key == offset_array[i].offset) {
            printf("Error: Key and offset values are not unique\n");
            return -1;
        }
    }

    // Handle concurrent access to shared resources using hybrid locking mechanism
    for (i = 0; i < 5; i++) {
        pthread_rwlock_wrlock(&lock_array[i].lock);
    }

    return 0;
}
