// Define the structure for an item in the cache
typedef struct Item {
    int id;
    float value;
    char* string;
} Item;

// Define the configuration structure for the cache
typedef struct CacheConfig {
    size_t numItems;
    int minId, maxId;
    float minValue, maxValue;
    size_t maxStringLength;
} CacheConfig;

// Define the cache structure
typedef struct Cache {
    Item* items;
    size_t capacity;
    size_t numItems;
    bool persisted;
} Cache;

// Initialize a new cache with the given configuration
Cache* initCache(const CacheConfig* config) {
    // Allocate memory for the cache structure
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) {
        return NULL;
    }

    // Allocate memory for the item array
    cache->items = malloc(config->numItems * sizeof(Item));
    if (!cache->items) {
        free(cache);
        return NULL;
    }

    // Initialize the cache structure
    cache->capacity = config->numItems;
    cache->numItems = 0;
    cache->persisted = false;

    // Populate each item with random values within the specified ranges and resolutions
    for (size_t i = 0; i < config->numItems; ++i) {
        Item* item = &cache->items[i];
        item->id = rand() % (config->maxId - config->minId + 1) + config->minId;
        item->value = (float)(rand() % (int)(config->maxValue - config->minValue + 1)) / RAND_MAX + config->minValue;
        item->string = malloc(config->maxStringLength * sizeof(char));
        if (!item->string) {
            free(cache);
            return NULL;
        }
        for (size_t j = 0; j < config->maxStringLength; ++j) {
            item->string[j] = rand() % ('Z' - 'A') + 'A';
        }
    }

    // Return the initialized cache structure
    return cache;
}

// Add a new item to the cache, evicting the least frequently used item if necessary
void addItem(Cache* cache, const Item* item) {
    // Check if the cache is full and needs to be resized
    if (cache->numItems == cache->capacity) {
        // Evict the least frequently used item from the cache
        size_t lfu = 0;
        for (size_t i = 1; i < cache->numItems; ++i) {
            if (cache->items[i].frequency < cache->items[lfu].frequency) {
                lfu = i;
            }
        }
        free(cache->items[lfu].string);
        --cache->numItems;
    }

    // Add the new item to the cache
    Item* newItem = &cache->items[cache->numItems];
    memcpy(newItem, item, sizeof(Item));
    ++cache->numItems;
}

// Update an existing item in the cache with a new value
void updateItem(Cache* cache, size_t index, const Item* item) {
    // Check if the index is valid
    if (index >= cache->numItems) {
        return;
    }

    // Update the item in the cache
    Item* existingItem = &cache->items[index];
    memcpy(existingItem, item, sizeof(Item));
}

// Retrieve an item from the cache by its index
const Item* getItem(Cache* cache, size_t index) {
    // Check if the index is valid
    if (index >= cache->numItems) {
        return NULL;
    }

    // Return the item at the given index
    return &cache->items[index];
}

// Persist the cache contents to disk
void persistCache(Cache* cache) {
    // Check if the cache is persisted already
    if (cache->persisted) {
        return;
    }

    // Open a file for writing and write the cache contents
    FILE* file = fopen("cache.dat", "wb");
    if (!file) {
        return;
    }
    fwrite(cache->items, sizeof(Item), cache->numItems, file);
    fclose(file);

    // Set the persisted flag to true
    cache->persisted = true;
}

// Load the cache contents from disk
void loadCache(Cache* cache) {
    // Check if the cache is already loaded
    if (cache->persisted) {
        return;
    }

    // Open a file for reading and read the cache contents
    FILE* file = fopen("cache.dat", "rb");
    if (!file) {
        return;
    }
    size_t numItems = 0;
    fread(&numItems, sizeof(size_t), 1, file);
    for (size_t i = 0; i < numItems; ++i) {
        Item* item = &cache->items[i];
        fread(item, sizeof(Item), 1, file);
    }
    cache->numItems = numItems;
    fclose(file);

    // Set the persisted flag to true
    cache->persisted = true;
}

// Free the memory allocated for the cache
void freeCache(Cache* cache) {
    // Check if the cache is already freed
    if (!cache) {
        return;
    }

    // Free the memory allocated for the item array
    for (size_t i = 0; i < cache->numItems; ++i) {
        free(cache->items[i].string);
    }
    free(cache->items);

    // Free the memory allocated for the cache structure
    free(cache);
}
