void manage_memory(struct my_struct **array, size_t *size, size_t growth_factor) {
    // Check if the array needs to be resized
    if (*size > 0 && *size <= growth_factor) {
        // Reallocate memory for the array with a new size that is a multiple of the growth factor
        struct my_struct *new_array = realloc(*array, (*size + growth_factor) * sizeof(struct my_struct));
        if (new_array == NULL) {
            // Handle error
            return;
        }
        *array = new_array;
        *size += growth_factor;
    }
