// Structure to represent each record in the dataset
typedef struct {
    int key;
    long offset;
} Record;

// Function to read and process a CSV file containing records
int read_csv(const char *filename, Record **records) {
    // Open the CSV file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    // Read the header line to determine the number of columns
    char header[256];
    if (fgets(header, sizeof(header), file) == NULL) {
        fclose(file);
        perror("Error reading CSV header");
        return -1;
    }

    // Count the number of columns in the header line
    int num_columns = 0;
    for (int i = 0; i < strlen(header); i++) {
        if (header[i] == ',') {
            num_columns++;
        }
    }

    // Allocate memory for the records array
    *records = malloc(sizeof(Record) * num_columns);
    if (*records == NULL) {
        fclose(file);
        perror("Error allocating memory for records");
        return -1;
    }

    // Read each line of the CSV file and process the records
    while (fgets(header, sizeof(header), file) != NULL) {
        char *token = strtok(header, ",");
        int i = 0;
        while (token != NULL && i < num_columns) {
            // Check if the token is a valid integer
            if (!isdigit(token[0])) {
                fclose(file);
                perror("Error reading CSV file: invalid integer");
                return -1;
            }

            // Convert the token to an integer and store it in the record
            (*records)[i].key = atoi(token);

            // Check if the offset is valid
            if (strlen(token) > 0 && token[strlen(token) - 1] == 'L') {
                fclose(file);
                perror("Error reading CSV file: invalid offset");
                return -1;
            }

            // Convert the token to a long integer and store it in the record
            (*records)[i].offset = atol(token);

            i++;
            token = strtok(NULL, ",");
        }
    }

    fclose(file);
    return 0;
}
