// Define a function to add a new contributor and revision to the linked list for each version
void add_to_list(document_version_t *version, char *contributor, char *revision) {
    // Create a new node for the contributor and revision
    node_t *new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) {
        printf("Error: Failed to allocate memory for a new node\n");
        return;
    }

    // Set the contributor and revision for the new node
    new_node->contributor = contributor;
    new_node->revision = revision;

    // Add the new node to the end of the linked list
    if (!version->contributors) {
        version->contributors = new_node;
    } else {
        node_t *current_node = version->contributors;
        while (current_node->next) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }

    // Add the new node to the end of the linked list for the revision history
    if (!version->revision_history) {
        version->revision_history = new_node;
    } else {
        node_t *current_node = version->revision_history;
        while (current_node->next) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }
