// Define a function to remove a contributor and revision from the linked list for each version
void remove_from_list(document_version_t *version, char *contributor, char *revision) {
    // Find the node containing the contributor and revision in the linked list
    node_t *current_node = version->contributors;
    while (current_node && strcmp(current_node->contributor, contributor)) {
        current_node = current_node->next;
    }

    // Remove the node from the linked list if it is found
    if (current_node) {
