// Define a function to handle concurrent access from multiple threads, ensuring thread safety and preventing data races
void manage_memory(document_version_t *versions, int num_versions) {
    // Create a mutex for the version map
    pthread_mutex_t version_map_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Create a mutex for each linked list in the version map
