    pthread_mutex_t revisions_mutex[num_versions];

    // Initialize the mutexes for the linked lists
    for (int i = 0; i < num_versions; i++) {
        pthread_mutex_init(&contributors_mutex[i], NULL);
        pthread_mutex_init(&revisions_mutex[i], NULL);
    }

    // Create a thread for each version to manage its memory allocation and access
