// Structure to represent a record in the dataset
typedef struct Record {
    int key;
    long offset;
} Record;

// Function to manage memory allocation and initialization for a dynamic dataset
void init_dataset(const char* filename, int segment_size, int parallelism) {
    // Open the CSV file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Initialize the dataset with an initial size of 1024 records
    int num_records = 1024;
    Record* dataset = (Record*)malloc(num_records * sizeof(Record));
    if (dataset == NULL) {
        printf("Error: unable to allocate memory for the dataset\n");
        fclose(fp);
        return;
    }

    // Read the CSV file and populate the dataset
    while (!feof(fp)) {
        int key, offset;
        if (fscanf(fp, "%d,%ld", &key, &offset) != 2) {
            printf("Error: invalid data format in file %s\n", filename);
            fclose(fp);
            free(dataset);
            return;
        }

        // Check if the key is already present in the dataset
        int i = 0;
        for (i = 0; i < num_records; i++) {
            if (dataset[i].key == key) {
                break;
            }
        }

        // If the key is not present, add it to the dataset
        if (i == num_records) {
            if (num_records == 1024) {
                // Double the size of the dataset if it reaches its maximum capacity
                Record* new_dataset = (Record*)realloc(dataset, 2 * num_records * sizeof(Record));
                if (new_dataset == NULL) {
                    printf("Error: unable to allocate memory for the dataset\n");
                    fclose(fp);
                    free(dataset);
                    return;
                }
                dataset = new_dataset;
            }
            dataset[num_records].key = key;
            dataset[num_records].offset = offset;
            num_records++;
        } else {
            // If the key is already present, update its offset value if necessary
            if (dataset[i].offset != offset) {
                dataset[i].offset = offset;
            }
        }
    }

    // Close the CSV file
    fclose(fp);

    // Partition the dataset into segments of size segment_size
    int num_segments = (num_records + segment_size - 1) / segment_size;
    Record** segments = (Record**)malloc(num_segments * sizeof(Record*));
    if (segments == NULL) {
        printf("Error: unable to allocate memory for the segments\n");
        free(dataset);
        return;
    }

    // Initialize each segment with a distinct range of keys
    int i = 0;
    while (i < num_records) {
        int j = i + segment_size;
        if (j > num_records) {
            j = num_records;
        }
        segments[i] = &dataset[i];
        i = j;
    }

    // Validate and initialize each segment independently
    for (int i = 0; i < num_segments; i++) {
        Record* segment = segments[i];
        int num_records = segment->key - dataset[0].key + 1;
        long offset = segment->offset;
        for (int j = 0; j < num_records; j++) {
            if (dataset[j].key != segment->key) {
                printf("Error: invalid data in segment %d\n", i);
                free(segments);
                return;
            }
            dataset[j].offset = offset;
            offset += dataset[j].offset;
        }
    }

    // Free the original dataset and return the segments
    free(dataset);
    return segments;
}
