struct record* allocate_record_array(int size) {
    struct record* arr = (struct record*)malloc(size * sizeof(struct record));
    if (!arr) {
        printf("Error: Failed to allocate memory for record array\n");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        arr[i].value = rand() % 1000;
    }
    return arr;
}

// Function to start and stop a simulated service with a random delay between starts
void simulate_service(long* offset_arr, int* key_arr, struct record* rec_arr) {
    // Set the initial state of the service
    bool running = false;
    long current_offset = 0;
    int current_key = 0;
    struct record current_rec = {0};

    while (true) {
        // Generate a random delay between starts
        int delay = rand() % 10 + 1;
        sleep(delay);

        // Check if the service is running and update it accordingly
        if (!running) {
            current_offset = offset_arr[rand() % size];
            current_key = key_arr[rand() % size];
            current_rec.value = rec_arr[rand() % size].value;
            running = true;
        } else {
            running = false;
        }

        // Send a message to the messaging system to notify of the event
        printf("Service stopped with offset: %ld, key: %d, and value: %d\n", current_offset, current_key, current_rec.value);
    }
}

int main() {
    // Set the size of the arrays
    int size = 10;

    // Allocate and initialize the offset array
    long* offset_arr = allocate_offset_array(size);
    if (!offset_arr) {
        return 1;
    }

    // Allocate and initialize the key array
    int* key_arr = allocate_key_array(size);
    if (!key_arr) {
        free(offset_arr);
        return 1;
    }

    // Allocate and initialize the record array
    struct record* rec_arr = allocate_record_array(size);
    if (!rec_arr) {
        free(offset_arr);
        free(key_arr);
        return 1;
    }

    // Start and stop the simulated service with a random delay between starts
    simulate_service(offset_arr, key_arr, rec_arr);

    // Deallocate the memory for the arrays
    free(offset_arr);
    free(key_arr);
    free(rec_arr);

    return 0;
}
