// Custom data structure to store image metadata
typedef struct {
    char *file_path;
    int width;
    int height;
    int resolution;
    char *format;
} ImageMetadata;

// Function to load and transform image metadata from a JSON file
ImageMetadata* load_metadata(const char *json_file) {
    // Allocate memory for the custom data structure
    ImageMetadata *metadata = malloc(sizeof(ImageMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for metadata\n");
        return NULL;
    }

    // Load JSON file and parse its contents
    json_object *root = json_object_from_file(json_file);
    if (root == NULL) {
        fprintf(stderr, "Error: failed to load JSON file\n");
        free(metadata);
        return NULL;
    }

    // Extract image metadata from the JSON object
    json_object *image = json_object_get_object(root, "image");
    if (image == NULL) {
        fprintf(stderr, "Error: failed to extract image metadata\n");
        json_object_put(root);
        free(metadata);
        return NULL;
    }

    // Get file path and convert it to a standardized format
    const char *file_path = json_object_get_string(json_object_get_object(image, "file_path"));
    if (file_path == NULL) {
        fprintf(stderr, "Error: failed to get file path\n");
        json_object_put(root);
        free(metadata);
        return NULL;
    }
    metadata->file_path = malloc(strlen(file_path) + 1);
    if (metadata->file_path == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for file path\n");
        json_object_put(root);
        free(metadata);
        return NULL;
    }
    strcpy(metadata->file_path, file_path);

    // Get image width and height
    metadata->width = json_object_get_int(json_object_get_object(image, "width"));
    metadata->height = json_object_get_int(json_object_get_object(image, "height"));

    // Get image resolution
    metadata->resolution = json_object_get_int(json_object_get_object(image, "resolution"));

    // Get image format
    const char *format = json_object_get_string(json_object_get_object(image, "format"));
    if (format == NULL) {
        fprintf(stderr, "Error: failed to get image format\n");
        json_object_put(root);
        free(metadata->file_path);
        free(metadata);
        return NULL;
    }
    metadata->format = malloc(strlen(format) + 1);
    if (metadata->format == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for image format\n");
        json_object_put(root);
        free(metadata->file_path);
        free(metadata);
        return NULL;
    }
    strcpy(metadata->format, format);

    // Clean up JSON object and return metadata structure
    json_object_put(root);
    return metadata;
}
