    manager->pool = pool;
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->entries = (struct LogEntry**)malloc(maxEntries * sizeof(struct LogEntry*));
    manager->numEntries = 0;
    manager->maxEntries = maxEntries;
    manager->priorityThreshold = 0;
}

// Add a new log entry to the log manager, allocating memory for it using the custom memory pool allocator
void addLogEntry(struct LogManager* manager, time_t timestamp, int logLevel, const char* message) {
    struct LogEntry* entry = (struct LogEntry*)malloc(sizeof(struct LogEntry));
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    strcpy(entry->message, message);

    pthread_mutex_lock(&manager->mutex);
    if (manager->numEntries < manager->maxEntries) {
        manager->entries[manager->numEntries++] = entry;
    } else {
        // If the log pool is full, allocate a new memory block and add the entry to it
        struct MemoryPool* newPool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
        newPool->buffer = malloc(manager->pool->size * 2);
        newPool->size = manager->pool->size * 2;
        memcpy(newPool->buffer, manager->pool->buffer, manager->pool->size);
        free(manager->pool->buffer);
        manager->pool = newPool;
        manager->entries[manager->numEntries++] = entry;
    }
    pthread_mutex_unlock(&manager->mutex);
}

// Retrieve a log entry from the log manager, based on its timestamp and priority level
struct LogEntry* getLogEntry(struct LogManager* manager, time_t timestamp, int priorityLevel) {
    struct LogEntry* entry = NULL;
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->numEntries; i++) {
        if (manager->entries[i]->timestamp == timestamp && manager->entries[i]->logLevel >= priorityLevel) {
            entry = manager->entries[i];
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
    return entry;
}

// Release the memory allocated for a log entry, and remove it from the log manager
void releaseLogEntry(struct LogManager* manager, struct LogEntry* entry) {
    free(entry);
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->numEntries; i++) {
        if (manager->entries[i] == entry) {
            memmove(&manager->entries[i], &manager->entries[i + 1], sizeof(struct LogEntry*) * (manager->numEntries - i - 1));
            manager->numEntries--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

