#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent a user profile
struct UserProfile {
    char* identifier;
    char* email;
    int subscriptionStatus;
    time_t lastLoginTimestamp;
};

// Define a hash table to store the unique user identifiers
typedef struct HashTable {
    struct UserProfile** buckets;
    size_t bucketCount;
} HashTable;

// Initialize a new hash table with a given number of buckets
HashTable* initHashTable(size_t bucketCount) {
    HashTable* table = malloc(sizeof(HashTable));
    table->buckets = calloc(bucketCount, sizeof(struct UserProfile*));
    table->bucketCount = bucketCount;
    return table;
}

// Add a new user profile to the hash table
void addUserProfile(HashTable* table, struct UserProfile* profile) {
    size_t index = hashCode(profile->identifier);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = malloc(sizeof(struct UserProfile));
        memcpy(table->buckets[index], profile, sizeof(struct UserProfile));
    } else {
        // Handle duplicate user identifiers gracefully
        struct UserProfile* existingProfile = table->buckets[index];
        if (strcmp(existingProfile->identifier, profile->identifier) == 0) {
            free(profile);
        } else {
            // Update the existing profile with the new data
            existingProfile->subscriptionStatus = profile->subscriptionStatus;
            existingProfile->lastLoginTimestamp = profile->lastLoginTimestamp;
            free(profile);
        }
    }
}

// Hash function to map user identifiers to buckets
size_t hashCode(const char* identifier) {
    size_t hash = 0;
    for (int i = 0; i < strlen(identifier); i++) {
        hash = hash * 31 + identifier[i];
    }
    return hash % table->bucketCount;
}

// Free the memory allocated to the hash table
void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->bucketCount; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]);
        }
    }
    free(table);
}

// Load and transform user profile data from a structured log file into a custom data structure
void loadUserProfiles(const char* filename, HashTable* table) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
