    fclose(file);
}

// Parse a single user profile from a log line and perform necessary transformations
struct UserProfile* parseUserProfile(const char* line) {
    struct UserProfile* profile = malloc(sizeof(struct UserProfile));
    // Extract the user identifier, email address, subscription status, and last login timestamp
    const char* delimiter = ",";
    char* token = strtok(line, delimiter);
    if (token != NULL) {
        profile->identifier = strdup(token);
    } else {
        free(profile);
        return NULL;
    }
    token = strtok(NULL, delimiter);
    if (token != NULL) {
        profile->email = normalizeEmailAddress(strdup(token));
    } else {
        free(profile);
        return NULL;
    }
    token = strtok(NULL, delimiter);
    if (token != NULL) {
        profile->subscriptionStatus = atoi(token);
    } else {
        free(profile);
        return NULL;
    }
    token = strtok(NULL, delimiter);
    if (token != NULL) {
        profile->lastLoginTimestamp = parseTimeStamp(strdup(token));
    } else {
        free(profile);
        return NULL;
    }
    // Perform any necessary transformations on the user profile data
    normalizeUserProfile(profile);
    return profile;
}

// Normalize an email address to a standardized format
char* normalizeEmailAddress(const char* email) {
    char* normalized = strdup(email);
    // Remove any leading or trailing whitespace characters
    trimWhitespace(normalized);
    // Convert all letters to lowercase
    for (int i = 0; i < strlen(normalized); i++) {
        normalized[i] = tolower(normalized[i]);
    }
    return normalized;
}

// Parse a time stamp string and convert it to a Unix timestamp
time_t parseTimeStamp(const char* timestamp) {
    struct tm tm;
    strptime(timestamp, "%Y-%m-%d %H:%M:%S", &tm);
    return mktime(&tm);
}

