import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class EventManager {
    private static final AtomicLong eventIdCounter = new AtomicLong(0);
    private static final ConcurrentHashMap<Long, Event> events = new ConcurrentHashMap<>();

    public static void createEvent(String title, ZonedDateTime dateTime, String location, int ticketAvailability, Set<String> tags) {
        long eventId = eventIdCounter.incrementAndGet();
        Event event = new Event(eventId, title, dateTime, location, ticketAvailability, tags);
        events.put(eventId, event);
    }

    public static void updateEvent(long eventId, String title, ZonedDateTime dateTime, String location, int ticketAvailability, Set<String> tags) {
        Event event = events.get(eventId);
        if (event != null) {
            event.setTitle(title);
            event.setDateTime(dateTime);
            event.setLocation(location);
            event.setTicketAvailability(ticketAvailability);
            event.setTags(tags);
        }
    }

    public static void deleteEvent(long eventId) {
        events.remove(eventId);
    }

    public static Event getEvent(long eventId) {
        return events.get(eventId);
    }

    public static Set<Long> getAllEventIds() {
        return events.keySet();
    }

    public static void notifyAdministrators(int threshold) {
        for (Event event : events.values()) {
            if (event.getTicketAvailability() < threshold) {
                // Notify administrators through email or other means
            }
        }
    }

    public static void garbageCollectEvents() {
        Set<Long> inactiveEventIds = new HashSet<>();
        for (Event event : events.values()) {
            if (event.getTicketAvailability() == 0) {
                inactiveEventIds.add(event.getId());
            }
        }
        for (Long eventId : inactiveEventIds) {
            events.remove(eventId);
        }
    }

    public static void exportEvents(String format, String filePath) {
        // Export events to CSV or JSON file
    }

