    int startingID;
    int incrementValue;
    double minPerformanceMetric;
    double maxPerformanceMetric;
    float minTemperatureReading;
    float maxTemperatureReading;
};

// Define a cache for frequently accessed transaction IDs
struct lruCache {
    int capacity;
    struct transactionDetails* transactions[];
};

// Define a lock for synchronizing access to the data structures
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define a semaphore for controlling concurrent access to the cache
semaphore_t cacheSemaphore = SEMAPHORE_INITIALIZER;

// Define a method for deallocating all allocated memory when the function is done
