    // Deallocate memory for transaction details array
    free(transactionDetails);

    // Deallocate memory for merchant record array
    free(merchantRecord);

    // Deallocate memory for combined record array
    free(combinedRecord);

    // Deallocate memory for error message structure
    free(errorMessage);
}

// Define a method for initializing the data structures
void initializeDataStructures(struct configOptions* options) {
    // Initialize transaction details array with random performance metrics and temperature readings within specified ranges
    transactionDetails = (struct transactionDetails*) malloc(sizeof(struct transactionDetails) * options->numTransactionTypes);
    for (int i = 0; i < options->numTransactionTypes; i++) {
        transactionDetails[i].transactionID = options->startingID + i * options->incrementValue;
        transactionDetails[i].amount = rand() % (options->maxPerformanceMetric - options->minPerformanceMetric) + options->minPerformanceMetric;
        transactionDetails[i].description = "Transaction Type";
    }

    // Initialize merchant record array with random names within specified ranges
    merchantRecord = (struct merchantRecord*) malloc(sizeof(struct merchantRecord) * options->numSensorIdentifiers);
    for (int i = 0; i < options->numSensorIdentifiers; i++) {
        merchantRecord[i].name = "Merchant Name";
    }

    // Initialize combined record array with random performance metrics, temperature readings, transaction types, and sensor identifiers within specified ranges
    combinedRecord = (struct combinedRecord*) malloc(sizeof(struct combinedRecord) * options->numTransactionTypes);
    for (int i = 0; i < options->numTransactionTypes; i++) {
        combinedRecord[i].transactionID = transactionDetails[i].transactionID;
        combinedRecord[i].performanceMetric = rand() % (options->maxPerformanceMetric - options->minPerformanceMetric) + options->minPerformanceMetric;
        combinedRecord[i].temperatureReading = rand() % (options->maxTemperatureReading - options->minTemperatureReading) + options->minTemperatureReading;
        combinedRecord[i].transactionType = transactionDetails[i].description[0];
        combinedRecord[i].sensorIdentifier = merchantRecord[i % options->numSensorIdentifiers].name[0];
    }

    // Initialize error message structure with a default message
    errorMessage = (struct errorMessage*) malloc(sizeof(struct errorMessage));
    errorMessage->message = "No errors detected";
}

// Define a method for managing system resources and monitoring performance
void manageResources() {
    // Monitor CPU usage and adjust memory allocation accordingly
    if (cpuUsage > 80) {
        // Increase memory allocation by 25%
        transactionDetails = realloc(transactionDetails, sizeof(struct transactionDetails) * (options->numTransactionTypes + options->numTransactionTypes / 4));
        merchantRecord = realloc(merchantRecord, sizeof(struct merchantRecord) * (options->numSensorIdentifiers + options->numSensorIdentifiers / 4));
        combinedRecord = realloc(combinedRecord, sizeof(struct combinedRecord) * (options->numTransactionTypes + options->numTransactionTypes / 4));
    } else if (cpuUsage < 50) {
        // Decrease memory allocation by 25%
        transactionDetails = realloc(transactionDetails, sizeof(struct transactionDetails) * (options->numTransactionTypes - options->numTransactionTypes / 4));
        merchantRecord = realloc(merchantRecord, sizeof(struct merchantRecord) * (options->numSensorIdentifiers - options->numSensorIdentifiers / 4));
        combinedRecord = realloc(combinedRecord, sizeof(struct combinedRecord) * (options->numTransactionTypes - options->numTransactionTypes / 4));
    }
}

// Define a method for detecting and responding to memory pressure
void handleMemoryPressure() {
    // Check if there is any memory pressure
    if (memoryUsage > 80) {
        // Deallocate unused memory
        transactionDetails = realloc(transactionDetails, sizeof(struct transactionDetails) * options->numTransactionTypes);
        merchantRecord = realloc(merchantRecord, sizeof(struct merchantRecord) * options->numSensorIdentifiers);
        combinedRecord = realloc(combinedRecord, sizeof(struct combinedRecord) * options->numTransactionTypes);
    }
}

// Define a method for caching frequently accessed transaction IDs
void cacheTransactions() {
    // Acquire lock on cache semaphore
    pthread_mutex_lock(&cacheSemaphore);

    // Check if the cache is full
    if (lruCache.capacity == lruCache.size) {
        // Evict least recently used transaction ID from cache
        int evictedTransactionID = lruCache.transactions[0].transactionID;
        for (int i = 1; i < lruCache.size; i++) {
            if (lruCache.transactions[i].transactionID == evictedTransactionID) {
                memmove(&lruCache.transactions[i], &lruCache.transactions[i + 1], sizeof(struct transactionDetails) * (lruCache.size - i));
            }
        }
    } else {
        // Add new transaction ID to cache
        lruCache.transactions[lruCache.size].transactionID = transactionDetails[0].transactionID;
        lruCache.size++;
    }

    // Release lock on cache semaphore
    pthread_mutex_unlock(&cacheSemaphore);
}

// Define a method for dealing with invalid inputs and providing clear error messages
void handleInvalidInputs() {
    // Check if any transaction types or sensor identifiers exceed the available lists
    if (transactionDetails[0].description[0] > 'Z' || merchantRecord[0].name[0] > 'Z') {
        // Set error message to "Invalid input: transaction type or sensor identifier exceeds available list"
        errorMessage->message = "Invalid input: transaction type or sensor identifier exceeds available list";
    } else {
        // Set error message to "No errors detected"
        errorMessage->message = "No errors detected";
    }
}

