// Define a struct to represent a record in the hash table
struct Record {
    char* identifier;
    float score;
    time_t timestamp;
};

// Define a struct to represent the hash table
struct HashTable {
    int num_buckets;
    int num_records;
    struct Record** buckets;
};

// Function to initialize the hash table with a user-specified number of buckets
struct HashTable* init_hash_table(int num_buckets) {
    // Check if the input number of buckets is valid
    if (num_buckets < 16 || num_buckets > 4096) {
        return NULL;
    }

    // Allocate memory for the hash table struct and its buckets array
    struct HashTable* table = malloc(sizeof(struct HashTable));
    if (!table) {
        return NULL;
    }
    table->buckets = calloc(num_buckets, sizeof(struct Record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    // Initialize the number of records and buckets in the hash table
    table->num_records = 0;
    table->num_buckets = num_buckets;

    // Return a pointer to the initialized hash table
    return table;
}

// Function to insert a new record into the hash table
void insert_record(struct HashTable* table, char* identifier, float score) {
    // Check if the input identifier is valid
    if (!identifier || !score) {
        return;
    }

    // Calculate the hash value for the identifier
    int hash = hash_function(identifier);

    // Find an empty bucket in the hash table to store the record
    struct Record* record = NULL;
    while (record == NULL && hash < table->num_buckets) {
        if (table->buckets[hash] == NULL || table->buckets[hash]->identifier == NULL) {
            record = malloc(sizeof(struct Record));
            if (!record) {
                return;
            }
            record->identifier = strdup(identifier);
            record->score = score;
            record->timestamp = time(NULL);
            table->buckets[hash] = record;
        } else {
            hash++;
        }
    }

    // If no empty bucket was found, resize the hash table and retry inserting the record
    if (record == NULL) {
        int new_num_buckets = table->num_buckets * 2;
        struct HashTable* new_table = realloc(table, sizeof(struct HashTable) + new_num_buckets * sizeof(struct Record*));
        if (!new_table) {
            return;
        }
        table = new_table;
        table->num_buckets = new_num_buckets;
        insert_record(table, identifier, score);
    }
}

// Function to retrieve a record from the hash table by its identifier
struct Record* get_record(struct HashTable* table, char* identifier) {
    // Check if the input identifier is valid
    if (!identifier) {
        return NULL;
    }

    // Calculate the hash value for the identifier
    int hash = hash_function(identifier);

    // Search for the record in the hash table
    while (hash < table->num_buckets && table->buckets[hash] != NULL) {
        if (strcmp(table->buckets[hash]->identifier, identifier) == 0) {
            return table->buckets[hash];
        }
        hash++;
    }

    // If the record was not found, return NULL
    return NULL;
}

// Function to update a record in the hash table by its identifier
void update_record(struct HashTable* table, char* identifier, float score) {
    // Check if the input identifier is valid
    if (!identifier || !score) {
        return;
    }

    // Calculate the hash value for the identifier
    int hash = hash_function(identifier);

    // Search for the record in the hash table
    while (hash < table->num_buckets && table->buckets[hash] != NULL) {
        if (strcmp(table->buckets[hash]->identifier, identifier) == 0) {
            table->buckets[hash]->score = score;
            table->buckets[hash]->timestamp = time(NULL);
            return;
        }
        hash++;
    }
}

// Function to delete a record from the hash table by its identifier
void delete_record(struct HashTable* table, char* identifier) {
    // Check if the input identifier is valid
    if (!identifier) {
        return;
    }

    // Calculate the hash value for the identifier
    int hash = hash_function(identifier);

    // Search for the record in the hash table
    while (hash < table->num_buckets && table->buckets[hash] != NULL) {
        if (strcmp(table->buckets[hash]->identifier, identifier) == 0) {
            free(table->buckets[hash]);
            table->buckets[hash] = NULL;
            return;
        }
        hash++;
    }
}

// Function to destroy the hash table and release all memory allocated for it
void destroy_hash_table(struct HashTable* table) {
    // Check if the input pointer is valid
    if (!table) {
        return;
    }

    // Free the memory allocated for the buckets array
    free(table->buckets);

    // Free the memory allocated for the hash table struct itself
    free(table);
}
