    // Implement support for manual and automatic triggering of garbage collection based on configurable thresholds
    if (coll->total_size > 0.8 * coll->capacity) {
        // Trigger garbage collection to free up unused memory
        size_t num_records = coll->num_records;
        for (size_t i = 0; i < num_records; ++i) {
            if (coll->records[i] == NULL) {
                // Remove the record from the collection
                coll->offsets[i] = coll->keys[i] = 0;
                coll->records[i] = NULL;
                --coll->num_records;
            }
        }
    }

    // Implement support for logging system events, such as memory allocation, deallocation, and garbage collection
    if (coll->total_size > 0.8 * coll->capacity) {
