        record_t *record = coll->records[i];
        fwrite(&record->value, sizeof(int), 1, file);
    }
}

// Define the function to deserialize the collection state from disk for persistence across sessions
void deserialize_collection(collection_t *coll, FILE *file) {
    // Deserialize the offsets array
