#include <sys/socket.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

class NetworkCommunicationHandler {
public:
    NetworkCommunicationHandler(const std::string& protocol, const std::string& address, int port) :
        _protocol(protocol), _address(address), _port(port) {}

    ~NetworkCommunicationHandler() {
        close(_socket);
    }

    void start() {
        // Create a socket
        if ((_socket = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
            std::cerr << "Error creating socket: " << strerror(errno) << std::endl;
            return;
        }

        // Set up the address structure
        struct sockaddr_in server_address;
        memset(&server_address, 0, sizeof(server_address));
        server_address.sin_family = AF_INET;
        server_address.sin_port = htons(_port);
        if (inet_pton(AF_INET, _address.c_str(), &server_address.sin_addr) <= 0) {
            std::cerr << "Error setting up address: " << strerror(errno) << std::endl;
            return;
        }

        // Connect to the server
        if (connect(_socket, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
            std::cerr << "Error connecting to server: " << strerror(errno) << std::endl;
            return;
        }

        // Set up the SSL context
        _ssl_context = SSL_CTX_new(TLSv1_2_client_method());
        if (_ssl_context == NULL) {
            std::cerr << "Error creating SSL context: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return;
        }

        // Set up the SSL object
        _ssl = SSL_new(_ssl_context);
        if (_ssl == NULL) {
            std::cerr << "Error creating SSL object: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return;
        }

        // Set up the SSL connection
        if (SSL_set_fd(_ssl, _socket) < 0) {
            std::cerr << "Error setting up SSL connection: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return;
        }

        // Connect to the server using SSL
        if (SSL_connect(_ssl) < 0) {
            std::cerr << "Error connecting to server using SSL: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
            return;
        }
    }

    void stop() {
        // Close the socket
        close(_socket);

        // Free the SSL object and context
        SSL_free(_ssl);
        SSL_CTX_free(_ssl_context);
    }

    void send(const std::string& data) {
        // Send the data over the SSL connection
        if (SSL_write(_ssl, data.c_str(), data.size()) < 0) {
            std::cerr << "Error sending data: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
        }
    }

    void receive() {
        // Receive the data over the SSL connection
        char buffer[1024];
        int bytes_received = SSL_read(_ssl, buffer, sizeof(buffer));
        if (bytes_received < 0) {
            std::cerr << "Error receiving data: " << ERR_error_string(ERR_get_error(), NULL) << std::endl;
        } else {
            // Print the received data
            std::cout << buffer << std::endl;
        }
    }

private:
    int _socket = -1;
    SSL* _ssl = nullptr;
    SSL_CTX* _ssl_context = nullptr;
    std::string _protocol;
    std::string _address;
    int _port;
};
