use std::time;
use std::process::Command;
use std::sync::{Arc, Mutex};
use rustc_driver::catch_with_exit_code;
use early_error;
use log::{info, warn};

struct CompilationResult {
    exit_code: i32,
    duration: u128,
    resident_set_size: usize,
}

fn compile(target_triple: &str) -> Result<CompilationResult, String> {
    let start = time::Instant::now();
    let mut process = Command::new("rustc")
        .arg("--target-triple")
        .arg(target_triple)
        .spawn()?;
    let resident_set_size_before = get_resident_set_size(&process)?;
    let exit_code = process.wait()?;
    let duration = start.elapsed().as_millis();
    let resident_set_size_after = get_resident_set_size(&process)?;
    if resident_set_size_before > RESIDENT_SET_SIZE_MAX {
        warn!("Resident set size exceeded maximum threshold");
    }
    Ok(CompilationResult {
        exit_code,
        duration,
        resident_set_size: resident_set_size_after - resident_set_size_before,
    })
}

fn get_resident_set_size(process: &Process) -> Result<usize, String> {
    process.try_wait()?;
    let mut resident_set_size = 0;
    for status in process.status().unwrap() {
        if let Some(status) = status {
            resident_set_size += status.resident_set_size();
        }
    }
    Ok(resident_set_size)
}

fn log_compilation_result(result: &CompilationResult) {
    info!(
        "Compilation result: exit code {}, duration {} ms, resident set size {}",
        result.exit_code,
        result.duration,
        result.resident_set_size
    );
}

fn main() {
    let target_triple = "x86_64-unknown-linux-gnu";
    let result = compile(target_triple).unwrap();
    log_compilation_result(&result);
}
