    size_t usage_limit;
    size_t warning_threshold;
};

struct notification_settings {
    bool send_email;
    bool send_sms;
};

// Define function to initialize storage system
int init_storage(size_t initial_array_size) {
    // Allocate memory for arrays of structs
    struct file_metadata* metadata = malloc(initial_array_size * sizeof(struct file_metadata));
    struct directory_entry* directories = malloc(initial_array_size * sizeof(struct directory_entry));
    struct volume_info* volumes = malloc(initial_array_size * sizeof(struct volume_info));
    struct file_access_log* access_logs = malloc(initial_array_size * sizeof(struct file_access_log));
    struct backup_schedule* backups = malloc(initial_array_size * sizeof(struct backup_schedule));
    struct quota_policy* policies = malloc(initial_array_size * sizeof(struct quota_policy));
    struct notification_settings* notifications = malloc(initial_array_size * sizeof(struct notification_settings));

    // Initialize arrays with default values
    for (int i = 0; i < initial_array_size; i++) {
        metadata[i].creation_time = time(NULL);
        metadata[i].modification_time = time(NULL);
        metadata[i].access_count = 0;

        directories[i].name = NULL;
        directories[i].size = 0;
        directories[i].files = NULL;
        directories[i].num_files = 0;
        pthread_mutex_init(&directories[i].lock, NULL);

        volumes[i].name = NULL;
        volumes[i].capacity = 0;
        volumes[i].used_space = 0;
        volumes[i].directories = NULL;
        volumes[i].num_directories = 0;
        volumes[i].last_backup = time(NULL);
        policies[i].usage_limit = 0;
        policies[i].warning_threshold = 0;

        access_logs[i].access_time = time(NULL);
        access_logs[i].is_read = false;

        backups[i].interval = 0;
        backups[i].frequency = 0;

        notifications[i].send_email = false;
        notifications[i].send_sms = false;
    }

    // Return number of successfully initialized entries
    return initial_array_size;
}

// Define function to add a new file entry
int add_file(struct volume_info* volume, const char* path) {
    // Check if file exists and is not already in the array
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            if (strcmp(dir->files[j].name, path) == 0) {
                return -1; // File already exists
            }
        }
    }

    // Allocate memory for new file entry and initialize it
    struct file_entry* file = malloc(sizeof(struct file_entry));
    file->name = strdup(path);
    file->metadata.creation_time = time(NULL);
    file->metadata.modification_time = time(NULL);
    file->metadata.access_count = 0;

    // Add new file entry to the array of files in the volume
    struct directory_entry* dir = &volume->directories[volume->num_directories - 1];
    dir->files = realloc(dir->files, (dir->num_files + 1) * sizeof(struct file_entry));
    dir->files[dir->num_files++] = file;

    // Return success
    return 0;
}

// Define function to remove a file entry
int remove_file(struct volume_info* volume, const char* path) {
    // Find the file entry in the array of files in the volume
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            if (strcmp(dir->files[j].name, path) == 0) {
                // Remove the file entry from the array of files in the volume
                struct file_entry* file = &dir->files[j];
                free(file->name);
                free(file);
                dir->num_files--;
                dir->files = realloc(dir->files, dir->num_files * sizeof(struct file_entry));

                // Return success
                return 0;
            }
        }
    }

    // File not found
    return -1;
}

// Define function to update the metadata of a file entry
int update_file_metadata(struct volume_info* volume, const char* path) {
    // Find the file entry in the array of files in the volume
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            if (strcmp(dir->files[j].name, path) == 0) {
                // Update the metadata of the file entry
                struct file_entry* file = &dir->files[j];
                file->metadata.modification_time = time(NULL);
                file->metadata.access_count++;

                // Return success
                return 0;
            }
        }
    }

    // File not found
    return -1;
}

// Define function to get the current storage usage status
int get_storage_usage(struct volume_info* volume) {
    int used_space = 0;
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            used_space += dir->files[j].metadata.size;
        }
    }
    return used_space;
}

// Define function to get a report on compliance with quota policies
int get_quota_report(struct volume_info* volume) {
    int usage = get_storage_usage(volume);
    if (usage > volume->policy.usage_limit) {
        return -1; // Quota exceeded
    } else {
        return 0; // Quota not exceeded
    }
}

// Define function to periodically clear old entries from memory
void clear_old_entries(struct volume_info* volume) {
    // Check if the oldest entry is older than the warning threshold
    struct file_entry* oldest = NULL;
    time_t oldest_time = 0;
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            if (!oldest || oldest->metadata.creation_time > dir->files[j].metadata.creation_time) {
                oldest = &dir->files[j];
                oldest_time = oldest->metadata.creation_time;
            }
        }
    }
    if (oldest && oldest_time < time(NULL) - volume->policy.warning_threshold) {
        // Remove the oldest entry from memory
        struct file_entry* file = oldest;
        free(file->name);
        free(file);
        dir->num_files--;
        dir->files = realloc(dir->files, dir->num_files * sizeof(struct file_entry));
    }
}

// Define function to monitor storage usage and enforce policies
void monitor_storage(struct volume_info* volume) {
    // Check if the current usage is above the warning threshold
    int usage = get_storage_usage(volume);
    if (usage > volume->policy.warning_threshold) {
        // Send notifications to configured recipients
        for (int i = 0; i < volume->num_directories; i++) {
            struct directory_entry* dir = &volume->directories[i];
            for (int j = 0; j < dir->num_files; j++) {
                if (dir->files[j].metadata.access_count > volume->policy.warning_threshold) {
                    // Send notification to configured recipients
                    printf("Notification sent: Storage usage above warning threshold\n");
                }
            }
        }
    }
}

// Define function to trigger backups according to schedules
void backup(struct volume_info* volume) {
    // Check if the current time is within the backup interval
    time_t now = time(NULL);
    for (int i = 0; i < volume->num_directories; i++) {
        struct directory_entry* dir = &volume->directories[i];
        for (int j = 0; j < dir->num_files; j++) {
            if (now % dir->files[j].metadata.backup_schedule.interval == 0) {
                // Trigger backup of the file entry
                printf("Backup triggered: File entry '%s' in directory '%s'\n", dir->files[j].name, dir->name);
            }
        }
    }
}
