// Define the function to manage the records
void manage_records(record_t **records, int num_records) {
    // Initialize the dynamic memory pool
    struct mempool *mempool = malloc(sizeof(struct mempool));
    mempool->size = 0;
    mempool->data = NULL;

    // Allocate memory for the record arrays
    records[0] = malloc(num_records * sizeof(long));
    records[1] = malloc(num_records * sizeof(int));
    records[2] = malloc(num_records * sizeof(record_t));

    // Initialize the record values with random values within specified ranges
    for (int i = 0; i < num_records; i++) {
        records[0][i] = rand() % 1000;
        records[1][i] = rand() % 1000;
        records[2][i].key = rand() % 1000;
        records[2][i].offset = rand() % 1000;
    }

    // Define the lock for concurrent access
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Define the function to update the record values
    void update_record(int index, int key, long offset) {
        // Acquire the lock
        pthread_mutex_lock(&lock);

        // Update the record value
        records[0][index] = offset;
        records[1][index] = key;
        records[2][index].key = key;
        records[2][index].offset = offset;

        // Release the lock
