    void garbage_collection() {
        // Calculate the total size of the allocated memory
        mempool->size = (records[0] + records[1] + records[2]) * sizeof(record_t);

        // Free up unused memory
        for (int i = 0; i < num_records; i++) {
            if (records[i] == NULL) {
                free(records[i]);
            }
        }
    }

    // Define the function to handle unexpected growth in the number of records by reallocating memory as needed
    void reallocate_memory() {
        // Reallocate memory for the record arrays
        records[0] = realloc(records[0], num_records * sizeof(long));
        records[1] = realloc(records[1], num_records * sizeof(int));
