};

// Function to allocate memory for a new record
struct Record* allocRecord(size_t dataSize) {
    struct Record* record = malloc(sizeof(struct Record));
    if (record == NULL) {
        return NULL;
    }
    record->data = malloc(dataSize);
    if (record->data == NULL) {
        free(record);
        return NULL;
    }
    record->dataSize = dataSize;
    return record;
}

