    struct Record** records = malloc(numRecords * sizeof(struct Record*));
    if (records == NULL) {
        return NULL;
    }
    for (int i = 0; i < numRecords; i++) {
        records[i] = allocRecord(dataSize);
        if (records[i] == NULL) {
