    if (chunk != NULL) {
        for (int i = 0; i < pool->numChunks; i++) {
            if (pool->chunks[i] == chunk) {
                free(pool->chunks[i]);
                pool->chunks[i] = NULL;
                break;
            }
        }
    }
}

