// Lock-free algorithm for concurrent access to the tree
void* tree_get(struct Tree* tree, void* key) {
    // Implement fine-grained locking and atomic operations as needed
    struct Node* node = tree->root;
    while (node != NULL && !key_equal(node->data, key)) {
        node = node->next;
    }
    return node ? node->data : NULL;
}

void* tree_put(struct Tree* tree, void* data) {
