    struct Node* node = malloc(sizeof(struct Node));
    node->data = data;
    node->next = tree->root;
    tree->root = node;
}

void* tree_delete(struct Tree* tree, void* key) {
    // Implement fine-grained locking and atomic operations as needed
    struct Node* node = tree->root;
    while (node != NULL && !key_equal(node->data, key)) {
        node = node->next;
    }
    if (node == NULL) return NULL;
    struct Node* next = node->next;
    free(node);
    tree->root = next;
}

