// C++ class for managing a dynamic set of geometric shapes in a performance-critical graphics application
class ShapeManager {
public:
    // Constructor initializes arrays for shape coordinates, types, and structures
    ShapeManager() : m_coords(nullptr), m_types(nullptr), m_shapes(nullptr) {}

    // Destructor frees memory allocated by the class
    ~ShapeManager() {
        delete[] m_coords;
        delete[] m_types;
        delete[] m_shapes;
    }

    // Adds a new shape to the manager, returning its index
    int addShape(const float* coords, const int type) {
        // Reallocate memory if necessary to accommodate the new shape
        if (m_numShapes == m_capacity) {
            reallocate();
        }

        // Initialize the new shape's attributes and add it to the arrays
        m_coords[m_numShapes] = coords;
        m_types[m_numShapes] = type;
        m_shapes[m_numShapes].color = rand() % 256;
        m_shapes[m_numShapes].textureIndex = rand() % 10;
        return m_numShapes++;
    }

    // Updates the attributes of a shape in the manager
    void updateShape(int index, const float* coords, const int type) {
        // Check if the index is valid and the shape exists
        if (index < 0 || index >= m_numShapes) {
            return;
        }

        // Update the shape's attributes
        m_coords[index] = coords;
        m_types[index] = type;
    }

    // Removes a shape from the manager, returning its index
    int removeShape(int index) {
        // Check if the index is valid and the shape exists
        if (index < 0 || index >= m_numShapes) {
            return -1;
        }

        // Shift all shapes after the removed one to fill the gap
        for (int i = index + 1; i < m_numShapes; ++i) {
            m_coords[i - 1] = m_coords[i];
            m_types[i - 1] = m_types[i];
            m_shapes[i - 1] = m_shapes[i];
        }

        // Decrement the number of shapes and reallocate memory if necessary
        --m_numShapes;
        if (m_numShapes < m_capacity / 4) {
            reallocate();
        }

        return index;
    }

    // Returns the total size of allocated memory in bytes
    int getMemoryUsage() const {
        return m_capacity * sizeof(float) + m_numShapes * sizeof(int) + m_numShapes * sizeof(Shape);
    }

private:
    // Reallocates memory for the arrays to accommodate new shapes
    void reallocate() {
        int newCapacity = m_capacity == 0 ? 1 : m_capacity * 2;
        float* newCoords = new float[newCapacity];
        int* newTypes = new int[newCapacity];
        Shape* newShapes = new Shape[newCapacity];

        // Copy the existing shapes to the new arrays
        for (int i = 0; i < m_numShapes; ++i) {
            newCoords[i] = m_coords[i];
            newTypes[i] = m_types[i];
            newShapes[i] = m_shapes[i];
        }

        // Free the old arrays and assign the new ones
        delete[] m_coords;
        delete[] m_types;
        delete[] m_shapes;
        m_coords = newCoords;
        m_types = newTypes;
        m_shapes = newShapes;
        m_capacity = newCapacity;
    }

    // Arrays for shape coordinates, types, and structures
    float* m_coords;
    int* m_types;
    Shape* m_shapes;

    // Number of shapes in the manager and its capacity
    int m_numShapes = 0;
    int m_capacity = 0;
};

// Struct for shape attributes
struct Shape {
    int color;
    int textureIndex;
};

// Function to generate random values within specified ranges
int rand(int min, int max) {
    return min + (rand() % (max - min + 1));
}"]

