#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <limits.h>

// Define the record structure
typedef struct {
    int key;
    char *value;
} record_t;

// Define the hash table data structure
typedef struct {
    int size;
    int count;
    record_t **records;
} hash_table_t;

// Function to dynamically allocate memory for an array of long values
long *allocate_long_array(int size) {
    long *arr = malloc(size * sizeof(long));
    if (arr == NULL) {
        perror("Failed to allocate memory for long array");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Function to dynamically allocate memory for an array of int values
int *allocate_int_array(int size) {
    int *arr = malloc(size * sizeof(int));
    if (arr == NULL) {
        perror("Failed to allocate memory for int array");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Function to dynamically allocate memory for an array of record structures
record_t **allocate_record_array(int size) {
    record_t **arr = malloc(size * sizeof(record_t*));
    if (arr == NULL) {
        perror("Failed to allocate memory for record array");
        exit(EXIT_FAILURE);
    }
    return arr;
}

// Function to dynamically allocate memory for a hash table
hash_table_t *allocate_hash_table(int size) {
    hash_table_t *ht = malloc(sizeof(hash_table_t));
    if (ht == NULL) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    ht->size = size;
    ht->count = 0;
    ht->records = malloc(size * sizeof(record_t*));
    if (ht->records == NULL) {
        perror("Failed to allocate memory for hash table records");
        exit(EXIT_FAILURE);
    }
    return ht;
}

// Function to initialize a record structure with a random integer and a null-terminated string
void init_record(record_t *rec, int min, int max) {
    rec->key = rand() % (max - min + 1) + min;
    char str[256];
    for (int i = 0; i < 256; i++) {
        str[i] = 'a' + (rand() % 26);
    }
    str[255] = '\0';
    rec->value = strdup(str);
}

// Function to insert a record into the hash table
void insert_record(hash_table_t *ht, int key, record_t *rec) {
    if (ht->count == ht->size) {
        // Resize the hash table if it is full
        resize_hash_table(ht);
    }
    ht->records[key] = rec;
    ht->count++;
}

// Function to delete a record from the hash table
void delete_record(hash_table_t *ht, int key) {
    if (ht->count == 0) {
        // Do nothing if the hash table is empty
        return;
    }
    ht->records[key] = NULL;
    ht->count--;
}

// Function to lookup a record in the hash table
record_t *lookup_record(hash_table_t *ht, int key) {
    if (ht->count == 0) {
        // Return NULL if the hash table is empty
        return NULL;
    }
    return ht->records[key];
}

// Function to resize the hash table
void resize_hash_table(hash_table_t *ht) {
    int new_size = ht->size * 2;
    record_t **new_records = allocate_record_array(new_size);
    for (int i = 0; i < ht->size; i++) {
        if (ht->records[i] != NULL) {
            new_records[i] = ht->records[i];
        }
    }
    free(ht->records);
    ht->records = new_records;
    ht->size = new_size;
}

// Function to free the memory allocated for a hash table
void free_hash_table(hash_table_t *ht) {
    if (ht == NULL) {
        return;
    }
    for (int i = 0; i < ht->size; i++) {
        if (ht->records[i] != NULL) {
            free(ht->records[i]->value);
            free(ht->records[i]);
        }
    }
    free(ht->records);
    free(ht);
}

// Function to free the memory allocated for an array of long values
void free_long_array(long *arr) {
    if (arr == NULL) {
        return;
    }
    free(arr);
}

// Function to free the memory allocated for an array of int values
void free_int_array(int *arr) {
    if (arr == NULL) {
        return;
    }
    free(arr);
}

// Function to free the memory allocated for an array of record structures
void free_record_array(record_t **arr) {
    if (arr == NULL) {
        return;
    }
    for (int i = 0; i < ht->size; i++) {
        if (ht->records[i] != NULL) {
            free(ht->records[i]->value);
            free(ht->records[i]);
        }
    }
    free(arr);
}

// Function to handle errors and exceptions gracefully
void error_handler(int err, char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Main function that demonstrates the use of the hash table
int main() {
    // Define the size of the hash table and the number of records to be processed
    int size = 100;
    int num_records = 1000000;

    // Allocate memory for the hash table and initialize it
    hash_table_t *ht = allocate_hash_table(size);

    // Allocate memory for the arrays of long, int, and record structures
    long *offset_arr = allocate_long_array(num_records);
    int *key_arr = allocate_int_array(num_records);
    record_t **record_arr = allocate_record_array(num_records);

    // Initialize the arrays with random values and insert them into the hash table
    for (int i = 0; i < num_records; i++) {
        init_record(&record_arr[i], 1, 1000000);
        offset_arr[i] = rand() % 1000000;
        key_arr[i] = rand() % 1000000;
        insert_record(ht, key_arr[i], record_arr[i]);
    }

    // Process the records in parallel using asynchronous data processing
    pthread_t threads[num_records];
    for (int i = 0; i < num_records; i++) {
        pthread_create(&threads[i], NULL, process_record, &record_arr[i]);
    }

    // Wait for all threads to complete and free the memory allocated for the hash table and arrays
    for (int i = 0; i < num_records; i++) {
        pthread_join(threads[i], NULL);
    }
    free_hash_table(ht);
    free_long_array(offset_arr);
    free_int_array(key_arr);
    free_record_array(record_arr);

    return 0;
}

// Function to process a record in parallel using asynchronous data processing
void *process_record(void *arg) {
    // Get the record structure from the argument
    record_t *rec = (record_t *) arg;

    // Do some computation on the record
    printf("Processing record with key %d and value %s\n", rec->key, rec->value);

    // Free the memory allocated for the record structure
    free(rec->value);
    free(rec);

    return NULL;
