// Define a struct for the node in the binary tree
struct Node {
    double value;
    char* string;
    struct Node* left;
    struct Node* right;
};

// Define a struct for the data structure that stores the nodes
struct DataStructure {
    int size_limit;
    int num_nodes;
    struct Node** nodes;
};

// Function to dynamically allocate memory for the data structures
void allocate_memory(int size_limit, struct DataStructure* ds) {
    // Allocate memory for the array of pointers to nodes
    ds->nodes = (struct Node**)malloc(size_limit * sizeof(struct Node*));
    if (!ds->nodes) {
        printf("Error: Failed to allocate memory for nodes\n");
        exit(1);
    }

    // Initialize the array of pointers to NULL
    memset(ds->nodes, 0, size_limit * sizeof(struct Node*));
}

// Function to dynamically allocate memory for a new node
void allocate_node(double value, char* string, struct DataStructure* ds) {
    // Allocate memory for the new node
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new node\n");
        exit(1);
    }

    // Initialize the fields of the new node
    new_node->value = value;
    new_node->string = string;
    new_node->left = NULL;
    new_node->right = NULL;

    // Add the new node to the array of pointers in the data structure
    ds->nodes[ds->num_nodes++] = new_node;
}

// Function to insert a new node into the binary tree based on the value of the double field
void insert_node(double value, struct DataStructure* ds) {
    // Find the index where the new node should be inserted
    int index = 0;
    while (index < ds->num_nodes && ds->nodes[index]->value <= value) {
        index++;
    }

    // Allocate memory for the new node and initialize its fields
    allocate_node(value, NULL, ds);
    struct Node* new_node = ds->nodes[ds->num_nodes - 1];

    // Insert the new node into the binary tree
    if (index == 0) {
        // The new node is the smallest value in the tree
        new_node->left = NULL;
        new_node->right = ds->nodes[index];
        ds->nodes[index]->left = new_node;
    } else if (index == ds->num_nodes) {
        // The new node is the largest value in the tree
        new_node->right = NULL;
        new_node->left = ds->nodes[index - 1];
        ds->nodes[index - 1]->right = new_node;
    } else {
        // The new node is between two existing nodes in the tree
        struct Node* left_node = ds->nodes[index - 1];
        struct Node* right_node = ds->nodes[index];
        new_node->left = left_node;
        new_node->right = right_node;
        left_node->right = new_node;
        right_node->left = new_node;
    }
}

// Function to traverse the binary tree in order
void traverse_tree(struct DataStructure* ds) {
    // Iterate through the array of pointers in the data structure
    for (int i = 0; i < ds->num_nodes; i++) {
