        // Print the value and string fields of each node
        printf("Value: %f, String: %s\n", node->value, node->string);

        // Recursively traverse the left and right subtrees
        if (node->left) {
            traverse_tree(ds, node->left);
        }
        if (node->right) {
            traverse_tree(ds, node->right);
        }
    }
}

// Function to handle duplicate values by storing additional metadata in the nodes
void handle_duplicates(struct DataStructure* ds) {
    // Iterate through the array of pointers in the data structure
    for (int i = 0; i < ds->num_nodes; i++) {
        struct Node* node = ds->nodes[i];

        // Check if there are any duplicate values in the tree
        int duplicate_index = -1;
        for (int j = i + 1; j < ds->num_nodes; j++) {
            if (node->value == ds->nodes[j]->value) {
                duplicate_index = j;
                break;
            }
        }

        // If there are duplicates, store additional metadata in the nodes
        if (duplicate_index != -1) {
            struct Node* duplicate_node = ds->nodes[duplicate_index];
            node->left = duplicate_node;
            duplicate_node->right = node;
        }
    }
}

// Function to efficiently insert new nodes into the binary tree based on the value of the double field
void efficient_insert(double value, struct DataStructure* ds) {
    // Lock the data structure to prevent concurrent modifications
    pthread_mutex_lock(&ds->mutex);

