void init_gui(int num_widgets, int num_events) {
    // Allocate memory for the widget array
    Widget *widgets = malloc(num_widgets * sizeof(Widget));
    if (!widgets) {
        printf("Error: Failed to allocate memory for widgets\n");
        return;
    }

    // Initialize the offset and key arrays
    long offsets[num_events];
    int keys[num_events];
    for (int i = 0; i < num_events; i++) {
        offsets[i] = rand() % MAX_SHUFFLE_BUFFER_SIZE;
        keys[i] = rand();
    }

    // Initialize the widgets
    for (int i = 0; i < num_widgets; i++) {
        widgets[i].offset = offsets[i];
        widgets[i].key = keys[i];
    }

    // Allocate memory for the record array
