    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the records
    for (int i = 0; i < num_events; i++) {
        records[i].widget = &widgets[i];
        records[i].timestamp = time(NULL);
    }

    // Shuffle the indices of the records
    shuffle_records(records, num_events);

    // Serialize the records to a file
    serialize_records(records, num_events);

    // Free the memory allocated for the widgets and records
    free(widgets);
    free(records);
}

// Function to shuffle the indices of the records
void shuffle_records(Record *records, int num_records) {
    // Create a buffer to hold the shuffled indices
    int *shuffle_buffer = malloc(num_records * sizeof(int));
    if (!shuffle_buffer) {
        printf("Error: Failed to allocate memory for shuffle buffer\n");
        return;
    }

    // Fill the shuffle buffer with sequential numbers
    for (int i = 0; i < num_records; i++) {
        shuffle_buffer[i] = i;
    }

    // Shuffle the indices of the records using the Fisher-Yates algorithm
    for (int i = num_records - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        int temp = shuffle_buffer[i];
        shuffle_buffer[i] = shuffle_buffer[j];
        shuffle_buffer[j] = temp;
    }

    // Use the shuffled indices to reorder the records
    for (int i = 0; i < num_records; i++) {
        int index = shuffle_buffer[i];
        Record *record = &records[index];
        records[i] = record;
    }

    // Free the memory allocated for the shuffle buffer
    free(shuffle_buffer);
}

// Function to serialize the records to a file
void serialize_records(Record *records, int num_records) {
    // Open the output file in binary mode
    FILE *output = fopen("records.bin", "wb");
    if (!output) {
        printf("Error: Failed to open output file\n");
        return;
    }

    // Write the records to the output file
    for (int i = 0; i < num_records; i++) {
        Record *record = &records[i];
        fwrite(record, sizeof(Record), 1, output);
    }

    // Close the output file
    fclose(output);
}
