} Record;

// Define memory pool for allocating and deallocating memory efficiently
struct MemoryPool {
    size_t capacity;
    size_t used;
    void** blocks;
};

// Initialize memory pool with a given capacity
void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->blocks = malloc(sizeof(void*) * capacity);
}

// Allocate memory from the memory pool
void* allocateMemory(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void* block = malloc(size);
    pool->blocks[pool->used++] = block;
    return block;
}

// Deallocate memory from the memory pool
void deallocateMemory(struct MemoryPool* pool, void* block) {
    for (int i = 0; i < pool->used; i++) {
        if (pool->blocks[i] == block) {
            free(block);
            pool->used--;
            return;
        }
    }
}

// Initialize and manage memory for four distinct data structures:
// an array of long offsets, an array of int keys, an array of custom record structures, and a dynamically allocated array of char strings.
