    if (usedMemory > 0.8 * pool.capacity) {
        printf("Triggering garbage collection...\n");
        for (int i = 0; i < pool.used; i++) {
            deallocateMemory(&pool, pool.blocks[i]);
        }
    }

    // Clean up memory and return the arrays and custom record structures
    free(offsets);
    free(keys);
    free(records);
    for (int i = 0; i < numRecords; i++) {
