#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SHUFFLE_BUFFER_SIZE 1024
#define MIN_RANDOM_VALUE 0
#define MAX_RANDOM_VALUE 1000000

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record *records;
    size_t num_records;
} widget;

typedef struct {
    widget *widgets;
    size_t num_widgets;
} gui;

gui* create_gui(size_t num_widgets) {
    // Allocate memory for the GUI structure and initialize it
    gui *gui = malloc(sizeof(gui));
    if (gui == NULL) {
        fprintf(stderr, "Failed to allocate memory for GUI\n");
        return NULL;
    }
    gui->widgets = malloc(num_widgets * sizeof(widget));
    if (gui->widgets == NULL) {
        fprintf(stderr, "Failed to allocate memory for widgets\n");
        free(gui);
        return NULL;
    }
    gui->num_widgets = num_widgets;

    // Initialize the widgets and their records
    size_t i;
    for (i = 0; i < num_widgets; ++i) {
        widget *w = &gui->widgets[i];
        w->records = malloc(sizeof(record) * MAX_SHUFFLE_BUFFER_SIZE);
        if (w->records == NULL) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            free(gui->widgets);
            free(gui);
            return NULL;
        }
        w->num_records = 0;
    }

    // Initialize the shuffle buffer and its indices
    gui->shuffle_buffer = malloc(sizeof(int) * MAX_SHUFFLE_BUFFER_SIZE);
    if (gui->shuffle_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for shuffle buffer\n");
        free(gui->widgets);
        free(gui);
        return NULL;
    }
    gui->num_shuffle_indices = 0;

    // Initialize the event serialization format and its buffers
    gui->event_serialization_format = malloc(sizeof(char) * MAX_SHUFFLE_BUFFER_SIZE);
    if (gui->event_serialization_format == NULL) {
        fprintf(stderr, "Failed to allocate memory for event serialization format\n");
        free(gui->widgets);
        free(gui);
        return NULL;
    }
    gui->num_events = 0;

    // Initialize the logging mechanism and its buffers
    gui->logging_buffer = malloc(sizeof(char) * MAX_SHUFFLE_BUFFER_SIZE);
    if (gui->logging_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for logging buffer\n");
        free(gui->widgets);
        free(gui);
        return NULL;
    }
    gui->num_log_entries = 0;

    // Initialize the thread-safe access and synchronization mechanisms
    pthread_mutex_init(&gui->mutex, NULL);
    pthread_cond_init(&gui->cond, NULL);

    return gui;
}

void destroy_gui(gui *gui) {
    // Free the memory allocated for the GUI structure and its components
    size_t i;
    for (i = 0; i < gui->num_widgets; ++i) {
        free(gui->widgets[i].records);
    }
    free(gui->widgets);
    free(gui->shuffle_buffer);
    free(gui->event_serialization_format);
    free(gui->logging_buffer);
    pthread_mutex_destroy(&gui->mutex);
    pthread_cond_destroy(&gui->cond);
    free(gui);
}

void add_widget(gui *gui, widget *w) {
    // Add the new widget to the GUI structure and initialize its records
    size_t i;
    for (i = 0; i < gui->num_widgets; ++i) {
        if (gui->widgets[i].records == NULL) {
            break;
        }
    }
    if (i == gui->num_widgets) {
        fprintf(stderr, "Failed to add widget: no more space in GUI\n");
        return;
    }
    gui->widgets[i] = *w;
    gui->widgets[i].records = malloc(sizeof(record) * MAX_SHUFFLE_BUFFER_SIZE);
    if (gui->widgets[i].records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }
    gui->num_widgets++;
}

void remove_widget(gui *gui, size_t index) {
    // Remove the widget at the specified index from the GUI structure and free its records
    if (index >= gui->num_widgets) {
        fprintf(stderr, "Failed to remove widget: invalid index\n");
        return;
    }
    size_t i;
