        record_array[i].data_ptr = (data_source*)malloc(sizeof(data_source));
        if (!record_array[i].data_ptr) {
            printf("Error: Failed to allocate memory for data pointer field\n");
            free(offset_array);
            free(key_array);
            free(record_array);
            return;
        }
    }

    // Print the allocated memory usage and the number of records
    printf("Allocated memory usage: %lu bytes\n", (limit * sizeof(long)) + (limit * sizeof(int)) + (limit * sizeof(record)));
    printf("Number of records: %d\n", limit);
}

// Free the allocated memory when the function is completed or an error occurs
