        ret = -1;
        goto cleanup;
    }

    // Initialize arrays with random values
    init_arrays(offset, offset_size, key, key_size, range);

    // Set mutex for thread-safe memory allocation and initialization
    pthread_mutex_lock(&mutex);

    // Initialize records array with random values
    for (i = 0; i < offset_size; i++) {
        records[i].value = rand() % range;
    }

    // Unlock mutex
    pthread_mutex_unlock(&mutex);

cleanup:
