#define MAX_SHUFFLE_BUFFER_SIZE 1024
#define MIN_TEMPERATURE -273.15f
#define MAX_TEMPERATURE 85.0f
#define MAX_RECORDS 1000000
#define LOGGING_LEVEL_INFO 0
#define LOGGING_LEVEL_WARNING 1
#define LOGGING_LEVEL_ERROR 2
