#define ALERT_THRESHOLD_TEMPERATURE 30.0f

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    float temperature;
    int records[MAX_RECORDS];
} shuffle_buffer;

void init_shuffle_buffer(shuffle_buffer *buffer, int size) {
    buffer->temperature = MIN_TEMPERATURE;
    for (int i = 0; i < size; i++) {
        buffer->records[i] = i;
    }
}

void shuffle(shuffle_buffer *buffer, int size) {
    srand(time(NULL));
    for (int i = 0; i < size - 1; i++) {
        int j = rand() % (size - i);
        if (j != 0) {
            int temp = buffer->records[i];
            buffer->records[i] = buffer->records[i + j];
            buffer->records[i + j] = temp;
        }
    }
}

void allocate_memory(record *records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].offset = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (records[i].offset == MAP_FAILED) {
            printf("Failed to allocate memory for record %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void deallocate_memory(record *records, int size) {
    for (int i = 0; i < size; i++) {
        munmap(records[i].offset, sizeof(long));
    }
}

void init_records(record *records, int size) {
    for (int i = 0; i < size; i++) {
        records[i].key = rand() % MAX_RECORDS;
        records[i].offset = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (records[i].offset == MAP_FAILED) {
            printf("Failed to allocate memory for record %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void deallocate_records(record *records, int size) {
    for (int i = 0; i < size; i++) {
        munmap(records[i].offset, sizeof(long));
    }
}

void init_shuffle_buffer_from_file(shuffle_buffer *buffer, char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        printf("Failed to open file %s\n", filename);
        exit(EXIT_FAILURE);
