// Define the structure for profile data
typedef struct {
    int age;
    char* location;
    enum status_type status;
} profile_data;

// Define the function to allocate and initialize memory for user profiles
void init_user_profiles(int num_profiles) {
    // Allocate memory for the array of user names
    char** user_names = malloc(num_profiles * sizeof(char*));
    if (user_names == NULL) {
        printf("Error: Failed to allocate memory for user names\n");
        return;
    }

    // Allocate memory for the array of profile IDs
    int* profile_ids = malloc(num_profiles * sizeof(int));
    if (profile_ids == NULL) {
        printf("Error: Failed to allocate memory for profile IDs\n");
        free(user_names);
        return;
    }

    // Allocate memory for the array of profile data
    profile_data* profiles = malloc(num_profiles * sizeof(profile_data));
    if (profiles == NULL) {
        printf("Error: Failed to allocate memory for profile data\n");
        free(user_names);
        free(profile_ids);
        return;
    }

    // Initialize the array of user names with random lengths between 3 and 15 characters
    for (int i = 0; i < num_profiles; i++) {
        int name_length = rand() % 12 + 3;
        char* name = malloc(name_length * sizeof(char));
        if (name == NULL) {
            printf("Error: Failed to allocate memory for user name\n");
            free(user_names);
            free(profile_ids);
            free(profiles);
            return;
        }
        memset(name, 0, name_length * sizeof(char));
        sprintf(name, "User %d", i + 1);
        user_names[i] = name;
    }

    // Initialize the array of profile IDs with unique values
    for (int i = 0; i < num_profiles; i++) {
        profile_ids[i] = i + 1;
    }

    // Initialize the array of profile data with random ages between 18 and 65, and assign locations and statuses
    for (int i = 0; i < num_profiles; i++) {
        profiles[i].age = rand() % 52 + 18;
        profiles[i].location = "Location";
        profiles[i].status = STATUS_ACTIVE;
    }
}

// Define the function to allocate and initialize memory for records
void init_records(int num_records) {
    // Allocate memory for the array of record values
    int* record_values = malloc(num_records * sizeof(int));
    if (record_values == NULL) {
        printf("Error: Failed to allocate memory for record values\n");
        return;
    }

    // Initialize the array of record values with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        record_values[i] = rand() % 10 + 1;
    }
}

// Define the function to generate certificates from OAuth requests
void generate_certificates(int num_requests) {
    // Allocate memory for the array of certificate data
    char** cert_data = malloc(num_requests * sizeof(char*));
    if (cert_data == NULL) {
        printf("Error: Failed to allocate memory for certificate data\n");
        return;
    }

    // Generate certificates from the OAuth requests
    for (int i = 0; i < num_requests; i++) {
        char* cert = malloc(1024 * sizeof(char));
        if (cert == NULL) {
            printf("Error: Failed to allocate memory for certificate\n");
            free(cert_data);
            return;
        }
        memset(cert, 0, 1024 * sizeof(char));
        sprintf(cert, "Certificate %d", i + 1);
        cert_data[i] = cert;
    }
}
