    const char* ext = strrchr(filename, '.');
    if (ext == NULL) {
        return NULL;
    }

    // Increment the number of digits in the file extension
    int num_digits = ceil(log10(fsa->num_records + 1));

    // Create a new filename with the modified extension
    char* modified_filename = (char*)malloc(strlen(filename) + num_digits + 1);
    if (modified_filename == NULL) {
        return NULL;
