#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the struct for dataPoint
struct dataPoint {
    float temperature;
    char identifier;
    unsigned long timestamp;
    bool status;
    int alertLevel;
};

// Define the error log struct
struct errorLog {
    char functionName[50];
    int lineNumber;
    char reasonForFailure[100];
    int totalDataPointsAttempted;
};

// Define the alarm notification struct
struct alarmNotification {
    bool isAlarmTriggered;
    int alertLevel;
};

// Define the function to dynamically allocate memory for and initialize five arrays: one for 'float' temperature readings, one for 'char' sensor identifiers, one for 'struct dataPoint' records, one for 'errorLog' entries, and one for 'alarm' notifications.
void initDataPoints(int seed, char* configFilePath) {
    // Declare variables to store the allocated memory addresses
    float* temperatureReadings = NULL;
    char* sensorIdentifiers = NULL;
    struct dataPoint* dataPoints = NULL;
    struct errorLog* errorLogs = NULL;
    struct alarmNotification* alarmNotifications = NULL;

    // Declare variables to store the size of each array
    int temperatureReadingsSize = 0;
    int sensorIdentifiersSize = 0;
    int dataPointsSize = 0;
    int errorLogsSize = 0;
    int alarmNotificationsSize = 0;

    // Declare variables to store the maximum number of data points and the temperature range
    int maxDataPoints = 0;
    float temperatureRange[2] = {0.0, 0.0};

    // Declare variables to store the list of valid sensor identifiers and alarm thresholds
    char* validSensorIdentifiers = NULL;
    int* alarmThresholds = NULL;

    // Declare a variable to store the number of sensors
    int numSensors = 0;

    // Declare a variable to store the current sensor identifier
    char currentSensorIdentifier[10] = {0};

    // Declare a variable to store the current temperature reading
    float currentTemperatureReading = 0.0;

    // Declare a variable to store the current timestamp
    unsigned long currentTimestamp = 0;

    // Declare a variable to store the current status flag
    bool currentStatusFlag = false;

    // Declare a variable to store the current alert level
    int currentAlertLevel = 0;

    // Declare a variable to store the current error message
    char currentErrorMessage[100] = {0};

    // Declare a variable to store the current error log entry
    struct errorLog currentErrorLogEntry;

    // Declare a variable to store the current alarm notification
    struct alarmNotification currentAlarmNotification;

    // Initialize the random number generator with the seed
    srand(seed);

    // Load the configuration file and extract the maximum number of data points, temperature range, list of valid sensor identifiers, and alarm thresholds
    if (loadConfigFile(configFilePath) == 0) {
        printf("Error: Failed to load configuration file.\n");
        return;
    }

    // Allocate memory for the temperature readings array
    temperatureReadingsSize = maxDataPoints * sizeof(float);
    temperatureReadings = (float*)malloc(temperatureReadingsSize);
    if (temperatureReadings == NULL) {
        printf("Error: Failed to allocate memory for temperature readings.\n");
        return;
    }

    // Allocate memory for the sensor identifiers array
    sensorIdentifiersSize = maxDataPoints * sizeof(char);
    sensorIdentifiers = (char*)malloc(sensorIdentifiersSize);
    if (sensorIdentifiers == NULL) {
        printf("Error: Failed to allocate memory for sensor identifiers.\n");
        return;
    }

    // Allocate memory for the data points array
    dataPointsSize = maxDataPoints * sizeof(struct dataPoint);
    dataPoints = (struct dataPoint*)malloc(dataPointsSize);
    if (dataPoints == NULL) {
        printf("Error: Failed to allocate memory for data points.\n");
        return;
    }

    // Allocate memory for the error logs array
    errorLogsSize = maxDataPoints * sizeof(struct errorLog);
    errorLogs = (struct errorLog*)malloc(errorLogsSize);
    if (errorLogs == NULL) {
        printf("Error: Failed to allocate memory for error logs.\n");
        return;
    }

    // Allocate memory for the alarm notifications array
    alarmNotificationsSize = maxDataPoints * sizeof(struct alarmNotification);
    alarmNotifications = (struct alarmNotification*)malloc(alarmNotificationsSize);
    if (alarmNotifications == NULL) {
        printf("Error: Failed to allocate memory for alarm notifications.\n");
        return;
    }

    // Initialize the temperature readings array with random temperature readings within the specified range
    for (int i = 0; i < maxDataPoints; i++) {
        currentTemperatureReading = rand() % (temperatureRange[1] - temperatureRange[0]) + temperatureRange[0];
        temperatureReadings[i] = currentTemperatureReading;
    }

    // Initialize the sensor identifiers array with unique sensor identifiers derived from the provided list
    for (int i = 0; i < maxDataPoints; i++) {
        numSensors = strlen(validSensorIdentifiers);
        currentSensorIdentifier[0] = validSensorIdentifiers[i % numSensors];
        sensorIdentifiers[i] = currentSensorIdentifier[0];
    }

    // Initialize the data points array with random temperature readings, timestamps, status flags, and alert levels
    for (int i = 0; i < maxDataPoints; i++) {
        currentTemperatureReading = temperatureReadings[i];
        currentTimestamp = time(NULL);
        currentStatusFlag = true;
        currentAlertLevel = getAlertLevel(currentTemperatureReading, alarmThresholds);
        dataPoints[i].temperature = currentTemperatureReading;
        dataPoints[i].identifier = sensorIdentifiers[i];
        dataPoints[i].timestamp = currentTimestamp;
        dataPoints[i].status = currentStatusFlag;
        dataPoints[i].alertLevel = currentAlertLevel;
    }

    // Initialize the error logs array with empty entries
    for (int i = 0; i < maxDataPoints; i++) {
        memset(&errorLogs[i], 0, sizeof(struct errorLog));
    }

    // Initialize the alarm notifications array with empty entries
    for (int i = 0; i < maxDataPoints; i++) {
        memset(&alarmNotifications[i], 0, sizeof(struct alarmNotification));
    }

    // Log successful allocations and record the initial and final sizes of each allocated array
    printf("Successfully allocated memory for temperature readings (%d bytes).\n", temperatureReadingsSize);
    printf("Successfully allocated memory for sensor identifiers (%d bytes).\n", sensorIdentifiersSize);
    printf("Successfully allocated memory for data points (%d bytes).\n", dataPointsSize);
    printf("Successfully allocated memory for error logs (%d bytes).\n", errorLogsSize);
    printf("Successfully allocated memory for alarm notifications (%d bytes).\n", alarmNotificationsSize);
    printf("Initial size of temperature readings array: %d.\n", maxDataPoints);
    printf("Final size of temperature readings array: %d.\n", maxDataPoints);
    printf("Initial size of sensor identifiers array: %d.\n", maxDataPoints);
    printf("Final size of sensor identifiers array: %d.\n", maxDataPoints);
    printf("Initial size of data points array: %d.\n", maxDataPoints);
    printf("Final size of data points array: %d.\n", maxDataPoints);
    printf("Initial size of error logs array: %d.\n", maxDataPoints);
    printf("Final size of error logs array: %d.\n", maxDataPoints);
    printf("Initial size of alarm notifications array: %d.\n", maxDataPoints);
    printf("Final size of alarm notifications array: %d.\n", maxDataPoints);

    // Periodically check the health of the system by verifying the integrity of the allocated memory
    while (1) {
        // Check if any corruption is detected in the allocated memory
        if (checkMemoryIntegrity(temperatureReadings, temperatureReadingsSize) == 0) {
            printf("Error: Corruption detected in temperature readings array.\n");
            return;
        }
        if (checkMemoryIntegrity(sensorIdentifiers, sensorIdentifiersSize) == 0) {
            printf("Error: Corruption detected in sensor identifiers array.\n");
            return;
        }
        if (checkMemoryIntegrity(dataPoints, dataPointsSize) == 0) {
            printf("Error: Corruption detected in data points array.\n");
            return;
        }
        if (checkMemoryIntegrity(errorLogs, errorLogsSize) == 0) {
            printf("Error: Corruption detected in error logs array.\n");
            return;
        }
        if (checkMemoryIntegrity(alarmNotifications, alarmNotificationsSize) == 0) {
            printf("Error: Corruption detected in alarm notifications array.\n");
            return;
        }

        // Sleep for a short period of time before checking the health of the system again
        sleep(1);
    }
}

// Define the function to load the configuration file and extract the maximum number of data points, temperature range, list of valid sensor identifiers, and alarm thresholds
int loadConfigFile(char* configFilePath) {
    // Declare variables to store the contents of the configuration file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    // Open the configuration file for reading
    FILE* fp = fopen(configFilePath, "r");
    if (fp == NULL) {
        printf("Error: Failed to open configuration file.\n");
        return -1;
    }

    // Read each line of the configuration file and extract the maximum number of data points, temperature range, list of valid sensor identifiers, and alarm thresholds
    while ((read = getline(&line, &len, fp)) != -1) {
        char* token = strtok(line, " ");
        if (strcmp(token, "maxDataPoints") == 0) {
            maxDataPoints = atoi(strtok(NULL, " "));
        } else if (strcmp(token, "temperatureRange") == 0) {
            temperatureRange[0] = atof(strtok(NULL, " "));
            temperatureRange[1] = atof(strtok(NULL, " "));
        } else if (strcmp(token, "validSensorIdentifiers") == 0) {
            validSensorIdentifiers = strdup(strtok(NULL, " "));
        } else if (strcmp(token, "alarmThresholds") == 0) {
            alarmThresholds = (int*)malloc(maxDataPoints * sizeof(int));
            for (int i = 0; i < maxDataPoints; i++) {
                alarmThresholds[i] = atoi(strtok(NULL, " "));
            }
        }
    }

    // Close the configuration file
    fclose(fp);

    // Return success if all parameters were successfully extracted from the configuration file
    return 0;
}

// Define the function to get the alert level based on predefined thresholds
int getAlertLevel(float temperature, int* alarmThresholds) {
    for (int i = 0; i < maxDataPoints; i++) {
        if (temperature >= alarmThresholds[i]) {
            return i + 1;
        }
    }
    return 0;
}

// Define the function to check the integrity of the allocated memory
int checkMemoryIntegrity(void* memory, int size) {
    // Declare variables to store the current and previous values of the memory address
    char currentValue = 0;
    char previousValue = 0;

    // Iterate through each byte of the memory block
    for (int i = 0; i < size; i++) {
        currentValue = ((char*)memory)[i];
        if (previousValue != 0 && currentValue == previousValue) {
            return 0;
        }
        previousValue = currentValue;
    }

    // Return success if the memory integrity check passed
    return 1;
}
