const char* get_base_name(const char* filename) {
    const char* dot = strrchr(filename, '.');
    if (dot == NULL) {
        return filename;
    }
    size_t len = dot - filename;
    char* base_name = malloc(len + 1);
    memcpy(base_name, filename, len);
    base_name[len] = '\0';
    return base_name;
}

