    const char* dot = strrchr(filename, '.');
    if (dot == NULL) {
        return "";
    }
    size_t len = strlen(dot);
    char* extension = malloc(len + 1);
    memcpy(extension, dot, len);
    extension[len] = '\0';
    return extension;
}

