        new_base_name[len] = '\0';
        snprintf(new_filename, MAX_FILENAME_LENGTH, "%s%d-%s", new_base_name, num_digits, unique_id);
        free(unique_id);
        free(new_base_name);
    }

    // Preserve the original filename if the new filename exceeds the maximum length constraint
    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        return NULL;
    }

    // Handle filenames with Unicode characters, special characters, and those with embedded null bytes gracefully
    wchar_t* wide_base_name = malloc(sizeof(wchar_t) * (strlen(base_name) + 1));
    mbstowcs(wide_base_name, base_name, strlen(base_name) + 1);
