void add_event(event_storage_t* storage, time_t timestamp, int type, char* identifier) {
    // Check if the event is already in memory
    for (size_t i = 0; i < storage->memory->count; i++) {
        if (strcmp(storage->memory->events[i].identifier, identifier) == 0) {
            return;
        }
    }

    // Check if the event is already on disk
    for (size_t i = 0; i < storage->disk->count; i++) {
        if (strcmp(storage->disk->events[i].identifier, identifier) == 0) {
            return;
        }
    }

    // Add the event to memory
    if (storage->memory->count < storage->memory->capacity) {
        storage->memory->events[storage->memory->count++] = (event_t){timestamp, type, identifier};
    } else {
        // Add the event to disk
        if (storage->disk->count < storage->disk->capacity) {
            storage->disk->events[storage->disk->count++] = (event_t){timestamp, type, identifier};
        } else {
