    if (!requests[j].data) {
        // Memory allocation failed
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    memcpy(requests[j].data, request->data, REQUEST_SIZE);
    session->num_requests++;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

int updateRequest(char *session_id, int timestamp) {
    int i, j;
    session_t *session;
    pthread_mutex_lock(&session_lock);
    if (getSession(session_id, &session) < 0) {
        // Session not found
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    for (j = 0; j < session->num_requests; j++) {
        if (session->request_keys[j] == timestamp) {
            // Found the request
            break;
        }
    }
    if (j == session->num_requests) {
        // Request not found
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    session->request_keys[j] = timestamp + 1;
    pthread_mutex_unlock(&session_lock);
    return 0;
}

int getRequest(char *session_id, int timestamp, request_t **request) {
    int i, j;
    session_t *session;
    pthread_mutex_lock(&session_lock);
    if (getSession(session_id, &session) < 0) {
        // Session not found
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    for (j = 0; j < session->num_requests; j++) {
        if (session->request_keys[j] == timestamp) {
            // Found the request
            break;
        }
    }
    if (j == session->num_requests) {
        // Request not found
        pthread_mutex_unlock(&session_lock);
        return -1;
    }
    *request = &requests[session->request_offsets[j]];
    pthread_mutex_unlock(&session_lock);
    return 0;
}

void deallocateMemory() {
