void init_data(data_struct_t *data, const char *json_file) {
    // Open the JSON file and read its contents
    FILE *fp = fopen(json_file, "r");
    if (fp == NULL) {
        perror("Error opening JSON file");
        return;
    }

    // Read the number of records from the JSON file
    size_t num_records = 0;
    char *line = NULL;
    size_t line_len = 0;
    ssize_t read;
    while ((read = getline(&line, &line_len, fp)) != -1) {
        if (strncmp(line, "\"num_records\":", 13) == 0) {
            num_records = atoi(line + 13);
            break;
        }
    }
    free(line);
    fclose(fp);

    // Allocate memory for the array of records and initialize it with values from the JSON file
    data->num_records = num_records;
    data->segment_size = 1024; // Default segment size
    data->records = (record_t *)malloc(sizeof(record_t) * data->num_records);
    if (data->records == NULL) {
        perror("Error allocating memory for records");
        return;
    }

    // Open the JSON file again and read its contents
    fp = fopen(json_file, "r");
    if (fp == NULL) {
        perror("Error opening JSON file");
        return;
    }

    // Read the values for each record from the JSON file and initialize them
    size_t i = 0;
    while ((read = getline(&line, &line_len, fp)) != -1) {
        if (strncmp(line, "\"records\":", 9) == 0) {
            char *token = strtok(line + 9, ",");
            while (token != NULL) {
                record_t *record = &data->records[i];
                record->offset = atol(token);
                token = strtok(NULL, ",");
                record->key = atoi(token);
                token = strtok(NULL, ",");
                for (int j = 0; j < record->values.length; j++) {
                    record->values[j] = atoi(token);
                    token = strtok(NULL, ",");
                }
                i++;
            }
        }
    }
    free(line);
    fclose(fp);
}

// Function to manage memory allocation and initialization for a dynamic data structure
void init_data_struct(data_struct_t *data) {
    // Initialize the mutex for thread safety
    pthread_mutex_init(&data->mutex, NULL);

    // Allocate memory for the array of records
    data->records = (record_t *)malloc(sizeof(record_t) * data->num_records);
    if (data->records == NULL) {
        perror("Error allocating memory for records");
        return;
    }

    // Initialize the array of records with values from an external JSON file
    init_data(data, "external_json_file.json");
}

// Function to free memory allocated by the data structure
void free_data_struct(data_struct_t *data) {
    // Free the mutex for thread safety
    pthread_mutex_destroy(&data->mutex);

    // Free the array of records
    free(data->records);
}

// Function to add a new record to the data structure
void add_record(data_struct_t *data, long offset, int key, int values[]) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&data->mutex);

    // Check if there is enough memory allocated for the new record
    if (data->num_records >= data->segment_size) {
        // Reallocate memory for the array of records with a larger size
        data->records = (record_t *)realloc(data->records, sizeof(record_t) * (data->num_records + 1));
        if (data->records == NULL) {
            perror("Error reallocating memory for records");
            return;
        }
    }

    // Add the new record to the array of records
    data->records[data->num_records].offset = offset;
    data->records[data->num_records].key = key;
    memcpy(data->records[data->num_records].values, values, sizeof(int) * 1024); // Default size of the array of values
    data->num_records++;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&data->mutex);
}

// Function to remove a record from the data structure
void remove_record(data_struct_t *data, long offset) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&data->mutex);

    // Find the index of the record with the specified offset
    size_t i = 0;
    while (i < data->num_records && data->records[i].offset != offset) {
        i++;
    }

    // Check if the record was found
    if (i == data->num_records) {
        printf("Record with offset %ld not found\n", offset);
        return;
    }

    // Remove the record from the array of records
    for (size_t j = i; j < data->num_records - 1; j++) {
        data->records[j] = data->records[j + 1];
    }
    data->num_records--;

    // Release the mutex for thread safety
    pthread_mutex_unlock(&data->mutex);
}

// Function to retrieve a record from the data structure
record_t *get_record(data_struct_t *data, long offset) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&data->mutex);

    // Find the index of the record with the specified offset
    size_t i = 0;
    while (i < data->num_records && data->records[i].offset != offset) {
        i++;
    }

    // Check if the record was found
    if (i == data->num_records) {
        printf("Record with offset %ld not found\n", offset);
        return NULL;
    }

    // Return a pointer to the record
    record_t *record = &data->records[i];

    // Release the mutex for thread safety
    pthread_mutex_unlock(&data->mutex);

    return record;
}
