        fprintf(stderr, "Error: Total allocated memory exceeds maximum allowed size\n");
        exit(1);
    }

    // Allocate memory for arrays
    void *data = malloc(total_size);
    if (!data) {
        fprintf(stderr, "Error: Failed to allocate memory for arrays\n");
        exit(1);
    }

    return data;
}

