// Define a class to generate random values within a specified range
class DynamicRandomValueGenerator {
private:
    int minValue;
    int maxValue;
    unsigned long seed;

public:
    // Constructor with parameters for minValue, maxValue, and seed
    DynamicRandomValueGenerator(int minValue, int maxValue, unsigned long seed) {
        this->minValue = minValue;
        this->maxValue = maxValue;
        this->seed = seed;
    }

    // Method to generate a random integer within the specified range
    int GetRandomInt() {
        return (int)(this->minValue + ((double)rand_r(&this->seed) / RAND_MAX) * (this->maxValue - this->minValue));
    }

    // Method to generate a random float within the specified range
    float GetRandomFloat() {
        return (float)(this->minValue + ((double)rand_r(&this->seed) / RAND_MAX) * (this->maxValue - this->minValue));
    }
}

// Function to manage memory allocation and initialization for a flexible file indexing system
void DynamicFileIndexer(int numFiles, bool indexByName, int maxFileSize, int numMetadataFields, int minMetadataValue, int maxMetadataValue) {
    // Allocate memory dynamically for an array of 'file' structures
    File* files = (File*)malloc(numFiles * sizeof(File));
    if (!files) {
        printf("Error: Failed to allocate memory for file index\n");
        return;
    }

    // Initialize file names and sizes randomly within the specified range
    srand(time(NULL));
    for (int i = 0; i < numFiles; i++) {
        files[i].id = i + 1;
        if (indexByName) {
            files[i].name = (char*)malloc(strlen("file") + rand() % 10);
            strcpy(files[i].name, "file");
            for (int j = 0; j < strlen(files[i].name); j++) {
                files[i].name[j] += rand() % 26;
            }
        } else {
            files[i].size = rand() % maxFileSize + 1;
        }
    }

    // Fill the metadata fields with random values using the DynamicRandomValueGenerator class
    for (int i = 0; i < numFiles; i++) {
        for (int j = 0; j < numMetadataFields; j++) {
            files[i].metadata[j] = DynamicRandomValueGenerator(minMetadataValue, maxMetadataValue).GetRandomFloat();
        }
    }

    // Implement methods to add new files to the index and retrieve metadata for existing files
    void AddFile(int id, char* name, size_t size) {
        File* file = (File*)malloc(sizeof(File));
        if (!file) {
            printf("Error: Failed to allocate memory for new file\n");
            return;
        }
        file->id = id;
        file->name = name;
        file->size = size;
        for (int i = 0; i < numMetadataFields; i++) {
            file->metadata[i] = DynamicRandomValueGenerator(minMetadataValue, maxMetadataValue).GetRandomFloat();
        }
        files = (File*)realloc(files, (numFiles + 1) * sizeof(File));
        if (!files) {
            printf("Error: Failed to reallocate memory for file index\n");
            return;
        }
        files[numFiles] = file;
        numFiles++;
    }

    void GetMetadata(int id, float* metadata) {
        File* file = (File*)malloc(sizeof(File));
        if (!file) {
            printf("Error: Failed to allocate memory for new file\n");
            return;
        }
        file->id = id;
        file->name = name;
        file->size = size;
        for (int i = 0; i < numMetadataFields; i++) {
            metadata[i] = files[id].metadata[i];
        }
    }

    // Handle potential memory allocation failures gracefully, providing a meaningful error message
    if (!files) {
        printf("Error: Failed to allocate memory for file index\n");
        return;
    }

    // Ensure that all allocated memory is properly deallocated upon function exit to prevent memory leaks
    free(files);
}
