// Define the data structure for a single data packet
typedef struct {
    long offset;
    int key;
    float timestamp;
    char* identifier;
} data_packet;

// Define the memory pool for dynamic allocation and initialization
typedef struct {
    size_t capacity; // Total capacity of the memory pool in bytes
    size_t used; // Used memory in the pool in bytes
    void* buffer; // Pointer to the start of the memory pool
} mempool;

// Define the hash table for tracking used numbers
typedef struct {
    int size; // Size of the hash table
    int* keys; // Array of keys
    int* values; // Array of values
} hashtable;

// Initialize a new memory pool with the given capacity in bytes
void mempool_init(mempool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->buffer = malloc(capacity);
}

// Allocate a new data packet from the memory pool
data_packet* mempool_alloc(mempool* pool, size_t payload_size) {
    // Check if there is enough space in the pool for the given payload size
    if (pool->used + payload_size > pool->capacity) {
        return NULL;
    }

    // Allocate memory for the data packet and initialize it with random values
    data_packet* packet = (data_packet*)((char*)pool->buffer + pool->used);
    packet->offset = rand() % 1000000;
    packet->key = rand() % 1000000;
    packet->timestamp = (float)rand() / RAND_MAX;
    packet->identifier = malloc(payload_size);
    memset(packet->identifier, 'a', payload_size);

    // Update the used memory in the pool
    pool->used += sizeof(data_packet) + payload_size;

    return packet;
}

// Free a data packet from the memory pool
void mempool_free(mempool* pool, data_packet* packet) {
    // Check if the packet is in the pool
    if (packet < (data_packet*)pool->buffer || packet > (data_packet*)((char*)pool->buffer + pool->used)) {
        return;
    }

    // Free the memory for the data packet and update the used memory in the pool
    free(packet->identifier);
    pool->used -= sizeof(data_packet) + payload_size;
}

// Initialize a new hash table with the given size
void hashtable_init(hashtable* table, int size) {
    table->size = size;
    table->keys = malloc(sizeof(int) * size);
    table->values = malloc(sizeof(int) * size);
}

// Insert a new key-value pair into the hash table
void hashtable_insert(hashtable* table, int key, int value) {
    // Check if the key is already in the table
    for (int i = 0; i < table->size; i++) {
        if (table->keys[i] == key) {
            return;
        }
    }

    // Find an empty slot in the table and insert the new key-value pair
    int index = rand() % table->size;
    while (table->keys[index] != 0) {
        index = (index + 1) % table->size;
    }
    table->keys[index] = key;
    table->values[index] = value;
}

// Look up a key in the hash table and return its associated value
int hashtable_lookup(hashtable* table, int key) {
    // Check if the key is in the table
    for (int i = 0; i < table->size; i++) {
        if (table->keys[i] == key) {
            return table->values[i];
        }
    }

    // If the key is not found, return -1
    return -1;
}

// Generate a unique random number within the specified range
int generate_random(int min, int max) {
    int range = (max - min) + 1;
    return min + (rand() % range);
}

// Allocate and initialize a new data packet from the memory pool
data_packet* allocate_packet(mempool* pool, size_t payload_size) {
    // Check if there is enough space in the pool for the given payload size
    if (pool->used + payload_size > pool->capacity) {
        return NULL;
    }

    // Allocate memory for the data packet and initialize it with random values
    data_packet* packet = (data_packet*)((char*)pool->buffer + pool->used);
    packet->offset = generate_random(0, 1000000);
    packet->key = generate_random(0, 1000000);
    packet->timestamp = (float)generate_random(0, 1000000) / RAND_MAX;
    packet->identifier = malloc(payload_size);
    memset(packet->identifier, 'a', payload_size);

    // Update the used memory in the pool
    pool->used += sizeof(data_packet) + payload_size;

