    public NetworkMonitorHelper(int initialLatencyMeasurementSize, int initialPacketIdentifierSize, int initialPacketSize)
    {
        this.latencyMeasurements = new int[initialLatencyMeasurementSize];
        this.packetIdentifiers = new uint[initialPacketIdentifierSize];
        this.packets = new LinkedList<Packet>();
        this.packetTimestamps = new TimeVal[initialPacketSize];
        this.errorCodes = new int[0];
    }

    public void Initialize(int minimumValue, int maximumValue)
    {
        this.minimumValue = minimumValue;
        this.maximumValue = maximumValue;
    }

    public void AddPacket(long timestamp, uint packetIdentifier, string sourceIPAddress, ushort destinationPort)
    {
        Packet newPacket = new Packet();
        newPacket.Timestamp = timestamp;
        newPacket.PacketIdentifier = packetIdentifier;
        newPacket.SourceIPAddress = sourceIPAddress;
        newPacket.DestinationPort = destinationPort;
        this.packets.AddLast(newPacket);
    }

    public void AddLatencyMeasurement(long latency)
    {
        this.latencyMeasurements[this.latencyMeasurements.Length - 1] = latency;
    }

    public void AddPacketIdentifier(uint packetIdentifier)
    {
        this.packetIdentifiers[this.packetIdentifiers.Length - 1] = packetIdentifier;
    }

    public void AddPacketTimestamp(TimeVal timestamp)
    {
        this.packetTimestamps[this.packetTimestamps.Length - 1] = timestamp;
    }

    public void AddErrorCode(int errorCode)
    {
        this.errorCodes[this.errorCodes.Length - 1] = errorCode;
    }

    public int[] GetLatencyMeasurements()
    {
        return this.latencyMeasurements;
    }

    public uint[] GetPacketIdentifiers()
    {
        return this.packetIdentifiers;
    }

    public LinkedList<Packet> GetPackets()
    {
        return this.packets;
    }

    public TimeVal[] GetPacketTimestamps()
    {
        return this.packetTimestamps;
    }

    public int[] GetErrorCodes()
    {
        return this.errorCodes;
    }

    public void ResizeLatencyMeasurements(int newSize)
    {
        this.latencyMeasurements = new int[newSize];
    }

    public void ResizePacketIdentifiers(int newSize)
    {
        this.packetIdentifiers = new uint[newSize];
    }

    public void ResizePackets(int newSize)
    {
        this.packets = new LinkedList<Packet>(newSize);
    }

    public void ResizePacketTimestamps(int newSize)
    {
        this.packetTimestamps = new TimeVal[newSize];
    }

    public void ResizeErrorCodes(int newSize)
    {
        this.errorCodes = new int[newSize];
    }

    public float GetRandomFloatValue()
    {
        return UnityEngine.Random.Range(this.minimumValue, this.maximumValue);
    }

    public int GetRandomIntegerValue()
    {
        return UnityEngine.Random.Range(this.minimumValue, this.maximumValue + 1);
    }

    public override string ToString()
    {
        return $"{this.minimumValue} - {this.maximumValue}";
    }
}
