    memset(session->request_offsets, 0, sizeof(long) * MAX_REQUESTS);
    session->request_keys = (int *)malloc(sizeof(int) * MAX_REQUESTS);
    memset(session->request_keys, 0, sizeof(int) * MAX_REQUESTS);
}

void addSession(char *session_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        initSession(&sessions[i]);
        strcpy(sessions[i].session_id, session_id);
        printf("Added new session: %s\n", sessions[i].session_id);
    }
    pthread_mutex_unlock(&session_lock);
}

void updateSession(char *session_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        printf("Session not found: %s\n", session_id);
    } else {
        sessions[i].num_requests++;
        printf("Updated session: %s, num_requests = %d\n", sessions[i].session_id, sessions[i].num_requests);
    }
    pthread_mutex_unlock(&session_lock);
}

void removeSession(char *session_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        printf("Session not found: %s\n", session_id);
    } else {
        free(sessions[i].request_offsets);
        free(sessions[i].request_keys);
        memset(&sessions[i], 0, sizeof(session_t));
        printf("Removed session: %s\n", sessions[i].session_id);
    }
    pthread_mutex_unlock(&session_lock);
}

void addRequest(char *session_id, char *request_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        printf("Session not found: %s\n", session_id);
    } else {
        int j = sessions[i].num_requests++;
        strcpy(requests[j].request_id, request_id);
        requests[j].timestamp = time(NULL);
        requests[j].data = NULL;
        printf("Added new request: %s\n", requests[j].request_id);
    }
    pthread_mutex_unlock(&session_lock);
}

void updateRequest(char *session_id, char *request_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        printf("Session not found: %s\n", session_id);
    } else {
        int j = 0;
        for (j = 0; j < sessions[i].num_requests; j++) {
            if (!strcmp(requests[j].request_id, request_id)) {
                break;
            }
        }
        if (j == sessions[i].num_requests) {
            printf("Request not found: %s\n", request_id);
        } else {
            requests[j].timestamp = time(NULL);
            printf("Updated request: %s, timestamp = %ld\n", requests[j].request_id, requests[j].timestamp);
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void removeRequest(char *session_id, char *request_id) {
    pthread_mutex_lock(&session_lock);
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        if (!strcmp(sessions[i].session_id, session_id)) {
            break;
        }
    }
    if (i == MAX_SESSIONS) {
        printf("Session not found: %s\n", session_id);
    } else {
        int j = 0;
        for (j = 0; j < sessions[i].num_requests; j++) {
            if (!strcmp(requests[j].request_id, request_id)) {
                break;
            }
        }
        if (j == sessions[i].num_requests) {
            printf("Request not found: %s\n", request_id);
        } else {
            memmove(&requests[j], &requests[j + 1], sizeof(request_t) * (sessions[i].num_requests - j));
            sessions[i].num_requests--;
            printf("Removed request: %s\n", requests[j].request_id);
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void deallocateMemory() {
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        free(sessions[i].request_offsets);
        free(sessions[i].request_keys);
        memset(&sessions[i], 0, sizeof(session_t));
    }
}

int main() {
    int i;
    for (i = 0; i < MAX_SESSIONS; i++) {
        initSession(&sessions[i]);
    }
    addSession("session1");
    updateSession("session1");
    removeSession("session1");
    addRequest("session1", "request1");
    updateRequest("session1", "request1");
    removeRequest("session1", "request1");
    deallocateMemory();
    return 0;
}
