// Initialize cache with maximum capacity
struct cache* initialize_cache(size_t max_capacity) {
    struct cache* cache = malloc(sizeof(struct cache));
    cache->capacity = max_capacity;
    cache->size = 0;
    cache->entries = NULL;
    return cache;
}

// Add document to cache
void add_to_cache(struct cache* cache, struct document_data* data) {
    // Check if cache is full
    if (cache->size == cache->capacity) {
        // Evict least recently used item
        evict_lru(cache);
    }

    // Create new cache entry
    struct cache_entry* entry = malloc(sizeof(struct cache_entry));
    entry->timestamp = data->timestamp;
    entry->user_id = data->user_id;
    entry->data = data;
    entry->next = NULL;
    entry->prev = NULL;

    // Add entry to cache
    if (cache->entries == NULL) {
        cache->entries = entry;
    } else {
        struct cache_entry* current = cache->entries;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = entry;
        entry->prev = current;
    }

    // Increment cache size
    cache->size++;
}

// Evict least recently used item from cache
void evict_lru(struct cache* cache) {
    struct cache_entry* entry = cache->entries;
    while (entry->next != NULL) {
        entry = entry->next;
    }
    free(entry);
    entry->prev->next = NULL;
    cache->size--;
}

