// Aggregate and transform document data into summary metrics
void aggregate_and_transform_data(struct cache* cache) {
    // Initialize aggregation variables
    int num_events = 0;
    time_t min_timestamp = 0;
    time_t max_timestamp = 0;
    int user_id = 0;
    struct document_data* data = NULL;

    // Iterate over cache entries
    for (struct cache_entry* entry = cache->entries; entry != NULL; entry = entry->next) {
        // Increment number of events and update minimum/maximum timestamps
        num_events++;
        if (min_timestamp == 0 || entry->data->timestamp < min_timestamp) {
            min_timestamp = entry->data->timestamp;
        }
        if (max_timestamp == 0 || entry->data->timestamp > max_timestamp) {
            max_timestamp = entry->data->timestamp;
        }

        // Update user ID and document data pointers
        user_id = entry->data->user_id;
        data = entry->data;
    }

    // Calculate average timestamp
    double avg_timestamp = (double)min_timestamp + ((double)max_timestamp - (double)min_timestamp) / 2.0;

    // Print summary metrics
    printf("Number of events: %d\n", num_events);
    printf("Minimum timestamp: %ld\n", min_timestamp);
    printf("Maximum timestamp: %ld\n", max_timestamp);
    printf("Average timestamp: %.2f\n", avg_timestamp);
    printf("User ID: %d\n", user_id);
}

// Free cache entries
void free_cache(struct cache* cache) {
