    void *memory_block = malloc(sensor_value_size + metadata_size);

    // Initialize the pointers to the beginning of the memory block
    double **sensor_values = (double**)memory_block;
    struct reading_metadata *metadata = (struct reading_metadata*)(memory_block + sensor_value_size);

