    for (int i = 0; i < num_readings; i++) {
        struct reading_metadata *current_metadata = &metadata[i];
        current_metadata->timestamp = time(NULL);
        current_metadata->source_id = rand() % 1000000; // Generate a random source ID between 0 and 999,999
        current_metadata->quality_score = (float)rand() / RAND_MAX; // Generate a random quality score between 0.0 and 1.0
    }

    return memory_block;
}

// Define a function to handle concurrent access from multiple threads without introducing race conditions or data corruption
void *handle_concurrent_access(void *memory_block) {
    // Use a thread-safe data structure (e.g., a mutex or a semaphore) to protect the memory block from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Perform operations on the memory block, e.g., read and write sensor values and metadata
    double **sensor_values = (double**)memory_block;
    struct reading_metadata *metadata = (struct reading_metadata*)(memory_block + sizeof(double*) * num_readings);

    // Release the mutex to allow other threads to access the memory block
    pthread_mutex_unlock(&mutex);
}

// Define a function to monitor and report on the performance metrics of the function, including memory usage, processing time per batch of sensor readings, and average time to free unused memory
void *monitor_performance(void *memory_block) {
    // Use a thread-safe data structure (e.g., a mutex or a semaphore) to protect the performance metrics from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Calculate memory usage and processing time per batch of sensor readings
    size_t num_readings = sizeof(double*) * num_readings;
    size_t metadata_size = sizeof(struct reading_metadata) * num_readings;
    double total_memory_usage = (double)(sensor_value_size + metadata_size);
    double average_processing_time = 0.0;

    // Calculate the average time to free unused memory
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    free(memory_block);
    clock_gettime(CLOCK_MONOTONIC, &end);
    double total_free_time = (double)(end.tv_sec - start.tv_sec) + (double)(end.tv_nsec - start.tv_nsec) / 1000000000;
    double average_free_time = total_free_time / num_readings;

    // Release the mutex to allow other threads to access the performance metrics
    pthread_mutex_unlock(&mutex);
}
