    // Allocate memory for the linked list of nodes
    Node* head = malloc(sizeof(Node));
    if (head == NULL) {
        return NULL;
    }

    // Initialize the head node
    head->value = 0;
    head->next = NULL;

    // Allocate memory for the array of elements
    Element* elements = malloc(sizeof(Element) * num_elements);
    if (elements == NULL) {
        free(head);
        return NULL;
    }

    // Initialize each element with a pointer to the corresponding node
    for (int i = 0; i < num_elements; i++) {
        elements[i].index = i;
        elements[i].node = head;
    }

    // Allocate memory for the array of attributes
    Attribute* attributes = malloc(sizeof(Attribute) * num_attributes);
    if (attributes == NULL) {
        free(head);
        free(elements);
        return NULL;
    }

    // Initialize each attribute with a string and active status
    for (int i = 0; i < num_attributes; i++) {
        attributes[i].string = malloc(sizeof(char) * 10);
        if (attributes[i].string == NULL) {
            free(head);
            free(elements);
            free(attributes);
            return NULL;
        }
        sprintf(attributes[i].string, "Attribute %d", i);
        attributes[i].active = true;
    }

    // Allocate memory for the hash table of key maps
    KeyMap* key_maps = malloc(sizeof(KeyMap) * num_elements);
    if (key_maps == NULL) {
        free(head);
        free(elements);
        free(attributes);
        return NULL;
    }

    // Initialize each key map with a unique key and corresponding node pointer
    for (int i = 0; i < num_elements; i++) {
        key_maps[i].key = i;
        key_maps[i].node = head;
    }

    return head;
}

// Function to free all allocated memory
void free_data(void* data) {
    Node* head = (Node*)data;
    while (head != NULL) {
        Node* next = head->next;
        free(head);
        head = next;
    }
}

// Function to iterate over the elements of the linked list and update their attributes based on certain conditions
void update_attributes(void* data, int condition) {
    Node* head = (Node*)data;
    while (head != NULL) {
        // Check if the current node meets the condition
        if (condition == 1) {
            // Update the attribute of the current node
            head->value++;
        } else {
            // Skip to the next node
            head = head->next;
            continue;
        }

        // Move to the next node
        head = head->next;
    }
}
