#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/resource.h>

// Define the data structure for a job
typedef struct {
    char uuid[37]; // 36 characters + null terminator
    int status;
    void* result;
} job_t;

// Define the data structure for a worker thread
typedef struct {
    pthread_t thread;
    int id;
    job_t* jobs;
    size_t num_jobs;
} worker_t;

// Define the data structure for a task handler
typedef struct {
    void (*request_processor)(void*);
    void (*result_parser)(void*);
    void (*event_emitter)(void*);
} task_handler_t;

// Define the data structure for a metric entry
typedef struct {
    time_t timestamp;
    int value;
} metric_t;

// Global variables
static size_t num_workers = 0;
static worker_t* workers = NULL;
static task_handler_t* task_handlers = NULL;
static size_t num_task_handlers = 0;
static size_t max_num_jobs = 0;
static size_t max_num_workers = 0;
static size_t max_num_metrics = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to allocate memory for a dynamic array of worker threads
worker_t* alloc_workers(size_t num_workers) {
    worker_t* workers = (worker_t*)malloc(num_workers * sizeof(worker_t));
    if (!workers) {
        perror("Failed to allocate memory for worker threads");
        exit(1);
    }
    return workers;
}

// Function to initialize a worker thread
void init_worker(worker_t* worker, int id) {
    worker->id = id;
    worker->jobs = NULL;
    worker->num_jobs = 0;
}

// Function to allocate memory for a dynamic array of job structures
job_t* alloc_jobs(size_t num_jobs) {
    job_t* jobs = (job_t*)malloc(num_jobs * sizeof(job_t));
    if (!jobs) {
        perror("Failed to allocate memory for job structures");
        exit(1);
    }
    return jobs;
}

// Function to initialize a job structure
void init_job(job_t* job, char* uuid, int status, void* result) {
    strcpy(job->uuid, uuid);
    job->status = status;
    job->result = result;
}

// Function to allocate memory for a dynamic array of task handler structures
task_handler_t* alloc_task_handlers(size_t num_task_handlers) {
    task_handler_t* task_handlers = (task_handler_t*)malloc(num_task_handlers * sizeof(task_handler_t));
    if (!task_handlers) {
        perror("Failed to allocate memory for task handler structures");
        exit(1);
    }
    return task_handlers;
}

// Function to initialize a task handler structure
void init_task_handler(task_handler_t* task_handler, void (*request_processor)(void*), void (*result_parser)(void*), void (*event_emitter)(void*)) {
    task_handler->request_processor = request_processor;
    task_handler->result_parser = result_parser;
    task_handler->event_emitter = event_emitter;
}

// Function to allocate memory for a dynamic array of metric entries
metric_t* alloc_metrics(size_t num_metrics) {
    metric_t* metrics = (metric_t*)malloc(num_metrics * sizeof(metric_t));
    if (!metrics) {
        perror("Failed to allocate memory for metric entries");
        exit(1);
    }
    return metrics;
}

// Function to initialize a metric entry
void init_metric(metric_t* metric, time_t timestamp, int value) {
    metric->timestamp = timestamp;
    metric->value = value;
}

// Function to add a job to the data structure
void add_job(char* uuid, int status, void* result) {
    pthread_mutex_lock(&lock);
    if (num_workers == 0) {
        perror("No worker threads available");
        exit(1);
    }
    // Find a free worker thread and assign the job to it
    for (size_t i = 0; i < num_workers; i++) {
        if (workers[i].num_jobs == 0) {
            init_job(workers[i].jobs + workers[i].num_jobs++, uuid, status, result);
            pthread_cond_signal(&cond);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Function to process a job asynchronously
void* process_job(void* arg) {
    worker_t* worker = (worker_t*)arg;
    while (1) {
        // Wait for a free job slot
        pthread_mutex_lock(&lock);
        while (worker->num_jobs == 0) {
            pthread_cond_wait(&cond, &lock);
        }
        // Process the job
        job_t* job = worker->jobs + worker->num_jobs - 1;
        task_handler_t* task_handler = task_handlers[job->status];
        if (task_handler) {
            (*task_handler->request_processor)(job);
            (*task_handler->result_parser)(job);
            (*task_handler->event_emitter)(job);
        } else {
            perror("Invalid job status");
            exit(1);
        }
        // Update the job status and result
        job->status = 0;
        job->result = NULL;
        worker->num_jobs--;
        pthread_mutex_unlock(&lock);
    }
}

// Function to start a worker thread
void start_worker(int id) {
    worker_t* worker = workers + id;
    if (pthread_create(&worker->thread, NULL, process_job, worker)) {
        perror("Failed to create worker thread");
        exit(1);
    }
}

// Function to stop a worker thread
void stop_worker(int id) {
    worker_t* worker = workers + id;
    pthread_cancel(&worker->thread);
}

// Function to add a task handler for a specific job status
void add_task_handler(int status, void (*request_processor)(void*), void (*result_parser)(void*), void (*event_emitter)(void*)) {
    pthread_mutex_lock(&lock);
    if (num_task_handlers == max_num_task_handlers) {
        perror("Maximum number of task handlers reached");
        exit(1);
    }
    init_task_handler(task_handlers + num_task_handlers++, request_processor, result_parser, event_emitter);
    pthread_mutex_unlock(&lock);
}

// Function to add a metric entry
void add_metric(time_t timestamp, int value) {
    pthread_mutex_lock(&lock);
    if (num_metrics == max_num_metrics) {
        perror("Maximum number of metrics reached");
        exit(1);
    }
    init_metric(metrics + num_metrics++, timestamp, value);
    pthread_mutex_unlock(&lock);
}

// Function to deallocate memory for a dynamic array of worker threads
void free_workers(worker_t* workers) {
    free(workers);
}

// Function to deallocate memory for a dynamic array of job structures
void free_jobs(job_t* jobs) {
    free(jobs);
}

// Function to deallocate memory for a dynamic array of task handler structures
void free_task_handlers(task_handler_t* task_handlers) {
    free(task_handlers);
}

// Function to deallocate memory for a dynamic array of metric entries
void free_metrics(metric_t* metrics) {
    free(metrics);
}
