// Function to parse and validate JSON documents
void parse_json(char* json, struct document_data* data) {
    // Parse JSON string into a JSON object
    json_object* obj = json_parse(json);

    // Validate JSON structure
    if (obj == NULL || !json_is_object(obj)) {
        printf("Invalid JSON\n");
        return;
    }

    // Get timestamp and event type from JSON object
    data->timestamp = json_get_int(obj, "timestamp");
    data->event_type = json_get_string(obj, "event_type");

    // Get user ID from JSON object
    data->user_id = json_get_int(obj, "user_id");

    // Get metadata from JSON object
    json_object* metadata_obj = json_get_object(obj, "metadata");
    if (metadata_obj != NULL) {
        int num_keys = json_object_num_keys(metadata_obj);
        for (int i = 0; i < num_keys; i++) {
            char* key = json_object_key_at(metadata_obj, i);
            char* value = json_get_string(metadata_obj, key);
            data->metadata[i].key = key;
            data->metadata[i].value = value;
        }
    }
}

