// Structure to represent a 'data' object
typedef struct {
    float value;
    char identifier;
    char* string;
} data_t;

// Function to allocate memory for a collection of 'data' objects
void allocate_data(int num_objects, data_t** data) {
    // Allocate memory for the array of pointers
    *data = (data_t*)malloc(num_objects * sizeof(data_t));
    if (*data == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data objects\n");
        return;
    }

    // Initialize each element of the array with a new 'data' object
    for (int i = 0; i < num_objects; i++) {
        (*data)[i].value = 0.0f;
        (*data)[i].identifier = '\0';
        (*data)[i].string = NULL;
    }
}

// Function to free memory for a collection of 'data' objects
void free_data(int num_objects, data_t** data) {
    // Free each element of the array
    for (int i = 0; i < num_objects; i++) {
        if ((*data)[i].string != NULL) {
            free((*data)[i].string);
        }
    }

    // Free the array of pointers
    free(*data);
}
