    // Allocate memory for the node and its children array
    Node* new_node = malloc(sizeof(Node));
    new_node->children = malloc(sizeof(struct Node*) * 10);

    // Initialize the node's fields
    new_node->value = value;
    new_node->identifier = identifier;

    return new_node;
