    // Free the memory for the node's children array
    free(node->children);

    // Free the memory for the node itself
    free(node);
}

// Define the function to insert a new node into the tree
void insert_node(Node* root, int value, char identifier) {
    // If the root node is null, create a new node and set it as the root
    if (root == NULL) {
        root = create_node(value, identifier);
    } else {
        // Find the appropriate position for the new node in the tree
        Node* current = root;
        while (current->children[0] != NULL) {
            if (current->identifier > identifier) {
                current = current->children[0];
            } else {
                current = current->children[1];
            }
        }

        // Create a new node and add it to the tree
        Node* new_node = create_node(value, identifier);
        if (current->identifier > identifier) {
            current->children[0] = new_node;
        } else {
            current->children[1] = new_node;
        }
    }
}

// Define the function to delete a node from the tree
void delete_node(Node* root, char identifier) {
    // If the root node is null or the identifier does not exist in the tree, return
    if (root == NULL || root->identifier != identifier) {
        return;
    }

    // Find the node to be deleted and its parent
    Node* current = root;
    while (current->children[0] != NULL && current->children[1] != NULL) {
        if (current->identifier > identifier) {
            current = current->children[0];
        } else {
            current = current->children[1];
        }
    }

    // If the node to be deleted is a leaf, simply remove it from its parent's children array
    if (current->children[0] == NULL && current->children[1] == NULL) {
        Node* parent = current->parent;
        int index = 0;
        while (parent->children[index] != current) {
            index++;
        }
        free(parent->children[index]);
        parent->children[index] = NULL;
    } else if (current->children[0] == NULL && current->children[1] != NULL) {
        // If the node to be deleted has only one child, replace it with its child and free the memory for the node
        Node* child = current->children[1];
        Node* parent = current->parent;
        int index = 0;
        while (parent->children[index] != current) {
            index++;
        }
        parent->children[index] = child;
        free(current);
    } else if (current->children[0] != NULL && current->children[1] == NULL) {
        // If the node to be deleted has only one child, replace it with its child and free the memory for the node
        Node* child = current->children[0];
        Node* parent = current->parent;
        int index = 0;
        while (parent->children[index] != current) {
            index++;
        }
        parent->children[index] = child;
        free(current);
    } else if (current->children[0] != NULL && current->children[1] != NULL) {
        // If the node to be deleted has two children, find its successor and replace it with its successor's value
        Node* successor = current->children[1];
        while (successor->children[0] != NULL) {
            successor = successor->children[0];
        }
        current->value = successor->value;
    }
}

// Define the function to search for a node in the tree
Node* search_node(Node* root, char identifier) {
    // If the root node is null or the identifier does not exist in the tree, return NULL
    if (root == NULL || root->identifier != identifier) {
        return NULL;
    }

    // Find the node with the given identifier and return it
    Node* current = root;
    while (current->children[0] != NULL && current->children[1] != NULL) {
        if (current->identifier > identifier) {
            current = current->children[0];
        } else {
            current = current->children[1];
        }
    }

    return current;
}

// Define the function to traverse the tree and perform operations on each node
void traverse_tree(Node* root, void (*operation)(Node*)) {
    // If the root node is null, return
    if (root == NULL) {
        return;
    }

    // Traverse the tree recursively and perform the operation on each node
    for (int i = 0; i < 2; i++) {
        if (root->children[i] != NULL) {
            traverse_tree(root->children[i], operation);
        }
    }

    // Perform the operation on the current node
