    struct Node** children;
} Node;

// Define the tree structure
typedef struct Tree {
    Node* root;
    pthread_mutex_t mutex;
} Tree;

// Initialize a new node with the given value and identifier
Node* initNode(int value, char identifier) {
    Node* node = malloc(sizeof(Node));
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->identifier = identifier;
    node->children = NULL;
    return node;
}

// Initialize a new tree with the given root node
Tree* initTree(Node* root) {
    Tree* tree = malloc(sizeof(Tree));
    if (tree == NULL) {
        return NULL;
    }
    tree->root = root;
    pthread_mutex_init(&tree->mutex, NULL);
    return tree;
}

// Insert a new node with the given value and identifier into the tree
void insertNode(Tree* tree, int value, char identifier) {
    Node* node = initNode(value, identifier);
    if (node == NULL) {
        return;
    }
    pthread_mutex_lock(&tree->mutex);
    // Insert the new node into the tree
    if (tree->root == NULL) {
        tree->root = node;
    } else {
        Node* current = tree->root;
        while (current != NULL) {
            if (current->value > value) {
                if (current->left == NULL) {
                    current->left = node;
                    break;
                } else {
                    current = current->left;
                }
            } else if (current->value < value) {
                if (current->right == NULL) {
                    current->right = node;
                    break;
                } else {
                    current = current->right;
                }
            } else {
                // Duplicate identifier, do nothing
                free(node);
                break;
            }
        }
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Delete a node with the given value from the tree
void deleteNode(Tree* tree, int value) {
    pthread_mutex_lock(&tree->mutex);
    // Find the node to be deleted
    Node* current = tree->root;
    while (current != NULL) {
        if (current->value == value) {
            break;
        } else if (current->value > value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
    // Delete the node and its children
    if (current != NULL) {
        Node* child = current->children;
        while (child != NULL) {
            deleteNode(tree, child->value);
            child = child->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Search for a node with the given value in the tree
Node* searchNode(Tree* tree, int value) {
    pthread_mutex_lock(&tree->mutex);
    // Find the node to be searched
    Node* current = tree->root;
    while (current != NULL) {
        if (current->value == value) {
            break;
        } else if (current->value > value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }
    pthread_mutex_unlock(&tree->mutex);
    return current;
}

// Free all allocated memory for the tree
void freeTree(Tree* tree) {
    pthread_mutex_lock(&tree->mutex);
    // Free the root node and its children
    Node* current = tree->root;
    while (current != NULL) {
        Node* child = current->children;
        while (child != NULL) {
            freeTree(child);
            child = child->next;
        }
        free(current);
        current = current->next;
    }
    pthread_mutex_unlock(&tree->mutex);
}

// Test the correctness of the tree operations under various scenarios
void testTreeOperations() {
    Tree* tree = initTree();
    // Insert nodes with different values and identifiers
    insertNode(tree, 10, 'a');
    insertNode(tree, 5, 'b');
    insertNode(tree, 20, 'c');
    insertNode(tree, 15, 'd');
    // Delete nodes with different values
    deleteNode(tree, 5);
    deleteNode(tree, 15);
    // Search for nodes with different values
    Node* node = searchNode(tree, 10);
    CU_ASSERT(node != NULL && node->value == 10 && node->identifier == 'a');
    node = searchNode(tree, 20);
    CU_ASSERT(node != NULL && node->value == 20 && node->identifier == 'c');
    // Free the tree
    freeTree(tree);
}
