    List* list = malloc(sizeof(List));
    if (!list) {
        return NULL;
    }
    list->nodes = malloc(sizeof(Node*) * 16);
    if (!list->nodes) {
        free(list);
        return NULL;
    }
    list->capacity = 16;
    list->count = 0;
    return list;
}

void destroyList(List* list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->nodes[i]);
    }
    free(list->nodes);
    free(list);
}

