    node->string = strdup(string);
    node->priority = priority;
    node->timestamp = timestamp;
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        Node** newNodes = realloc(list->nodes, sizeof(Node*) * newCapacity);
        if (!newNodes) {
            free(node);
            return -3;
