        index++;
    }
    if (index == list->count) {
        return -2;
    }
    free(list->nodes[index]);
    memmove(list->nodes + index, list->nodes + index + 1, sizeof(Node*) * (list->count - index - 1));
    list->count--;
    return 0;
}

int retrieveNode(List* list, char* string) {
    if (!list || !string) {
        return -1;
    }
    size_t index = 0;
    while (index < list->count && strcmp(list->nodes[index]->string, string) != 0) {
        index++;
    }
    if (index == list->count) {
        return -2;
    }
    return index;
}

