// Insert a new node into the list with the given data and priority
int insert(List* list, char* data, int priority) {
    // Acquire lock on the list
    pthread_mutex_lock(&list->mutex);

    // Create a new node with the given data and priority
    Node* new_node = (Node*)my_alloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure gracefully
