#define MAX_CONFIGURATIONS 1024
#define MAX_UPDATE_BUFFER_SIZE 1024
#define MIN_VERSION_LENGTH 3
#define MAX_VERSION_LENGTH 64
#define VERSION_RANGE 1000000

typedef struct {
    size_t byte_size;
    char version[MAX_VERSION_LENGTH];
} configuration_setting;

typedef struct {
    configuration_setting *settings;
    int num_settings;
    pthread_mutex_t mutex;
} configuration_manager;

configuration_manager *create_configuration_manager(int num_configurations) {
    if (num_configurations > MAX_CONFIGURATIONS) {
        return NULL;
    }
    configuration_manager *manager = malloc(sizeof(configuration_manager));
    manager->settings = malloc(sizeof(configuration_setting) * num_configurations);
    manager->num_settings = num_configurations;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_configuration_manager(configuration_manager *manager) {
    if (manager == NULL) {
        return;
    }
    free(manager->settings);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int allocate_configuration_setting(configuration_manager *manager, size_t byte_size, char *version) {
    if (manager == NULL || version == NULL || strlen(version) < MIN_VERSION_LENGTH || strlen(version) > MAX_VERSION_LENGTH) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    int index = manager->num_settings++;
    configuration_setting *setting = &manager->settings[index];
    setting->byte_size = byte_size;
    strncpy(setting->version, version, MAX_VERSION_LENGTH);
    pthread_mutex_unlock(&manager->mutex);
    return index;
}

int update_configuration_setting(configuration_manager *manager, int index, size_t byte_size, char *version) {
    if (manager == NULL || version == NULL || strlen(version) < MIN_VERSION_LENGTH || strlen(version) > MAX_VERSION_LENGTH) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    configuration_setting *setting = &manager->settings[index];
    setting->byte_size = byte_size;
    strncpy(setting->version, version, MAX_VERSION_LENGTH);
    pthread_mutex_unlock(&manager->mutex);
    return index;
}

int get_configuration_setting(configuration_manager *manager, int index) {
    if (manager == NULL || index < 0 || index >= manager->num_settings) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    configuration_setting *setting = &manager->settings[index];
    size_t byte_size = setting->byte_size;
    char version[MAX_VERSION_LENGTH];
    strncpy(version, setting->version, MAX_VERSION_LENGTH);
    pthread_mutex_unlock(&manager->mutex);
    return byte_size;
}

int serialize_configuration_settings(configuration_manager *manager, char *buffer) {
    if (manager == NULL || buffer == NULL) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    int num_bytes = 0;
    for (int i = 0; i < manager->num_settings; i++) {
        configuration_setting *setting = &manager->settings[i];
        size_t byte_size = setting->byte_size;
        char version[MAX_VERSION_LENGTH];
        strncpy(version, setting->version, MAX_VERSION_LENGTH);
        num_bytes += sprintf(buffer + num_bytes, "%d:%lu:%s\n", i, byte_size, version);
    }
    pthread_mutex_unlock(&manager->mutex);
    return num_bytes;
}

int deserialize_configuration_settings(configuration_manager *manager, char *buffer) {
    if (manager == NULL || buffer == NULL) {
        return -1;
    }
    pthread_mutex_lock(&manager->mutex);
    int num_bytes = 0;
    for (int i = 0; i < manager->num_settings; i++) {
        configuration_setting *setting = &manager->settings[i];
        size_t byte_size = setting->byte_size;
        char version[MAX_VERSION_LENGTH];
        strncpy(version, setting->version, MAX_VERSION_LENGTH);
        num_bytes += sprintf(buffer + num_bytes, "%d:%lu:%s\n", i, byte_size, version);
    }
    pthread_mutex_unlock(&manager->mutex);
    return num_bytes;
}
