#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <limits.h>
#include <pthread.h>
#include <sys/mman.h>
#include <unistd.h>
#include <errno.h>

#define MAX_RECORDS 1000000
#define MAX_LOG_BUFFER_SIZE 1000000
#define MIN_STATUS 200
#define MAX_STATUS 599
#define STATUS_RANGE (MAX_STATUS - MIN_STATUS + 1)
#define TIMESTAMP_RANGE (end_time - start_time)

struct DataRecord {
    time_t datetime;
    int status_code;
    struct TransactionLog* log;
};

struct TransactionLog {
    time_t timestamp;
    char* message;
};

void* allocate_memory(size_t size) {
    void* ptr = NULL;
    while (ptr == NULL) {
        ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (ptr == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
    return ptr;
}

void* initialize_memory(size_t size, void* ptr) {
    memset(ptr, 0, size);
    return ptr;
}

struct DataRecord* allocate_records(int num_objects) {
    if (num_objects > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    size_t size = sizeof(struct DataRecord) * num_objects;
    void* ptr = allocate_memory(size);
    return initialize_memory(size, ptr);
}

void initialize_records(struct DataRecord* records, int num_objects) {
    for (int i = 0; i < num_objects; i++) {
        struct DataRecord* record = &records[i];
        record->datetime = start_time + (rand() % TIMESTAMP_RANGE);
        record->status_code = MIN_STATUS + (rand() % STATUS_RANGE);
        record->log = NULL;
    }
}

void* allocate_logs(int num_objects) {
    size_t size = sizeof(struct TransactionLog) * num_objects;
    void* ptr = allocate_memory(size);
    return initialize_memory(size, ptr);
}

void initialize_logs(struct DataRecord* records, int num_objects) {
    for (int i = 0; i < num_objects; i++) {
        struct DataRecord* record = &records[i];
        record->log = allocate_logs(1);
        record->log->timestamp = record->datetime;
        record->log->message = "Transaction completed successfully.";
    }
}

void print_usage() {
    printf("Usage: ./program [options]\n");
    printf("\t-h, --help\tPrint this help message and exit.\n");
    printf("\t-v\t\tEnable verbose mode.\n");
    printf("\t-f FILE\t\tWrite output to FILE.\n");
}

int main(int argc, char** argv) {
    int num_objects = 0;
    time_t start_time = 0;
    time_t end_time = 0;
    struct DataRecord* records = NULL;
    struct TransactionLog* logs = NULL;
    bool verbose = false;
    char* output_file = NULL;

    // Parse command line options
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            return EXIT_SUCCESS;
        } else if (strcmp(argv[i], "-v") == 0) {
            verbose = true;
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            output_file = argv[++i];
        } else {
            num_objects = atoi(argv[i]);
        }
    }

    // Validate input parameters
    if (num_objects <= 0 || num_objects > MAX_RECORDS) {
        fprintf(stderr, "Error: Invalid number of records.\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for records and logs
    records = allocate_records(num_objects);
    logs = allocate_logs(num_objects);

    // Initialize records and logs
    initialize_records(records, num_objects);
    initialize_logs(records, num_objects);

    // Print output to file if specified
    if (output_file != NULL) {
        FILE* fp = fopen(output_file, "w");
        if (fp == NULL) {
            perror("fopen");
            return EXIT_FAILURE;
        }
        for (int i = 0; i < num_objects; i++) {
            struct DataRecord* record = &records[i];
            fprintf(fp, "%d %ld %s\n", record->status_code, record->datetime, record->log->message);
        }
        fclose(fp);
    }

    // Clean up memory
    free(records);
    free(logs);

    return EXIT_SUCCESS;
}
```
