} Edge;

// Function to manage memory allocation and initialization for a dynamic database-like structure
void initializeDatabase(int numRecords, int minValue, int maxValue, bool uniqueKeys) {
  // Allocate memory for an array of 'Record' structures
  Record* records = (Record*)malloc(numRecords * sizeof(Record));
  if (!records) {
    printf("Error: Failed to allocate memory for the database\n");
    return;
  }

  // Initialize the integer values in each record to a random number within the specified range
  srand(time(NULL));
  for (int i = 0; i < numRecords; i++) {
    records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    if (uniqueKeys) {
      snprintf(records[i].key, sizeof(records[i].key), "%d", i);
    }
  }

  // Add a random number of vertices and edges to the graph
  int numVertices = rand() % (numRecords / 2) + 1;
  Vertex* vertices = (Vertex*)malloc(numVertices * sizeof(Vertex));
  if (!vertices) {
    printf("Error: Failed to allocate memory for the vertices\n");
    return;
  }
  int numEdges = rand() % (numRecords / 2) + 1;
  Edge* edges = (Edge*)malloc(numEdges * sizeof(Edge));
  if (!edges) {
    printf("Error: Failed to allocate memory for the edges\n");
    return;
  }
  for (int i = 0; i < numVertices; i++) {
    vertices[i].id = i;
    vertices[i].degree = rand() % (numRecords / 2) + 1;
    for (int j = 0; j < vertices[i].degree; j++) {
      edges[j].source_id = i;
      edges[j].target_id = rand() % numVertices;
      while (edges[j].target_id == i) {
        edges[j].target_id = rand() % numVertices;
      }
    }
  }
}

