    // Handle filenames with no extension or multiple extensions gracefully
    if (extension == NULL) {
        strcat(newFilename, FILE_EXTENSION);
    } else if (strcmp(extension, FILE_EXTENSION) != 0) {
        printf("Error: Invalid file extension\n");
        return;
    }

    // Ensure that the new filename does not exceed a maximum length of 255 characters
    int newFilenameLength = strlen(newFilename);
    if (newFilenameLength > MAX_FILENAME_LENGTH) {
        // Append a unique identifier to the base name to ensure uniqueness within the current directory
        char* uniqueIdentifier = (char*)malloc(MAX_FILENAME_LENGTH + 1);
        snprintf(uniqueIdentifier, MAX_FILENAME_LENGTH + 1, "%ld", (long)time(NULL));
        strcat(newFilename, uniqueIdentifier);
