    // Preserve the original filename if the new filename exceeds the maximum length constraint
    if (strlen(newFilename) > MAX_FILENAME_LENGTH) {
        printf("Error: New filename exceeds maximum length of 255 characters\n");
        return;
    }

    // Handle Unicode filenames and filenames containing special characters
    for (int i = 0; i < strlen(newFilename); i++) {
        if (!isalnum(newFilename[i]) && newFilename[i] != '_' && newFilename[i] != '.') {
            printf("Error: Invalid character in filename\n");
            return;
