    char* modifiedFilename = (char*)malloc(MAX_FILENAME_LENGTH + 1);
    if (!modifiedFilename) {
        printf("Error: Insufficient memory to allocate modified filename\n");
        return;
    }
    sprintf(modifiedFilename, "%s", newFilename);

    // Free memory allocated for the new filename and return the modified filename
    free(newFilename);
    return modifiedFilename;
}
