        score = (double)rand() / RAND_MAX * 10.0;

        // Populate the timestamp with the current time
        timestamp = time(NULL);

        // Store the feedback data in the allocated arrays
        feedbacks[i] = malloc(sizeof(struct feedback));
        metadata[i] = malloc(sizeof(struct metadata));
        statuses[i] = malloc(sizeof(enum status));
        strcpy(feedbacks[i]->title, title);
        feedbacks[i]->ID = ID;
        feedbacks[i]->score = score;
        feedbacks[i]->timestamp = timestamp;
        strcpy(metadata[i]->user_id, user_id);
        statuses[i] = VALID;
    }

    // Free the JSON object and return the allocated arrays
    json_object_put(json);
    return feedbacks;
}
