void init_dataset(const char* filename, dataset_t** dataset) {
    // Open the CSV file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open CSV file\n");
        return;
    }

    // Read the header line and skip it
    char header[1024];
    fgets(header, 1024, fp);

    // Initialize the dataset with an initial size of 100 elements
