        feedbacks[i].timestamp = current_time;
    }
}

// Define the function to handle rate limiting
void handle_rate_limiting(CURL *curl, long http_code) {
    if (http_code == 429) {
        // Handle rate limiting by delaying between requests
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10);
    } else if (http_code == 503) {
        // Handle rate limiting by using backoff strategies
        curl_easy_setopt(curl, CURLOPT_RETRYCOUNT, 3);
        curl_easy_setopt(curl, CURLOPT_RETRYDELAY, 10);
    } else {
        fprintf(stderr, "HTTP error: %ld\n", http_code);
    }
}

