// Define custom memory pool for node objects
struct node_pool {
    struct node *nodes[10];
    int num_nodes;
};

void init_node_pool(struct node_pool *pool) {
    memset(pool, 0, sizeof(*pool));
}

void add_node_to_pool(struct node_pool *pool, struct node *node) {
    if (pool->num_nodes < 10) {
        pool->nodes[pool->num_nodes++] = node;
    } else {
        fprintf(stderr, "Error: Node pool is full\n");
        exit(1);
    }
}

struct node *get_node_from_pool(struct node_pool *pool) {
    if (pool->num_nodes > 0) {
        return pool->nodes[--pool->num_nodes];
    } else {
        fprintf(stderr, "Error: Node pool is empty\n");
