    total_size += sizeof(char) * 256 * num_strings;
    total_size += sizeof(struct point) * num_points;

    // Check if total size exceeds maximum allowed size
    if (total_size > MAX_MEMORY_SIZE) {
        fprintf(stderr, "Error: Total memory size exceeds maximum allowed size\n");
        exit(1);
    }

    // Allocate memory for structures
    void *memory = allocate_memory(total_size);

    // Initialize node objects
    struct node *nodes = (struct node *)memory;
    memory += sizeof(struct node) * num_nodes;
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].parent = NULL;
        nodes[i].ref_count = 0;
        nodes[i].value = '\0';
    }

    // Initialize edge objects
    struct edge *edges = (struct edge *)memory;
    memory += sizeof(struct edge) * num_edges;
    for (int i = 0; i < num_edges; i++) {
        edges[i].src = NULL;
        edges[i].dst = NULL;
        edges[i].index = 0;
        edges[i].weight = 0.0;
    }

    // Initialize graph objects
    struct graph *graphs = (struct graph *)memory;
    memory += sizeof(struct graph) * num_graphs;
    for (int i = 0; i < num_graphs; i++) {
        graphs[i].edges = NULL;
        graphs[i].num_edges = 0;
    }

    // Initialize metadata objects
    struct metadata *metadata = (struct metadata *)memory;
    memory += sizeof(struct metadata) * num_metadata;
    for (int i = 0; i < num_metadata; i++) {
        metadata[i].version = 0;
        metadata[i].timestamp = 0;
    }

    // Initialize config objects
    struct config *configs = (struct config *)memory;
    memory += sizeof(struct config) * num_configs;
    for (int i = 0; i < num_configs; i++) {
        configs[i].settings = NULL;
    }

    // Initialize string objects
    char *strings = (char *)memory;
    memory += sizeof(char) * 256 * num_strings;
    for (int i = 0; i < num_strings; i++) {
        strings[i] = '\0';
    }

    // Initialize point objects
    struct point *points = (struct point *)memory;
    memory += sizeof(struct point) * num_points;
    for (int i = 0; i < num_points; i++) {
        points[i].x = 0.0;
        points[i].y = 0.0;
    }

    // Initialize node pools
    init_node_pool(&node_pool);

    // Initialize edge pools
    init_edge_pool(&edge_pool);

    // Initialize graph pools
    init_graph_pool(&graph_pool);

    // Initialize metadata pools
    init_metadata_pool(&metadata_pool);

    // Initialize config pools
    init_config_pool(&config_pool);

    // Initialize string pools
    init_string_pool(&string_pool);

    // Initialize point pools
    init_point_pool(&point_pool);

    return memory;
}

// Define function to free structures
void free_structures(void *memory) {
    // Free all allocated memory
    if (memory != NULL) {
        free(memory);
        memory = NULL;
    }
}

int main() {
    int num_nodes = 10;
    int num_edges = 20;
    int num_graphs = 3;
    int num_metadata = 5;
    int num_configs = 2;
    int num_strings = 8;
    int num_points = 10;

    // Allocate and initialize structures
    void *memory = allocate_structures(num_nodes, num_edges, num_graphs, num_metadata, num_configs, num_strings, num_points);

    // Use the allocated memory for your application

    // Free all allocated memory
    free_structures(memory);

    return 0;
}
