#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a structure for records
typedef struct record {
    int key;
} Record;

// Define a function to dynamically allocate memory for arrays and initialize linked list of records
void init_records(int num_offsets, int num_keys, int min_key, int max_key) {
    // Allocate memory for offset array
    long *offsets = malloc(num_offsets * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize offset array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for key array
    int *keys = malloc(num_keys * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        return;
    }

    // Initialize key array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for record array
    Record *records = malloc(num_offsets * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize record array with random values within specified range
    srand(time(NULL));
    for (int i = 0; i < num_offsets; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }

    // Initialize linked list of records
    Record *current = records;
    for (int i = 0; i < num_offsets - 1; i++) {
        current->next = &records[i + 1];
        current = current->next;
    }
    current->next = NULL;

    // Free memory at the end of the function
    free(offsets);
    free(keys);
    free(records);
}
