    }

    // Parse the line and add it to the records list
    char* token = strtok(line, ",");
    while (token != NULL) {
        long offset = atol(token);
        token = strtok(NULL, ",");
        int key = atoi(token);
        token = strtok(NULL, ",");
        float precision = atof(token);
