        add_record(records, offset, key, precision, accuracy, index, string_identifier, flag);
        token = strtok(NULL, "\n");
    }
}

// Define the function to handle command line options
void handle_options(RecordsList* records, int argc, char** argv) {
    // Check if the --help option was specified
    if (argc > 1 && strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s [OPTION]...\n", argv[0]);
        printf("  -c, --count=N      set the number of records to initialize\n");
        printf("  -o, --output=FILE  write output to FILE\n");
        exit(EXIT_SUCCESS);
    }

    // Check if the --count option was specified
    int count = 0;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "--count") == 0) {
            if (++i >= argc) {
                fprintf(stderr, "Error: missing argument for --count\n");
                exit(EXIT_FAILURE);
            }
            count = atoi(argv[i]);
        } else if (strcmp(argv[i], "-o") == 0 || strcmp(argv[i], "--output") == 0) {
            if (++i >= argc) {
                fprintf(stderr, "Error: missing argument for --output\n");
                exit(EXIT_FAILURE);
            }
            FILE* output = fopen(argv[i], "w");
            if (!output) {
                fprintf(stderr, "Error: failed to open output file %s\n", argv[i]);
                exit(EXIT_FAILURE);
            }
            // Write the number of records to the output file
            fprintf(output, "%d\n", count);
            // Close the output file
            fclose(output);
        } else {
            fprintf(stderr, "Error: invalid option %s\n", argv[i]);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize the records list with the specified number of records
    init_records(records);
    for (int i = 0; i < count; i++) {
        add_record(records, i, i, i * 1.0f, i * 1.0, i, "string", true);
    }
}

