// Define the function to handle high-throughput scenarios and is robust against errors
void handle_high_throughput(RecordsList* records) {
    // Use a lock to ensure thread-safe access to the records list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define the function to handle a single record
    void handle_record(Record* record) {
        // Lock the mutex before accessing the records list
        pthread_mutex_lock(&mutex);
        // Add the record to the records list
        add_record(records, record->offset, record->key, record->precision, record->accuracy, record->index, record->string_identifier, record->flag);
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to handle a batch of records
    void handle_batch(Record* records, size_t num_records) {
        // Lock the mutex before accessing the records list
        pthread_mutex_lock(&mutex);
        // Add the records to the records list
        for (size_t i = 0; i < num_records; i++) {
            add_record(records, records[i].offset, records[i].key, records[i].precision, records[i].accuracy, records[i].index, records[i].string_identifier, records[i].flag);
        }
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }

