                exit(EXIT_FAILURE);
            }
            strcpy(string_identifier, token);
            token = strtok(NULL, ",");
            bool flag = atoi(token) == 1;
            add_record(records, offset, key, precision, accuracy, index, string_identifier, flag);
            token = strtok(NULL, "\n");
        }
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }
}

// Define the function to monitor memory usage in real-time and implement a dynamic resizing mechanism
void monitor_memory(RecordsList* records) {
    // Use a lock to ensure thread-safe access to the records list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define the function to monitor memory usage in real-time
    void monitor_memory_usage() {
        // Lock the mutex before accessing the records list
        pthread_mutex_lock(&mutex);
        // Check if there is enough memory available for the new record
        if (records->num_records >= 10000) {
            fprintf(stderr, "Error: no more space in records list\n");
            exit(EXIT_FAILURE);
        }
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to implement a dynamic resizing mechanism
    void resize_records() {
        // Lock the mutex before accessing the records list
        pthread_mutex_lock(&mutex);
        // Reallocate memory for the records list with a new size
        Record* new_records = (Record*)realloc(records->records, sizeof(Record) * 20000);
        if (!new_records) {
            fprintf(stderr, "Error: failed to reallocate memory for records\n");
            exit(EXIT_FAILURE);
        }
        // Update the records list with the new size
        records->records = new_records;
        records->num_records = 0;
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }
}

// Define the function to periodically evaluate the cache hit rate and adjust memory allocation policies accordingly
void evaluate_cache_hit_rate() {
    // Use a lock to ensure thread-safe access to the records list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define the function to periodically evaluate the cache hit rate
    void evaluate_cache_hit_rate() {
        // Lock the mutex before accessing the records list
        pthread_mutex_lock(&mutex);
        // Check if there is enough memory available for the new record
        if (records->num_records >= 10000) {
            fprintf(stderr, "Error: no more space in records list\n");
            exit(EXIT_FAILURE);
        }
        // Unlock the mutex after accessing the records list
        pthread_mutex_unlock(&mutex);
    }
}

// Define the function to implement a logging mechanism
void log_records() {
    // Use a lock to ensure thread-safe access to the records list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

