    private int[] errorCodes;

    public NetworkMonitorHelper(int initialSize = 100, int minLatencyMeasurementValue = 0, int maxLatencyMeasurementValue = 1000)
    {
        this.latencyMeasurements = new long[initialSize];
        this.packetIdentifiers = new uint32_t[initialSize];
        this.packets = new LinkedList<Packet>();
        this.packetTimestamps = new timeval[initialSize];
        this.errorCodes = new int[initialSize];

        for (int i = 0; i < initialSize; i++)
        {
            this.latencyMeasurements[i] = UnityEngine.Random.Range(minLatencyMeasurementValue, maxLatencyMeasurementValue);
            this.packetIdentifiers[i] = (uint32_t)UnityEngine.Random.Range(0, int.MaxValue);
        }
    }

    public void AddPacket(long latencyMeasurement, uint32_t packetIdentifier, Packet packet, timeval timestamp, int errorCode)
    {
        this.latencyMeasurements[this.packets.Count] = latencyMeasurement;
        this.packetIdentifiers[this.packets.Count] = packetIdentifier;
        this.packets.AddLast(packet);
        this.packetTimestamps[this.packets.Count] = timestamp;
        this.errorCodes[this.packets.Count] = errorCode;
    }

    public void RemovePacket(int index)
    {
        this.latencyMeasurements[index] = 0;
        this.packetIdentifiers[index] = 0;
        this.packets.RemoveAt(index);
        this.packetTimestamps[index] = new timeval();
        this.errorCodes[index] = 0;
    }

    public void UpdatePacket(int index, long latencyMeasurement, uint32_t packetIdentifier, Packet packet, timeval timestamp, int errorCode)
    {
        this.latencyMeasurements[index] = latencyMeasurement;
        this.packetIdentifiers[index] = packetIdentifier;
        this.packets[index] = packet;
        this.packetTimestamps[index] = timestamp;
        this.errorCodes[index] = errorCode;
    }

    public void Clear()
    {
        for (int i = 0; i < this.latencyMeasurements.Length; i++)
        {
            this.latencyMeasurements[i] = 0;
            this.packetIdentifiers[i] = 0;
            this.packets[i] = null;
            this.packetTimestamps[i] = new timeval();
            this.errorCodes[i] = 0;
        }
    }

    public void Resize(int newSize)
    {
        long[] newLatencyMeasurements = new long[newSize];
        uint32_t[] newPacketIdentifiers = new uint32_t[newSize];
        LinkedList<Packet> newPackets = new LinkedList<Packet>();
        timeval[] newPacketTimestamps = new timeval[newSize];
        int[] newErrorCodes = new int[newSize];

        for (int i = 0; i < Math.Min(this.latencyMeasurements.Length, newSize); i++)
        {
            newLatencyMeasurements[i] = this.latencyMeasurements[i];
            newPacketIdentifiers[i] = this.packetIdentifiers[i];
            newPackets.AddLast(this.packets[i]);
            newPacketTimestamps[i] = this.packetTimestamps[i];
            newErrorCodes[i] = this.errorCodes[i];
        }

        for (int i = Math.Min(this.latencyMeasurements.Length, newSize); i < newSize; i++)
        {
            newLatencyMeasurements[i] = UnityEngine.Random.Range(0, int.MaxValue);
            newPacketIdentifiers[i] = (uint32_t)UnityEngine.Random.Range(0, int.MaxValue);
        }

        this.latencyMeasurements = newLatencyMeasurements;
        this.packetIdentifiers = newPacketIdentifiers;
        this.packets = newPackets;
        this.packetTimestamps = newPacketTimestamps;
        this.errorCodes = newErrorCodes;
    }

    public void FilterPackets(Predicate<Packet> filter)
    {
        for (int i = 0; i < this.packets.Count; i++)
