#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

// Define data structures for offset, key, record, and string identifiers
typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    float precision;
    double accuracy;
    int index;
    char* string_identifier;
    bool flag;
} Record;

typedef struct {
    char* identifier;
} StringIdentifier;

// Define a function to dynamically allocate memory for and initialize multiple data structures
int init_data_structures(int num_records, int max_length, float min_precision, float max_precision, double min_accuracy, double max_accuracy) {
    // Initialize variables
    int i;
    long offset = 0;
    int key = 0;
    float precision = 0.0f;
    double accuracy = 0.0;
    char* string_identifier = NULL;
    bool flag = false;
    StringIdentifier* string_identifiers = NULL;
    Record* records = NULL;
    Offset* offsets = NULL;
    Key* keys = NULL;

    // Allocate memory for data structures
    offsets = (Offset*)malloc(num_records * sizeof(Offset));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offset array\n");
        return -1;
    }
    keys = (Key*)malloc(num_records * sizeof(Key));
    if (!keys) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsets);
        return -1;
    }
    records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        printf("Error: Failed to allocate memory for record array\n");
        free(keys);
        free(offsets);
        return -1;
    }
    string_identifiers = (StringIdentifier*)malloc(num_records * sizeof(StringIdentifier));
    if (!string_identifiers) {
        printf("Error: Failed to allocate memory for string identifier array\n");
        free(records);
        free(keys);
        free(offsets);
        return -1;
    }

    // Initialize data structures
    for (i = 0; i < num_records; i++) {
        offsets[i].offset = offset;
        keys[i].key = key;
        records[i].precision = precision;
        records[i].accuracy = accuracy;
        records[i].index = i;
        records[i].string_identifier = string_identifier;
        records[i].flag = flag;
        string_identifiers[i].identifier = string_identifier;
    }

    // Set random values for float and double fields
    srand(time(NULL));
    for (i = 0; i < num_records; i++) {
        precision = min_precision + ((float)rand() / RAND_MAX) * (max_precision - min_precision);
        accuracy = min_accuracy + ((double)rand() / RAND_MAX) * (max_accuracy - min_accuracy);
    }

    // Generate unique file paths for each entry
    for (i = 0; i < num_records; i++) {
        string_identifier = generate_string_identifier(max_length);
        if (!string_identifier) {
            printf("Error: Failed to generate string identifier\n");
            free(records);
            free(keys);
            free(offsets);
            return -1;
        }
    }

    // Determine existence status of files based on their paths
    for (i = 0; i < num_records; i++) {
        if (!file_exists(string_identifiers[i].identifier)) {
            printf("Error: File does not exist\n");
            free(records);
            free(keys);
            free(offsets);
            return -1;
        }
    }

    // Free memory for data structures
    free(string_identifiers);
    free(records);
    free(keys);
    free(offsets);

    return num_records;
}

// Define a function to generate unique string identifiers
char* generate_string_identifier(int max_length) {
    // Initialize variables
    int i;
    char* identifier = NULL;
    bool duplicate = true;

    // Generate random string identifier
    while (duplicate) {
        identifier = (char*)malloc(max_length * sizeof(char));
        if (!identifier) {
            printf("Error: Failed to allocate memory for string identifier\n");
            return NULL;
        }
        for (i = 0; i < max_length; i++) {
            identifier[i] = 'a' + ((int)rand() % ('z' - 'a'));
        }
        duplicate = false;
    }

    return identifier;
}

// Define a function to check if a file exists
bool file_exists(char* path) {
    // Initialize variables
    FILE* fp = NULL;

