#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the maximum length of a filename (including extension)
#define MAX_FILENAME_LENGTH 255

// Define the file type extension to be used for new filenames
#define FILE_EXTENSION ".txt"

// Define the number of digits in the base name
#define BASE_NAME_DIGITS 3

// Define the hash table size (number of buckets)
#define HASH_TABLE_SIZE 10

// Define the maximum number of nodes per bucket
#define MAX_NODES_PER_BUCKET 10

// Define the structure for a record in the database
typedef struct {
    int value;
    struct entry *entries;
} record;

// Define the structure for an entry in the linked list
typedef struct {
    long offset;
    struct entry *next;
} entry;

// Define the structure for a bucket in the hash table
typedef struct {
    int size;
    struct node **nodes;
} bucket;

// Define the structure for a node in the hash table
typedef struct {
    char *key;
    double value;
} node;

// Function to manage dynamic memory allocation and initialization for the database
void initialize_database(record *records, int num_records) {
    // Allocate memory for the linked list of entries
    records->entries = (struct entry *)malloc(sizeof(struct entry) * num_records);
    if (!records->entries) {
        printf("Error: unable to allocate memory for linked list\n");
        exit(1);
    }

    // Initialize the linked list of entries
    for (int i = 0; i < num_records; i++) {
        records->entries[i].offset = -1;
        records->entries[i].next = NULL;
    }

    // Allocate memory for the hash table
    bucket *buckets = (bucket *)malloc(sizeof(bucket) * HASH_TABLE_SIZE);
    if (!buckets) {
        printf("Error: unable to allocate memory for hash table\n");
        exit(1);
    }

    // Initialize the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        buckets[i].size = 0;
        buckets[i].nodes = (struct node **)malloc(sizeof(struct node *) * MAX_NODES_PER_BUCKET);
        if (!buckets[i].nodes) {
            printf("Error: unable to allocate memory for hash table nodes\n");
            exit(1);
        }
    }

    // Insert data into the linked list and update the hash table as necessary
    for (int i = 0; i < num_records; i++) {
        record *record = &records[i];
        entry *entry = &record->entries[0];
        while (entry) {
            // Insert the entry into the linked list
            if (!entry->next) {
                entry->next = (struct entry *)malloc(sizeof(struct entry));
                if (!entry->next) {
                    printf("Error: unable to allocate memory for linked list\n");
                    exit(1);
                }
            }
            entry = entry->next;
        }

        // Update the hash table
        char *key = record->value;
        int bucket_index = hash(key) % HASH_TABLE_SIZE;
        if (buckets[bucket_index].size == MAX_NODES_PER_BUCKET) {
            resize_bucket(&buckets[bucket_index]);
        }
        buckets[bucket_index].nodes[buckets[bucket_index].size++] = create_node(key, record->value);
    }
}

// Function to insert data into the linked list and update the hash table as necessary
void insert_data(record *records, int num_records) {
    // Insert data into the linked list
    for (int i = 0; i < num_records; i++) {
        record *record = &records[i];
        entry *entry = &record->entries[0];
        while (entry) {
            if (!entry->next) {
                entry->next = (struct entry *)malloc(sizeof(struct entry));
                if (!entry->next) {
                    printf("Error: unable to allocate memory for linked list\n");
                    exit(1);
                }
            }
            entry = entry->next;
        }
    }

    // Update the hash table
    for (int i = 0; i < num_records; i++) {
        record *record = &records[i];
        char *key = record->value;
        int bucket_index = hash(key) % HASH_TABLE_SIZE;
        if (buckets[bucket_index].size == MAX_NODES_PER_BUCKET) {
            resize_bucket(&buckets[bucket_index]);
        }
        buckets[bucket_index].nodes[buckets[bucket_index].size++] = create_node(key, record->value);
    }
}

// Function to update the hash table when a bucket needs to be resized
void resize_bucket(bucket *bucket) {
    // Allocate memory for the new nodes array
    struct node **new_nodes = (struct node **)malloc(sizeof(struct node *) * MAX_NODES_PER_BUCKET);
    if (!new_nodes) {
        printf("Error: unable to allocate memory for hash table nodes\n");
        exit(1);
    }

    // Copy the existing nodes into the new array
    for (int i = 0; i < bucket->size; i++) {
        new_nodes[i] = bucket->nodes[i];
    }

    // Free the old nodes array and update the bucket with the new one
    free(bucket->nodes);
    bucket->nodes = new_nodes;
}

// Function to create a node in the hash table
node *create_node(char *key, double value) {
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        printf("Error: unable to allocate memory for hash table node\n");
        exit(1);
    }
    new_node->key = key;
    new_node->value = value;
    return new_node;
}

// Function to extract the base name and extension from a filename
void extract_base_name(char *filename, char **base_name, char **extension) {
    // Find the last occurrence of the '.' character in the filename
    int dot_index = strlen(filename) - 1;
    while (dot_index >= 0 && filename[dot_index] != '.') {
        dot_index--;
    }

    // If there is no extension, set the base name and extension to be the same as the filename
    if (dot_index < 0) {
        *base_name = filename;
        *extension = "";
    } else {
        // Set the base name to be everything before the '.' character
        *base_name = (char *)malloc(sizeof(char) * (dot_index + 1));
        strncpy(*base_name, filename, dot_index);
        (*base_name)[dot_index] = '\0';

        // Set the extension to be everything after the '.' character
        *extension = (char *)malloc(sizeof(char) * (strlen(filename) - dot_index));
        strcpy(*extension, filename + dot_index + 1);
    }
}

// Function to generate a new filename based on the base name and extension
void generate_new_filename(char *base_name, char *extension, char **new_filename) {
    // Determine the number of digits in the base name
    int num_digits = strlen(base_name);
    while (num_digits > 0 && base_name[num_digits - 1] >= '0' && base_name[num_digits - 1] <= '9') {
        num_digits--;
    }

    // Generate a new filename by appending the number of digits in the base name followed by the specified file type extension
    *new_filename = (char *)malloc(sizeof(char) * (num_digits + strlen(extension) + 1));
    sprintf(*new_filename, "%s%d%s", base_name, num_digits, extension);
}

// Function to handle filenames with no extension or multiple extensions gracefully
void handle_filename(char *filename, char **base_name, char **extension) {
    // If the filename has no extension, set the base name and extension to be the same as the filename
    if (strchr(filename, '.') == NULL) {
        *base_name = filename;
        *extension = "";
    } else {
        // Extract the base name and extension from the filename
        extract_base_name(filename, base_name, extension);
    }
}

// Function to handle Unicode filenames and those containing special characters gracefully
void handle_unicode_filename(char *filename) {
    // Use sprintf to generate a new filename with the specified file type extension
    char *new_filename = (char *)malloc(sizeof(char) * (strlen(filename) + strlen(FILE_EXTENSION) + 1));
    sprintf(new_filename, "%s%s", filename, FILE_EXTENSION);
}

// Function to handle filenames with no extension or multiple extensions gracefully
void handle_multiple_extensions(char *filename) {
    // Use strchr to find the first occurrence of a '.' character in the filename
    char *dot = strchr(filename, '.');
    if (dot == NULL) {
        return;
    }

    // Use strtok to split the filename into its base name and extension parts
    char *base_name = (char *)malloc(sizeof(char) * (strlen(filename) + 1));
    strncpy(base_name, filename, dot - filename);
    base_name[dot - filename] = '\0';
    char *extension = (char *)malloc(sizeof(char) * (strlen(filename) + 1));
    strcpy(extension, dot + 1);
}

// Function to handle filenames with no extension or multiple extensions gracefully
void handle_long_filenames(char *filename) {
    // Use snprintf to generate a new filename with the specified file type extension and maximum length of 255 characters
    char *new_filename = (char *)malloc(sizeof(char) * (strlen(filename) + strlen(FILE_EXTENSION) + 1));
    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s%s", filename, FILE_EXTENSION);
}
