    for (int i = 0; i < num_widgets; i++) {
        offsets[i] = i + 1;
        keys[i] = rand() % RANDOM_VALUE_RANGE;
    }

    // Initialize widget state changes and support adaptive filtering based on widget type and state
    for (int i = 0; i < num_widgets; i++) {
        (*widgets)[i].state = WIDGET_STATE_INITIALIZED;
        (*widgets)[i].type = WIDGET_TYPE_BUTTON;
    }

    // Initialize fixed-size buffers for shuffled indices, limiting buffer size to MAX_SHUFFLE_BUFFER_SIZE elements
    int* shuffle_buffer = (int*)malloc(MAX_SHUFFLE_BUFFER_SIZE * sizeof(int));
    if (shuffle_buffer == NULL) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        return;
    }
    for (int i = 0; i < MAX_SHUFFLE_BUFFER_SIZE; i++) {
        shuffle_buffer[i] = i + 1;
    }

    // Implement mechanism to track widget state changes and support adaptive filtering based on widget type and state
    for (int i = 0; i < num_widgets; i++) {
        (*widgets)[i].state = WIDGET_STATE_INITIALIZED;
        (*widgets)[i].type = WIDGET_TYPE_BUTTON;
    }
}

