// Function to calculate the total memory usage required before any allocations are made
size_t estimate_memory_usage(const char* input_data) {
    // Calculate the size of the node and link structures
    size_t node_size = sizeof(struct node);
    size_t link_size = sizeof(struct link);

    // Calculate the total memory usage based on the input data length
    size_t total_memory = node_size * (input_data.length + 1) + link_size * (input_data.length + 1);

    // Check if the total estimated memory usage exceeds the system-defined maximum memory limit
    if (total_memory > max_memory) {
        printf("Error: Total estimated memory usage exceeds the system-defined maximum memory limit\n");
        exit(EXIT_FAILURE);
    }

