    for (size_t i = 0; i < graph->num_nodes; i++) {
        struct node* node = &graph->nodes[i];
        persist_node(node);
    }
}

// Function to ensure that the graph remains consistent under concurrent modifications by multiple threads
void synchronize_graph(struct graph* graph) {
    // Use appropriate synchronization primitives to prevent race conditions and ensure data integrity
    pthread_mutex_lock(&graph->mutex);
    for (size_t i = 0; i < graph->num_nodes; i++) {
        struct node* node = &graph->nodes[i];
        synchronize_node(node);
    }
    pthread_mutex_unlock(&graph->mutex);
}

// Function to traverse the graph starting from a given node, counting the number of nodes that can be reached from the start node
size_t count_reachable_nodes(struct graph* graph, struct node* start) {
    // Initialize the visited array to keep track of which nodes have been visited
    bool* visited = calloc(graph->num_nodes, sizeof(bool));

    // Initialize the queue to store the nodes to be processed
    struct queue* queue = create_queue();

    // Add the start node to the queue and mark it as visited
    enqueue(queue, start);
    visited[start->id] = true;

    // Process each node in the queue until it is empty
    while (!is_empty(queue)) {
        struct node* current = dequeue(queue);

        // For each neighbor of the current node, mark it as visited and add it to the queue if not already visited
        for (size_t i = 0; i < graph->num_links; i++) {
            struct link* link = &graph->links[i];
            if (link->target_id == current->id && !visited[link->target_id]) {
                visited[link->target_id] = true;
                enqueue(queue, &graph->nodes[link->target_id]);
            }
        }
    }

    // Free the queue and visited array
    free(queue);
    free(visited);

    return graph->num_nodes - count_unvisited_nodes(graph);
}

// Function to ensure that all allocated memory is properly freed upon successful completion of the function to prevent memory leaks
void cleanup_graph(struct graph* graph) {
    // Free the nodes and links arrays
    free(graph->nodes);
    free(graph->links);
}

// Function to dynamically resize the node and link arrays to accommodate additional nodes as they are added during traversal or insertion
void resize_graph(struct graph* graph) {
    // Calculate the new size of the node and link arrays based on the current number of nodes and links
    size_t new_node_size = graph->num_nodes * 2;
    size_t new_link_size = graph->num_links * 2;

    // Reallocate the memory for the node and link arrays
    struct node** new_nodes = realloc(graph->nodes, new_node_size);
    struct link** new_links = realloc(graph->links, new_link_size);

    // Check if the reallocation was successful
    if (new_nodes == NULL || new_links == NULL) {
        printf("Error: Reallocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Update the graph structure with the new arrays
    graph->nodes = new_nodes;
    graph->links = new_links;
}
