void allocateAndInitializeDataStructure(int num_records, int min_key, int max_key) {
    // Allocate memory for the array of long offset values
    long *offset_array = (long *)malloc(num_records * sizeof(long));
    if (!offset_array) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }

    // Allocate memory for the array of int keys
    int *key_array = (int *)malloc(num_records * sizeof(int));
    if (!key_array) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offset_array);
        return;
    }

    // Allocate memory for the array of record structures
    record *record_array = (record *)malloc(num_records * sizeof(record));
    if (!record_array) {
        printf("Error: Failed to allocate memory for record array\n");
        free(offset_array);
        free(key_array);
        return;
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = rand() % (max_key - min_key + 1) + min_key;
        key_array[i] = offset_array[i];
        record_array[i].key = key_array[i];
    }

    // Free the memory allocated for the arrays
    free(offset_array);
    free(key_array);
    free(record_array);
}

