    // Allocate memory for the random string
    char *random_string = (char *)malloc((length + 1) * sizeof(char));
    if (!random_string) {
        printf("Error: Failed to allocate memory for random string\n");
        return NULL;
    }

    // Generate the random string using the given character set
    for (int i = 0; i < length; i++) {
        int index = rand() % strlen(character_set);
        random_string[i] = character_set[index];
    }
    random_string[length] = '\0';

    return random_string;
}

