    // Allocate memory for the hashed password
    char *hashed_password = (char *)malloc((strlen(password) + 1) * sizeof(char));
    if (!hashed_password) {
        printf("Error: Failed to allocate memory for hashed password\n");
        return NULL;
    }

    // Hash the password using a default hash function
    strcpy(hashed_password, password);

    return hashed_password;
}
