// Define the function to initialize and manage data
void initialize_and_manage_data(int num_doubles, int num_result_types, int num_data_containers, int num_thread_infos, int num_statistics) {
    // Dynamically allocate memory for the arrays
    double* doubles = (double*)malloc(num_doubles * sizeof(double));
    enum result_type* result_types = (enum result_type*)malloc(num_result_types * sizeof(enum result_type));
    union data_container** data_containers = (union data_container**)malloc(num_data_containers * sizeof(union data_container*));
    struct thread_info** thread_infos = (struct thread_info**)malloc(num_thread_infos * sizeof(struct thread_info*));
    struct statistics* statistics = (struct statistics*)malloc(num_statistics * sizeof(struct statistics));

    // Initialize the arrays with random values
    for (int i = 0; i < num_doubles; i++) {
        doubles[i] = (double)rand() / RAND_MAX;
    }
    for (int i = 0; i < num_result_types; i++) {
        result_types[i] = (enum result_type)(rand() % 2);
    }
    for (int i = 0; i < num_data_containers; i++) {
        data_containers[i] = (union data_container*)malloc(sizeof(union data_container));
        if (data_containers[i] == NULL) {
