    for (int i = 0; i < num_result_types; i++) {
        if (result_types[i] != SUCCESS && result_types[i] != FAILURE) {
            printf("Error: result_types[%d] is not a valid value\n", i);
        }
    }
    for (int i = 0; i < num_data_containers; i++) {
        if (data_containers[i] == NULL) {
            printf("Error: data_containers[%d] is null\n", i);
        } else {
            if (!isnan(data_containers[i]->int_value)) {
                printf("Error: data_containers[%d].int_value is not a number\n", i);
            }
        }
    }
    for (int i = 0; i < num_thread_infos; i++) {
