        } else {
            if (!isnan(thread_infos[i]->execution_time.tv_sec)) {
                printf("Error: thread_infos[%d].execution_time.tv_sec is not a number\n", i);
            }
        }
    }

    // Update the statistics structure with the current elapsed time
    clock_gettime(CLOCK_MONOTONIC, &statistics->start_time);
    for (int i = 0; i < num_thread_infos; i++) {
        thread_infos[i]->execution_time.tv_sec -= statistics->start_time.tv_sec;
        thread_infos[i]->execution_time.tv_nsec -= statistics->start_time.tv_nsec;
    }

    // Ensure thread safety during the loop to set the data container union's int value field
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_data_containers; i++) {
