void initialize_arrays(unsigned long max_id, unsigned int window_size, double initial_seed, struct record** id_array, struct record** record_array) {
    // Allocate memory for the identifier array
    *id_array = (struct record*) malloc(max_id * sizeof(struct record));
    if (*id_array == NULL) {
        printf("Error: Failed to allocate memory for identifier array\n");
        return;
    }

    // Allocate memory for the record array
    *record_array = (struct record*) malloc(max_id * sizeof(struct record));
    if (*record_array == NULL) {
        printf("Error: Failed to allocate memory for record array\n");
        free(*id_array);
        return;
    }

    // Initialize the identifier and record arrays
    for (unsigned long i = 0; i < max_id; i++) {
        (*id_array)[i].timestamp = i + 1;
        (*record_array)[i].value = initial_seed;
    }

    // Populate the timestamps with current system time
    for (unsigned long i = 0; i < max_id; i++) {
        (*id_array)[i].timestamp = time(NULL);
    }

    // Calculate moving averages using a specified window size and initial seed value
    for (unsigned long i = 0; i < max_id - window_size + 1; i++) {
        double sum = 0;
        for (unsigned int j = 0; j < window_size; j++) {
            sum += (*record_array)[i + j].value;
        }
        (*record_array)[i].value = sum / window_size;
    }

    // Ensure moving averages do not exceed a specified maximum value
    for (unsigned long i = 0; i < max_id - window_size + 1; i++) {
        if ((*record_array)[i].value > maximum_value) {
            (*record_array)[i].value = maximum_value;
        }
    }
}

// Define function to validate the uniqueness of identifiers before initialization
void validate_identifiers(unsigned long max_id, struct record* id_array) {
    // Initialize a set to store unique identifiers
