    if (unique_ids == NULL) {
        printf("Error: Failed to allocate memory for unique identifier set\n");
        return;
    }

    // Iterate over the identifier array and add each identifier to the set
    for (unsigned long i = 0; i < max_id; i++) {
        if (!unique_ids[i]) {
            unique_ids[i] = id_array[i].timestamp;
        } else {
            printf("Error: Duplicate identifier found\n");
            free(unique_ids);
            return;
        }
    }

    // Free the set of unique identifiers
    free(unique_ids);
}

// Define function to validate the moving average calculations to ensure stability and accuracy
void validate_moving_averages(unsigned long max_id, struct record* record_array) {
    // Initialize a sum to store the total value of the records
    double sum = 0;

    // Iterate over the record array and add each record's value to the sum
    for (unsigned long i = 0; i < max_id - window_size + 1; i++) {
        sum += record_array[i].value;
    }

    // Ensure the sum of the records is equal to the total number of records multiplied by the initial seed value
    if (sum != (max_id - window_size + 1) * initial_seed) {
        printf("Error: Moving average calculations are not stable or accurate\n");
    }
}
