// Define the data manager function
void dataManager(int num_operations, int max_message_length, int min_value, int max_value) {
    // Initialize the arrays and linked list
    char** messages = malloc(num_operations * sizeof(char*));
    operation* operations = malloc(num_operations * sizeof(operation));
    event_log* event_logs = malloc(num_operations * sizeof(event_log));
    performance_metrics metrics;

    // Initialize the shared cache for frequently accessed operation metadata
    pthread_mutex_t cache_lock;
    pthread_cond_t cache_cv;
    struct {
        int* keys;
        void** values;
    } cache = {NULL, NULL};

    // Set up the thread-safe cache for operation metadata
    pthread_mutex_init(&cache_lock, NULL);
    pthread_cond_init(&cache_cv, NULL);

    // Initialize the performance metrics structure
    metrics.successful_allocations = 0;
    metrics.failed_allocations = 0;
    metrics.latency_mean = 0;
    metrics.latency_stddev = 0;

    // Loop through each operation and perform the necessary actions
    for (int i = 0; i < num_operations; i++) {
        // Generate a unique identifier for the message
        char* message = malloc(max_message_length * sizeof(char));
        sprintf(message, "Operation %d", i);

        // Set the event log's message field to the generated message
