        operations[i].status = rand() % (max_value - min_value + 1) + min_value;
        operations[i].metadata = NULL;
        operations[i].timestamp = time(NULL);

        // Update the performance metrics structure with the operation's status and timestamp
        metrics.successful_allocations++;
        metrics.latency_mean += (double)operations[i].status / metrics.successful_allocations;
        metrics.latency_stddev += pow((double)operations[i].status - metrics.latency_mean, 2);

        // Add the operation to the shared cache for frequently accessed metadata
        pthread_mutex_lock(&cache_lock);
        if (cache.keys == NULL) {
            cache.keys = malloc(num_operations * sizeof(int));
            cache.values = malloc(num_operations * sizeof(void*));
        }
        cache.keys[i] = i;
        cache.values[i] = &operations[i];
        pthread_cond_signal(&cache_cv);
        pthread_mutex_unlock(&cache_lock);
    }

    // Clean up the memory allocated for the arrays and linked list
    free(messages);
    free(operations);
    free(event_logs);

    // Clean up the thread-safe cache for operation metadata
    pthread_mutex_destroy(&cache_lock);
    pthread_cond_destroy(&cache_cv);
    if (cache.keys != NULL) {
        free(cache.keys);
        free(cache.values);
    }
}
