        pthread_join(threads[i], NULL);
    }
}

// Function to handle a file entry in a separate thread
void* handleFileEntry(void* args) {
    struct file_entry* entry = (struct file_entry*)args;

    // Acquire the mutex lock for this file entry
    pthread_mutex_lock(&mutex);

    // Check if the file entry is inactive and has not been accessed within the configured timeout
    if (entry->status == INACTIVE && time(NULL) - entry->metadata > TIMEOUT) {
        // Set the status to inactive
        entry->status = INACTIVE;
    } else {
        // Update the metadata field with the current timestamp
        entry->metadata = time(NULL);
    }

    // Release the mutex lock for this file entry
    pthread_mutex_unlock(&mutex);
}
