void allocateMemory(int numRecords, int offsetRange) {
    // Allocate memory for the long offset values array
    long *offsets = (long *)malloc(numRecords * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for offsets\n");
        return;
    }

    // Allocate memory for the int keys array
