    // Private fields for minValue, maxValue, and seed
    int minValue;
    int maxValue;
    unsigned int seed;

public:
    // Constructor to initialize the class with default values
    MemoryInitializer() : minValue(0), maxValue(100), seed(time(NULL)) {}

    // Method to generate random integers within the specified range
    int GetRandomInt(int isInclusive) {
        if (isInclusive) {
            return rand_r(&seed) % (maxValue - minValue + 1) + minValue;
        } else {
            return rand_r(&seed) % (maxValue - minValue) + minValue;
        }
    }

    // Method to generate random floating-point numbers within the specified range
    double GetRandomDouble(int isInclusive) {
        if (isInclusive) {
            return ((double)rand_r(&seed) / RAND_MAX) * (maxValue - minValue + 1) + minValue;
        } else {
            return ((double)rand_r(&seed) / RAND_MAX) * (maxValue - minValue);
        }
    }

