        records = (Record*)malloc(sizeof(Record) * numRecords);
        offsets = (long*)malloc(sizeof(long) * numRecords);

        // Generate random values within the specified range for each record
        for (int i = 0; i < numRecords; i++) {
            records[i].value = initializer.GetRandomInt();
            records[i].status = 'A';
            records[i].timestamp = initializer.GetRandomDouble();
            offsets[i] = i * sizeof(Record);
        }
    }

    // Method to allocate and initialize the offset array
