        // Check if there is enough memory for the new record
        if (numRecords >= records.length()) {
            // Reallocate the memory for the record array and offset array
            records = (Record*)realloc(records, sizeof(Record) * (numRecords + 1));
            offsets = (long*)realloc(offsets, sizeof(long) * (numRecords + 1));
        }

        // Insert the new record into the array
        records[numRecords] = record;
        offsets[numRecords] = numRecords * sizeof(Record);

        // Increment the number of records
        numRecords++;
