// Function to update the value of a record and increment its reference count
void update(size_t index, int new_value) {
    // Check if the index is within the bounds of the arrays
    if (index >= num_records) {
        printf("Error: Index %zu is out of bounds\n", index);
        exit(1);
    }

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Update the value of the record and increment its reference count
    records[index]->value = new_value;
    records[index]->ref_count++;

    // Unlock the mutex
