    if (num_longs >= long_pool_size) {
        // Reallocate the memory pool if necessary
        long_pool = (long*)realloc(long_pool, sizeof(long) * (long_pool_size + 1));
        assert(long_pool != NULL);
        long_pool_size++;
    }
    return &long_pool[num_longs++];
}

// Allocate an int from the memory pool
int* allocate_int() {
    if (num_ints >= int_pool_size) {
        // Reallocate the memory pool if necessary
