void init_records(char* data, size_t data_size) {
    // Initialize the collection of records if it has not been initialized yet
    if (records == NULL) {
        records = malloc(max_num_records * record_size);
        if (records == NULL) {
            printf("Error: Failed to allocate memory for the collection of records\n");
            return;
        }
    }

    // Batch process incoming data chunks to reduce overhead of frequent allocations
    size_t batch_size = 1024 * 1024; // Set a batch size in bytes
    char* current_data = data;
    while (current_data < data + data_size) {
        // Determine the number of records that can be initialized from the current batch of data
        size_t num_records_to_init = (data_size - (current_data - data)) / record_size;
        if (num_records + num_records_to_init > max_num_records) {
            num_records_to_init = max_num_records - num_records;
        }

        // Initialize the records from the current batch of data
        for (size_t i = 0; i < num_records_to_init; i++) {
            Record* record = &records[num_records + i];
            memcpy(record, current_data, record_size);
            total_memory_usage += record_size;
            current_data += record_size;
        }

        // Check if the data stream has concluded
        if (current_data >= data + data_size) {
