        fread(&project->due_date, sizeof(int), 1, input_file);
        fread(&tasks_length, sizeof(int), 1, input_file);
        project->num_tasks = tasks_length / sizeof(Task*);
        for (int j = 0; j < project->num_tasks; j++) {
