            fread(task->description, sizeof(char), description_length, input_file);
            fread(&task->priority, sizeof(int), 1, input_file);
            fread(&task->due_date, sizeof(int), 1, input_file);
            project->tasks[j] = task;
        }
    }

    // Close the input file
