using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

namespace MemoryEfficientDataProcessor
{
    public class MemoryEfficientDataProcessor
    {
        private readonly int _minValue;
        private readonly int _maxValue;
        private readonly Random _random;

        public MemoryEfficientDataProcessor(int minValue, int maxValue)
        {
            if (minValue > maxValue)
                throw new ArgumentException("Min value must be less than or equal to max value");

            _minValue = minValue;
            _maxValue = maxValue;
            _random = new Random();
        }

        public int GetRandomInt(bool isInclusive)
        {
            return isInclusive ? _random.Next(_minValue, _maxValue + 1) : _random.Next(_minValue, _maxValue);
        }

        public float GetRandomFloat(bool isInclusive)
        {
            return (float)(isInclusive ? _random.NextDouble() * (_maxValue - _minValue) + _minValue : _random.NextDouble() * (_maxValue - _minValue));
        }

        public string GetCurrentRange()
        {
            return $"{_minValue} to {_maxValue}";
        }
    }
}
