        strcpy(client_records[i].name, "Client ");
        client_records[i].session_list = (session **)malloc(sizeof(session *) * num_sessions);
    }
    for (int i = 0; i < num_sessions; i++) {
        session_objects[i].session_id = rand() % 1000000;
        strcpy(session_objects[i].buffer, "Session ");
        session_objects[i].next = NULL;
    }

    // Initialize reference counts for each session object
    for (int i = 0; i < num_sessions; i++) {
        ref_count[i] = 0;
    }

    // Log detailed information about each session, including timestamps and session IDs
    time_t timestamp = time(NULL);
    printf("Timestamp: %s\n", ctime(&timestamp));
    for (int i = 0; i < num_clients; i++) {
        printf("Client ID: %d\n", client_records[i].unique_id);
        printf("Client Name: %s\n", client_records[i].name);
        for (int j = 0; j < num_sessions; j++) {
            if (client_records[i].session_list[j] != NULL) {
                printf("Session ID: %d\n", session_objects[j].session_id);
                printf("Session Details: %s\n", session_objects[j].buffer);
            }
        }
    }
}

// Function to reset the memory allocation and re-initialize the data structures without losing previously computed random values
void reset_data_structures() {
    // Free all allocated memory for primary arrays, client records, and session objects
    free(primary_arrays);
    free(client_records);
    free(session_objects);

    // Re-initialize the data structures with new random values
    init_data_structures(num_clients, num_sessions);
}

