#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>

// Define cache entry structure
typedef struct {
    char* key;
    void* value;
    time_t timestamp;
    metadata_t metadata;
} cache_entry_t;

// Define cache structure
typedef struct {
    size_t capacity;
    size_t size;
    cache_entry_t** entries;
} cache_t;

// Initialize cache with given parameters
void init_cache(cache_t* cache, size_t capacity, size_t initial_size) {
    // Allocate memory for cache entries
    cache->entries = (cache_entry_t**)malloc(capacity * sizeof(cache_entry_t*));
    if (!cache->entries) {
        printf("Error: Failed to allocate memory for cache entries\n");
        exit(1);
    }

    // Initialize each entry with NULL value and timestamp
    for (size_t i = 0; i < capacity; i++) {
        cache->entries[i] = (cache_entry_t*)malloc(sizeof(cache_entry_t));
        if (!cache->entries[i]) {
            printf("Error: Failed to allocate memory for cache entry %zu\n", i);
            exit(1);
        }
        cache->entries[i]->key = NULL;
        cache->entries[i]->value = NULL;
        cache->entries[i]->timestamp = 0;
        cache->entries[i]->metadata.ref_count = 0;
        cache->entries[i]->metadata.size = initial_size;
    }

    // Set cache capacity and size
    cache->capacity = capacity;
    cache->size = 0;
}

// Add new entry to cache
void add_entry(cache_t* cache, char* key, void* value) {
    // Check if cache is full
    if (cache->size == cache->capacity) {
        // Evict least recently used entry
        size_t lru_index = 0;
        time_t lru_timestamp = cache->entries[0]->timestamp;
        for (size_t i = 1; i < cache->capacity; i++) {
            if (cache->entries[i]->timestamp < lru_timestamp) {
                lru_index = i;
                lru_timestamp = cache->entries[i]->timestamp;
            }
        }
        // Free memory for evicted entry
        free(cache->entries[lru_index]);
        // Remove evicted entry from cache
        memmove(&cache->entries[lru_index], &cache->entries[lru_index + 1], (cache->capacity - lru_index - 1) * sizeof(cache_entry_t*));
        cache->size--;
    }

    // Allocate memory for new entry
    size_t index = cache->size++;
    cache->entries[index] = (cache_entry_t*)malloc(sizeof(cache_entry_t));
    if (!cache->entries[index]) {
        printf("Error: Failed to allocate memory for cache entry %zu\n", index);
        exit(1);
    }

    // Set new entry key and value
    cache->entries[index]->key = key;
    cache->entries[index]->value = value;
    cache->entries[index]->timestamp = time(NULL);
    cache->entries[index]->metadata.ref_count = 0;
    cache->entries[index]->metadata.size = initial_size;
}

// Get entry from cache by key
void* get_entry(cache_t* cache, char* key) {
    // Check if cache is empty
    if (cache->size == 0) {
        return NULL;
    }

    // Find entry with matching key
    for (size_t i = 0; i < cache->capacity; i++) {
        if (strcmp(key, cache->entries[i]->key) == 0) {
            // Update timestamp and metadata
            cache->entries[i]->timestamp = time(NULL);
            cache->entries[i]->metadata.ref_count++;
            return cache->entries[i]->value;
        }
    }

    // Return NULL if entry not found
    return NULL;
}

// Update entry in cache by key
void update_entry(cache_t* cache, char* key, void* value) {
    // Find entry with matching key
    for (size_t i = 0; i < cache->capacity; i++) {
        if (strcmp(key, cache->entries[i]->key) == 0) {
            // Update entry value and timestamp
            cache->entries[i]->value = value;
            cache->entries[i]->timestamp = time(NULL);
            return;
        }
    }
}

// Remove entry from cache by key
void remove_entry(cache_t* cache, char* key) {
    // Find entry with matching key
    for (size_t i = 0; i < cache->capacity; i++) {
        if (strcmp(key, cache->entries[i]->key) == 0) {
            // Free memory for removed entry
            free(cache->entries[i]);
            // Remove removed entry from cache
            memmove(&cache->entries[i], &cache->entries[i + 1], (cache->capacity - i - 1) * sizeof(cache_entry_t*));
            cache->size--;
            return;
        }
    }
}

// Evict least recently used entries to make room for new ones
void evict_entries(cache_t* cache, size_t num_entries) {
    // Check if cache is full
    if (cache->size == cache->capacity) {
        // Evict least recently used entries
        size_t lru_index = 0;
        time_t lru_timestamp = cache->entries[0]->timestamp;
        for (size_t i = 1; i < cache->capacity; i++) {
            if (cache->entries[i]->timestamp < lru_timestamp) {
                lru_index = i;
                lru_timestamp = cache->entries[i]->timestamp;
            }
        }
        // Free memory for evicted entries
        for (size_t i = 0; i < num_entries; i++) {
            free(cache->entries[lru_index]);
            memmove(&cache->entries[lru_index], &cache->entries[lru_index + 1], (cache->capacity - lru_index - 1) * sizeof(cache_entry_t*));
            cache->size--;
        }
    }
}

// Merge consecutive unused entries to optimize memory usage
void merge_entries(cache_t* cache) {
    // Check if there are any consecutive unused entries
    for (size_t i = 0; i < cache->capacity - 1; i++) {
        if (cache->entries[i]->value == NULL && cache->entries[i + 1]->value == NULL) {
            // Merge consecutive unused entries
            cache->entries[i]->metadata.size += cache->entries[i + 1]->metadata.size;
            memmove(&cache->entries[i], &cache->entries[i + 1], (cache->capacity - i - 1) * sizeof(cache_entry_t*));
            cache->size--;
        }
    }
}

// Monitor cache hit rates, miss rates, and memory usage
void monitor_cache(cache_t* cache) {
    // Calculate cache hit rate
    size_t hits = 0;
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->entries[i]->value != NULL) {
            hits++;
        }
    }
    double hit_rate = (double)hits / cache->capacity * 100;

    // Calculate cache miss rate
    size_t misses = 0;
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->entries[i]->value == NULL) {
            misses++;
        }
    }
    double miss_rate = (double)misses / cache->capacity * 100;

    // Calculate memory usage
    size_t total_size = 0;
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->entries[i]->value != NULL) {
            total_size += cache->entries[i]->metadata.size;
        }
    }
    double memory_usage = (double)total_size / cache->capacity * 100;

    // Print monitoring results
    printf("Cache hit rate: %.2f%%\n", hit_rate);
    printf("Cache miss rate: %.2f%%\n", miss_rate);
    printf("Memory usage: %.2f%%\n", memory_usage);
}

// Persist cache entries to disk
void persist_cache(cache_t* cache) {
    // Open file for writing
    FILE* fp = fopen("cache.dat", "wb");
    if (!fp) {
        printf("Error: Failed to open cache file for writing\n");
        exit(1);
    }

    // Write cache entries to file
    for (size_t i = 0; i < cache->capacity; i++) {
        if (cache->entries[i]->value != NULL) {
            fwrite(&cache->entries[i], sizeof(cache_entry_t), 1, fp);
        }
    }

    // Close file
    fclose(fp);
}

// Load cache entries from disk
void load_cache(cache_t* cache) {
    // Open file for reading
    FILE* fp = fopen("cache.dat", "rb");
    if (!fp) {
        printf("Error: Failed to open cache file for reading\n");
        exit(1);
    }

    // Read cache entries from file
    while (fread(&cache->entries[cache->size], sizeof(cache_entry_t), 1, fp)) {
        cache->size++;
    }

    // Close file
    fclose(fp);
}
