#define MAX_RECORDS 1000000
#define MAX_CONNECTIONS 1000
#define MAX_SHUFFLE_BUFFER_SIZE 10000

typedef struct {
    int socket;
    char* request_handler;
    char* response_buffer;
} network_client_t;

typedef struct {
    long offset;
    int key;
} record_t;

typedef struct {
    int id;
    record_t* records;
    network_client_t* clients;
} connection_pool_t;

connection_pool_t* create_connection_pool(int num_connections, int num_records) {
    if (num_connections > MAX_CONNECTIONS || num_records > MAX_RECORDS) {
        printf("Invalid configuration: num_connections=%d, num_records=%d\n", num_connections, num_records);
        return NULL;
    }

    connection_pool_t* pool = (connection_pool_t*)malloc(sizeof(connection_pool_t));
    if (!pool) {
        printf("Failed to allocate memory for connection pool\n");
        return NULL;
    }

    pool->clients = (network_client_t*)malloc(num_connections * sizeof(network_client_t));
    if (!pool->clients) {
        printf("Failed to allocate memory for %d network clients\n", num_connections);
        free(pool);
        return NULL;
    }

    pool->records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!pool->records) {
        printf("Failed to allocate memory for %d records\n", num_records);
        free(pool->clients);
        free(pool);
        return NULL;
    }

    pool->id = 0;
    for (int i = 0; i < num_connections; i++) {
        pool->clients[i].socket = -1;
        pool->clients[i].request_handler = NULL;
        pool->clients[i].response_buffer = NULL;
    }

    for (int i = 0; i < num_records; i++) {
        pool->records[i].offset = -1;
        pool->records[i].key = -1;
    }

    return pool;
}

void deallocate_connection_pool(connection_pool_t* pool) {
    if (!pool) {
        return;
    }

    free(pool->clients);
    free(pool->records);
    free(pool);
}

int allocate_client(connection_pool_t* pool, int socket) {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (pool->clients[i].socket == -1) {
            pool->clients[i].socket = socket;
            return i;
        }
    }

    return -1;
}

int allocate_record(connection_pool_t* pool, long offset, int key) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (pool->records[i].offset == -1) {
            pool->records[i].offset = offset;
            pool->records[i].key = key;
            return i;
        }
    }

    return -1;
}

void deallocate_client(connection_pool_t* pool, int client_id) {
    if (client_id < 0 || client_id >= MAX_CONNECTIONS) {
        return;
    }

    pool->clients[client_id].socket = -1;
}

void deallocate_record(connection_pool_t* pool, int record_id) {
    if (record_id < 0 || record_id >= MAX_RECORDS) {
        return;
    }

    pool->records[record_id].offset = -1;
    pool->records[record_id].key = -1;
}

int get_next_client(connection_pool_t* pool, int client_id) {
    if (client_id < 0 || client_id >= MAX_CONNECTIONS) {
        return -1;
    }

    for (int i = client_id + 1; i < MAX_CONNECTIONS; i++) {
        if (pool->clients[i].socket != -1) {
            return i;
        }
    }

    return -1;
}

int get_next_record(connection_pool_t* pool, int record_id) {
    if (record_id < 0 || record_id >= MAX_RECORDS) {
        return -1;
    }

    for (int i = record_id + 1; i < MAX_RECORDS; i++) {
        if (pool->records[i].offset != -1) {
            return i;
        }
    }

    return -1;
}

void shuffle(int* arr, int n) {
    for (int i = 0; i < n; i++) {
        int j = rand() % (n - i) + i;
        int temp = arr[j];
        arr[j] = arr[i];
        arr[i] = temp;
    }
}

void process_requests(connection_pool_t* pool, int num_clients, int num_records) {
    // allocate memory for shuffled indices
    int* shuffle_buffer = (int*)malloc(MAX_SHUFFLE_BUFFER_SIZE * sizeof(int));
    if (!shuffle_buffer) {
        printf("Failed to allocate memory for shuffle buffer\n");
        return;
    }

    // initialize shuffled indices
    for (int i = 0; i < num_clients; i++) {
        shuffle_buffer[i] = i;
    }

    // process requests concurrently
    pthread_t threads[num_clients];
    for (int i = 0; i < num_clients; i++) {
        int client_id = shuffle_buffer[i];
        if (pool->clients[client_id].socket == -1) {
            continue;
        }

        pthread_create(&threads[i], NULL, process_request, pool);
    }

    // wait for all threads to complete
    for (int i = 0; i < num_clients; i++) {
        if (pool->clients[i].socket == -1) {
            continue;
        }

        pthread_join(threads[i], NULL);
    }

    // deallocate shuffled indices
    free(shuffle_buffer);
}

void* process_request(void* arg) {
    connection_pool_t* pool = (connection_pool_t*)arg;
    int client_id = allocate_client(pool, -1);
    if (client_id < 0) {
        return NULL;
    }

    // process request concurrently
    while (true) {
        // check for new connection
        if (pool->clients[client_id].socket == -1) {
            break;
        }

        // allocate record and update client state
        int record_id = allocate_record(pool, -1, -1);
        if (record_id < 0) {
            deallocate_client(pool, client_id);
            break;
        }

        pool->clients[client_id].request_handler = NULL;
        pool->clients[client_id].response_buffer = NULL;
    }

    // deallocate client state
    deallocate_client(pool, client_id);
}
