struct memory_pool {
    size_t capacity;
    size_t used;
    struct element* elements;
};

// Function to initialize the memory pool
void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
    pool->elements = (struct element*)malloc(sizeof(struct element) * capacity);
}

// Function to allocate a new element in the memory pool
struct element* alloc_element(struct memory_pool* pool) {
    if (pool->used == pool->capacity) {
        // Memory pool is full, resize it
        pool->capacity *= 2;
        pool->elements = (struct element*)realloc(pool->elements, sizeof(struct element) * pool->capacity);
    }
    struct element* element = &pool->elements[pool->used++];
    return element;
}

// Function to deallocate an element in the memory pool
void free_element(struct memory_pool* pool, struct element* element) {
    if (pool->used > 0) {
        // Move the last element to the freed position
        struct element* last = &pool->elements[pool->used - 1];
        *element = *last;
        pool->used--;
    } else {
        free(element);
    }
}

// Function to validate the integrity of the allocated memory
void validate_memory(struct memory_pool* pool) {
    for (size_t i = 0; i < pool->used; i++) {
        struct element* element = &pool->elements[i];
        if (!element->initialized) {
            // Element is not initialized, skip it
            continue;
        }
