    } else {
        printf("Deallocated memory block %p with size %zu\n", element, sizeof(struct element));
    }
}

// Function to handle memory allocation failures and ensure that all resources are properly released in case of early termination
void handle_memory_failure(struct memory_pool* pool) {
    if (pool->used == 0) {
        // No memory allocated, nothing to do
        return;
    }
    for (size_t i = 0; i < pool->used; i++) {
        struct element* element = &pool->elements[i];
