// Validate each file path against a specified naming convention and maximum depth limit
bool validate_filepath(char* filepath, char* convention, int max_depth) {
    // Check if the file path adheres to the specified naming convention
    if (!strcmp(convention, FILENAME_CONVENTION)) {
        return true;
    }

    // Check if the file path exceeds the maximum depth limit
    int depth = 0;
    char* token = strtok(filepath, "/");
    while (token != NULL) {
        ++depth;
        token = strtok(NULL, "/");
    }
    if (depth > max_depth) {
        return false;
    }

    // Return true if the file path adheres to both the naming convention and maximum depth limit
    return true;
}

// Dynamically allocate memory for a hierarchical tree structure to efficiently represent directories and files
