        return NULL;
    }
    new->value = 0.0;
    new->id = 0;
    new->status = 'A';
    new->initialized = true;
    new->timestamp = time(NULL);
    return new;
}

// Implement a custom memory pool to manage the dynamic allocation efficiently, considering both peak and average memory usage
struct MemoryPool* create_memory_pool() {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        fprintf(stderr, "Error: Failed to allocate memory for memory pool\n");
        return NULL;
    }
    pool->data = NULL;
    pool->size = 0;
    return pool;
}

