typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int size;
    int head;
    int tail;
    task_update_t *updates[1000];
} task_queue_t;

// Define the function to dynamically allocate memory for a collection of projects
project_t* alloc_projects(int num_projects) {
    project_t *projects = malloc(num_projects * sizeof(project_t));
    if (projects == NULL) {
        return NULL;
    }

    // Initialize each project with default values
    for (int i = 0; i < num_projects; i++) {
        projects[i].title = malloc(10 * sizeof(char));
        if (projects[i].title == NULL) {
            free(projects);
            return NULL;
        }
        projects[i].priority = rand() % 10 + 1;
        projects[i].start_date = time(NULL);
        projects[i].num_tasks = 0;
        projects[i].tasks = malloc(10 * sizeof(task_t));
        if (projects[i].tasks == NULL) {
            free(projects[i].title);
            free(projects);
            return NULL;
        }
    }

    // Initialize each task with default values
    for (int i = 0; i < num_projects; i++) {
        for (int j = 0; j < projects[i].num_tasks; j++) {
            projects[i].tasks[j].description = malloc(10 * sizeof(char));
            if (projects[i].tasks[j].description == NULL) {
                free(projects[i].title);
                free(projects);
                return NULL;
            }
            projects[i].tasks[j].priority = rand() % 10 + 1;
            projects[i].tasks[j].due_date = projects[i].start_date + (rand() % 30) + 1;
        }
    }

    return projects;
}

// Define the function to dynamically allocate memory for a task update
task_update_t* alloc_task_update(int project_index, int task_index) {
    task_update_t *update = malloc(sizeof(task_update_t));
    if (update == NULL) {
        return NULL;
    }

    update->project_index = project_index;
    update->task_index = task_index;
    update->description = malloc(10 * sizeof(char));
    if (update->description == NULL) {
        free(update);
        return NULL;
    }

    return update;
}

// Define the function to add a task update to the queue
void enqueue_task_update(task_queue_t *queue, int project_index, int task_index, char *description) {
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is full
    if (queue->size == 1000) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    // Add the task update to the queue
    queue->updates[queue->tail] = alloc_task_update(project_index, task_index, description);
    if (queue->updates[queue->tail] == NULL) {
        pthread_mutex_unlock(&queue->mutex);
        return;
    }

    // Increment the tail index and size of the queue
    queue->tail = (queue->tail + 1) % 1000;
    queue->size++;

    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Define the function to remove a task update from the queue
task_update_t* dequeue_task_update(task_queue_t *queue) {
    pthread_mutex_lock(&queue->mutex);

    // Check if the queue is empty
    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return NULL;
    }

    // Remove the task update from the queue
    task_update_t *update = queue->updates[queue->head];
    queue->head = (queue->head + 1) % 1000;
    queue->size--;

    pthread_mutex_unlock(&queue->mutex);

    return update;
}

// Define the function to update the priority of a task within a project
void update_task_priority(project_t *projects, int project_index, int task_index, int new_priority) {
    pthread_mutex_lock(&projects->mutex);

    // Check if the project and task indices are valid
    if (project_index < 0 || project_index >= projects->num_projects || task_index < 0 || task_index >= projects->tasks[project_index].num_tasks) {
        pthread_mutex_unlock(&projects->mutex);
        return;
    }

    // Update the priority of the task within the project
    projects->tasks[project_index].priority = new_priority;

    pthread_mutex_unlock(&projects->mutex);
}

// Define the function to delete a project and all associated tasks
void delete_project(project_t *projects, int project_index) {
    pthread_mutex_lock(&projects->mutex);

    // Check if the project index is valid
    if (project_index < 0 || project_index >= projects->num_projects) {
        pthread_mutex_unlock(&projects->mutex);
        return;
    }

    // Delete the tasks within the project
    for (int i = 0; i < projects[project_index].num_tasks; i++) {
        free(projects[project_index].tasks[i].description);
    }
    free(projects[project_index].tasks);

    // Delete the title of the project
    free(projects[project_index].title);

    // Remove the project from the list of projects
    for (int i = project_index; i < projects->num_projects - 1; i++) {
        projects[i] = projects[i + 1];
    }
    projects->num_projects--;

    pthread_mutex_unlock(&projects->mutex);
}
