// Define the structure for a project
typedef struct {
    char *title;
    int priority;
    time_t start_date;
    int num_tasks;
    task **tasks;
} project;

// Define the structure for a task
typedef struct {
    char *description;
    int priority;
    time_t due_date;
} task;

// Define the queue data structure for handling task updates
typedef struct {
    task **tasks;
    int size;
    int front, rear;
    pthread_mutex_t mutex;
} queue;

// Function to initialize a project
void init_project(project *p) {
    // Allocate memory for the project title and set it to an empty string
    p->title = malloc(1);
    *(p->title) = '\0';

    // Set the priority of the project to a random value within the specified range
    p->priority = rand() % 10 + 1;

    // Calculate the start date for the project as the current time plus a random duration between 1 and 30 days
    p->start_date = time(NULL) + (rand() % 29) + 1;

    // Initialize the number of tasks to 0
    p->num_tasks = 0;

    // Allocate memory for the task list and set it to NULL
    p->tasks = malloc(sizeof(task *) * 1);
    *(p->tasks) = NULL;
}

// Function to add a new task to a project
void add_task(project *p, char *description, int priority, time_t due_date) {
    // Allocate memory for the new task and set its fields
    task *new_task = malloc(sizeof(task));
    new_task->description = description;
    new_task->priority = priority;
    new_task->due_date = due_date;

    // Allocate memory for the new task list and copy the existing tasks to it
    int num_tasks = p->num_tasks + 1;
    task **new_tasks = malloc(sizeof(task *) * num_tasks);
    memcpy(new_tasks, p->tasks, sizeof(task *) * (p->num_tasks));

    // Add the new task to the list and update the number of tasks
    new_tasks[p->num_tasks] = new_task;
    p->num_tasks = num_tasks;

    // Free the old task list and set the new one as the current one
    free(p->tasks);
    p->tasks = new_tasks;
}

// Function to update the priority of a task within a project
void update_task_priority(project *p, int task_index, int new_priority) {
    // Check if the task index is valid
    if (task_index < 0 || task_index >= p->num_tasks) {
        return;
    }

    // Update the priority of the task and update the project's number of tasks
    p->tasks[task_index]->priority = new_priority;
}

// Function to delete a project and all associated tasks
void delete_project(project *p) {
    // Free the memory for the project title and task list
    free(p->title);
    free(p->tasks);

    // Set the project pointer to NULL
    p = NULL;
}

// Function to handle a task update in a thread-safe manner
void handle_task_update(queue *q, int task_index, char *description, int priority, time_t due_date) {
    // Lock the queue mutex
    pthread_mutex_lock(&q->mutex);

    // Update the task fields and update the project's number of tasks
    q->tasks[task_index]->description = description;
    q->tasks[task_index]->priority = priority;
    q->tasks[task_index]->due_date = due_date;

    // Unlock the queue mutex
    pthread_mutex_unlock(&q->mutex);
}

// Function to handle a task deletion in a thread-safe manner
void handle_task_deletion(queue *q, int task_index) {
    // Lock the queue mutex
    pthread_mutex_lock(&q->mutex);

    // Update the number of tasks and free the memory for the deleted task
    q->size--;
    free(q->tasks[task_index]);

    // Shift all tasks after the deleted one to fill the gap
    for (int i = task_index; i < q->size; i++) {
        q->tasks[i] = q->tasks[i + 1];
    }

    // Update the project's number of tasks and free the memory for the deleted task list
    p->num_tasks--;
    free(p->tasks);

    // Unlock the queue mutex
    pthread_mutex_unlock(&q->mutex);
}
