#define MAX_SHUFFLE_BUFFER_SIZE 1024

typedef struct {
    long* offsets;
    int* keys;
    void** widgets;
} record_t;

record_t* allocate_records(int num_keys, int min_key, int max_key) {
    // Allocate memory for the records
    record_t* records = (record_t*)malloc(sizeof(record_t) * num_keys);
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return NULL;
    }

    // Initialize the offsets and keys
    for (int i = 0; i < num_keys; i++) {
        records[i].offsets = (long*)malloc(sizeof(long) * num_keys);
        if (!records[i].offsets) {
            printf("Error: Failed to allocate memory for offsets\n");
            return NULL;
        }
        records[i].keys = (int*)malloc(sizeof(int) * num_keys);
        if (!records[i].keys) {
            printf("Error: Failed to allocate memory for keys\n");
            return NULL;
        }
    }

    // Initialize the widgets
    for (int i = 0; i < num_keys; i++) {
        records[i].widgets = (void**)malloc(sizeof(void*) * num_keys);
        if (!records[i].widgets) {
            printf("Error: Failed to allocate memory for widgets\n");
            return NULL;
        }
    }

    // Initialize the offsets and keys with sequential numbers starting from 0
    for (int i = 0; i < num_keys; i++) {
