        records[i].keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Initialize the widgets with pointers to image resources, text labels, and event handlers
    for (int i = 0; i < num_keys; i++) {
        records[i].widgets[i] = malloc(sizeof(void*) * num_keys);
        if (!records[i].widgets[i]) {
            printf("Error: Failed to allocate memory for widgets\n");
            return NULL;
        }
    }

    // Return the allocated records
    return records;
}

void deallocate_records(record_t* records) {
    // Deallocate the offsets and keys
    for (int i = 0; i < num_keys; i++) {
        free(records[i].offsets);
        free(records[i].keys);
    }

    // Deallocate the widgets
    for (int i = 0; i < num_keys; i++) {
        free(records[i].widgets);
    }

    // Deallocate the records
    free(records);
}

void reset_records(record_t* records) {
    // Reset the offsets and keys
    for (int i = 0; i < num_keys; i++) {
        records[i].offsets[i] = i;
        records[i].keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }
}

void track_widget_state(record_t* records, int widget_index, int state) {
    // Update the state of the widget
    records[widget_index].state = state;
}

int handle_event(record_t* records, int event_type, int widget_index) {
    // Handle the event based on the type and state of the widget
    switch (event_type) {
        case EVENT_TYPE_CLICK:
            if (records[widget_index].state == WIDGET_STATE_ENABLED) {
                // Perform action for click event
                return 1;
            } else {
                return 0;
            }
        case EVENT_TYPE_MOUSEOVER:
            if (records[widget_index].state == WIDGET_STATE_ENABLED) {
                // Perform action for mouseover event
                return 1;
            } else {
                return 0;
            }
        default:
            return 0;
    }
}

void shuffle_records(record_t* records, int num_keys) {
    // Shuffle the records using a fixed-size buffer
    long* offsets = (long*)malloc(sizeof(long) * MAX_SHUFFLE_BUFFER_SIZE);
    if (!offsets) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        return;
    }

    // Generate random offsets within the range of [0, num_keys - 1]
    for (int i = 0; i < MAX_SHUFFLE_BUFFER_SIZE; i++) {
        offsets[i] = rand() % (num_keys - 1);
    }

    // Shuffle the records using the generated offsets
    for (int i = 0; i < num_keys; i++) {
        int offset = offsets[i];
        record_t temp = records[offset];
        records[offset] = records[i];
        records[i] = temp;
    }

    // Free the generated offsets
    free(offsets);
}
