void readDirectory(const char* path, size_t depth) {
    // Validate input parameters
    if (path == NULL || depth > MAX_DEPTH) {
        return;
    }

    // Initialize memory pool for efficient allocation
    struct MemoryPool* mempool = initMemoryPool();

    // Loop through each file path in the directory
    DIR* dir = opendir(path);
    if (dir == NULL) {
        return;
    }
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        // Validate file path against naming convention and depth limit
        const char* filename = entry->d_name;
        if (filename == NULL || strlen(filename) > MAX_FILENAME_LENGTH || depth >= MAX_DEPTH) {
            continue;
        }

        // Allocate memory for file information struct
        struct FileInfo* info = malloc(sizeof(struct FileInfo));
        if (info == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for file information\n");
            continue;
        }

        // Initialize file information struct with random values
        srand((unsigned int)time(NULL));
        info->value = (double)rand() / RAND_MAX;
        info->id = rand() % MAX_ID;
        info->status = 'A';
        info->initialized = false;
        info->timestamp = time(NULL);
        info->filesize = 0;
        info->permission = READ_ONLY;

        // Log allocation event for monitoring purposes
        logAllocationEvent(info, sizeof(struct FileInfo));

        // Add file information struct to memory pool
        addToMemoryPool(mempool, info);
    }
    closedir(dir);

    // Release memory pool resources if no longer needed
    if (mempool->size == 0) {
        freeMemoryPool(mempool);
    }
}

