        fprintf(stderr, "Error: Failed to allocate memory for file information\n");
        return;
    }
    mempool->data = newdata;
    memcpy((char*)mempool->data + mempool->size, data, size);
    mempool->size += size;
}

// Define function to release memory pool resources
void freeMemoryPool(struct MemoryPool* mempool) {
    if (mempool == NULL) {
        return;
    }
    free(mempool->data);
    free(mempool);
}

