    for (int i = 0; i < num_sessions; i++) {
        sessions[i]->ref_count = 1;
    }

    // Log detailed information about each session
    for (int i = 0; i < num_sessions; i++) {
        printf("Session %d: %s\n", sessions[i]->session_id, sessions[i]->session_details);
    }
}

// Define the function to reset the memory allocation and re-initialize the data structures without losing previously computed random values
void reset_data_structures() {
    // Free all allocated memory for the primary arrays
    free(offsets);
    free(keys);
    free(records);
    free(metas);
    free(flags);

    // Allocate new memory for the primary arrays
