// Define the function to allocate and initialize data structures
void *allocateAndInitializeDataStructure(int num_records, int num_connections) {
    // Validate that num_records does not exceed the maximum allowed value
    if (num_records > MAX_NUM_RECORDS) {
        printf("Error: The number of records exceeds the maximum allowed value\n");
        return NULL;
    }

    // Allocate memory for an array of long offset values
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Error: Failed to allocate memory for the offsets\n");
        return NULL;
    }

    // Initialize the array of long offset values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(long);
    }

    // Allocate memory for an array of int keys
