    if (!keys) {
        printf("Error: Failed to allocate memory for the keys\n");
        free(offsets);
        return NULL;
    }

    // Initialize the array of int keys
    for (int i = 0; i < num_records; i++) {
        keys[i] = i + 1;
    }

    // Allocate memory for an array of record structures
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for the records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the array of record structures
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].data_block = NULL;
    }

    // Allocate memory for an array of TCP socket descriptors
    int *sockets = (int *)malloc(num_connections * sizeof(int));
    if (!sockets) {
        printf("Error: Failed to allocate memory for the sockets\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the array of TCP socket descriptors with sequential numbers
    for (int i = 0; i < num_connections; i++) {
        sockets[i] = i + 1;
    }

    // Create a fixed-size buffer to hold shuffled indices
    int *indices = (int *)malloc(INDEX_BUFFER_SIZE * sizeof(int));
    if (!indices) {
        printf("Error: Failed to allocate memory for the indices\n");
        free(offsets);
        free(keys);
        free(records);
        free(sockets);
        return NULL;
    }

    // Initialize the fixed-size buffer with sequential numbers
    for (int i = 0; i < INDEX_BUFFER_SIZE; i++) {
        indices[i] = i + 1;
    }

    // Create a mutex to synchronize access to the fixed-size buffer
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        printf("Error: Failed to allocate memory for the mutex\n");
        free(offsets);
        free(keys);
        free(records);
        free(sockets);
        free(indices);
        return NULL;
