#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define the memory pool for records
static Record* records = NULL;
static size_t num_records = 0;

// Function to initialize the records based on user-specified ranges and constraints
void init_records(long min_offset, long max_offset, int min_key, int max_key) {
    // Allocate memory for the records
    num_records = (max_offset - min_offset + 1) * (max_key - min_key + 1);
    records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the records with the specified ranges and constraints
    long offset = min_offset;
    int key = min_key;
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = offset;
        records[i].key = key;
        records[i].value = 0;
        if (++key > max_key) {
            key = min_key;
            offset++;
        }
    }
}

// Function to update the value of a record based on its offset and key
void update_record(long offset, int key, int new_value) {
    // Find the index of the record with the specified offset and key
    size_t i = 0;
    while (i < num_records && records[i].offset != offset || records[i].key != key) {
        ++i;
    }

    // Update the value of the record if it exists
    if (i < num_records) {
        records[i].value = new_value;
    } else {
        fprintf(stderr, "Error: Record with offset %ld and key %d does not exist\n", offset, key);
    }
}

// Function to retrieve the value of a record based on its offset and key
int get_record(long offset, int key) {
    // Find the index of the record with the specified offset and key
    size_t i = 0;
    while (i < num_records && records[i].offset != offset || records[i].key != key) {
        ++i;
    }

    // Return the value of the record if it exists, or -1 otherwise
    return i < num_records ? records[i].value : -1;
}

// Function to free the memory allocated for the records
void free_records() {
    free(records);
    records = NULL;
    num_records = 0;
}
```
