void shuffle_records(int num_records) {
    // Create a temporary buffer to hold the shuffled indices
    int *shuffled_indices = (int *)malloc(num_records * sizeof(int));
    if (!shuffled_indices) {
        printf("Error: Failed to allocate memory for shuffled indices\n");
        exit(1);
    }

    // Generate random indices for the records
    for (int i = 0; i < num_records; i++) {
        shuffled_indices[i] = rand() % num_records;
    }

    // Shuffle the records using the temporary buffer
    for (int i = 0; i < num_records; i++) {
        int temp = shuffled_indices[i];
        shuffled_indices[i] = shuffled_indices[temp];
        shuffled_indices[temp] = i;
    }

    // Free the temporary buffer
    free(shuffled_indices);
}

