struct Record {
    int value;
};

// Define the GUI widget structure
struct Widget {
    string imageResource;
    string textLabel;
    function<void()> eventHandler;
};

// Define the Union-Find data structure
struct UnionFind {
    vector<int> parent;
    vector<int> rank;

    UnionFind(int n) : parent(n), rank(n, 0) {}

    int find(int i) {
        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    void union(int i, int j) {
        int root1 = find(i);
        int root2 = find(j);
        if (root1 != root2) {
            if (rank[root1] < rank[root2]) {
                parent[root1] = root2;
            } else {
                parent[root2] = root1;
                if (rank[root1] == rank[root2]) {
                    rank[root1]++;
                }
            }
        }
    }
};

// Define the function to allocate memory for the array of records and initialize them with random values within a specified range
void allocateRecords(int numRecords, int minValue, int maxValue) {
    vector<Record> records;
    records.reserve(numRecords);
    srand(time(0));
    for (int i = 0; i < numRecords; i++) {
        Record record;
        record.value = rand() % (maxValue - minValue + 1) + minValue;
        records.push_back(record);
    }
}

// Define the function to utilize the Union-Find data structure to determine the number of disjoint pairs of elements in the array
void findDisjointPairs(vector<Record> &records, int numRecords) {
    UnionFind uf(numRecords);
    for (int i = 0; i < numRecords - 1; i++) {
        for (int j = i + 1; j < numRecords; j++) {
            if (records[i].value != records[j].value) {
                uf.union(i, j);
            }
        }
    }
}

// Define the function to output the count of disjoint pairs and the time taken in milliseconds for the computation
void printResults(vector<Record> &records, int numRecords) {
    chrono::steady_clock::time_point start = chrono::steady_clock::now();
    findDisjointPairs(records, numRecords);
    chrono::steady_clock::time_point end = chrono::steady_clock::now();
    long duration = chrono::duration_cast<chrono::milliseconds>(end - start).count();
    cout << "Number of disjoint pairs: " << uf.parent.size() << endl;
    cout << "Time taken in milliseconds: " << duration << endl;
}

