    float value;
    char label;
    std::string description;
    long last_modified;
    performance_metric metrics;
};

// Define the struct for performance_metric
struct performance_metric {
    double cpu_usage;
    double memory_usage;
    uint64_t io_operations;
};

// Define the struct for event_log
struct event_log {
    std::string message;
    long timestamp;
};

// Define the struct for dependency_flags
struct dependency_flags {
    bool is_dependency;
    uint8_t dependency_type;
};

// Define the function to initialize the arrays
void init_arrays(int num_elements, int num_threads) {
    // Allocate memory for the arrays
    double* values = (double*) malloc(num_elements * sizeof(double));
    bool* status_flags = (bool*) malloc(num_elements * sizeof(bool));
    custom_element** pointers = (custom_element**) malloc(num_elements * sizeof(custom_element*));
    int* thread_ids = (int*) malloc(num_threads * sizeof(int));
    struct timespec* time_stamps = (struct timespec*) malloc(num_elements * sizeof(struct timespec));
    event_log** event_logs = (event_log**) malloc(num_elements * sizeof(event_log*));
    performance_metric* performance_metrics = (performance_metric*) malloc(num_elements * sizeof(performance_metric));
    dependency_flags* dependency_flags = (dependency_flags*) malloc(num_elements * sizeof(dependency_flags));

    // Initialize the arrays
    for (int i = 0; i < num_elements; i++) {
        values[i] = 0.0;
        status_flags[i] = false;
        pointers[i] = NULL;
        time_stamps[i].tv_sec = 0;
        time_stamps[i].tv_nsec = 0;
        event_logs[i] = NULL;
        performance_metrics[i].cpu_usage = 0.0;
        performance_metrics[i].memory_usage = 0.0;
        performance_metrics[i].io_operations = 0;
        dependency_flags[i].is_dependency = false;
        dependency_flags[i].dependency_type = 0;
    }

    // Initialize the thread IDs
    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
    }
}

// Define the function to update the custom_element structs using a specified callback function
void update_custom_elements(int num_elements, int num_threads, void (*callback)(int, int)) {
    // Lock the mutex to prevent race conditions during updates
    pthread_mutex_lock(&mutex);

    // Update the custom_element structs using the specified callback function
    for (int i = 0; i < num_elements; i++) {
        if (pointers[i] != NULL) {
            (*callback)(i, pointers[i]->value);
        }
    }

    // Unlock the mutex to allow other threads to access the arrays
    pthread_mutex_unlock(&mutex);
}

