void validate_memory(int num_elements, int num_threads) {
    // Check if the memory has been properly initialized
    for (int i = 0; i < num_elements; i++) {
        if (values[i] == 0.0 && status_flags[i] == false && pointers[i] == NULL && time_stamps[i].tv_sec == 0 && time_stamps[i].tv_nsec == 0 && event_logs[i] == NULL && performance_metrics[i].cpu_usage == 0.0 && performance_metrics[i].memory_usage == 0.0 && performance_metrics[i].io_operations == 0 && dependency_flags[i].is_dependency == false && dependency_flags[i].dependency_type == 0) {
            printf("Memory has not been properly initialized\n");
        }
    }
}

// Define the function to handle potential memory leaks and ensure thread safety during updates
void update_thread_safe(int num_elements, int num_threads, void (*callback)(int, int)) {
    // Lock the mutex to prevent race conditions during updates
    pthread_mutex_lock(&mutex);

    // Update the custom_element structs using the specified callback function
    for (int i = 0; i < num_elements; i++) {
        if (pointers[i] != NULL) {
            (*callback)(i, pointers[i]->value);
        }
    }

    // Unlock the mutex to allow other threads to access the arrays
    pthread_mutex_unlock(&mutex);
}

// Define the function to log the event_log strings in a circular buffer
void log_event_logs(int num_elements, int num_threads) {
    // Lock the mutex to prevent race conditions during logging
    pthread_mutex_lock(&mutex);

    // Log the event_log strings in a circular buffer
    for (int i = 0; i < num_elements; i++) {
        if (event_logs[i] != NULL) {
            printf("Event log: %s\n", event_logs[i]->message.c_str());
        }
    }

