    pthread_mutex_unlock(&mutex);
}

// Define the function to flush the event_log strings to an external log file
void flush_event_logs(int num_elements, int num_threads) {
    // Lock the mutex to prevent race conditions during flushing
    pthread_mutex_lock(&mutex);

    // Flush the event_log strings to an external log file
    for (int i = 0; i < num_elements; i++) {
