    LinkedList *list = malloc(sizeof(LinkedList)); // Allocate memory for the linked list
    if (list == NULL) {
        handleMemoryAllocationFailure(); // Handle memory allocation failure
    }
    list->head = NULL; // Initialize head node to null
    list->tail = NULL; // Initialize tail node to null
    list->size = 0; // Initialize size to zero

    while (1) {
        Task *task = malloc(sizeof(Task)); // Allocate memory for the task
        if (task == NULL) {
            handleMemoryAllocationFailure(); // Handle memory allocation failure
        }
        initTask(task); // Initialize the task
        appendDescription(task, ""); // Append an empty description to the task
        list->size++; // Increment size of the linked list
        if (list->head == NULL) { // If head node is null
            list->head = task; // Set head node to the new task
            list->tail = task; // Set tail node to the new task
        } else { // Otherwise
            list->tail->next = task; // Set next pointer of the tail node to the new task
            list->tail = task; // Set tail node to the new task
        }
    }

    return 0;
}
